import type { CompletionItem } from 'vscode-languageserver';
import { InsertTextFormat, CompletionItemKind, TextEdit } from 'vscode-languageserver';
import type {
    CompletionContext,
    CompletionItemAdapterParams,
    JsonAttributeNameContext,
    ModularCompletionHandler
} from '../types';
import { basicItemProvider } from '../utils';

function jsonAttributeNameGate(context: CompletionContext): boolean {
    return context.type === 'edm-json' && context.kind === 'attribute-name';
}

function jsonAttributeNameAdapter({
    context: { proposedReplacementRange: replacementRange },
    originalItem
}: CompletionItemAdapterParams<JsonAttributeNameContext>): CompletionItem | undefined {
    const insertText = `$${originalItem.insertText}`;
    return {
        label: insertText,
        insertTextFormat: InsertTextFormat.PlainText,
        kind: CompletionItemKind.Property,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        filterText: insertText,
        textEdit: TextEdit.replace(replacementRange, insertText)
    };
}

export const jsonAttributeNameHandler: ModularCompletionHandler = {
    name: 'json-attribute-name',
    type: 'modular',
    gate: jsonAttributeNameGate,
    providers: [basicItemProvider],
    mappers: [],
    adapters: [jsonAttributeNameAdapter]
};
