import type { AnnotationNode, Expression, Identifier, Path } from '@sap-ux/cds-annotation-parser';
import {
    EXPRESSION_TYPES,
    IDENTIFIER_TYPE,
    PATH_TYPE,
    containsIncorrectExpressions,
    positionIsInExpressionWhiteSpace
} from '@sap-ux/cds-annotation-parser';
import type {
    CompletionContext,
    CompletionHandlerArgs,
    ExpressionContext,
    ModularCompletionHandler,
    ProviderResult
} from '../types';
import type { Element, Position, Range } from '@sap-ux/odata-annotation-core';
import { Edm, createElementNode, createTextNode, positionContained } from '@sap-ux/odata-annotation-core';

function expressionGate(context: CompletionContext): boolean {
    return context.type === 'container' && context.kind === 'expression';
}

function expressionProvider(
    context: ExpressionContext,
    { getCompletionItems, file, pointer, position }: CompletionHandlerArgs
): ProviderResult {
    // only code completion requests for paths are supported in expressions
    let isPathCompletionRequest = false;
    let pathForDummyContent: Path | undefined; // creation of dummy content with this path node is needed
    const targetNode = context.pathToNode[context.pathToNode.length - 1];
    const topExpression = context.pathToNode.find((node) => EXPRESSION_TYPES.includes(node.type));
    const correctExpressionsOnly = !containsIncorrectExpressions(topExpression as Expression);
    if (targetNode?.type === PATH_TYPE) {
        // code completion for existing path operand of expression - make sure current position is not touching operator
        isPathCompletionRequest = !isTouchingOperator(context.pathToNode, position);
        if (isPathCompletionRequest && !correctExpressionsOnly) {
            pathForDummyContent = targetNode;
        }
    } else if (EXPRESSION_TYPES.includes(targetNode?.type)) {
        // code completion in white space of expression
        isPathCompletionRequest = positionIsInExpressionWhiteSpace(targetNode as Expression, position);
        if (isPathCompletionRequest) {
            pathForDummyContent = getPathForPosition(targetNode as Expression, position);
        }
    }
    if (!isPathCompletionRequest) {
        // not a path code completion request
        return { itemsForAdapter: [], completionItems: [] };
    }
    if (pathForDummyContent) {
        // modify file and pointer: expression should contain dummy content to support all paths in cc for dummy path range
        const segments = pointer.split('/');
        const expressionElement: Element = segments
            .slice(1, -1)
            .reduce((accumulator, segment) => accumulator[segment], file);
        const { element, pointer: pointerDiff } = buildExpressionValueForPathCcSupport(pathForDummyContent);
        expressionElement.content = [element];
        pointer = [...segments.slice(0, -1), 'content', '0', ...pointerDiff.split('/')].join('/');
    }
    const items = getCompletionItems(file, position, false, pointer);
    return { itemsForAdapter: items, completionItems: [] };
}

function getPathForPosition(expression: Expression, position: Position): Path | undefined {
    if (positionContained(expression.range, position)) {
        const operand = expression.operands.find((operand) => positionContained(operand.range, position));
        if (operand) {
            if (operand.type === PATH_TYPE) {
                return operand;
            } else if (EXPRESSION_TYPES.includes(operand.type)) {
                return getPathForPosition(operand as Expression, position);
            }
        } else if (positionIsInExpressionWhiteSpace(expression, position)) {
            return getDummyPath(position);
        }
    }
}

function getDummyPath(position: Position): Path {
    const range = getRangeExtendingPosition(position);
    const identifier: Identifier = { type: IDENTIFIER_TYPE, value: '', range };
    const path: Path = { type: PATH_TYPE, value: '', segments: [identifier], separators: [], range };
    return path;
}

function getRangeExtendingPosition(position: Position): Range {
    return { start: { ...position }, end: { line: position.line, character: position.character + 1 } };
}

function buildExpressionValueForPathCcSupport(path: Path): { element: Element; pointer: string } {
    /**
     * return content to trigger code completion (returning any path) in provided range:
     *   <if>
     *     <eq>
     *        <path> | <path>
     *        <...>
     *     </eq>
     *     <.../>
     *     <.../>
     *   </if>
     */
    const { range, value } = path;
    const textPath = createTextNode(value, range);
    const elementPath: Element = createElementNode({
        name: Edm.Path,
        range,
        contentRange: range,
        content: [textPath]
    });
    const elementEqual: Element = createElementNode({
        name: Edm.Eq,
        range,
        contentRange: range,
        content: [elementPath]
    });
    const elementIf: Element = createElementNode({
        name: Edm.If,
        range,
        contentRange: range,
        content: [elementEqual]
    });
    return { element: elementIf, pointer: 'content/0/content/0/content/0/text/$0' };
}

function isTouchingOperator(pathToNode: AnnotationNode[], position: Position): boolean {
    let touched = false;
    for (const node of pathToNode) {
        if (EXPRESSION_TYPES.includes(node.type)) {
            const expressionNode = node as Expression;
            if (expressionNode.operators.some((operator) => positionContained(operator.range, position))) {
                touched = true;
            }
        }
    }
    return touched;
}

export const expressionHandler: ModularCompletionHandler = {
    name: 'path-in-expression',
    type: 'modular',
    gate: expressionGate,
    providers: [expressionProvider],
    mappers: [],
    adapters: []
};
