import { pathToFileURL } from 'url';

import type {
    ICdsCompiler,
    Token,
    XsnAnnotationAssignment,
    XsnArtifact,
    XsnElement,
    XsnLocation,
    XsnName,
    XsnNamedObject,
    XsnSource
} from '@sap/cds-compiler';

import { getStartLineColFromLocation, getTextForLocationRange } from './transform';
import { AnnotationAssignmentTokenImpl } from './annotationAssignmentToken';
import { GenericDefinitionImpl } from './genericDefinition';
import { IdentifierTokenImpl } from './identifierToken';
import type { AnnotationAssignmentToken, FileIndex, IdentifierToken } from './types';
import { getNameObj } from './utils';

const getDependencies = (source: XsnSource): string[] => {
    const directDependentUris: string[] = [];
    const dependencies = source.dependencies ?? [];
    for (const dependency of dependencies) {
        if (dependency.realname) {
            const dependencyUri = pathToFileURL(dependency.realname).toString();
            directDependentUris.push(dependencyUri);
        }
    }

    return directDependentUris;
};
const processElement = (
    artifact: XsnArtifact | XsnElement,
    collector: Collector,
    sourceUri: string,
    source: XsnSource,
    text: string,
    compiler: ICdsCompiler
): void => {
    const elements: XsnElement[] = [];
    Object.keys(artifact.elements || artifact.columns || {}).forEach((name) => {
        const el = artifact.elements || artifact.columns;
        if (el?.[name]) {
            elements.push(el[name]);
        }
    });
    for (const element of elements) {
        const buildElementName = (artifact: XsnNamedObject): string => {
            const namedObj = getNameObj(artifact, compiler);
            return [namedObj.absolute, namedObj.element].join('.');
        };
        processArtifact(element, collector, sourceUri, source, text, compiler, buildElementName);
    }
};
const processBoundActionFun = (
    artifact: XsnArtifact | XsnElement,
    collector: Collector,
    sourceUri: string,
    source: XsnSource,
    text: string,
    compiler: ICdsCompiler
): void => {
    const actions: XsnElement[] = [];
    Object.keys(artifact.actions || {}).forEach((name) => {
        if (artifact.actions?.[name]) {
            actions.push(artifact.actions[name]);
        }
    });
    for (const action of actions) {
        const buildActionName = (artifact: XsnNamedObject): string => {
            const namedObj = getNameObj(artifact, compiler);
            return [namedObj.absolute, namedObj.action].join('.');
        };
        processArtifact(action, collector, sourceUri, source, text, compiler, buildActionName);
        //  parameter of bound actions functions
        const params: XsnElement[] = [];
        Object.keys(action.params || {}).forEach((name) => {
            if (action.params?.[name]) {
                params.push(action.params[name]);
            }
        });
        for (const param of params) {
            const buildParamName = (artifact: XsnNamedObject): string => {
                const namedObj = getNameObj(artifact, compiler);
                return [namedObj.absolute, namedObj.action, namedObj.param].join('.');
            };
            processArtifact(param, collector, sourceUri, source, text, compiler, buildParamName);
        }
    }
};
const processBoundActionFunParam = (
    artifact: XsnArtifact | XsnElement,
    collector: Collector,
    sourceUri: string,
    source: XsnSource,
    text: string,
    compiler: ICdsCompiler
): void => {
    const params: XsnElement[] = [];
    Object.keys(artifact.params || {}).forEach((name) => {
        if (artifact.params?.[name]) {
            params.push(artifact.params[name]);
        }
    });
    for (const param of params) {
        const buildParamName = (artifact: XsnNamedObject): string => {
            const namedObj = getNameObj(artifact, compiler);
            return [namedObj.absolute, namedObj.param].join('.');
        };
        processArtifact(param, collector, sourceUri, source, text, compiler, buildParamName);
    }
};
export function createFileIndexFromSource(sourceUri: string, source: XsnSource, compiler: ICdsCompiler): FileIndex {
    const directDependentUris: string[] = [];
    const annotationAssignments = new Map<string, AnnotationAssignmentToken>();
    const collector: Collector = {
        idTokens: [],
        annotationAssignments
    };

    directDependentUris.push(...getDependencies(source));

    if (!source.tokenStream) {
        return Object.freeze({
            directDependentUris,
            idTokens: collector.idTokens,
            compilerMessages: [],
            i18nTokens: [],
            stringTokens: [],
            tokens: [],
            get annotationAssignments(): IterableIterator<AnnotationAssignmentToken> {
                return annotationAssignments.values();
            }
        });
    }
    const text = source.tokenStream.tokenSource?.inputStream.strdata ?? '';
    const artifacts = Object.keys(source.artifacts || {}).map((name) => source.artifacts[name]);
    artifacts.push(...getArtifactsRecursively(artifacts));
    if (source.extensions && source.extensions.length) {
        artifacts.push(...(source.extensions as XsnArtifact[]));
    }
    for (const artifact of artifacts) {
        // entities, (unbound) actions/functions
        const buildEntityName = (artifact: XsnNamedObject): string => {
            const namedObj = getNameObj(artifact, compiler);
            return namedObj.absolute;
        };
        processArtifact(artifact, collector, sourceUri, source, text, compiler, buildEntityName);
        // entity elements
        processElement(artifact, collector, sourceUri, source, text, compiler);
        // bound actions/functions
        processBoundActionFun(artifact, collector, sourceUri, source, text, compiler);
        //  parameters (of unbound actions functions)
        processBoundActionFunParam(artifact, collector, sourceUri, source, text, compiler);
    }
    return Object.freeze({
        idTokens: collector.idTokens,
        directDependentUris,
        compilerMessages: [],
        i18nTokens: [],
        stringTokens: [],
        tokens: [],
        get annotationAssignments(): IterableIterator<AnnotationAssignmentToken> {
            return annotationAssignments.values();
        }
    });
}

interface Collector {
    idTokens: IdentifierToken[];
    annotationAssignments: Map<string, AnnotationAssignmentToken>;
}

const isDifferentLocation = (location: XsnLocation, source: XsnSource): boolean => {
    if (location && source) {
        if (location.file && source.location?.file) {
            return location.file !== source.location.file;
        }
    }
    return false; // keep logic as it was before
};

const processAnnotationAssignment = (
    annotationAssignments: readonly XsnAnnotationAssignment[],
    collector: Collector,
    sourceUri: string,
    source: XsnSource,
    text: string,
    carrierName: string,
    carrierToken: IdentifierToken | undefined,
    buildName: (name: XsnNamedObject) => string
): void => {
    // add annotation assignments
    for (const assignment of annotationAssignments) {
        if (isDifferentLocation(assignment.location, source)) {
            continue;
        }
        let annotationText = getTextForLocationRange(assignment.location, text);
        if (annotationText.length && annotationText[0] === '@') {
            // Sometimes assignment location includes @ symbol
            annotationText = annotationText.substr(1);
        }
        // starting with cds-compiler 3.0, 'name' property sometimes appears as property of 'value'
        const name = assignment.name ?? assignment['value'].name;
        const location = name.path?.slice(0, 1)[0].location;
        const { line, col } = getStartLineColFromLocation(location);
        const assignmentNativeToken = source.tokenStream.tokens.find(
            (token) => token.line === line && token.column === col
        );
        if (assignmentNativeToken) {
            const idToken = createIdentifierFromToken(sourceUri, assignmentNativeToken, undefined, buildName);

            collector.idTokens.push(idToken);
            const key = `${idToken.range.start.line}:${idToken.range.start.character}`;
            if (!collector.annotationAssignments.has(key)) {
                const annotationToken = new AnnotationAssignmentTokenImpl(
                    sourceUri,
                    idToken.tokenIndex,
                    annotationText,
                    idToken.line,
                    idToken.character,
                    carrierName,
                    carrierToken
                );

                collector.annotationAssignments.set(key, annotationToken);
            }
        }
    }
};

function processArtifact(
    artifact: XsnArtifact | XsnElement,
    collector: Collector,
    sourceUri: string,
    source: XsnSource,
    text: string,
    compiler: ICdsCompiler,
    buildName: (name: XsnNamedObject) => string
): void {
    const annotationAssignments = artifact.$annotations;
    if (isDifferentLocation(artifact.location, source)) {
        return;
    }
    if (annotationAssignments && annotationAssignments.length) {
        // build tokens
        const locatable = artifact.name.path ? artifact.name.path.slice(-1)[0] : artifact.name;
        // find line/col for location
        const { line, col } = getStartLineColFromLocation(locatable.location);
        const carrierNativeToken = source.tokenStream.tokens.find(
            (token) => token.line === line && token.column === col
        );
        let carrierToken: IdentifierToken | undefined;
        if (carrierNativeToken) {
            carrierToken = createIdentifierFromToken(sourceUri, carrierNativeToken, artifact, buildName);

            collector.idTokens.push(carrierToken);
        }
        // add annotation assignments
        const carrierName = getCarrierName(artifact?.name?._artifact ?? artifact, compiler);
        processAnnotationAssignment(
            annotationAssignments,
            collector,
            sourceUri,
            source,
            text,
            carrierName,
            carrierToken,
            buildName
        );
    }
}

function getArtifactsRecursively(artifacts: XsnArtifact[]): XsnArtifact[] {
    const newArtifacts: XsnArtifact[] = [];
    for (const artifact of artifacts) {
        Object.keys(artifact.artifacts || {}).forEach((name) => {
            if (artifact.artifacts?.[name]) {
                newArtifacts.push(artifact.artifacts[name]);
            }
        });
        newArtifacts.push(...((artifact.extensions || []) as XsnArtifact[]));
    }
    if (newArtifacts.length) {
        return [...newArtifacts, ...getArtifactsRecursively(newArtifacts)];
    } else {
        return newArtifacts;
    }
}

function getName(
    carrier: XsnArtifact | XsnElement | XsnNamedObject | XsnAnnotationAssignment,
    compiler: ICdsCompiler
): XsnName {
    if (carrier.kind === 'annotate') {
        return carrier.name?._artifact?.name || carrier.name;
    }
    return getNameObj(carrier as XsnNamedObject, compiler);
}

function getCarrierName(
    carrier: XsnArtifact | XsnElement | XsnNamedObject | XsnAnnotationAssignment,
    compiler: ICdsCompiler
): string {
    let namedObj = getName(carrier, compiler);
    const segments: string[] = [];
    if (!namedObj?.absolute) {
        namedObj = getNameObj(carrier as XsnNamedObject, compiler);
    }
    segments.push(namedObj.absolute);
    if (namedObj.element) {
        segments.push(namedObj.element);
    }
    if (namedObj.action) {
        segments.push(namedObj.action);
    }
    if (namedObj.param) {
        segments.push(namedObj.param);
    }
    return segments.join('.');
}

function createIdentifierFromToken(
    uri: string,
    { tokenIndex, text, line, column }: Token,
    artifact: XsnArtifact | XsnElement | undefined,
    buildName: (name: XsnNamedObject) => string
): IdentifierToken {
    const carrierArtifact = artifact?.name?._artifact ?? artifact;
    const definition =
        artifact?.name && carrierArtifact
            ? new GenericDefinitionImpl(buildName(carrierArtifact), carrierArtifact.kind)
            : undefined;

    return new IdentifierTokenImpl(uri, tokenIndex, text, line - 1, column, definition);
}
