import { EMPTY_VALUE_TYPE } from '@sap-ux/cds-annotation-parser';
import { CompletionItemKind, InsertTextFormat, Range, TextEdit } from 'vscode-languageserver';
import type {
    EnumValueContext,
    CompletionItemAdapterWithGate,
    EmptyValueContext,
    CollectionValueContext,
    CompletionItemAdapterParams
} from '../types';

export const enumValueAdapter: CompletionItemAdapterWithGate = {
    gate: ({ context, originalItem }: CompletionItemAdapterParams) =>
        ((context.type === 'value' && [EMPTY_VALUE_TYPE, 'enum'].includes(context.valueType)) ||
            (context.type === 'container' && context.kind === 'collection')) &&
        originalItem.kind === CompletionItemKind.Enum,
    adapter: ({
        context,
        originalItem
    }: CompletionItemAdapterParams<EnumValueContext | EmptyValueContext | CollectionValueContext>) => {
        const text = `#${originalItem.insertText.split('/')[1]}`;
        const range: Range =
            context.type === 'container' || context.valueType === EMPTY_VALUE_TYPE
                ? Range.create(context.position, context.position)
                : context.proposedReplacementRange;
        return {
            label: text,
            insertTextFormat: InsertTextFormat.PlainText,
            kind: CompletionItemKind.EnumMember,
            sortText: originalItem.sortText,
            filterText: text,
            textEdit: TextEdit.replace(range, text)
        };
    }
};
