import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, Position, Range, TextEdit } from 'vscode-languageserver';

import { EMPTY_VALUE_TYPE, PATH_TYPE, STRING_LITERAL_TYPE } from '@sap-ux/cds-annotation-parser';
import { positionContained } from '@sap-ux/odata-annotation-core';
import type { Identifier } from '@sap-ux/cds-annotation-parser';
import type { CompletionItemAdapterParams, CompletionItemAdapterWithGate, ValueCompletionContext } from '../types';
import { wrapWithExclamationSquareBrackets } from '../utils';

export const pathAdapter: CompletionItemAdapterWithGate = {
    gate: ({ context, originalItem }: CompletionItemAdapterParams) =>
        originalItem.label.startsWith('@') || (context.type === 'value' && context.valueType === PATH_TYPE),
    adapter: ({ context, originalItem }: CompletionItemAdapterParams<ValueCompletionContext>) => {
        const textEdit = getTextEdit(context, originalItem);

        return {
            label: textEdit.newText,
            insertTextFormat: InsertTextFormat.PlainText,
            kind: CompletionItemKind.Class,
            sortText: originalItem.sortText,
            documentation: originalItem.documentation,
            filterText: textEdit.newText,
            textEdit
        };
    }
};

function processNode(nodes: Identifier[], i: number, isTermCastItem: boolean, text: string, newText: string): TextEdit {
    const node = nodes[i];
    const prev = nodes[i - 1];
    if (i > 1 && prev.value.startsWith('@')) {
        const range = Range.create(prev.range.start, node.range.end);
        const newTxt = !(node.quoted || prev.quoted) && isTermCastItem ? newText : text;
        return TextEdit.replace(range, newTxt);
    }
    if (i + 1 < nodes.length && node.value.startsWith('@')) {
        const next = nodes[i + 1];
        const range = Range.create(node.range.start, next.range.end);
        const newTxt = !(node.quoted || next.quoted) && isTermCastItem ? newText : text;
        return TextEdit.replace(range, newTxt);
    }
    return TextEdit.replace(node.range, !node.quoted && isTermCastItem ? newText : text);
}

function getTextEdit(context: ValueCompletionContext, originalItem: CompletionItem): TextEdit {
    const text = originalItem.label;
    const isTermCastItem = text.startsWith('@');
    const newText = wrapWithExclamationSquareBrackets(text, false);
    if (context.type === 'container' || context.valueType === EMPTY_VALUE_TYPE) {
        return TextEdit.insert(context.position, newText);
    }
    const { pathToNode, proposedReplacementRange } = context;
    const value = pathToNode[pathToNode.length - 1];
    if (value.type === PATH_TYPE) {
        const nodes = value.segments;
        for (let i = 0; i < nodes.length; i++) {
            const node = nodes[i];
            if (positionContained(node.range, context.position)) {
                return processNode(nodes, i, isTermCastItem, text, newText);
            }
        }
    } else if (value.type === STRING_LITERAL_TYPE) {
        const replacementRange =
            TextEdit.is(originalItem.textEdit) && originalItem.textEdit.range
                ? originalItem.textEdit.range
                : Range.create(
                      Position.create(
                          proposedReplacementRange.start.line,
                          value.openToken?.range.end.character || proposedReplacementRange.start.character
                      ),
                      Position.create(
                          proposedReplacementRange.end.line,
                          value.closeToken?.range.start.character || proposedReplacementRange.end.character
                      )
                  );
        return TextEdit.replace(replacementRange, text);
    }
    return TextEdit.replace(proposedReplacementRange, isTermCastItem ? newText : text);
}
