import type { CompletionItem } from '../types/general';
import { CompletionItemCategory, CompletionItemType } from '../types/general';
import type { ValueHandlingContext, ValueType } from '../types/context';
import { getVocabularyType } from '../vocabulary/access';
import { Snippet } from './snippet';
import { getPropertyDescriptorsForRecord, adjustRequestedTypes } from '../value-handling';
import { EdmType, dynamicExpressionSignatureMap } from '../specification';
import type { Element } from '@sap-ux/odata-annotation-core';
import { Edm } from '@sap-ux/odata-annotation-core';
import { createPropertyValueSnippet, recordSnippets, createCollectionSnippet } from './collection';
import { snippetsForElementsProvidingValue } from './simpleValues';
import { appendNameToDocumentationAndTruncate } from '../utils/annotationService';
import { MarkupKind } from 'vscode-languageserver';
import { snippetsForDynamicExpressionParameters } from './dynamicExpressions';
import type { JsonPath } from '../utils/path';
import { getSnippetsForApplyContent } from './applyFunction';

export interface SnippetHandlingContext {
    valueHandlingContext: ValueHandlingContext;
    type: ValueType;
    useSnippets: boolean;
}

/**
 * Snippet completion handler for annotation value providing elements
 * ------------------------------------------------------------------
 * @param valueHandlingContext - value handling context object
 * @param type - value type object
 * @param element - parent element object
 */
export function handleSnippets(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    element: Element,
    path: JsonPath
): CompletionItem[] {
    const useSnippets = valueHandlingContext.context.useSnippets;
    const snippetContext: SnippetHandlingContext = {
        valueHandlingContext,
        type,
        useSnippets: valueHandlingContext.context.useSnippets
    };

    if (element.name === Edm.Apply) {
        // snippets within Apply element
        return getSnippetsForApplyContent(snippetContext, element, path);
    } else if ([...dynamicExpressionSignatureMap.keys()].includes(element.name as Edm)) {
        const vocabularyType = getVocabularyType(valueHandlingContext.context, type.name);
        const complexType = vocabularyType?.kind === Edm.ComplexType ? vocabularyType : undefined;
        return snippetsForDynamicExpressionParameters(snippetContext, element, path, complexType);
    } else if (type?.asCollection) {
        // compose collection member type
        if (valueHandlingContext.nodeContext?.dataFieldValueProperty) {
            // For DataField Value we don't support nested collections
            return [];
        }
        const itemType = { ...type, asCollection: false };
        if (element.name !== Edm.Collection) {
            // collection snippets
            const vocabularyType = getVocabularyType(valueHandlingContext.context, type.name);
            const collection = createCollectionSnippet({ ...snippetContext, type: itemType }, vocabularyType, 1, true);
            return [
                collection.toCompletionItem(),
                new Snippet(Edm.Path, useSnippets)
                    .appendFinalTabStopToContent()
                    .toCompletionItem(null, null, CompletionItemCategory.Path)
            ];
        } else {
            // snippets within collection
            // handle collection member
            const restrictedTypes = adjustRequestedTypes([itemType], valueHandlingContext);
            const result: CompletionItem[] = [];
            restrictedTypes.forEach((t) => result.push(...handleSnippets(valueHandlingContext, t, element, path)));
            return result;
        }
    } else if (type?.name && (!type.name.startsWith('Edm.') || type.name === EdmType.PrimitiveType)) {
        // complex type element handling
        return handleNonPrimitiveTypeSnippets(snippetContext, valueHandlingContext, element, type, path);
    } else if (type?.name && type.name.startsWith('Edm.')) {
        // snippets within element of Edm.* type
        if ([...dynamicExpressionSignatureMap.keys()].includes(element.name as Edm)) {
            return snippetsForDynamicExpressionParameters(snippetContext, element, path);
        }
        return snippetsForElementsProvidingValue(snippetContext);
    }
    return [];
}

function handleNonPrimitiveTypeSnippets(
    snippetContext: SnippetHandlingContext,
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    type: ValueType,
    path: JsonPath
): CompletionItem[] {
    const vocabularyType = getVocabularyType(valueHandlingContext.context, type.name);
    if (vocabularyType?.kind === Edm.ComplexType) {
        const complexType = vocabularyType;
        if ([Edm.Collection, Edm.Annotation].includes(element.name as Edm)) {
            // snippets within collection/annotation
            return [
                ...recordSnippets(snippetContext, complexType),
                ...recordSnippets(snippetContext, complexType, true),
                ...snippetsForElementsProvidingValue(snippetContext)
            ];
        } else if (element.name === Edm.Record) {
            return getRecordContentSnippets(snippetContext, valueHandlingContext, element, type);
        } else if (element.name === Edm.PropertyValue) {
            // snippets within PropertyValue of complex type
            return [
                ...recordSnippets(snippetContext, complexType),
                ...recordSnippets(snippetContext, complexType, true),
                ...snippetsForElementsProvidingValue(snippetContext)
            ];
        } else if ([...dynamicExpressionSignatureMap.keys()].includes(element.name as Edm)) {
            return snippetsForDynamicExpressionParameters(snippetContext, element, path, complexType);
        }
    } else {
        // snippets within element of not recognized or non-complex type
        if ([...dynamicExpressionSignatureMap.keys()].includes(element.name as Edm)) {
            return snippetsForDynamicExpressionParameters(snippetContext, element, path);
        }
        return snippetsForElementsProvidingValue(snippetContext);
    }
    return [];
}

function getRecordContentSnippets(
    snippetContext: SnippetHandlingContext,
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    type: ValueType
): CompletionItem[] {
    // snippets within record (PropertyValue elements)
    const recordProps = getPropertyDescriptorsForRecord(valueHandlingContext, type, element);
    snippetContext.type = recordProps.resolvedRecordType;

    // combined snippet for all remaining properties
    let propTabStop = 1;
    const combined: Element[] = [];
    recordProps.notProvided.forEach((prop, idx) => {
        const snippet = createPropertyValueSnippet(
            snippetContext,
            prop,
            idx === recordProps.notProvided.length - 1,
            propTabStop
        );
        propTabStop = snippet.getNextTabStopId();
        combined.push(snippet.generic);
    });
    const combinedItem: CompletionItem = {
        name: 'Remaining Properties...',
        text: 'Remaining Properties...',
        category: CompletionItemCategory.ValueElementSet,
        data: combined,
        type: CompletionItemType.Snippet,
        sorting: { isNotMandatory: true }
    };

    const openPropertySnippets: CompletionItem[] = [];
    if (recordProps.isOpenType) {
        const snippet = new Snippet(Edm.PropertyValue, snippetContext.useSnippets, propTabStop);
        snippet
            .setAttribute(
                Edm.Property,
                snippet.getPlaceHolderText({
                    id: snippet.getNextTabStopId(),
                    value: 'Enter property name'
                })
            )
            .appendFinalTabStopToContent();
        const compItem = snippet.toCompletionItem(`Property`, true, CompletionItemCategory.ValueElement, true);
        compItem.documentation = {
            kind: MarkupKind.Markdown,
            value: '**Description:** Open complex type property template\n'
        };
        openPropertySnippets.push(compItem);
    }

    // return list of single elements and combined item
    return [
        ...(combined.length ? [combinedItem] : []),
        ...(recordProps.dollarTypeAllowed ? [{ name: '$CdsRecordType$', text: '$CdsRecordType$' }] : []),
        ...recordProps.notProvided.map((prop) => {
            const documentation = valueHandlingContext.context.vocabularies.getDocumentation(
                recordProps.resolvedRecordType.name,
                prop.name,
                snippetContext.valueHandlingContext.aliasInfo
            );
            appendNameToDocumentationAndTruncate(
                prop.name,
                documentation,
                valueHandlingContext.context,
                true,
                snippetContext.valueHandlingContext.aliasInfo
            );

            const item = createPropertyValueSnippet(snippetContext, prop, false, undefined).toCompletionItem(
                `Property "${prop.name}"`,
                false,
                CompletionItemCategory.ValueElement,
                true
            );
            item.data.documentation = documentation;
            return item;
        }),
        ...openPropertySnippets
    ];
}
