import type { Position } from 'vscode-languageserver';
import { Range } from 'vscode-languageserver';

import type { Annotation, RecordProperty, AnnotationNode } from '@sap-ux/cds-annotation-parser';
import {
    RECORD_PROPERTY_TYPE,
    ANNOTATION_TYPE,
    RECORD_TYPE,
    ANNOTATION_GROUP_TYPE
} from '@sap-ux/cds-annotation-parser';
import { positionContained, isBefore } from '@sap-ux/odata-annotation-core';

import type { CompletionContextResolverArgs, AnnotationContainerRefactorContext } from '../types';
import { nodeHasComma } from '../../../utils/hasComma';

export function annotationRefactoringResolver(
    args: CompletionContextResolverArgs
): AnnotationContainerRefactorContext | undefined {
    const { targetNode, position } = args;
    if (targetNode.type === RECORD_PROPERTY_TYPE && targetNode.name.value.startsWith('$')) {
        // CDS "special" properties can not be annotated
        return;
    }
    if (
        (targetNode.type === ANNOTATION_TYPE || targetNode.type === RECORD_PROPERTY_TYPE) &&
        !isBeforeColon(targetNode, position)
    ) {
        // Cursor is after ":" of annotatable key
        const { value } = targetNode;
        if (
            value?.type !== RECORD_TYPE &&
            !(targetNode.type === RECORD_PROPERTY_TYPE && targetNode.name.value === '$value')
        ) {
            return createAnnotationRefactoringContext(targetNode, args);
        }
        if (
            value?.type === RECORD_TYPE &&
            !positionContained(
                Range.create(
                    {
                        ...targetNode.value.range.start,
                        character: targetNode.value.range.start.character + 1
                    },
                    {
                        ...targetNode.value.range.end
                    }
                ),
                position
            )
        ) {
            if (value.properties.find((property) => property.name.value === '$value')) {
                // nesting $value is not allowed
                return;
            }
            return createAnnotationRefactoringContext(targetNode, args);
        }
    }
}

function createAnnotationRefactoringContext(
    targetNode: Annotation | RecordProperty,
    { pathToNode, startPosition, position, text, isCompoundAnnotation }: CompletionContextResolverArgs
): AnnotationContainerRefactorContext {
    const { range } = targetNode.value;
    const startLine = range.start.line - startPosition.line;
    const endLine = range.end.line - startPosition.line;
    const startCharacter = startLine === 0 ? range.start.character - startPosition.character : range.start.character;
    const endCharacter = endLine === 0 ? range.end.character - startPosition.character : range.end.character;
    const lines = text.split(/\r\n|\r|\n/).slice(startLine, endLine + 1);
    if (startLine === endLine) {
        lines[0] = lines[0].substring(startCharacter, endCharacter);
    } else {
        lines[0] = lines[0].substr(startCharacter);
        lines[lines.length - 1] = lines[lines.length - 1].substr(0, endCharacter);
    }

    text = lines.join('\n');
    return {
        type: 'refactor',
        kind: 'annotation-container',
        pathToNode,
        position,
        text,
        isCompoundAnnotation,
        hasComma: nodeHasComma(pathToNode, position)
    };
}

const isBeforeColon = (node: AnnotationNode, position: Position): boolean => {
    if (
        (node.type === ANNOTATION_GROUP_TYPE || node.type === ANNOTATION_TYPE || node.type === RECORD_PROPERTY_TYPE) &&
        node.colon
    ) {
        return isBefore(position, node.colon?.range.end);
    }

    return false;
};
