import type { SapUi5 } from './sapUi5';
import type * as ManifestNamespace from '@ui5/manifest/types/manifest';

export { ManifestNamespace };

export * from './sapUiGeneric';
export * from './sapUi5';
export * from './sapOvp';

export interface Manifest extends ManifestNamespace.SAPJSONSchemaForWebApplicationManifestFile {
    'sap.ui5': (SapUi5 & ManifestNamespace.JSONSchemaForSAPUI5Namespace) | undefined;
    'sap.app': SapApp & ManifestNamespace.JSONSchemaForSAPAPPNamespace;
}

export interface ManifestAppDescrVar {
    fileName: string;
    layer: string;
    fileType: 'appdescr_variant';
    reference: string;
    id: string;
    namespace: string;
    version: string;
    content: Array<object>;
}

export interface SapUi {
    technology?: string;
    icons?: { [key: string]: string };
    deviceTypes: { [key: string]: boolean };
    supportedThemes?: Array<string>;
}

export interface SapApp {
    [key: string]: string | object | boolean;
    id?: string;
    type?: string;
    dataSources: SapAppDataSources | SapAppDataSourcesWithOptions;
    offline?: boolean;
    resources?: string;
    sourceTemplate?: SapAppSourceTemplate;
    crossNavigation?: CrossNavigation;
}

export interface SapAppSourceTemplate {
    id: string;
    version: string;
    toolsId?: string;
}

export interface SapAppDataSources {
    [key: string]: ManifestNamespace.DataSource;
    mainService: ManifestNamespace.DataSource;
}

export interface SapAppDataSourcesWithOptions {
    [key: string]: SapAppDataSourceWithOptions;
}

export enum DataSourceType {
    OData = 'OData',
    ODataAnnotation = 'ODataAnnotation'
}

export type SapAppDataSource = ManifestNamespace.DataSource;

export type SapAppDataSourceWithOptions = SapAppDataSource & {
    isLocal: boolean;
    order: number;
    isActive: boolean;
};

export type ODataVersionType = '2.0' | '4.0';

export interface CrossNavigation {
    inbounds: {
        [key: string]: ManifestNamespace.Inbound;
    };
}
