import { promises as fs } from 'fs';
import type { Manifest, SapUi5ResourceModel } from '@sapux/project-spec';
import type { I18nEntry } from '@sap/ux-i18n-properties';
import { loadPropertiesTexts } from '@sap/ux-i18n-properties';
import { getPath, getWebappUri } from './path';
import type { FileUri } from '@sap-ux/odata-annotation-core';

export type I18nUri = string;

const uriMap: Map<FileUri | I18nUri, I18nUri> = new Map();
let fileExists = true;

/**
 * Set i18n uri
 */
export const setI18nUri = (uri: FileUri | I18nUri, i18nUri: I18nUri): void => {
    uriMap.set(uri, i18nUri);
};

/**
 * Get i18n uri from uri map
 */
export const getI18nUri = (uri: FileUri | I18nUri): I18nUri => {
    return uriMap.get(uri);
};

/**
 * It returns false if the i18n file could not be fetched.
 *
 * I18n file can no be fetched for two reasons:
 * a. i18n file does not exist in the project
 * b. i18n entries is missing or the entry mismatches in manifest.json file
 */
export const i18nFileExists = (): boolean => {
    return fileExists;
};

/**
 * Get i18n.properties file content
 *
 * If i18n file can not be fetched, it sets 'fileExists' flag to false
 */
const getI18nContent = async (uri: FileUri): Promise<string> => {
    fileExists = true;
    try {
        const bufferContent = await fs.readFile(uri);
        return bufferContent.toString('utf8');
    } catch (error) {
        fileExists = false;
        console.log(error);
        return '';
    }
};

/**
 * Get i18n entries
 */
export const getI18nEntries = async (uri: FileUri | I18nUri, manifest: Manifest): Promise<I18nEntry[]> => {
    const webAppUri = getWebappUri(uri);
    const i18n = manifest['sap.ui5'].models['@i18n'] as SapUi5ResourceModel;
    const i18nUriInManifest = i18n && i18n.uri;
    let i18nUri = [webAppUri, i18nUriInManifest].join('/');
    // Set i18n uri map. It is needed in quick fix
    setI18nUri(uri, i18nUri);
    i18nUri = getPath(i18nUri);
    const content = await getI18nContent(i18nUri);
    return loadPropertiesTexts(content ?? '', i18nUri);
};
