import type { Position, Range } from 'vscode-languageserver-types';
import type { Context } from '..';

import type { TermOrPropertyMap, StructurePropertyIdentification } from '../types/context';
import type { Element, FileUri } from '@sap-ux/odata-annotation-core';
import {
    positionContained,
    Edm,
    ELEMENT_TYPE,
    isBefore,
    getElementAttribute,
    getElementAttributeValue,
    getAliasInformation,
    getAllNamespacesAndReferences,
    resolveName,
    getSegmentWithoutAlias
} from '@sap-ux/odata-annotation-core';

/**
 * Check if the second parameter is within the first
 * @param a
 * @param b
 */
export function rangeContained(a: Range, b: Range): boolean {
    return isBefore(a.start, b.start, true) && isBefore(b.end, a.end, true);
}

/**
 * Utility function: get files containing a specific structure (nested) property supporting split annotations
 * returns a Set of file uris containing the property and a Map of direct sub properties with the same information
 *
 * @param context
 * @param structureProperty
 * @param findType - find type of resulting structure
 */
export function getSplitStructurePropertySources(
    context: Context,
    structureProperty?: StructurePropertyIdentification,
    findType?: boolean
): { fileUris: Set<FileUri>; nestedProperties: { [propName: string]: Set<FileUri> } } {
    if (!context.supportSplit || !structureProperty || !structureProperty.propertyPathSegments) {
        // no splitting supported (or maybe not anymore e.g. inside collections)
        return { fileUris: null, nestedProperties: null };
    }
    const termQualifier =
        '@' + structureProperty.term + (structureProperty.qualifier ? '#' + structureProperty.qualifier : '');
    let cacheEntry: Set<FileUri> | TermOrPropertyMap =
        context.splitAnnotationKeys &&
        context.splitAnnotationKeys[structureProperty.targetPath] &&
        context.splitAnnotationKeys[structureProperty.targetPath][termQualifier];
    if (cacheEntry) {
        const propNames = findType
            ? [...structureProperty.propertyPathSegments, '$Type']
            : structureProperty.propertyPathSegments;
        propNames.forEach((propertyName) => {
            if (cacheEntry && propertyName && cacheEntry[propertyName]) {
                cacheEntry = cacheEntry[propertyName];
            } else {
                cacheEntry = null;
            }
        });
    }
    if (cacheEntry) {
        const fileUris: Set<FileUri> = cacheEntry['$Self'] || cacheEntry;
        const nestedProperties: { [propName: string]: Set<FileUri> } = {};
        if (!(cacheEntry instanceof Set)) {
            Object.keys(cacheEntry).forEach((propName) => {
                if (propName !== '$Self') {
                    nestedProperties[propName] = cacheEntry[propName]['$Self'] || cacheEntry[propName];
                }
            });
        }
        return { fileUris, nestedProperties };
    } else {
        return { fileUris: null, nestedProperties: null };
    }
}

/**
 * Utility function: get value (as string for '$Type' else as Element) of (nested) structure property supporting split annotations
 *
 * @param context
 * @param structureProperty
 * @param findType - find type ($Type) of resulting structure
 * @param fileUris - set of fileUris containing property
 * @param considerDefaultType - flag indicating if record types defaulted by adapter should be considered
 */
export function getSplitStructurePropertyValue(
    context: Context,
    structureProperty?: StructurePropertyIdentification,
    findType?: boolean,
    fileUris?: Set<FileUri>,
    considerDefaultType = false
): string | Element {
    if (!context.supportSplit || !structureProperty || !structureProperty.propertyPathSegments) {
        // no splitting supported (or maybe not anymore e.g. inside collections)
        return null;
    }
    let resultElement: Element = null;
    let resultType: string = null;
    if (!fileUris) {
        fileUris = getSplitStructurePropertySources(context, structureProperty, findType).fileUris;
    }
    if (!fileUris || fileUris.size === 0) {
        return null;
    }
    for (
        let fileIndex = context.annotationFileSequence.length - 1;
        fileIndex >= 0 && !(resultType || resultElement);
        fileIndex--
    ) {
        if (fileUris.has(context.annotationFileSequence[fileIndex])) {
            const annotationFile = context.fileCache[context.annotationFileSequence[fileIndex]].serviceFile.content;
            const namespaces = getAllNamespacesAndReferences(annotationFile?.namespace, annotationFile.references);
            const aliasInfo = getAliasInformation(namespaces, context.metadata.getNamespaces());
            const propNames = findType
                ? [...structureProperty.propertyPathSegments, '$Type']
                : structureProperty.propertyPathSegments;
            const matchingAnnotations: Element[] = [];
            // collect all matching annotations
            annotationFile.targets
                .filter((targetInFile) => {
                    const targetNameResolved = targetInFile.name
                        .split('/')
                        .map((segment) => {
                            return getSegmentWithoutAlias(aliasInfo, segment);
                        })
                        .join('/');
                    return structureProperty.targetPath === targetNameResolved;
                })
                .forEach((matchingTarget) => {
                    matchingAnnotations.push(
                        ...matchingTarget.terms.filter((termInFile) => {
                            const termName = getElementAttributeValue(termInFile, Edm.Term);
                            const resolvedTermName = resolveName(termName, aliasInfo.aliasMap).qName;
                            const qualifierName = getElementAttributeValue(termInFile, Edm.Qualifier);
                            return (
                                structureProperty.term === resolvedTermName &&
                                (structureProperty.qualifier === qualifierName ||
                                    (!structureProperty.qualifier && !qualifierName))
                            );
                        })
                    );
                });
            // get value from last occurrence in matching annotations
            matchingAnnotations
                .sort((a, b) => (a.range && b.range ? (isBefore(a.range.start, b.range.start, true) ? 1 : -1) : -1))
                .forEach((annotation) => {
                    if (resultType || resultElement) {
                        return;
                    }
                    let currentElement = annotation;
                    propNames.forEach((propName) => {
                        if (currentElement) {
                            // find embedded annotation applied to record
                            if (propName.includes('@')) {
                                if (propName.startsWith('@')) {
                                    // find embedded annotation applied to nested record
                                    currentElement = (currentElement.content || []).find((entry) => {
                                        return entry.type === ELEMENT_TYPE && entry.name === Edm.Record;
                                    }) as Element;
                                }
                                if (currentElement) {
                                    const [term, qualifier] = propName.split('@').pop().split('#');
                                    const embeddedAnnotation: Element = (currentElement.content || [])
                                        .filter((entry) => entry.type === ELEMENT_TYPE && entry.name === Edm.Annotation)
                                        .find((ann: Element) => {
                                            const annTerm = resolveName(
                                                getElementAttributeValue(ann, Edm.Term) ?? '',
                                                aliasInfo.aliasMap
                                            ).qName;
                                            const annQualifier = getElementAttributeValue(ann, Edm.Qualifier) ?? '';
                                            return annTerm === term && annQualifier === (qualifier ?? '');
                                        }) as Element;

                                    currentElement = embeddedAnnotation;
                                }
                            } else {
                                // find Record element
                                const record: Element = (currentElement.content || []).find((entry) => {
                                    return entry.type === ELEMENT_TYPE && entry.name === Edm.Record;
                                }) as Element;
                                if (record) {
                                    // find PropertyValue
                                    if (propName === '$Type') {
                                        currentElement = null;
                                        const typeAttr = getElementAttribute(record, Edm.Type);
                                        resultType =
                                            typeAttr && (typeAttr.valueRange || considerDefaultType)
                                                ? typeAttr.value
                                                : null;
                                        if (resultType) {
                                            resultType = resolveName(resultType, aliasInfo.aliasMap).qName;
                                        }
                                    } else {
                                        currentElement = (record.content || []).find((entry) => {
                                            return (
                                                entry.type === ELEMENT_TYPE &&
                                                entry.name === Edm.PropertyValue &&
                                                propName === getElementAttributeValue(entry, Edm.Property)
                                            );
                                        }) as Element;
                                    }
                                }
                            }
                        }
                    });
                    // ignore elements with only embedded annotations as content (e.g. from @Common.Text.@UI.TextArrangement when asking for @Common.Text)
                    if (
                        !currentElement?.content?.some(
                            (sub) => sub.type === ELEMENT_TYPE && sub.name !== Edm.Annotation
                        )
                    ) {
                        currentElement = null;
                    }
                    if (currentElement) {
                        resultElement = currentElement;
                    }
                });
        }
    }
    return resultType || resultElement;
}

/**
 * Utility function: get type of structured annotation value supporting split annotations
 *    of a (deeply) nested structured annotation value
 * @param context
 * @param structureProperty
 * @param considerDefaultType - flag indicating if record types defaulted by adapter should be considered
 **/
export function getSplitStructureType(
    context: Context,
    structureProperty?: StructurePropertyIdentification,
    considerDefaultType = false
): string {
    return getSplitStructurePropertyValue(context, structureProperty, true, null, considerDefaultType) as string;
}

/**
 * Utility function: find referenced metadata element based on the position of its definition
 * @param context
 * @param uri
 * @param position
 * @returns
 */
export function findReferencedMdElementByPosition(context: Context, uri: string, position: Position): string {
    let mdPath = '';
    // find first referenced metadata element the definition of which covers location
    for (const namespaces of Object.keys(context.metadataReferenceLocations)) {
        for (const referencedMdPath of Object.keys(context.metadataReferenceLocations[namespaces])) {
            const locations = context.metadata.getMetadataElementLocations(referencedMdPath);
            if (locations.some((location) => location.uri === uri && positionContained(location.range, position))) {
                mdPath = referencedMdPath;
                break;
            }
        }
        if (!mdPath) {
            break;
        }
    }
    // try to find child element containing cursor position
    const childMdELement = (context.metadata.getMetadataElement(mdPath)?.content || []).find(
        (mdElement) => uri === mdElement.location?.uri && positionContained(mdElement.location.range, position)
    );
    return childMdELement?.path || mdPath;
}
