import { Range } from 'vscode-languageserver';

import {
    RECORD_TYPE,
    RECORD_PROPERTY_TYPE,
    PATH_TYPE,
    STRING_LITERAL_TYPE,
    BOOLEAN_TYPE,
    NUMBER_LITERAL_TYPE,
    ENUM_TYPE,
    EMPTY_VALUE_TYPE,
    COLLECTION_TYPE
} from '@sap-ux/cds-annotation-parser';
import { positionContained } from '@sap-ux/odata-annotation-core';
import { nodeHasComma } from '../../../utils/hasComma';

import type {
    BooleanValueContext,
    CollectionValueContext,
    CompletionContextResolverArgs,
    EmptyValueContext,
    EnumValueContext,
    NumberValueContext,
    PathValueContext,
    PropertyNameContext,
    StringValueContext,
    ValueCompletionContext
} from '../types';
import { findNodeWithMatchingPosition } from '../utils';

export function recordPropertyNameResolver({
    pathToNode,
    position
}: CompletionContextResolverArgs): PropertyNameContext | undefined {
    if (pathToNode.length < 3) {
        return;
    }
    const [record, property, name] = pathToNode.slice(-3);
    if (record.type === RECORD_TYPE && property.type === RECORD_PROPERTY_TYPE && name.type === PATH_TYPE) {
        if (property.name !== name) {
            return;
        }
        if (name.segments.length === 1) {
            return {
                type: 'key',
                kind: 'property-name',
                pathToNode,
                proposedReplacementRange: name.range,
                isQuoted: (name.segments[0].quoted && positionContained(name.segments[0].range, position)) ?? false,
                flattened: false,
                propertyName: name.segments[0].value
            };
        }
        // flattened property names
        const segment = findNodeWithMatchingPosition(name.segments, position);
        return {
            type: 'key',
            kind: 'property-name',
            pathToNode,
            proposedReplacementRange: segment?.range,
            isQuoted: segment?.quoted ?? false,
            flattened: name.segments.length > 1,
            propertyName: segment.value
        };
    }
}

export function recordPropertyValueResolver({
    pathToNode,
    position
}: CompletionContextResolverArgs):
    | PathValueContext
    | StringValueContext
    | BooleanValueContext
    | NumberValueContext
    | EnumValueContext
    | EmptyValueContext
    | CollectionValueContext
    | undefined {
    if (pathToNode.length < 3) {
        return;
    }
    const [record, property, value] = pathToNode.slice(-3);
    if (record.type === RECORD_TYPE && property.type === RECORD_PROPERTY_TYPE && property.value === value) {
        const hasComma = nodeHasComma(pathToNode, position);

        if (value.type === PATH_TYPE) {
            const context: PathValueContext = {
                type: 'value',
                kind: 'property',
                valueType: PATH_TYPE,
                pathToNode,
                proposedReplacementRange: value.range,
                position,
                hasComma
            };

            if (value.segments.length === 1) {
                return context;
            }
            const segment = findNodeWithMatchingPosition(value.segments, position);
            if (segment) {
                return {
                    type: 'value',
                    kind: 'property',
                    valueType: PATH_TYPE,
                    pathToNode,
                    proposedReplacementRange: segment.range,
                    position,
                    hasComma
                };
            }
            const quoted = value.segments.reduce((acc, segment) => acc || segment.quoted === true, false);
            if (quoted) {
                context.cursorInDelimiter = true;
                return context;
            }
        }
        if (
            value.type === STRING_LITERAL_TYPE ||
            value.type === BOOLEAN_TYPE ||
            value.type === NUMBER_LITERAL_TYPE ||
            value.type === ENUM_TYPE ||
            value.type === EMPTY_VALUE_TYPE
        ) {
            return {
                type: 'value',
                kind: 'property',
                valueType: value.type,
                pathToNode,
                proposedReplacementRange:
                    value.type === EMPTY_VALUE_TYPE ? Range.create(position, position) : value.range,
                position,
                hasComma
            };
        }
        if (value.type === COLLECTION_TYPE) {
            return {
                type: 'container',
                kind: 'collection',
                pathToNode,
                position,
                hasComma,
                proposedReplacementRange: Range.create(position, position)
            };
        }
    }

    if (property.type === RECORD_TYPE && value.type === RECORD_PROPERTY_TYPE && value.name.value === '$value') {
        // $value: | context, pathToNode doesn't contain value node
        const hasComma = nodeHasComma(pathToNode, position);
        return {
            type: 'value',
            kind: 'property',
            valueType: EMPTY_VALUE_TYPE,
            pathToNode,
            proposedReplacementRange: value.value?.range || Range.create(position, position),
            position,
            hasComma
        };
    }
}

export function collectionValueResolver({
    pathToNode,
    position,
    targetNode
}: CompletionContextResolverArgs): ValueCompletionContext | undefined {
    if (pathToNode.length < 2) {
        return;
    }
    const parent = pathToNode.slice(-2)[0];
    if (parent?.type === COLLECTION_TYPE) {
        const hasComma = nodeHasComma(pathToNode, position);
        if (targetNode.type === PATH_TYPE) {
            const context: PathValueContext = {
                type: 'value',
                kind: 'collection',
                valueType: PATH_TYPE,
                pathToNode,
                proposedReplacementRange: targetNode.range,
                position,
                hasComma
            };
            if (targetNode.segments.length === 1) {
                return context;
            }
            const segment = findNodeWithMatchingPosition(targetNode.segments, position);
            if (segment) {
                context.proposedReplacementRange = segment.range;
                return context;
            }
            const quoted = targetNode.segments.reduce((acc, segment) => acc || segment.quoted === true, false);
            if (quoted) {
                context.cursorInDelimiter = true;
                return context;
            }
        }
        // TODO: better kind ?
        if (targetNode.type === STRING_LITERAL_TYPE) {
            const proposedReplacementRange =
                targetNode.openToken && targetNode.closeToken
                    ? Range.create(targetNode.openToken.range.end, targetNode.closeToken.range.start)
                    : targetNode.range;
            return {
                type: 'value',
                kind: 'collection',
                pathToNode,
                valueType: targetNode.type,
                proposedReplacementRange,
                position,
                hasComma
            };
        }
        if (
            targetNode.type === BOOLEAN_TYPE ||
            targetNode.type === NUMBER_LITERAL_TYPE ||
            targetNode.type === ENUM_TYPE ||
            targetNode.type === EMPTY_VALUE_TYPE
        ) {
            return {
                type: 'value',
                kind: 'collection',
                pathToNode,
                valueType: targetNode.type,
                proposedReplacementRange: targetNode.range,
                position,
                hasComma
            };
        }
    }
}
