import type { CompletionItem } from 'vscode-languageserver';
import { cdsLogger } from '../../log';

import type {
    CompletionContext,
    CompletionHandler,
    CompletionHandlerArgs,
    CompletionItemAdapter,
    CompletionItemAdapterParams,
    CompletionItemAdapterWithGate,
    CompletionItemMapperParams,
    CompletionItemMapperWithGate,
    CompletionItemProvider,
    MonolithicCompletionHandler
} from './types';

/**
 * Provides completion items based on context and handlers
 * @param handlers Completion handlers that will be used to generate completion items
 * @param context Context for which completion items is requested
 * @param args Arguments that will be passed to each of the handlers
 * @param globalAdapters A list of adapters that will be run (after handler adapters) for all completion items that needs to be adapted.
 */
export function runHandlers(
    handlers: CompletionHandler[],
    context: CompletionContext,
    args: CompletionHandlerArgs,
    globalAdapters: (CompletionItemAdapter | CompletionItemAdapterWithGate)[] = []
): CompletionItem[] {
    const preparedGlobalAdapters: CompletionItemAdapterWithGate[] = prepareAdapters(globalAdapters);
    return handlers.reduce(
        (acc, handler) => {
            switch (handler.type) {
                case 'modular': {
                    const { gate, providers, mappers, adapters, name } = handler;
                    return gate(context)
                        ? [
                              ...acc,
                              ...runModularHandler(
                                  {
                                      name,
                                      providers,
                                      mappers: mappers.map((mapper) =>
                                          typeof mapper === 'function' ? { gate: (): boolean => true, mapper } : mapper
                                      ),
                                      adapters: prepareAdapters(adapters)
                                  },
                                  preparedGlobalAdapters,
                                  context,
                                  args
                              )
                          ]
                        : acc;
                }
                case 'monolithic': {
                    const { gate } = handler;
                    return gate(context)
                        ? [...acc, ...runMonolithicHandler(handler, preparedGlobalAdapters, context, args)]
                        : acc;
                }
            }
            return acc;
        },

        []
    );
}

function prepareAdapters(
    adapters: (CompletionItemAdapter | CompletionItemAdapterWithGate)[]
): CompletionItemAdapterWithGate[] {
    return adapters.map((adapter) =>
        typeof adapter === 'function' ? { gate: (): boolean => true, adapter } : adapter
    );
}

function runMonolithicHandler(
    { providers, adapter, name }: MonolithicCompletionHandler,
    globalAdapters: CompletionItemAdapterWithGate[],
    context: CompletionContext,
    args: CompletionHandlerArgs
): CompletionItem[] {
    cdsLogger.info(`Running annotation completion handler: '${name}'`);
    return providers.reduce((acc, provider) => {
        const { completionItems, itemsForAdapter } = provider(context, args);
        const adapterResult = adapter(context, itemsForAdapter);
        return [...acc, ...completionItems, ...runMappersAndAdapters([], globalAdapters, context, args, adapterResult)];
    }, []);
}

function runModularHandler(
    {
        providers,
        mappers,
        adapters,
        name
    }: {
        name: string;
        providers: CompletionItemProvider[];
        mappers: CompletionItemMapperWithGate[];
        adapters: CompletionItemAdapterWithGate[];
    },
    globalAdapters: CompletionItemAdapterWithGate[],
    context: CompletionContext,
    args: CompletionHandlerArgs
): CompletionItem[] {
    cdsLogger.info(`Running annotation completion handler: '${name}'`);
    return providers.reduce((acc, provider) => {
        const { completionItems, itemsForAdapter } = provider(context, args);
        return [
            ...acc,
            ...completionItems,
            ...runMappersAndAdapters(mappers, [...adapters, ...globalAdapters], context, args, itemsForAdapter)
        ];
    }, []);
}

function runMappersAndAdapters(
    mappers: CompletionItemMapperWithGate[],
    adapters: CompletionItemAdapterWithGate[],
    context: CompletionContext,
    args: CompletionHandlerArgs,
    items: CompletionItem[]
): CompletionItem[] {
    return items.reduce((acc, item) => {
        const mappedItems = runMappers(mappers, adapters, context, args, item);
        return [...acc, ...mappedItems];
    }, []);
}
function runAdapters(
    adapters: CompletionItemAdapterWithGate[],
    context: CompletionContext,
    args: CompletionHandlerArgs,
    item: CompletionItem
): CompletionItem | undefined {
    let adaptedItem = item;
    for (const { gate, adapter } of adapters) {
        const params: CompletionItemAdapterParams = { context, originalItem: item, lastItem: adaptedItem, args };
        if (gate(params)) {
            adaptedItem = adapter(params);
        }
    }
    return adaptedItem;
}
function runMappers(
    mappers: CompletionItemMapperWithGate[],
    adapters: CompletionItemAdapterWithGate[],
    context: CompletionContext,
    args: CompletionHandlerArgs,
    item: CompletionItem
): CompletionItem[] {
    let mapperCount = 0;
    const mappedItems = mappers.reduce((acc, { gate, mapper }) => {
        const params: CompletionItemMapperParams = { context, item, args };
        if (gate(params)) {
            const { completionItems, itemsForAdapter } = mapper(params);
            mapperCount++;
            return [...acc, ...completionItems, ...runMappersAndAdapters([], adapters, context, args, itemsForAdapter)];
        }
        return acc;
    }, []);

    if (mapperCount) {
        return mappedItems;
    }
    const adaptedItem = runAdapters(adapters, context, args, item);
    if (adaptedItem) {
        return [adaptedItem];
    }
    return [];
}
