import Uri from 'vscode-uri';
import { join } from 'path';
import { DirName } from '@sapux/project-spec';
import type { FileUri } from '@sap-ux/odata-annotation-core';

/**
 * Converts uri to path
 *
 * @param uri - Uri in internal format: file:\<path>
 * @returns     Path: \<path>
 */
export const getPath = function (uri): string {
    return Uri.parse(uri).fsPath;
};

/**
 * Returns the uri of the corresponding webapp folder for a given file uri
 *
 * The webapp folder contains the manifest.json file
 *
 * @param fileUri - Uri of file in current project (i.e. file:///Users/someUser/project/webapp/annotations/annotation1.xml)
 * @returns         Uri of webapp folder (i.e. file:///Users/someUser/project/webapp)
 */
export const getWebappUri = function (fileUri: FileUri): string {
    const path = getPath(fileUri);
    const pathSegments = path.split(DirName.Webapp);
    pathSegments.pop();
    const webappUri = join(...pathSegments, DirName.Webapp);
    return Uri.file(webappUri).toString();
};

/**
 * Returns uri build from webapp folder uri and relative path
 *
 * @param webappUri    - Uri of the webapp folder file:///<path1>
 * @param relativePath - Path relative to webapp uri /path/
 * @returns            - Uri internal format file:///<path1>/<path2>
 */
export const getUri = function (webappUri: FileUri, relativePath: string): FileUri {
    const path = getPath(webappUri);
    const result = join(path, relativePath);
    return Uri.file(result).toString();
};
