function checkLanguageDependentString(
    valueHandlingContext: ValueHandlingContext,
    value: TextValue | AttributeValue,
    multilineType: MultilineType,
    range: Range,
    messages: Diagnostic[]
): Diagnostic[] {
    const missingKey = 'missing-i18n-key';
    const i18nData = valueHandlingContext.context.i18n;
    const fileNotExits = i18nData && !i18nData.length && !i18nFileExists();
    if (value.indexOf('{@i18n>') !== -1 || value.indexOf('{@i18n&gt;') !== -1) {
        const key = extractI18nKey(value);
        const i18nEntries = i18nData.filter((item) => item.key.value === key);
        if (!i18nEntries.length) {
            const message = fileNotExits
                ? i18n.t('Text_key_is_not_available')
                : i18n.t('Text_key_is_not_available_in_i18Properties_file');
            const msg: MissingI18nKeyDiagnostic = {
                message,
                severity: DiagnosticSeverity.Warning,
                data: {
                    value: value
                },
                rule: missingKey,
                range
            };
            if (multilineType) {
                msg.data.multilineType = multilineType;
            }
            messages.push(msg);
        }
    } else if (value.trim().length) {
        // translatable text exits
        const i18nEntries = i18nData.filter((item) => item.value.value === value);
        if (i18nEntries.length) {
            const key = i18nEntries[0].key.value;
            const substitute = `{@i18n>${i18nEntries[0].key.value}}`;
            let message = i18n.t(
                'Text_key_0_for_value_1_is_available_in_i18nProperties_file_Consider_substituting_1_by_2',
                {
                    key: key,
                    value: value,
                    substitute: substitute
                }
            );
            message = message.replace('&gt;', '>');
            const msg: MissingI18nKeyDiagnostic = {
                message,
                severity: DiagnosticSeverity.Warning,
                data: {
                    value: value
                },
                rule: missingKey,
                range
            };
            if (multilineType) {
                msg.data.multilineType = multilineType;
            }
            messages.push(msg);
        } else {
            // simple string
            const message = fileNotExits
                ? i18n.t('Text_key_0_is_not_available', {
                      value: value
                  })
                : i18n.t('Text_key_or_value_for_0_is_not_available_in_i18nProperties_file', {
                      value: value
                  });
            const msg: MissingI18nKeyDiagnostic = {
                message,
                severity: DiagnosticSeverity.Warning,
                data: {
                    value: value
                },
                rule: missingKey,
                range
            };
            if (multilineType) {
                msg.data.multilineType = multilineType;
            }
            messages.push(msg);
        }
    }
    return messages;
}

function checkIfValid(
    valueHandlingContext: ValueHandlingContext,
    typeName: string,
    expression: string,
    value: string,
    type: ValueType,
    range: Range,
    messages: Diagnostic[]
): Diagnostic[] {
    const primitiveType = getPrimitiveType(typeName as PrimitiveType | 'Edm.PrimitiveType', expression);
    if (!Validation.isValid(primitiveType, value, type.facets)) {
        let message = i18n.t('Invalid_value_for_primitive_type_0', {
            type: typeName
        });
        if (type.facets && type.facets.precision !== undefined) {
            message = i18n.t(
                'Value_0_not_allowed_due_to_restrictions_defined_in_vocabulary_Provide_a_value_with_precision_1',
                {
                    value: value,
                    precision: String(type.facets.precision)
                }
            );
        }
        if (typeName !== type.name) {
            message = `${message} (${toAliasQualifiedName(type.name, valueHandlingContext.aliasInfo)})`;
        }
        const msg: InvalidPrimitiveType = {
            message: message,
            severity: DiagnosticSeverity.Error,
            range: range,
            rule: INVALID_PRIMITIVE_TYPE,
            data: {
                name: typeName
            }
        };
        messages.push(msg);
    }
    return messages;
}

export function checkPrimitiveValue(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    expression: string,
    value: TextValue | AttributeValue,
    range: Range,
    multilineType?: MultilineType
): Diagnostic[] {
    let messages: Diagnostic[] = [];
    const vocabularyType = getVocabularyType(valueHandlingContext.context, type.name);
    const typeName = vocabularyType
        ? getBuiltInTypeViaUnderlyingType(valueHandlingContext.context, vocabularyType)
        : type.name;

    const primitiveValueExpression = primitiveValueConstantExpressionMap[expression];
    if (
        primitiveTypeMap[typeName] &&
        primitiveValueExpression.supportedTypes &&
        !primitiveValueExpression.supportedTypes[typeName]
    ) {
        const aliasedName = toAliasQualifiedName(type.name, valueHandlingContext.aliasInfo);
        const underlyingType = i18n.t('underlying_type_0', {
            type: typeName
        });
        const underlyingTypeName = typeName !== type.name ? underlyingType : '';
        const message = i18n.t('0_cannot_provide_value_for_type_1_2', {
            expression: expression,
            aliasedName: aliasedName,
            underlyingType: underlyingTypeName
        });
        messages.push({
            message: message,
            severity: DiagnosticSeverity.Error,
            range: range
        });
    }
    if (expression === Edm.String && type.constraints && type.constraints.isLanguageDependent) {
        messages = checkLanguageDependentString(valueHandlingContext, value, multilineType, range, messages);
    } else if (type.constraints && type.constraints.allowedValues) {
        value = replaceAliasByName(value, valueHandlingContext.aliasInfo.aliasMap);
        const isAllowed = isAllowedValue(type, value);
        if (!isAllowed) {
            const message = i18n.t('Value_not_allowed_Use_the_code_completion_to_select_one_of_the_allowed_values');
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Warning,
                range: range
            });
        }
    } else {
        checkIfValid(valueHandlingContext, typeName, expression, value, type, range, messages);
    }
    return messages;
}

export function replaceAliasByName(value: TextValue, aliasMap: AliasMap): TextValue {
    if (value.includes('(') && value.includes(')')) {
        // value is action/function with signature -> replace aliases in action/function name and parameter types
        // OR "Collection(myService.EntityType)"
        const openingBracketIndex = value.indexOf('(');
        const closingBracketIndex = value.lastIndexOf(')');
        const actionFunctionName = value.substring(0, openingBracketIndex);
        const signature = value.substring(openingBracketIndex + 1, closingBracketIndex);
        const trailingString = value.substring(closingBracketIndex + 1) || '';
        const parameters = signature.split(',').map((par) => par.trim());
        const parametersNoAlias = parameters.map((par) => replaceAliasByName(par, aliasMap));
        value = `${replaceAliasByName(actionFunctionName, aliasMap)}(${parametersNoAlias.join(',')})${trailingString}`;
    } else if (value.includes('.')) {
        // value is a qualified name
        const [nameQualifier, name] = value.split('.');
        const namespace = aliasMap[nameQualifier];
        if (namespace) {
            // replace alias by namespace
            value = `${namespace}.${name}`;
        }
    }
    return value;
}

export function isAllowedValue(type: ValueType, value: TextValue | AttributeValue): boolean {
    const validConstraintValue = type.constraints.allowedValues.filter((constraint) => {
        return constraint.value.toString() === value.toString();
    });

    return validConstraintValue.length > 0;
}

export function getPrimitiveType(type: PrimitiveType | 'Edm.PrimitiveType', constantExpression: string): PrimitiveType {
    const primitiveTypes = [
        'Edm.Binary',
        'Edm.Boolean',
        'Edm.Byte',
        'Edm.Date',
        'Edm.DateTimeOffset',
        'Edm.Decimal',
        'Edm.Double',
        'Edm.Duration',
        'Edm.Guid',
        'Edm.Int16',
        'Edm.Int32',
        'Edm.Int64',
        'Edm.SByte',
        'Edm.Single',
        'Edm.Stream',
        'Edm.String',
        'Edm.TimeOfDay'
    ];
    let result: PrimitiveType;

    if (primitiveTypes.indexOf(type) >= 0) {
        result = type as PrimitiveType;
    } else if (type === 'Edm.PrimitiveType') {
        switch (constantExpression) {
            case 'Bool':
                result = 'Edm.Boolean';
                break;
            case 'Float':
                result = 'Edm.Decimal';
                break;
            case 'Int':
                result = 'Edm.Int64';
                break;
            default:
                result = `Edm.${constantExpression}` as PrimitiveType;
        }
    }

    return result;
}

export function handleNonStructuredValue(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    vocabularyType: VocabularyObject,
    ccStrings: { [key: string]: CompletionItemCategory }
): void {
    // options to provide value for non structured types
    if (vocabularyType && vocabularyType.kind === Edm.EnumType) {
        ccStrings[Edm.EnumMember] = CompletionItemCategory.ValueElement;
        ccStrings['@' + Edm.EnumMember] = CompletionItemCategory.ValueElement;
    }
    let resolvedTypeName = type.name;
    if (vocabularyType) {
        resolvedTypeName =
            getBuiltInTypeViaUnderlyingType(valueHandlingContext.context, vocabularyType) || resolvedTypeName;
    }
    const primitiveTypeProp = primitiveTypeMap[resolvedTypeName] || null;
    if (primitiveTypeProp && primitiveTypeProp.constantExpressionName) {
        ccStrings[primitiveTypeProp.constantExpressionName] = CompletionItemCategory.ValueElement;
        ccStrings['@' + primitiveTypeProp.constantExpressionName] = CompletionItemCategory.ValueElement;
    }
    addDynamicExpressionsWithType(Object.assign({}, type, { name: resolvedTypeName }), ccStrings);
    if (getFunctionNamesForValueType({ name: resolvedTypeName }, valueHandlingContext).length) {
        ccStrings[Edm.Apply] = CompletionItemCategory.Apply;
    }
}

export function extractProperty(pathTargetInElement: PathTargetInElement, element: Element): Property {
    let propName = '';
    let propValue: string | Element = null;
    let propIsStringValue = false;
    let propValueRange: Range = null;
    let propNameRange: Range = null;
    if (pathTargetInElement.isAttributeValue) {
        propName = pathTargetInElement.attribute.name;
        propValue = pathTargetInElement.attribute.value;
        propIsStringValue = true;
        propValueRange = pathTargetInElement.attribute.valueRange;
        propNameRange = pathTargetInElement.attribute.nameRange;
    } else if (pathTargetInElement.isElementSubNode) {
        propName = pathTargetInElement.element.name;
        propValue = pathTargetInElement.element;
        propValueRange = pathTargetInElement.element.range;
        propNameRange = pathTargetInElement.element.nameRange;
    } else if (pathTargetInElement.isTextSubNode) {
        propName = element.name;
        propValue = pathTargetInElement.textNode.text;
        propIsStringValue = true;
        propValueRange = pathTargetInElement.textNode.range;
    } else if (pathTargetInElement.isName) {
        propName = element.name;
        propValue = element;
        propValueRange = element.range;
        propNameRange = element.nameRange;
    }
    return {
        name: propName,
        value: propValue,
        isStringValue: propIsStringValue,
        valueRange: propValueRange,
        nameRange: propNameRange
    };
}

export function handleAllowedValueConstraint(type: ValueType, valueRange: Range): CompletionItem[] {
    const compItems: CompletionItem[] = [];
    type.constraints.allowedValues.forEach((allowedValue) => {
        if (typeof allowedValue === 'object' && allowedValue.value['kind'] === ACTION_FUNCTION_NAME_OBJECT_TYPE) {
            if (allowedValue.value.forCompletion) {
                const value: ActionFunctionNameValue = allowedValue.value;

                const docLines: string[] = [`**Namespace:** ${value.namespace}\n`];
                if (value.entityContainer) {
                    docLines.push(`**Entity Container:** ${value.entityContainer}\n`);
                }
                docLines.push(`**Name:** ${value.name}\n`);

                docLines.push(`**Kind:** ${value.targetKind}\n`);

                const text = `${value.name}${
                    value.targetKind === Edm.ActionImport || value.targetKind === Edm.FunctionImport
                        ? ' (' + value.targetKind + ')'
                        : ''
                }`;

                compItems.push({
                    insertText: value.toString(),
                    filterText: value.toString(),
                    name: text,
                    text,
                    category: CompletionItemCategory.Action,
                    affectedRange: valueRange,
                    documentation: {
                        kind: MarkupKind.Markdown,
                        value: docLines.join('\n')
                    }
                });
            }
        } else {
            const docLines: string[] = [`**Value:** ${allowedValue.value}\n`];
            docLines.push(`**Description:** ${allowedValue.description}\n`);
            if (allowedValue.longDescription) {
                docLines.push(`**Long Description:** ${allowedValue.longDescription}\n`);
            }
            compItems.push({
                insertText: `${allowedValue.value}`,
                name: `${allowedValue.value}`,
                text: `${allowedValue.value}`,
                documentation: {
                    kind: MarkupKind.Markdown,
                    value: docLines.join('\n')
                }
            });
        }
    });
    return compItems;
}

/**
 * check attribute value
 * @param valueHandlingContext
 * @param attribute
 * @param type
 */
export function checkAttributeValue(
    valueHandlingContext: ValueHandlingContext,
    attribute: Attribute,
    type: ValueType
): { messages: Diagnostic[]; providesValue: boolean } {
    const nonValueProvidingAttributes = {
        Target: true,
        Term: true,
        Qualifier: true,
        Type: true,
        Property: true,
        Function: true,
        Name: true
    };
    let messages: Diagnostic[] = [];
    let providesValue = false;
    // Check constraint
    if (primitiveValueConstantExpressionMap[attribute.name]) {
        // check primitive type value
        providesValue = true;
        messages = checkPrimitiveValue(
            valueHandlingContext,
            type,
            attribute.name,
            attribute.value,
            attribute.valueRange
        );
    } else if (attribute.name === Edm.EnumMember) {
        // check enum member value
        providesValue = true;
        messages = handleEnumValue(valueHandlingContext, type, attribute.value, attribute.valueRange) as Diagnostic[];
    } else if (pathExpressionMap[attribute.name]) {
        // check path expression value
        providesValue = true;
        const property = {
            name: attribute.name,
            nameRange: attribute.nameRange,
            value: attribute.value,
            isStringValue: true,
            valueRange: attribute.valueRange
        };
        messages = checkPathExpressions(valueHandlingContext, type, property);
    } else if (nonValueProvidingAttributes[attribute.name]) {
        // non value providing attributes
        if (attribute.name === 'Type') {
            // no need to check - checked already for deriving record type
        } else if (attribute.name === Edm.Property) {
            // no need to check - property attribute is checked for record already
        } else if (attribute.name === Edm.Function) {
            // check function name is valid for expected value type
            messages = checkFunctionNameForValueType(type, attribute, valueHandlingContext);
        } else if (attribute.name === 'Name') {
            // check labeled element name is valid
            messages = checkLabeledElementName(valueHandlingContext, attribute);
        } else {
            // Target/Term/Qualifier: already checked outside valueHandling
        }
    }
    return { messages, providesValue };
}

/**
 * check that element contains only single text node, return it
 * - empty text nodes are ignored
 * - exception: String elements containing only single text node
 * - (needed to check string values having list of allowed values e.g. @Common.ValueList/CollectionPath)
 *
 * @param element
 * @param messages - add messages for any attributes/sub element/additional text nodes
 */
export function checkSingleTextNode(element: Element, messages: Diagnostic[]): TextNode {
    let firstTextNode: TextNode = null;
    Object.keys(element.attributes || {}).forEach((attributeName) => {
        const attribute = element.attributes[attributeName];
        const message = i18n.t('Attribute_not_allowed_here_0', {
            attribute: attribute.name
        });
        messages.push({
            message: message,
            severity: DiagnosticSeverity.Error,
            range: attribute.nameRange,
            rule: 'attribute-not-allowed-here',
            data: {
                name: attribute.name
            }
        });
    });
    const considerEmptyTextNodes =
        element.name === Edm.String && element.content.filter((entry) => entry.type === TEXT_TYPE).length === 1;
    element.content.forEach((elementChild) => {
        if (elementChild.type === ELEMENT_TYPE) {
            const subElement = elementChild;
            const message = i18n.t('Element_0_not_allowed_below_element_1', {
                element0: subElement.name,
                element1: element.name
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: subElement.nameRange
            });
        } else if (elementChild.type === TEXT_TYPE) {
            const textNode = elementChild;
            if (considerEmptyTextNodes || (textNode.text && textNode.text.trim())) {
                if (!firstTextNode) {
                    firstTextNode = textNode;
                } else {
                    const message = i18n.t('Additional_text_nodes_ignored_in_element_0', {
                        element: element.name
                    });
                    messages.push({
                        message: message,
                        severity: DiagnosticSeverity.Warning,
                        range: textNode.range
                    });
                }
            }
        }
    });
    return firstTextNode;
}

export function hasUnsupportedDynamicExpression(element: Element, valueHandlingContext: ValueHandlingContext): boolean {
    if (valueHandlingContext.context.supportSplit) {
        unsupportedDynamicExpressionMap['EdmJson'] = {
            $ResultType: 'void'
        };
    }

    // check sub node names and collect values for allowed sub nodes
    let elementNotSupported = false;
    (element.content || []).forEach((node) => {
        if (node.type === ELEMENT_TYPE) {
            const childElement: Element = node;
            if (
                unsupportedDynamicExpressionMap[childElement.name] ||
                (childElement.name === Edm.Apply && !isSupportedFunction(childElement))
            ) {
                elementNotSupported = true;
            }
        }
    });
    return elementNotSupported;
}

export function convertType(type: ValueType, valueHandlingContext: ValueHandlingContext): string {
    const vocabularyType = getVocabularyType(valueHandlingContext.context, type.name);
    const buildInType = vocabularyType
        ? getBuiltInTypeViaUnderlyingType(valueHandlingContext.context, vocabularyType)
        : '';

    let result = buildInType || type.name;
    if (type.asCollection) {
        result = 'Collection(' + result + ')';
    }
    return result;
}
