function isAbstract(context: Context, type: FullyQualifiedName): boolean {
    const complexType: ComplexType = context.vocabularies.getType(type) as ComplexType;
    return !!(complexType && complexType.isAbstract);
}

function isParentType(context: Context, parentType: QualifiedName, type: FullyQualifiedName): boolean {
    let isReallyParentType = false;
    let parentTypeTest = type;
    do {
        isReallyParentType = parentTypeTest === parentType;
        if (!isReallyParentType) {
            const vocabularyType = getVocabularyType(context, parentTypeTest);
            parentTypeTest = vocabularyType && vocabularyType.kind === Edm.ComplexType && vocabularyType.baseType;
        }
    } while (!isReallyParentType && parentTypeTest);
    return isReallyParentType;
}

/**
 * Returns true if vocabulary restriction is NOT defined or the element type exist in the vocabulary restriction
 * @param constraints - vocabulary constraints
 * @param typeName - fully qualified name of type
 */
function isConstraintApplicable(constraints: Constraints, typeName: string): boolean {
    if (constraints && constraints.derivedTypeConstraints) {
        return constraints.derivedTypeConstraints.includes(typeName);
    } else {
        return true;
    }
}

/**
 * Add the derived type in to complex type
 * @param derivedTypeName - derived type name
 * @param typeMap - map of types
 */
function addComplexType(
    derivedTypeName: string,
    typeMap: { [namespace: string]: { [typeName: string]: boolean } }
): void {
    const resolved = resolveName(derivedTypeName);
    typeMap = typeMap || {};
    typeMap[resolved.namespace] = typeMap[resolved.namespace] || {};
    typeMap[resolved.namespace][resolved.name] = true;
}

export function getPossibleTypes(
    context: Context,
    type: ValueType,
    typeMap: { [namespace: string]: { [typeName: string]: boolean } }
): void {
    const derivedTypeNames = context.vocabularies.getDerivedTypeNames(type.name);
    typeMap = typeMap || {};
    derivedTypeNames.forEach((derivedTypeName) => {
        if (isConstraintApplicable(type.constraints, derivedTypeName)) {
            addComplexType(derivedTypeName, typeMap);
        }
    });
}

function completeRecordType(context: Context, type: ValueType, aliasInfo: AliasInformation): CompletionItem[] {
    const completionItems: CompletionItem[] = [];
    const typeMap: { [namespace: string]: { [typeName: string]: boolean } } = {};
    let resolvedTypeName: ResolvedName;
    if (isAbstract(context, type.name)) {
        getPossibleTypes(context, type, typeMap);
    } else {
        resolvedTypeName = resolveName(type.name);
        typeMap[resolvedTypeName.namespace] = {};
        typeMap[resolvedTypeName.namespace][resolvedTypeName.name] = true;
    }
    Object.keys(typeMap).forEach((namespace) => {
        Object.keys(typeMap[namespace]).forEach((item) => {
            const fullyQualifiedName = `${namespace}.${item}`;
            const aliasedName = toAliasQualifiedName(fullyQualifiedName, aliasInfo);
            // by default show alias
            const textName = aliasedName;
            const name = textName;
            const text = textName;
            const id = fullyQualifiedName;
            const category = CompletionItemCategory.ComplexType;
            const completionItem = { name, text, id, category };
            completionItems.push(completionItem);
        });
    });

    return completionItems;
}

function checkRecordType(
    context: Context,
    type: ValueType,
    property: Element,
    aliasInfo: AliasInformation
): Diagnostic[] {
    const messages = [];
    let bTypeFound: boolean;
    let bPrefixFound: boolean;
    const resolvedTypeName: ResolvedName = resolveName(type.name);
    const typeMap: { [namespace: string]: { [typeName: string]: boolean } } = {};
    const typeName = type.name.split('.').pop();

    if (!getElementAttribute(property, 'Type')) {
        if (isAbstract(context, type.name)) {
            const message = i18n.t(
                'Does_not_conform_to_OData_Specification_Type_attribute_for_record_element_is_missing'
            );
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: property.nameRange
            });
        }
    } else {
        const userDefinedType = resolveName(property.attributes.Type.value, aliasInfo.aliasMap);
        const aPrefixes = getNamespaceAndAlias(userDefinedType.namespace, aliasInfo, context);
        if (isAbstract(context, type.name)) {
            getPossibleTypes(context, type, typeMap);
            const aDerivedTypes = Object.keys(typeMap[resolvedTypeName.namespace]);
            bPrefixFound = aPrefixes.includes(userDefinedType.namespace);
            bTypeFound = aDerivedTypes.includes(userDefinedType.name);
        } else {
            bPrefixFound = aPrefixes.includes(userDefinedType.namespace);
            bTypeFound = [typeName].includes(userDefinedType.name);
        }

        if (!bPrefixFound || !bTypeFound) {
            const message = i18n.t('Invalid_type_0', {
                type: property.attributes.Type.value
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: property.attributes.Type.valueRange
            });
        }
    }

    return messages;
}

export function hoverRecordType(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement
): Hover {
    const aliasInfo = valueHandlingContext.aliasInfo;
    const aliasMap = aliasInfo.aliasMap;
    const namespace = resolveName(pathTargetInElement.attribute.value, aliasMap).namespace;
    const type = pathTargetInElement.attribute.value.split('.').pop();
    const fullyQualifiedName = `${namespace}.${type}`;

    return {
        contents: {
            kind: MarkupKind.Markdown,
            value: valueHandlingContext.context.vocabularies
                .getDocumentation(fullyQualifiedName, undefined, aliasInfo)
                .join('\n')
        },
        range: pathTargetInElement.attribute.valueRange
    };
}

export function handleRecordType(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    property?: Element
): Diagnostic[] | CompletionItem[] {
    if (property) {
        return checkRecordType(valueHandlingContext.context, type, property, valueHandlingContext.aliasInfo);
    } else {
        return completeRecordType(valueHandlingContext.context, type, valueHandlingContext.aliasInfo);
    }
}

/**
 * get property descriptors for record
 * @param valueHandlingContext
 * @param recordType - type that whole record should represent (can be abstract)
 * @param recordElement - Record XML element, can have more specific type specified in Type attribute
 */
export function getPropertyDescriptorsForRecord(
    valueHandlingContext: ValueHandlingContext,
    recordType: ValueType,
    recordElement?: Element
): {
    resolvedRecordType: ValueType | null;
    all: ComplexTypeProperty[];
    mandatory: ComplexTypeProperty[];
    missingMandatory: ComplexTypeProperty[];
    notProvided: ComplexTypeProperty[];
    existing: ComplexTypeProperty[];
    dollarTypeAllowed: boolean;
    isOpenType: boolean;
} {
    if (!recordElement) {
        // snippet's fake record element (need to be passed to universal functions)
        recordElement = {
            name: Edm.Record,
            type: ELEMENT_TYPE,
            nameRange: null,
            attributes: {
                Type: {
                    name: 'Type',
                    type: ATTRIBUTE_TYPE,
                    nameRange: null,
                    value: recordType.name,
                    valueRange: { start: { line: 0, character: 0 }, end: { line: 0, character: 0 } }
                }
            },
            content: []
        };
    }
    const resolvedRecordType =
        resolveRecordType(valueHandlingContext, [(recordType && recordType.name) || ''], recordElement) || recordType;

    const structuredTypeDefinition = valueHandlingContext.context.vocabularies.getComplexType(resolvedRecordType.name);

    const allProperties: ComplexTypeProperty[] = structuredTypeDefinition
        ? Array.from(structuredTypeDefinition.properties.values())
        : [];

    const mandatoryProperties = allProperties.filter((prop) => isMandatoryProperty(prop) && !prop.isCollection);

    const existingPropNames = getSplitStructurePropertySources(
        valueHandlingContext.context,
        valueHandlingContext.currentStructureProperty
    ).nestedProperties;
    let existingProperties: ComplexTypeProperty[] = [];
    let missingMandatoryProperties: ComplexTypeProperty[] = [];
    let dollarTypeEntryAllowed = !!valueHandlingContext.context.supportSplit;

    if (existingPropNames) {
        // CDS split support: consider properties as already existing if they are anywhere in same file
        existingProperties = allProperties.filter((prop) => {
            let found = false;
            if (existingPropNames[prop.name]) {
                if (
                    valueHandlingContext.currentFileUri &&
                    existingPropNames[prop.name].has(valueHandlingContext.currentFileUri)
                ) {
                    found = true;
                }
            }
            return found;
        });
        // CDS split support: consider mandatory properties as missing if they are not found in any file
        missingMandatoryProperties = mandatoryProperties.filter((prop) => !existingPropNames[prop.name]);
        // CDS split support: indicate $Type is missing if not found in current file
        dollarTypeEntryAllowed = false;
        if (!existingPropNames['$Type']) {
            dollarTypeEntryAllowed = true;
        } else if (
            valueHandlingContext.currentFileUri &&
            !existingPropNames['$Type'].has(valueHandlingContext.currentFileUri)
        ) {
            dollarTypeEntryAllowed = true;
        }
    } else {
        existingProperties = allProperties.filter((prop) =>
            (recordElement.content || [])
                .filter((child) => child.type === ELEMENT_TYPE && child.name === Edm.PropertyValue)
                .find((child) => getElementAttributeValue(child as Element, 'Property') === prop.name)
        );
        missingMandatoryProperties = mandatoryProperties.filter(
            (prop) => !existingProperties.find((item) => item.name === prop.name)
        );
    }

    const notProvidedProperties = allProperties.filter(
        (prop) => !existingProperties.find((item) => item.name === prop.name)
    );

    return {
        resolvedRecordType: resolvedRecordType,
        all: allProperties,
        mandatory: mandatoryProperties,
        missingMandatory: missingMandatoryProperties,
        notProvided: notProvidedProperties,
        existing: existingProperties,
        dollarTypeAllowed: dollarTypeEntryAllowed,
        isOpenType: !!structuredTypeDefinition?.isOpenType
    };
}

export function handleRecordPropertyValue(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    element: Element,
    path: JsonPath
): CompletionItem[] {
    // handle PropertyValue as sub node of Record: only Property attribute needs to be handled here!
    // (if Property is set, remaining logic is handled for PropertyValue tag)
    let compItems: CompletionItem[] = [];
    const propValue = getPathTargetInElement(path, element);
    const target = getPathTargetInElement(propValue.remainingPathForElement, propValue.element);
    if (target.attribute && target.isAttributeName) {
        compItems = [
            {
                text: Edm.Property,
                name: Edm.Property,
                affectedRange: target.attribute.nameRange
            }
        ];
    } else if (target.attribute && target.isAttributeValue && target.attribute.name === Edm.Property) {
        if (element.name === Edm.Record) {
            const props = getPropertyDescriptorsForRecord(valueHandlingContext, type, element);
            const availableProps = props.notProvided;
            const selectedProperty = props.existing.find((item) => item.name === target.attribute.value);
            if (selectedProperty) {
                availableProps.push(selectedProperty);
            }

            compItems = availableProps.map((item) => {
                const compItem: CompletionItem = {
                    text: item.name,
                    name: item.name,
                    affectedRange: target.attribute.valueRange,
                    category: CompletionItemCategory.Property,
                    id: props.resolvedRecordType.name
                };
                return compItem;
            });
            if (props.dollarTypeAllowed) {
                // add marker item - final entry will be created in CDS LSP extension
                compItems.push({ name: '$CdsRecordType$', text: '$CdsRecordType$' });
            }
        }
    }
    return compItems;
}

function resolveRecordTypeName(
    valueHandlingContext: ValueHandlingContext,
    derivedTypes: FullyQualifiedTypeName[],
    recordElement: Element
): string {
    let result: string;
    const typeAttribute = getElementAttribute(recordElement, 'Type');
    let typeName = typeAttribute && typeAttribute.valueRange ? typeAttribute.value : '';
    if (typeName) {
        // type attribute is specified in source file
        result = resolveName(typeName, valueHandlingContext.aliasInfo.aliasMap).qName;
    } else {
        // split support: try to get type defined somewhere else
        result = getSplitStructureType(valueHandlingContext.context, valueHandlingContext.currentStructureProperty);
        if (!result) {
            typeName = typeAttribute ? typeAttribute.value : '';
            if (typeName) {
                // use value from type attribute even if valuRange is not provided (e.g. type is defaulted in CDS annotation adapter)
                result = resolveName(typeName, valueHandlingContext.aliasInfo.aliasMap).qName;
            } else {
                // type attribute not specified: restrict types to structured types
                const structuredTypes = derivedTypes.filter((typesEntry) => {
                    if (typesEntry.startsWith('Collection(') || typesEntry.startsWith('Edm.')) {
                        return false;
                    } else {
                        const typeDefinition = getVocabularyType(valueHandlingContext.context, typesEntry);
                        return !!typeDefinition && typeDefinition.kind === Edm.ComplexType;
                    }
                });
                result = structuredTypes.length ? structuredTypes[0] : '';
            }
        }
    }
    return result;
}

/**
 * resolve record type for element representing Edm.Record
 * @param types
 * @param recordElement
 */
export function resolveRecordType(
    valueHandlingContext: ValueHandlingContext,
    derivedTypes: string[],
    recordElement: Element
): ValueType | null {
    const resolvedTypeName = resolveRecordTypeName(valueHandlingContext, derivedTypes, recordElement);
    const resolvedVocabularyType = getVocabularyType(valueHandlingContext.context, resolvedTypeName);
    if (resolvedVocabularyType) {
        return {
            name: resolvedTypeName,
            asCollection: false // record type cannot be a collection
        };
    } else {
        return null;
    }
}

export { resolveRecordTypeName };

export function checkDuplicateSiblings(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    property: Element,
    ignoreType = false
): Diagnostic[] {
    const elementMap: { [elementName: string]: { [type: string]: Element[] } } = {};
    const textNodeMap: { [elementName: string]: Element[] } = {};
    const result: Diagnostic[] = [];

    const pushElementToMap = (map: { [key: string]: Element[] }, key: string, element: Element): void => {
        if (!map[key]) {
            map[key] = [];
        }
        map[key].push(element);
    };

    // build maps for text nodes and elements
    (property.content || []).forEach((element) => {
        if (element.type === ELEMENT_TYPE) {
            const textNode = getSingleTextNode(element);
            if (textNode) {
                pushElementToMap(textNodeMap, element.name, element);
            } else {
                if (!elementMap[element.name]) {
                    elementMap[element.name] = {};
                }
                const typeMap = elementMap[element.name];
                if (element.name === Edm.PropertyValue) {
                    const propertyName = getElementAttributeValue(element, Edm.Property);
                    const propType = getValueTypeForComplexTypeProperty(
                        valueHandlingContext.context,
                        (type && type.name) || '',
                        propertyName
                    );
                    if (ignoreType || (propType && propType.name)) {
                        pushElementToMap(typeMap, propertyName, element);
                    }
                } else {
                    pushElementToMap(typeMap, '', element);
                }
            }
        }
    });

    // check for duplicates
    Object.keys(elementMap).forEach((name) => {
        Object.keys(elementMap[name])
            .filter((typeName) => typeName && elementMap[name][typeName].length > 1)
            .forEach((typeName) => {
                elementMap[name][typeName].forEach((elm) => {
                    const message = i18n.t('Duplicate_element');
                    result.push({
                        message: message,
                        severity: DiagnosticSeverity.Warning,
                        range: elm.range,
                        rule: IGNORE_DUPLICATE
                    });
                });
            });
    });

    return result;
}

/**
 * for Record element: check and extract record type
 * @param valueHandlingContext
 * @param type
 * @param element
 * @param messages
 */
export function checkAndExtractTypeForRecord(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    element: Element,
    messages: Diagnostic[]
): ValueType {
    let checkedRecordType: ValueType = null;
    // get/check record type
    const recordTypeAttribute = getElementAttribute(element, Edm.Type);
    // CDS split annotation support: find $Type
    const typeNameCds = getSplitStructureType(
        valueHandlingContext.context,
        valueHandlingContext.currentStructureProperty
    );
    if (
        isAbstract(valueHandlingContext.context, type.name) &&
        !typeNameCds &&
        (!recordTypeAttribute || !recordTypeAttribute.value)
    ) {
        // requested type is abstract: Type attribute required for Record
        const aliasedName = toAliasQualifiedName(type.name, valueHandlingContext.aliasInfo);
        if (!recordTypeAttribute) {
            const message = i18n.t('Missing_required_attribute_Type_Type_0_is_abstract', {
                type: aliasedName
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: element.nameRange ? element.nameRange : element.range,
                rule: MISSING_REQUIRED_ATTRIBUTE
            });
        } else if (!recordTypeAttribute.value) {
            const message = i18n.t('Missing_required_value_for_Type_Type_0_is_abstract', {
                type: aliasedName
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: recordTypeAttribute.valueRange,
                rule: MISSING_REQUIRED_VALUE_FOR_ATTRIBUTE
            });
        }
    } else if ((recordTypeAttribute && recordTypeAttribute.value) || typeNameCds) {
        // Type provided
        let recordTypeNameOrig = '';
        if (recordTypeAttribute && recordTypeAttribute.valueRange && recordTypeAttribute.value) {
            recordTypeNameOrig = recordTypeAttribute.value; // type was 'really' specified in source file
        } else {
            recordTypeNameOrig = typeNameCds || recordTypeAttribute.value; // type was not specified in source file
        }
        const resolvedName = resolveName(recordTypeNameOrig, valueHandlingContext.aliasInfo.aliasMap);
        const recordTypeName = resolvedName.qName;
        const resolvedRecordType = getVocabularyType(valueHandlingContext.context, recordTypeName);
        const messageRange = recordTypeAttribute ? recordTypeAttribute.valueRange : element.range || element.nameRange;
        if (!resolvedRecordType) {
            const supportedVocabularyNamespace =
                valueHandlingContext.context.vocabularies.getVocabularyNamespace(recordTypeName);
            if (supportedVocabularyNamespace && supportedVocabularyNamespace !== resolvedName.namespace) {
                const xmlDocNamespaceOrAlias =
                    supportedVocabularyNamespace === recordTypeName ||
                    recordTypeName.startsWith(supportedVocabularyNamespace)
                        ? supportedVocabularyNamespace
                        : !resolvedName.namespace
                        ? recordTypeName.split('.')[0]
                        : resolvedName.namespace;
                const diagnostic = createUnknownVocabularyDiagnostic(
                    xmlDocNamespaceOrAlias,
                    supportedVocabularyNamespace,
                    messageRange,
                    valueHandlingContext.context.vocabularies
                );
                messages.push(diagnostic);
            } else {
                const message = i18n.t('Unknown_Type_0', {
                    type: recordTypeNameOrig
                });
                let caseCheck: CaseCheck;
                if (resolvedName.namespace) {
                    caseCheck = {
                        value: resolvedName.name,
                        lookupPath: ['vocabularies', resolvedName.namespace],
                        isNamespacedValue: true
                    };
                }
                const nameQualifier = recordTypeNameOrig.split('.')[0];
                const diagnostic = createErrorDiagnosticWithRule(INVALID_TYPE_TYPE, message, messageRange, {
                    alias: nameQualifier,
                    name: recordTypeNameOrig,
                    caseCheck
                });
                messages.push(diagnostic);
            }
        } else {
            const aliasedRecordTypeName = toAliasQualifiedName(recordTypeName, valueHandlingContext.aliasInfo);
            let isRecordValueAllowed = true;
            if (type && type.constraints) {
                isRecordValueAllowed = isConstraintApplicable(type.constraints, recordTypeName);
            }
            if (!isRecordValueAllowed) {
                const message = i18n.t(
                    'Record_type_0_not_allowed_due_to_restrictions_defined_in_vocabulary_Use_the_code_completion_to_select_one_of_the_allowed_values',
                    { recordType: recordTypeNameOrig }
                );
                messages.push({
                    message: message,
                    severity: DiagnosticSeverity.Error,
                    range: messageRange
                });
            } else if (isAbstract(valueHandlingContext.context, recordTypeName)) {
                const message = i18n.t('Record_Type_0_must_not_be_abstract', {
                    recordType: aliasedRecordTypeName
                });
                messages.push({
                    message: message,
                    severity: DiagnosticSeverity.Error,
                    range: messageRange
                });
            } else if (!isParentType(valueHandlingContext.context, type.name, recordTypeName)) {
                const aliasedName = toAliasQualifiedName(type.name, valueHandlingContext.aliasInfo);
                const message = i18n.t('Record_Type_0_must_be_derived_from_1', {
                    recordType: aliasedRecordTypeName,
                    element: aliasedName
                });
                messages.push({
                    message: message,
                    severity: DiagnosticSeverity.Error,
                    range: messageRange
                });
            } else {
                checkedRecordType = {
                    ...convertValueTypeFromString(recordTypeName),
                    facets: type.facets,
                    constraints: type.constraints
                };
            }
        }
    } else {
        // requested type is not abstract, no Type attribute provided
        checkedRecordType = type;
    }

    if (checkedRecordType) {
        const complexType: ComplexType = valueHandlingContext.context.vocabularies.getType(type.name) as ComplexType;
        adjustApplicableTermsConstraint(checkedRecordType, complexType?.constraints);
        // check missing mandatory properties
        const props = getPropertyDescriptorsForRecord(valueHandlingContext, checkedRecordType, element);
        if (props.missingMandatory.length) {
            const message = i18n.t('Mandatory_properties_not_provided_0', {
                properties: props.missingMandatory.map((prop) => prop.name).join(',')
            });
            messages.push({
                message: message,
                severity: valueHandlingContext.context.supportSplit
                    ? DiagnosticSeverity.Warning
                    : DiagnosticSeverity.Error,
                range: element.nameRange ? element.nameRange : element.range
            });
        }
        messages.push(...checkDuplicateSiblings(valueHandlingContext, checkedRecordType, element, props.isOpenType));
    }
    return checkedRecordType;
}

/**
 * check property value element
 * @param valueHandlingContext
 * @param propertyValueElement
 * @param recordType
 */
export function checkPropertyValueElement(
    valueHandlingContext: ValueHandlingContext,
    propertyValueElement: Element,
    recordType: ValueType,
    checkCallback: CheckCallback,
    checkTrace: CheckTrace,
    logger: Logger
): Diagnostic[] {
    let messages: Diagnostic[] = [];
    if (recordType) {
        // subElements needs to be PropertyValues
        // get type of property value based on record type and property name
        checkTrace.registerElement(propertyValueElement);
        const propertyNameAttribute = getElementAttribute(propertyValueElement, Edm.Property);
        const propertyName = propertyNameAttribute ? propertyNameAttribute.value : '';
        const propertyType = propertyName
            ? getValueTypeForComplexTypeProperty(
                  valueHandlingContext.context,
                  recordType && recordType.name,
                  propertyName
              )
            : null;
        if (
            (!propertyName || (recordType.constraints?.openPropertyTypeConstraints || []).length === 0) &&
            (!propertyType || !propertyType.name)
        ) {
            if (propertyNameAttribute && propertyNameAttribute.value) {
                if (propertyNameAttribute.value.toUpperCase() !== '$Type'.toUpperCase()) {
                    // handle '$Type' case issue in cds-annotation-adapter module
                    let diagnosticMessage: Diagnostic;
                    if (
                        valueHandlingContext.context.supportSplit &&
                        recordType.name === 'com.sap.vocabularies.Common.v1.ValueListType' &&
                        propertyNameAttribute.value === 'entity'
                    ) {
                        diagnosticMessage = {
                            message: i18n.t('Invalid_Entity_Property'),
                            severity: DiagnosticSeverity.Warning,
                            range: propertyNameAttribute.valueRange
                        };
                    } else {
                        const message = i18n.t('Invalid_Property_0', {
                            property: propertyNameAttribute.value
                        });
                        diagnosticMessage = {
                            message: message,
                            severity: DiagnosticSeverity.Error,
                            range: propertyNameAttribute.valueRange,
                            data: {
                                caseCheck: {
                                    value: propertyNameAttribute.value,
                                    lookupPath: ['vocabularies', recordType.name]
                                }
                            }
                        };
                    }
                    messages.push(diagnosticMessage);
                }
            } else if (propertyNameAttribute) {
                const message = i18n.t('Missing_value_for_Property');
                messages.push({
                    message: message,
                    severity: DiagnosticSeverity.Error,
                    range: propertyNameAttribute.nameRange
                });
            }
        } else {
            if (isActionNameProperty(recordType.name, propertyName, valueHandlingContext.aliasInfo.aliasMap)) {
                propertyType.constraints = propertyType.constraints || {};
                propertyType.constraints.allowedValues = getAllowedActionFunctionNames(
                    valueHandlingContext.context.metadata
                );
            }
            const entityContainerName = valueHandlingContext.context.serviceNamespaceMap?.get(
                resolveName((valueHandlingContext.pathBase?.path || '').split('/')[0])?.namespace
            );
            if (entityContainerName && isCollectionPathProperty(recordType.name, propertyName)) {
                propertyType.constraints = propertyType.constraints || {};
                const entitySetProperties = valueHandlingContext.context.availableEntitySetPropertyMap ?? new Map();
                propertyType.constraints.allowedValues = [...entitySetProperties.keys()]
                    .filter((key) => key.split('/')[0] === entityContainerName)
                    .map((key) => {
                        const entitySetName = key.split('/').pop();
                        return { value: entitySetName, description: entitySetName, longDescription: '' };
                    });
            }
            if (
                entityContainerName &&
                isValueListProperty(recordType.name, propertyName) &&
                (getPropertyStringValue(propertyValueElement) || '').indexOf('/') < 0 // no check for paths
            ) {
                propertyType.constraints = propertyType.constraints || {};
                if (
                    valueHandlingContext.nodeContext?.valueListProps &&
                    valueHandlingContext.nodeContext.valueListProps.currentEntitySetName
                ) {
                    const entitySetProperties = valueHandlingContext.context.availableEntitySetPropertyMap ?? new Map();
                    const propNameMap = entitySetProperties.get(
                        entityContainerName + '/' + valueHandlingContext.nodeContext.valueListProps.currentEntitySetName
                    );
                    propertyType.constraints.allowedValues = propNameMap
                        ? [...propNameMap.keys()].map((key) => ({
                              value: key,
                              description: key,
                              longDescription: ''
                          }))
                        : [];
                }
            }
            if (!propertyType?.name && (recordType.constraints?.openPropertyTypeConstraints || []).length) {
                // complex type open property check
                // TODO: support multiple open property type constraints
                // TODO: facets, constraints for propertyType ?
                const typeName = recordType.constraints.openPropertyTypeConstraints[0];
                const propValueType = convertValueTypeFromString(typeName);
                messages = checkCallback(
                    valueHandlingContext,
                    [propValueType],
                    propertyValueElement,
                    null,
                    checkTrace,
                    logger
                );
                if (!isValidSimpleIdentifier(propertyName)) {
                    messages.push({
                        message: i18n.t('Property_name_0_should_be_of_type_SimpleIdentifier', { propertyName }),
                        severity: DiagnosticSeverity.Error,
                        range: propertyNameAttribute.valueRange
                    });
                }
            } else {
                if (isTemplateProperty(recordType.name, propertyName)) {
                    propertyType.constraints = propertyType.constraints || {};
                    propertyType.constraints.isLanguageDependent = false;
                }

                messages = checkCallback(
                    valueHandlingContext,
                    [propertyType],
                    propertyValueElement,
                    null,
                    checkTrace,
                    logger
                );
            }
        }
    }
    return messages;
}

export function isActionNameProperty(resolvedRecordType: string, propertyName: string, aliasMap: AliasMap): boolean {
    return (
        propertyName === Edm.Action &&
        ['UI.DataFieldForAction', 'UI.DataFieldWithAction']
            .map((item) => resolveName(item, aliasMap).qName)
            .includes(resolvedRecordType)
    );
}

export function getAllowedActionFunctionNames(metadata: MetadataService): AllowedValues[] {
    const names = getActionFunctionNames(metadata);
    const values: ActionFunctionNameValue[] = names.reduce((acc, v) => {
        if (v.name.includes('/')) {
            const [prefix, actionOrFunctionName] = v.name.split('/');
            const [simpleName] = actionOrFunctionName.split('(');
            const { namespace, name } = resolveName(prefix);
            const result: ActionFunctionNameValue = {
                kind: ACTION_FUNCTION_NAME_OBJECT_TYPE,
                name: actionOrFunctionName,
                namespace,
                entityContainer: name,
                targetKind: v.kind,
                toString: () => v.name
            };
            acc.push(result, {
                ...result,
                forCompletion: true,
                name: simpleName,
                toString: () => `${prefix}/${simpleName}`
            });
        } else {
            const { namespace, name } = resolveName(v.name);
            const [simpleName] = name.split('(');
            const result: ActionFunctionNameValue = {
                kind: ACTION_FUNCTION_NAME_OBJECT_TYPE,
                name,
                namespace,
                targetKind: v.kind,
                toString: () => v.name
            };
            acc.push(result, {
                ...result,
                forCompletion: true,
                name: simpleName,
                toString: () => `${namespace}.${simpleName}`
            });
        }
        return acc;
    }, []);
    return values.map((value) => ({ value, description: '', longDescription: '' }));
}

function getActionFunctionNames(metadata: MetadataService): { kind: string; name: string }[] {
    const values: { kind: string; name: string }[] = [];
    const paths = [...metadata.getRootMetadataElements().keys()];
    const metadataKinds = [ACTION_KIND, FUNCTION_KIND, ACTION_IMPORT_KIND, FUNCTION_IMPORT_KIND];
    paths.forEach((path) => {
        const metadataElement = metadata.getMetadataElement(path);
        const targetKinds = metadata.getEdmTargetKinds(path);
        const kind = targetKinds.find((k) => metadataKinds.includes(k));
        if (kind) {
            values.push({ kind, name: metadataElement.name });
        } else if (targetKinds.includes(ENTITY_CONTAINER_KIND)) {
            const entityContainerElementNames = [...(metadataElement.content ?? []).map((element) => element.name)];
            entityContainerElementNames.forEach((containerElementName) => {
                const containerElementPath = `${path}/${containerElementName}`;
                const targetKinds = metadata.getEdmTargetKinds(containerElementPath);
                const kind = targetKinds.find((k) => metadataKinds.includes(k));
                if (kind) {
                    values.push({ kind, name: containerElementPath });
                }
            });
        }
    });
    return values;
}
