import type { Logger } from '@sap/ux-annotation-service';
import type { ContributionContext, ContributionTracer } from './lspTypes';

/**
 * Logger using CDS API
 *
 * Singleton
 *
 * Method initialize is called by CDS LSP
 */
class LoggerCDS implements Logger {
    private static instance: LoggerCDS;
    private trace: ContributionTracer;

    // eslint-disable-next-line @typescript-eslint/no-empty-function
    private constructor() {} // enforce singleton

    static getInstance(): LoggerCDS {
        if (!LoggerCDS.instance) {
            LoggerCDS.instance = new LoggerCDS();
        }
        return LoggerCDS.instance;
    }

    private _init(context: ContributionContext): void {
        if (!this.trace) {
            this.trace = context.trace;
        }
    }

    initialize(context: ContributionContext): void {
        const instance = LoggerCDS.getInstance();
        instance._init(context);
    }

    error(message: string): void {
        if (this.trace) {
            this.trace.error(() => {
                return message;
            });
        }
    }
    warn(message: string): void {
        if (this.trace) {
            this.trace.warn(() => {
                return message;
            });
        }
    }
    info(message: string): void {
        if (this.trace) {
            this.trace.info(() => {
                return message;
            });
        }
    }
}

export const cdsLogger = LoggerCDS.getInstance();
