import { DirName } from '@sapux/project-spec';

import type { Context } from '../types/context';

import {
    addNavPropPathToPathExpressions,
    addPathToPathExpressions,
    addNavPropToNavSourceMap,
    removeActionFunctionSignatureFromPath
} from './path';
import { addAnnotationFileToContext, removeOutdatedCacheContent } from './sync';

import type { MetadataElement } from '@sap-ux/odata-annotation-core-types';
import type {
    Alias,
    AnnotationFile,
    FileUri,
    Namespace,
    Reference,
    ServiceAnnotationFile
} from '@sap-ux/odata-annotation-core';
import { getAliasInformation, getAllNamespacesAndReferences } from '@sap-ux/odata-annotation-core';

function buildNamespaceFromFileUri(fileUri: FileUri, namespaces: (Namespace | Reference)[]): Namespace {
    // build namespace using folders after 'webapp' and filename without extension
    let parts = fileUri.split('.');
    parts.pop();
    const fileUriWithoutExtension = parts.join('.');
    const folderSeparatorCharacter = fileUriWithoutExtension.indexOf('\\') > -1 ? '\\' : '/';
    parts = fileUriWithoutExtension
        .split(folderSeparatorCharacter)
        .filter((part) => !!part)
        .map((part) => part.replace(new RegExp('\\.', 'g'), ''));
    let startIndex = 1;
    if (parts.indexOf(DirName.Webapp) > -1) {
        startIndex = parts.indexOf(DirName.Webapp) + 1;
    } else if (parts.length > 3) {
        startIndex = parts.length - 3;
    }
    parts = parts.slice(startIndex);
    let namespaceName = parts.join('.');
    // make sure namespace is none of the currently referenced ones
    const namespaceMap = namespaces
        .filter((ns) => ns.name)
        .reduce((namespaceMap, namespace) => {
            namespaceMap[namespace.name] = true;
            return namespaceMap;
        }, {});
    let i = 0;
    const namespaceNameBase = namespaceName;
    while (namespaceMap[namespaceName]) {
        namespaceName = namespaceNameBase + ++i;
    }
    return { type: 'namespace', name: namespaceName, nameRange: null };
}

export function getSchemaNamespaces(annotationFile: AnnotationFile, uri: FileUri): Namespace {
    // TODO handle schemaNamespace is initial
    let schemaNamespace = annotationFile.namespace;
    if (!schemaNamespace) {
        const namespaces: (Namespace | Reference)[] = annotationFile.namespace
            ? [annotationFile.namespace, ...annotationFile.references]
            : [...annotationFile.references];
        schemaNamespace = buildNamespaceFromFileUri(uri, namespaces);
    }
    return schemaNamespace;
}

export function addMetadataToContext(context: Context): void {
    const metadataService = context.metadata;
    // call back function for handling metadata elements
    function visitMetadataElement(metadataElement: MetadataElement): void {
        // ignore metadata elements representing anonymous complex types
        // -> they are not part of service metadata (hence not annotatable), elements of it are generated as separate primitive elements <complexTypeName>_<complexTypeElement>
        // also when used as target, EDMX target is generated as <complexTypeName>_<complexTypeElement>
        if (metadataElement.isComplexType && !metadataElement.isAnnotatable) {
            return;
        }
        // fill path caches
        if (metadataElement.structuredType) {
            addNavPropToNavSourceMap(context, metadataElement, metadataService.fileUri);
            // TODO for navigation properties: exclude depending on containment
            // "Containment navigation properties MUST NOT be specified as the last path segment in the path of a navigation property binding."
            // https://docs.oasis-open.org/odata/odata-csdl-xml/v4.01/csprd06/odata-csdl-xml-v4.01-csprd06.html#sec_ContainmentNavigationProperty
            addNavPropPathToPathExpressions(context, metadataElement, metadataService.fileUri);
        }
        addPathToPathExpressions(context, metadataElement, metadataService.fileUri);
        if (metadataElement.path.indexOf('(') > 0) {
            // path includes action or function signature - add entries without signature
            const pathNoBrackets = removeActionFunctionSignatureFromPath(metadataElement.path);
            if (metadataElement.structuredType) {
                addNavPropToNavSourceMap(context, metadataElement, metadataService.fileUri, pathNoBrackets);
                addNavPropPathToPathExpressions(context, metadataElement, metadataService.fileUri, pathNoBrackets);
            }
            addPathToPathExpressions(context, metadataElement, metadataService.fileUri, pathNoBrackets);
        }
    }

    // build up path cache
    metadataService.visitMetadataElements(visitMetadataElement);
    [...metadataService.getNamespaces()].forEach((namespace) => {
        context.namespaceFileUriMap.metadata = context.namespaceFileUriMap.metadata || {};
        context.namespaceFileUriMap.metadata[namespace] = metadataService.fileUri;
    });
}

export function addServiceFileToContext(context: Context, serviceFile: ServiceAnnotationFile, index?: number): void {
    const schemaNamespace = getSchemaNamespaces(serviceFile.content, serviceFile.uri);
    // put service files file cache
    context.fileCache[serviceFile.uri] = {
        serviceFile: serviceFile,
        namespace: schemaNamespace.name
    };
    // only remove content for non duplicate namespaces to enable namespace error handling
    if (serviceFile.uri !== context.metadata.fileUri) {
        // cache refresh for metadata is already called in 'onMetadataChanged()'
        removeOutdatedCacheContent(context, serviceFile.uri);
    }
    if (!context.annotationFileSequence.includes(serviceFile.uri)) {
        // removed check: for CDS all files are metadata files and currently might have no targets
        // but they are changeable and thus annotations could be added -> they should be added to annotationFileSequence
        // if (serviceFile.kind === FileKind.Annotations || serviceFile.content.targets.length) {
        if (index >= 0) {
            // insert
            if (!context.metadata.isCds && serviceFile.uri !== context.metadata.fileUri) {
                // increment index to get annotations from annotation data sources inserted after annotations from metadata file
                index++;
            }
            context.annotationFileSequence.splice(index, 0, serviceFile.uri);
        } else {
            // append
            context.annotationFileSequence.push(serviceFile.uri);
        }
        //}
    }

    // add content of all external targeting annotations to context (include files after changed file )
    const startIndex = context.annotationFileSequence.findIndex((uri) => uri === serviceFile.uri);
    for (let i = startIndex; i < context.annotationFileSequence.length; i++) {
        const uri = context.annotationFileSequence[i];
        const content = context.fileCache[uri]?.serviceFile?.content;
        if (content) {
            const refs = content?.references || [];
            const namespaces = getAllNamespacesAndReferences(content.namespace, refs);
            const aliasInfo = getAliasInformation(namespaces, context.metadata.getNamespaces());
            addAnnotationFileToContext(context, content, aliasInfo, uri);
        }
    }
}

enum NamespaceKind {
    Vocabulary = 'vocabulary',
    Other = 'other',
    Schema = 'schema'
}

interface NamespaceEntry {
    alias: Alias;
    kind: NamespaceKind;
    uri: FileUri;
}
