export function addDynamicExpressionsWithType(
    type: ValueType,
    ccPropNames: { [key: string]: CompletionItemCategory }
): void {
    const isTypePrimitive = !!primitiveTypeMap[type.name];

    const isTypeMatching = (resultType: string, isResultTypePrimitive: boolean): boolean => {
        return (
            type.name === resultType ||
            (type.name === EdmType.PrimitiveType && isResultTypePrimitive) ||
            (resultType === EdmType.PrimitiveType && isTypePrimitive)
        );
    };

    dynamicExpressionSignatureMap.forEach((signature, name) => {
        const resultType = signature.resultType;
        const isResultTypePrimitive = !!primitiveTypeMap[typeof resultType === 'object' ? resultType.name : resultType];
        let typeMatch = false;
        if (typeof resultType === 'object') {
            if (!resultType.constraints) {
                if (!!type.asCollection === !!resultType.isCollection) {
                    typeMatch = isTypeMatching(resultType.name, isResultTypePrimitive);
                }
            } else {
                // e.g. If should be allowed anywhere
                if (resultType.name === EdmType.Untyped && resultType.constraints.compatibleWithRequestedType) {
                    typeMatch = true;
                }
            }
        } else {
            typeMatch =
                resultType === EdmType.Untyped ||
                (!type.asCollection && isTypeMatching(resultType, isResultTypePrimitive));
        }

        if (typeMatch) {
            ccPropNames[name] = CompletionItemCategory.DynamicExpressionName;
        }
    });
}

function getTypesToCheck(context: Context, types: ValueType[], nodeValueTypeNames: string[]): ValueType[] {
    const typesToCheck: ValueType[] = [];
    if (nodeValueTypeNames.length) {
        expandWithCompatibleTypes(context, types).forEach((type) => {
            if (type.asCollection) {
                typesToCheck.push(type);
            } else if (nodeValueTypeNames.find((t) => t === type.name)) {
                typesToCheck.push(type);
            } else if (type.name === EdmType.PrimitiveType) {
                typesToCheck.push(
                    ...Object.keys(primitiveTypeMap)
                        .filter((key) => nodeValueTypeNames.find((t) => t === key))
                        .map((key) => ({ ...type, name: key } as ValueType))
                );
            } else if (nodeValueTypeNames.find((t) => t === EdmType.PrimitiveType) && primitiveTypeMap[type.name]) {
                typesToCheck.push(type);
            }
        });
    }
    return typesToCheck;
}

function collapseErrorsForVariantType(messages: Diagnostic[], types: ValueType[], nodeRange: Range): Diagnostic[] {
    const result = messages.filter((m) => m.severity !== DiagnosticSeverity.Error);
    const errorMsg = messages.find((m) => m.severity === DiagnosticSeverity.Error);
    if (errorMsg) {
        const typeList = types.map((t) => convertValueTypeToString(t)).join(', ');
        result.push({
            ...errorMsg,
            range: nodeRange || errorMsg.range,
            message: i18n.t('Invalid_value_for_types_0', {
                types: typeList
            })
        });
    }
    return result;
}
/**
 * The function sequentially calls check handler for every meaningful requested type
 *
 * NOTE: Meaningful requested types are those from the requested type list (1 argument)
 * which are matching with value types resolved for the current node (2 argument)
 * If there are no matching types then check is done as following:
 *      1) handler is called sequentially for all requested types
 *      2) if handler returns empty result for some of requested types then total result considered as successful and function exits with empty messages
 *      3) if for all requested types handler returns some messages then:
 *          a) if requested type is single one then result is returned as it is
 *          b) if requested types are multiple then result depends on collapseVariantTypeErrors parameter value as following:
 *             true - All error messages are replaced with a single error 'Invalid value for type(s)...',
 *                     warnings and info messages remain untouched
 *             false - result of first type check is returned
 *
 * @param types  - requested value types
 * @param nodeValueTypes - value types of the node being checked
 * @param nodeRange - range of current node being checked (used to generate common error message in case if no error ranges provided in handler results)
 * @param checkProcedure - node's check handler returning diagnostic messages for a certain value type
 * @param collapseVariantTypeErrors - controls how error messages are returned (see description above)
 */
export function checkValueForVariantType(
    context: Context,
    types: ValueType[],
    nodeValueTypeNames: string[],
    nodeRange: Range,
    checkProcedure: (type: ValueType) => Diagnostic[],
    collapseVariantTypeErrors = true
): Diagnostic[] {
    let result: Diagnostic[] = [];
    const typesToCheck: ValueType[] = getTypesToCheck(context, types, nodeValueTypeNames);
    const isNoMatchingTypes = typesToCheck.length === 0;

    const msgKey = (msg: Diagnostic): string => {
        return (
            msg.message +
            `${msg.range.start.line},${msg.range.start.character}:${msg.range.end.line},${msg.range.end.character}`
        );
    };

    if (typesToCheck.length === 0) {
        typesToCheck.push(...types);
    }

    let defaultResult: Diagnostic[];
    for (const type of typesToCheck) {
        const checkResult = checkProcedure(type);
        if (checkResult.length) {
            defaultResult = defaultResult || checkResult;
            // duplicating messages are possible if node value types are multiple (i.e. some If expression) - eliminating them
            result.push(...checkResult.filter((item) => !result.find((r) => msgKey(r) === msgKey(item))));
        } else {
            result = [];
            defaultResult = [];
            break;
        }
    }

    if (types.length > 1 && isNoMatchingTypes) {
        if (collapseVariantTypeErrors) {
            // replace diagnostics error messages with a single generic one
            result = collapseErrorsForVariantType(result, types, nodeRange);
        } else {
            result = defaultResult;
        }
    }

    return result;
}

const containsError = (messages: Diagnostic[]): boolean => {
    return messages.some((m) => m.severity === DiagnosticSeverity.Error);
};

function checkDynamiExpressionNode(
    valueHandlingContext: ValueHandlingContext,
    types: ValueType[],
    element: Element,
    dynamicExpressionSignature: DynamicExpressionSignature,
    checkTrace: CheckTrace,
    logger: Logger,
    targetTermMap: Map<string, boolean>,
    parameters: Array<{ node: Node; parameter: DynamicExpressionParameter }>,
    childElementIndex: number,
    messages: Diagnostic[]
): { messages: Diagnostic[]; childElementIndex: number } {
    element.content.forEach((node) => {
        if (!containsError(messages) && node.type === ELEMENT_TYPE) {
            if (node.name !== 'Annotation') {
                childElementIndex++;
                const childElement = node;
                const parameterSignature = dynamicExpressionSignature?.parameters[childElementIndex];
                if (parameterSignature) {
                    parameters.push({ node: childElement, parameter: parameterSignature });
                } else {
                    const message = i18n.t('Unknown_child_element_0', {
                        element: node.name
                    });
                    messages.push({
                        message: message,
                        severity: DiagnosticSeverity.Error,
                        range: childElement.nameRange
                    });
                }
            } else {
                // embedded annotation - build targetKinds and targetType
                const childElement = node;
                const targetKinds = [element.name];
                if (types.length && types[0].asCollection) {
                    targetKinds.push(Edm.Collection);
                }
                messages.push(
                    ...checkValueForVariantType(valueHandlingContext.context, types, [], childElement.range, (type) => {
                        const targetType = convertValueTypeToString(type);
                        return checkAnnotationValue(
                            valueHandlingContext.context,
                            childElement,
                            valueHandlingContext.pathBase,
                            null,
                            '',
                            valueHandlingContext.aliasInfo,
                            targetTermMap,
                            checkTrace,
                            logger,
                            type?.constraints?.applicableTerms,
                            targetKinds,
                            targetType
                        );
                    })
                );
            }
        }
    });
    return { messages: messages, childElementIndex: childElementIndex };
}

function checkParameter(
    param: { node: Node; parameter: DynamicExpressionParameter },
    paramIndex: number,
    valueHandlingContext: ValueHandlingContext,
    types: ValueType[],
    element: Element,
    dynamicExpressionSignature: DynamicExpressionSignature,
    getPropertyNamesProvidingValueForType: GetPropertyNamesProvidingValueForTypeCallback,
    checkCallback: CheckCallback,
    checkTrace: CheckTrace,
    logger: Logger,
    requestedTypes,
    messages: Diagnostic[]
): void {
    const node = param.node;
    // check correct value
    let keepFacetsAndConstraints = true;
    const nodeHandlingContext = {
        ...valueHandlingContext,
        nodeContext: valueHandlingContext.nodeContext ? { ...valueHandlingContext.nodeContext } : null
    };

    const resolvedExpression = resolveDynamicExpressionTypes(
        nodeHandlingContext,
        paramIndex,
        dynamicExpressionSignature,
        element,
        requestedTypes
    );
    if (keepFacetsAndConstraints) {
        keepFacetsAndConstraints = resolvedExpression.keepFacetsAndConstraints;
    }
    const allowedTypes = resolvedExpression.possibleTypes;
    if (node.type === ATTRIBUTE_TYPE && (node as Attribute).name === param.parameter.name) {
        // type attribute: allowed types represent all allowed values
        const resolvedValue = resolveName((node as Attribute).value, valueHandlingContext.aliasInfo.aliasMap);
        if (!allowedTypes.filter((allowedType) => allowedType === resolvedValue.qName).length) {
            const message = i18n.t('Invalid_type_0', {
                type: (node as Attribute).value
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: (node as Attribute).valueRange
            });
        }
    } else {
        // check child element represents at least one of the types
        let childElement: Element = null;
        if (node.type === ELEMENT_TYPE) {
            childElement = node as Element; // use child element as it is
        } else {
            // Is it really needed ?
            childElement = createElementFromAttribute(node as Attribute);
        }
        // TODO: facets and constraints might not be equal for all requested types
        const allowedTypeObjects = allowedTypes.map((t) => ({
            ...convertValueTypeFromString(t),
            facets: keepFacetsAndConstraints ? types[0].facets : null,
            constraints: keepFacetsAndConstraints ? types[0].constraints : null
        }));

        messages.push(
            ...checkDynamicExpressionSubNode(
                nodeHandlingContext,
                allowedTypeObjects,
                childElement,
                element,
                getPropertyNamesProvidingValueForType,
                checkCallback,
                checkTrace,
                logger
            )
        );
    }
}

/**
 * Check dynamic expression
 * @param type - dynamic expression needs to comply to this type
 * @param element - value object representing dynamic expression (e.g. content of <Edm.If> tag in xmlJson)
 * @param pathBase - any relative paths start here (represents target object from metadata)
 */
export function checkDynamicExpression(
    valueHandlingContext: ValueHandlingContext,
    types: ValueType[],
    element: Element,
    parentElement: Element,
    dynamicExpressionSignature: DynamicExpressionSignature,
    adjustRequestedTypes: AdjustRequestedTypesCallback,
    getPropertyNamesProvidingValueForType: GetPropertyNamesProvidingValueForTypeCallback,
    checkCallback: CheckCallback,
    checkTrace: CheckTrace,
    logger: Logger
): Diagnostic[] {
    // read pattern and derive valid tag/attribute names
    let messages: Diagnostic[] = [];
    const containsError = (messages: Diagnostic[]): boolean => {
        return messages.some((m) => m.severity === DiagnosticSeverity.Error);
    };

    // check all present attributes and required number of subnodes (with correct types)
    // const propEntries: Array<{ node: Node; typeExpression: string }> = [];
    const parameters: Array<{ node: Node; parameter: DynamicExpressionParameter }> = [];
    const targetTermMap: Map<string, boolean> = new Map();

    let childElementIndex = -1;
    const resultcheckDynamiExpressionNode = checkDynamiExpressionNode(
        valueHandlingContext,
        types,
        element,
        dynamicExpressionSignature,
        checkTrace,
        logger,
        targetTermMap,
        parameters,
        childElementIndex,
        messages
    );
    messages = resultcheckDynamiExpressionNode.messages;
    childElementIndex = resultcheckDynamiExpressionNode.childElementIndex;

    if (!containsError(messages)) {
        const requestedTypes = adjustRequestedTypes(types, valueHandlingContext).map((t) =>
            convertValueTypeToString(t)
        );
        const isNullFound = parameters.some((p) => (p.node as Element).name === Edm.Null);
        valueHandlingContext.nodeContext.nullExpressionParameterFound =
            valueHandlingContext.nodeContext.nullExpressionParameterFound || isNullFound;
        parameters.forEach((param, paramIndex) => {
            checkParameter(
                param,
                paramIndex,
                valueHandlingContext,
                types,
                element,
                dynamicExpressionSignature,
                getPropertyNamesProvidingValueForType,
                checkCallback,
                checkTrace,
                logger,
                requestedTypes,
                messages
            );
        });
    }

    const param = dynamicExpressionSignature.parameters[childElementIndex + 1];
    if (param && !containsError(messages)) {
        const paramConstraints = typeof param.type === 'object' ? param.type.constraints : null;

        if (param.isMandatory && !(paramConstraints?.optionalWithInParent || []).includes(parentElement?.name as Edm)) {
            const message = i18n.t('Missing_mandatory_child_element_0_on_position_1', {
                elementName: element.name,
                position: String(childElementIndex + 2)
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: element.nameRange
            });
        }
    }

    return messages;
}

export function generateUnsupportedElementWarning(
    valueHandlingContext: ValueHandlingContext,
    element: Element
): Diagnostic {
    const message = i18n.t(
        'Element_0_and_its_child_elements_are_not_validated_by_current_version_of_XML_annotation_language_server',
        {
            element: element.name
        }
    );
    return {
        message: message,
        severity: DiagnosticSeverity.Information,
        range: valueHandlingContext.context.supportSplit ? element.contentRange : element.nameRange,
        rule: NO_VALIDATION_FOR_SUBNODES,
        data: valueHandlingContext.context.supportSplit ? { name: (element.content[0] as Element).name } : { name: '' }
    };
}

function checkDynamicExpressionSubNode(
    valueHandlingContext: ValueHandlingContext,
    types: ValueType[],
    childElement: Element,
    element: Element,
    getPropertyNamesProvidingValueForType: GetPropertyNamesProvidingValueForTypeCallback,
    checkCallback: CheckCallback,
    checkTrace: CheckTrace,
    logger: Logger
): Diagnostic[] {
    const elementNotSupported =
        (childElement.name === Edm.Record && valueHandlingContext.nodeContext?.noComplexTypeSupported) ||
        (childElement.name === Edm.Collection && valueHandlingContext.nodeContext?.noCollectionsSupported) ||
        (childElement.name === Edm.EnumMember &&
            valueHandlingContext.nodeContext?.noEnumTypeSupported &&
            !types.find(
                (t) =>
                    !t.name.startsWith('Edm') &&
                    valueHandlingContext.context.vocabularies.getType(t.name)?.kind === 'EnumType'
            ));
    if (elementNotSupported) {
        return [generateUnsupportedElementWarning(valueHandlingContext, childElement)];
    }
    const nodeValueTypeNames = getTypesForElement(valueHandlingContext, childElement, valueHandlingContext.pathBase);

    // Explicitly suppress validation of Null element
    // Better to do it generically?
    const skipValueTypeValidation =
        valueHandlingContext.nodeContext?.strictEqualityComparison && childElement.name === Edm.Null;

    const messages = checkValueForVariantType(
        valueHandlingContext.context,
        types,
        nodeValueTypeNames,
        childElement.range,
        (type) => {
            if (valueHandlingContext.nodeContext?.strictEqualityComparison && childElement.name === Edm.Null) {
                return []; // no diagnostic message if Null is used in EQ expression
            }
            const propNamesForValue = getPropertyNamesProvidingValueForType(valueHandlingContext, type);
            if (!Object.keys(propNamesForValue).includes(childElement.name)) {
                const message = i18n.t('Element_not_allowed_here_0', {
                    element: childElement.name
                });
                return [
                    {
                        message: message,
                        severity: DiagnosticSeverity.Error,
                        range: childElement.nameRange || childElement.range,
                        rule: 'record-collection-path-not-allowed',
                        data: {
                            name: childElement.name,
                            type
                        }
                    }
                ];
            }
            return [];
        }
    );
    if (messages.length && !skipValueTypeValidation) {
        return messages;
    }
    return checkCallback(valueHandlingContext, types, childElement, element, checkTrace, logger);
}

export function addDynamicExpressionsForAnyType(ccPropNames: { [key: string]: CompletionItemCategory }): {
    [key: string]: CompletionItemCategory;
} {
    dynamicExpressionSignatureMap.forEach((signature, name) => {
        const resultType = signature.resultType;
        const typeMatch =
            typeof resultType === 'object'
                ? resultType.name === EdmType.Untyped && resultType.constraints.compatibleWithRequestedType
                : resultType === EdmType.Untyped;
        if (typeMatch) {
            ccPropNames[name] = CompletionItemCategory.DynamicExpressionName;
        }
    });
    return ccPropNames;
}

function getTypesForElementDynamic(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    pathBase: any,
    types: string[]
): string[] {
    const resultType = dynamicExpressionSignatureMap.get(element.name as Edm).resultType;
    const resultTypeString = typeof resultType === 'object' ? resultType.name : resultType;
    if (primitiveTypeMap[resultTypeString]) {
        types.push(resultTypeString);
    } else if (resultTypeString === EdmType.Untyped && element.name === Edm.If) {
        // only case here is 'If', the potential type of which can be either the 2nd or 3rd (optional) parameter

        const secondArgument = getChildElementForPosition(1, element);
        types.push(...getTypesForElement(valueHandlingContext, secondArgument, pathBase));
        const thirdArgument = getChildElementForPosition(2, element);
        if (thirdArgument) {
            const thirdArgumentTypes = getTypesForElement(valueHandlingContext, thirdArgument, pathBase);
            (thirdArgumentTypes || []).forEach((type) => {
                if (!types.includes(type)) {
                    types.push(type);
                }
            });
        }
    }
    return types;
}

function getTypesForElementEnum(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    types: string[]
): string[] {
    const enumValue = getSingleTextNode(element);
    if (enumValue) {
        const tokens = enumValue.text.split(' ').filter((item) => !!item);
        const [ns, type] = getEnumValueSegments(tokens[0].trim());
        if (ns && type) {
            const resolvedTypeName = resolveName(ns + type.replace('/', ''), valueHandlingContext.aliasInfo.aliasMap);
            const enumType = valueHandlingContext.context.vocabularies.getType(resolvedTypeName.qName);
            if (enumType?.kind === 'EnumType') {
                types.push(resolvedTypeName.qName);
            }
        }
    }
    return types;
}

/**
 * Derived types from a value
 * This is needed for dynamic expressions like Eq where based on any first input, second input is restricted to a
 * 'comparable type' - type for first input needs to be inferred from it's actual value
 * @param element
 */
export function getTypesForElement(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    pathBase: any
): string[] {
    let types: string[] = [];
    if (element) {
        if (primitiveValueConstantExpressionMap[element.name]) {
            // default type for constant expression of primitive value
            types.push(primitiveValueConstantExpressionMap[element.name].defaultType);
        } else if (pathExpressionMap[element.name]) {
            // get path value, ex: to_Manager/PersonFullName
            const pathValue = getSingleTextNode(element)?.text;
            const pathValueType = getTypeOfPathExpression(pathValue || '', valueHandlingContext);
            if (pathValueType) {
                types.push(pathValueType);
            }
        } else if (dynamicExpressionSignatureMap.has(element.name as Edm)) {
            types = getTypesForElementDynamic(valueHandlingContext, element, pathBase, types);
        } else if (element.name === Edm.Apply) {
            const functionName = getElementAttributeValue(element, Edm.Function) as FunctionName;
            if (functionName) {
                types.push(...getFunctionResultTypes(functionName).map((t) => convertValueTypeToString(t)));
            }
        } else if (element.name === Edm.EnumMember) {
            types = getTypesForElementEnum(valueHandlingContext, element, types);
        }
    }
    return types;
}

function getTypeForComplex(
    valueHandlingContext: ValueHandlingContext,
    vocabularyType: ComplexType,
    valueType: ValueType,
    segment: string
) {
    let property: ComplexTypeProperty = vocabularyType.properties.get(segment);
    if (!property && vocabularyType.isAbstract) {
        // search the property in derived type records
        const derivedTypeNames = valueHandlingContext.context.vocabularies.getDerivedTypeNames(valueType.name);
        for (const key of [...derivedTypeNames.keys()]) {
            const vType = valueHandlingContext.context.vocabularies.getType(key);
            if (vType?.kind === 'ComplexType' && vType.properties.has(segment)) {
                property = vType.properties.get(segment);
                break;
            }
        }
    }
    if (property) {
        valueType = {
            name: property.type,
            asCollection: property.isCollection,
            constraints: property.constraints,
            facets: property.facets
        };
        return valueType;
    }
}

function getTypeForPrimitive(vocabularyType: TypeDefinition): ValueType {
    let valueType: ValueType;
    const type = vocabularyType.underlyingType || vocabularyType;
    if (typeof type === 'string') {
        valueType = { name: type };
    } else {
        valueType = {
            name: type.name,
            asCollection: false,
            constraints: type.constraints,
            facets: type.facets
        };
    }
    return valueType;
}

function getTypeOfPathExpressionForEmbeddedSegments(
    valueHandlingContext: ValueHandlingContext,
    embeddedSegments: string[],
    valueType: ValueType
): ValueType {
    for (let i = 0; i < embeddedSegments.length; i++) {
        const segment = embeddedSegments[i];

        if (valueType.asCollection && !isNaN(Number(segment))) {
            valueType.asCollection = false;
            continue;
        }

        const vocabularyType = valueHandlingContext.context.vocabularies.getType(valueType.name);
        if (!vocabularyType) {
            return;
        }
        if (vocabularyType.kind === 'ComplexType') {
            valueType = getTypeForComplex(valueHandlingContext, vocabularyType, valueType, segment);
            if (!valueType) {
                return;
            }
        } else if (vocabularyType.kind === 'EnumType') {
            valueType = {
                name: vocabularyType.name,
                asCollection: false
            };
        } else {
            // ToDo: unit test (is this really needed?)
            if (i === embeddedSegments.length - 1) {
                valueType = getTypeForPrimitive(vocabularyType);
            } else {
                return;
            }
        }
    }
    return valueType;
}

function getSegmentsInfo(segments: string[]): {
    targetPathSegments: string[];
    embeddedSegments: string[];
    termQualifier: string;
} {
    let termQualifier = '';
    const targetPathSegments = [];
    const embeddedSegments = [];
    (segments || []).forEach((segment) => {
        if (!termQualifier) {
            // before '@' collect target path segments
            const atIndex = segment.indexOf('@');
            if (atIndex < 0) {
                targetPathSegments.push(segment);
            } else {
                termQualifier = segment.slice(atIndex + 1);
            }
        } else {
            // after @ collect embedded segments
            embeddedSegments.push(segment);
        }
    });
    return { targetPathSegments: targetPathSegments, embeddedSegments: embeddedSegments, termQualifier: termQualifier };
}

export function getTypeOfPathExpression(pathValue: string, valueHandlingContext: ValueHandlingContext): string {
    // resolve target type of path expression

    // determine metadata path value for ex: Z1_PROJEC_SRV.Z1_C_ProjectType/to_Manager/PersonFullName
    const { segments } = determineSegmentsFromPath(pathValue, valueHandlingContext);
    const { targetPathSegments, embeddedSegments, termQualifier } = getSegmentsInfo(segments);
    const mdPathValue = targetPathSegments.join('/');
    // get target metadata element
    const targetMdElement = lookupTarget(
        valueHandlingContext.context,
        mdPathValue,
        valueHandlingContext.aliasInfo
    )?.metadataElement;
    if (!termQualifier) {
        return targetMdElement?.edmPrimitiveType;
    } else {
        const resolvedTermName = resolveName(
            termQualifier.split('#').shift(),
            valueHandlingContext.aliasInfo.aliasMapVocabulary
        );
        const term = valueHandlingContext.context.vocabularies.getTerm(resolvedTermName.qName);
        // exclude CDS ?
        if (!term || resolvedTermName.namespace === valueHandlingContext.context.vocabularies.cdsVocabulary.namespace) {
            return;
        }
        let valueType = getValueTypeFromTerm(valueHandlingContext.context, term);
        if (!embeddedSegments.length) {
            return convertValueTypeToString(valueType);
        } else {
            valueType = getTypeOfPathExpressionForEmbeddedSegments(valueHandlingContext, embeddedSegments, valueType);
            if (valueType) {
                return convertValueTypeToString(valueType);
            }
        }
    }
}

export function getAllowedTypesForDynamicExp(
    valueHandlingContext: ValueHandlingContext,
    dynamicExpressionSignature: DynamicExpressionSignature,
    element: Element,
    path: string,
    requestedTypes: string[]
): { allowedTypes: string[]; keepFacetsAndConstraints: boolean; completionItems: CompletionItem[] } {
    let allowedTypes: string[] = [];
    let keepFacetsAndConstraints = true;
    const completionItems: CompletionItem[] = [];

    let subNodePosition: number;

    // find where exactly the path is going
    const pathTargetInElement = getPathTargetInElement(path, element);
    if (pathTargetInElement.isElementSubNode) {
        // completion request for element sub node
        // find position among content elements (ignoring embedded annotations)
        subNodePosition = getChildElementPosition(pathTargetInElement.nodeIndex, element);
    }
    if (subNodePosition > -1) {
        const resolvedExpression = resolveDynamicExpressionTypes(
            valueHandlingContext,
            subNodePosition,
            dynamicExpressionSignature,
            element,
            requestedTypes
        );
        if (keepFacetsAndConstraints) {
            keepFacetsAndConstraints = resolvedExpression.keepFacetsAndConstraints;
        }
        allowedTypes = resolvedExpression.possibleTypes;
    }
    return {
        allowedTypes,
        completionItems: completionItems,
        keepFacetsAndConstraints: keepFacetsAndConstraints
    };
}

const setNodeContext = (valueHandlingContext: ValueHandlingContext, parameter: DynamicExpressionParameter) => {
    if (typeof parameter.type === 'object') {
        valueHandlingContext.nodeContext = {
            ...(valueHandlingContext.nodeContext || {}),
            noComplexTypeSupported:
                valueHandlingContext.nodeContext?.noComplexTypeSupported ||
                parameter.type.constraints?.noComplexTypeSupported,
            noEnumTypeSupported:
                valueHandlingContext.nodeContext?.noEnumTypeSupported ||
                parameter.type.constraints?.noEnumTypeSupported,
            noCollectionsSupported:
                valueHandlingContext.nodeContext?.noCollectionsSupported ||
                parameter.type.constraints?.noCollectionsSupported
        };
    }
};

function handleObject(
    valueHandlingContext: ValueHandlingContext,
    parameter: DynamicExpressionParameter,
    signature: DynamicExpressionSignature,
    requestedTypes: string[],
    element: Element
): { valueHandlingContext: ValueHandlingContext; possibleTypes: string[]; keepFacetsAndConstraints: boolean } {
    let possibleTypes: string[] = [];
    let keepFacetsAndConstraints = false;
    const parType = parameter.type as DynamicExpressionType;
    const compTypeParameterIndex = parType.constraints?.comparableTypeParameterIndex;

    if (compTypeParameterIndex >= 0) {
        valueHandlingContext.nodeContext = {
            nullExpressionParameterFound: valueHandlingContext.nodeContext?.nullExpressionParameterFound,
            nestedNodesMessages: valueHandlingContext.nodeContext?.nestedNodesMessages
        };
        const compParameter = signature.parameters[compTypeParameterIndex];
        // find type of value provided for compTypeParameter
        const compTypeParValue = getChildElementForPosition(compTypeParameterIndex, element);
        if (compTypeParValue.name === Edm.Null) {
            // For Null any type is comparable
            // Boolean is chosen as default just to trigger validation handler for current parameter value
            // unjustified error messages regarding wrong type should be filtered out on parent element level
            possibleTypes = [EdmType.PrimitiveType];
        } else {
            possibleTypes = getComparableTypes(
                getTypesForElement(valueHandlingContext, compTypeParValue, valueHandlingContext.pathBase)
            );
        }
        if (parType.isCollection) {
            valueHandlingContext.nodeContext.restrictedTypes = possibleTypes as EdmType[];
            possibleTypes = [
                convertDynamicExpressionTypeToString(
                    parType.name === EdmType.Untyped ? { ...parType, name: EdmType.PrimitiveType } : parType
                )
            ];
        }
        keepFacetsAndConstraints = !!(
            typeof compParameter.type === 'object' && compParameter.type.constraints?.compatibleWithRequestedType
        );
    } else if (parType.constraints?.compatibleWithRequestedType) {
        possibleTypes = requestedTypes;
        keepFacetsAndConstraints = true;
    } else if (parType.name === EdmType.Untyped || parType.name === EdmType.PrimitiveType) {
        possibleTypes.push(
            convertValueTypeToString({ name: EdmType.PrimitiveType, asCollection: parType.isCollection })
        );
        valueHandlingContext.nodeContext = {
            nullExpressionParameterFound: valueHandlingContext.nodeContext?.nullExpressionParameterFound,
            nestedNodesMessages: valueHandlingContext.nodeContext?.nestedNodesMessages
        };
    } else {
        possibleTypes.push(
            convertDynamicExpressionTypeToString(
                (parType.name as EdmType) === EdmType.Untyped ? { ...parType, name: EdmType.PrimitiveType } : parType
            )
        );
        valueHandlingContext.nodeContext = {
            nullExpressionParameterFound: valueHandlingContext.nodeContext?.nullExpressionParameterFound,
            nestedNodesMessages: valueHandlingContext.nodeContext?.nestedNodesMessages
        };
    }
    // remove key, if value is undefined.
    Object.keys(valueHandlingContext.nodeContext).forEach(
        (key) => valueHandlingContext.nodeContext[key] === undefined && delete valueHandlingContext.nodeContext[key]
    );
    setNodeContext(valueHandlingContext, parameter);

    return {
        valueHandlingContext: valueHandlingContext,
        possibleTypes: possibleTypes,
        keepFacetsAndConstraints: keepFacetsAndConstraints
    };
}

/**
 * Resolve dynamic expression types
 *
 * @param valueHandlingContext
 * @param parameterIndex - index of parameter for which allowed types should be determined
 * @param signature - of dynmaic expression
 * @param element - representing dynamic expression
 * @param requestedTypes
 */
export function resolveDynamicExpressionTypes(
    valueHandlingContext: ValueHandlingContext,
    parameterIndex: number,
    signature: DynamicExpressionSignature,
    element: Element,
    requestedTypes: string[]
): { possibleTypes: string[]; keepFacetsAndConstraints: boolean } {
    let possibleTypes: string[] = [];
    let keepFacetsAndConstraints = false;
    const parameter = signature.parameters[parameterIndex];
    // extract argument
    if (typeof parameter.type === 'object') {
        ({ valueHandlingContext, possibleTypes, keepFacetsAndConstraints } = handleObject(
            valueHandlingContext,
            parameter,
            signature,
            requestedTypes,
            element
        ));
    } else {
        valueHandlingContext.nodeContext = {
            nullExpressionParameterFound: valueHandlingContext.nodeContext?.nullExpressionParameterFound,
            nestedNodesMessages: valueHandlingContext.nodeContext?.nestedNodesMessages
        };
        if (parameter.type === EdmType.Untyped || parameter.type === EdmType.PrimitiveType) {
            possibleTypes.push(EdmType.PrimitiveType);
        } else {
            possibleTypes.push(parameter.type);
        }
    }

    if (signature.metadata?.comparisonOperator) {
        valueHandlingContext.nodeContext = {
            ...(valueHandlingContext.nodeContext || {}),
            comparisonOperator: true,
            strictEqualityComparison: !!signature.metadata.strictEqualityComparison
        };
    }

    // remove key, if value is undefined.
    Object.keys(valueHandlingContext.nodeContext).forEach(
        (key) =>
            (key === 'nullExpressionParameterFound' || key === 'nestedNodesMessages') &&
            valueHandlingContext.nodeContext[key] === undefined &&
            delete valueHandlingContext.nodeContext[key]
    );
    return {
        possibleTypes: possibleTypes,
        keepFacetsAndConstraints: keepFacetsAndConstraints
    };
}

export function getComparableTypes(requiredTypes: string[]): string[] {
    const comparableTypeSet: Set<string> = new Set();
    requiredTypes.forEach((type) => {
        if (!comparableTypeSet.has(type)) {
            const valueType = convertValueTypeFromString(type);
            if (valueType.asCollection) {
                comparableTypeSet.add(type);
            } else {
                const typeGroup = primitiveTypeMap[type]?.compatibleTypeGroup;
                if (primitiveTypeMap[type]?.compatibleTypeGroup) {
                    Object.keys(primitiveTypeMap)
                        .filter((key) => primitiveTypeMap[key].compatibleTypeGroup === typeGroup)
                        .forEach((key) => comparableTypeSet.add(key));
                } else {
                    comparableTypeSet.add(type);
                }
            }
        }
    });
    return [...comparableTypeSet.keys()];
}

export function convertDynamicExpressionTypeToString(type: DynamicExpressionType): string {
    return convertValueTypeToString(convertDynamicExpressionTypeToValueType(type));
}

export function convertDynamicExpressionTypeToValueType(type: EdmType | DynamicExpressionType): ValueType {
    if (typeof type === 'object') {
        return {
            name: type.name,
            asCollection: type.isCollection
        };
    } else {
        return {
            name: type
        };
    }
}

function processParameters(parameters, values: MarkdownString[]) {
    (parameters || []).forEach((parameter, index) => {
        let text = '';
        const type = Array.isArray(parameter.type) ? parameter.type[0] : parameter.type;
        const typeDefinition: DynamicExpressionType = typeof type === 'object' ? type : null;
        let typeText = typeof type === 'string' ? type : typeDefinition.name;
        if (typeText === EdmType.Untyped) {
            typeText = EdmType.PrimitiveType;
        }
        if (typeDefinition) {
            if (!isNaN(typeDefinition.constraints?.comparableTypeParameterIndex)) {
                typeText =
                    'comparable with argument in position ' +
                    (typeDefinition.constraints?.comparableTypeParameterIndex + 1);
            }
            if (typeDefinition.constraints?.compatibleWithRequestedType) {
                typeText = 'compatible with the type expected by the surrounding element or expression';
            }
            if (typeDefinition.isCollection) {
                typeText = 'Collection(' + typeText + ')';
            }
        }
        text += 'Type: ' + typeText;
        if (parameter?.isMandatory) {
            text += '. Mandatory';
        }
        if (typeDefinition?.constraints?.optionalWithInParent) {
            text += ` (optional if parent element is ${typeDefinition?.constraints?.optionalWithInParent.join(
                ' or '
            )})`;
        }

        values.push(`**Argument ${index + 1}:** ${text} \n`);
    });
    return values;
}

/**
 * Get dynamic expression documentation (used for hover and code completion)
 * (no translation required - we also don't have it for vocabulary based documentation)
 * @param functionName
 */
export function getDynamicExpressionDocumentation(elementName: Edm): MarkdownString[] {
    const signature = dynamicExpressionSignatureMap.get(elementName);
    const doc = dynamicExpressionDocumentations.get(elementName);
    const isComparisonOperator = signature.metadata?.comparisonOperator;
    if (!signature || !doc) {
        return null;
    }

    let values: MarkdownString[] = [];

    values.push(`**Name:** ${elementName} \n`);
    values.push(`**Description:** ${doc.description} \n`);
    if (isComparisonOperator) {
        values.push(comparisonOperatorDescription + '\n');
    }
    values = processParameters(signature?.parameters, values);
    const resultType: ValueType = convertParameterTypeToValueType(signature.resultType);
    if (
        resultType.name === EdmType.Untyped &&
        typeof signature.resultType === 'object' &&
        signature.resultType.constraints?.compatibleWithRequestedType
    ) {
        values.push(`**ReturnType:** compatible with the type expected by the surrounding element or expression \n`);
    } else {
        values.push(`**ReturnType:** ${convertValueTypeToString(resultType)} \n`);
    }

    if (doc.note) {
        values.push(`**Note:** ${doc.note} \n`);
    }

    return values;
}
