import type { CompletionItem, Position } from 'vscode-languageserver';
import { VocabularyService } from '@sap-ux/odata-vocabularies';
import type { Element } from '@sap-ux/odata-annotation-core';
import { ELEMENT_TYPE, TEXT_TYPE, positionContained, Edm } from '@sap-ux/odata-annotation-core';

import type { AnnotationNode, Node } from '@sap-ux/cds-annotation-parser';
import { ANNOTATION_GROUP_TYPE } from '@sap-ux/cds-annotation-parser';

import type { CompletionHandlerArgs, ProviderResult, CompletionContext } from './types';

const vocabularyService = new VocabularyService(true);
export function getAliasesFromTermCompletionItems(items: CompletionItem[]): string[] {
    const aliasSet = new Set<string>();
    for (const item of items) {
        const vocabularyAlias = item.label.split('.')[0];
        if (
            vocabularyService.cdsVocabulary.groupNames.has(vocabularyAlias) ||
            vocabularyService.cdsVocabulary.singletonNames.has(vocabularyAlias)
        ) {
            continue;
        }
        if (!aliasSet.has(vocabularyAlias)) {
            aliasSet.add(vocabularyAlias);
        }
    }
    return [...aliasSet];
}

export function basicItemProvider(
    context: CompletionContext,
    { getCompletionItems, file, pointer, position }: CompletionHandlerArgs
): ProviderResult {
    const segments = pointer.split('/').slice(1);
    const isTargetContext = segments.length === 2 && segments[0] === 'targets';
    const items = getCompletionItems(file, position, isTargetContext, pointer);
    return {
        itemsForAdapter: items,
        completionItems: []
    };
}

export function recordTypeItemsProvider(
    context: CompletionContext,
    { getCompletionItems, file, pointer, position }: CompletionHandlerArgs
): ProviderResult {
    const segments = pointer.split('/');
    const targetSegments = segments.slice(1);
    const isTargetContext = targetSegments.length === 2 && targetSegments[0] === 'targets';
    segments.pop();
    const newPointer = [...segments, 'attributes', Edm.Type, 'value'].join('/');
    const items = getCompletionItems(file, position, isTargetContext, newPointer);
    return {
        itemsForAdapter: items,
        completionItems: []
    };
}

export function updatePlaceholder(snippet: Element, isEmbeddedAnnotationSnippet: boolean): void {
    // adapt snippet for printing qualifier tabstop
    const attrNames = Object.keys(snippet.attributes ?? {});
    if (!attrNames.includes('Qualifier') && !isEmbeddedAnnotationSnippet) {
        const qualifierTabAttr = attrNames.find(
            // looking in the original item because $x attributes are removed from snippet by stringify/parse transformation
            (attrName) => attrName.match(/\$\d/) && !(snippet.attributes ?? {})[attrName].value
        );
        const valueAttrName = attrNames.find((attrName) => snippet.attributes[attrName].value?.match(/\$\d/));
        const hasValue = valueAttrName || (snippet.content || []).length;
        if (qualifierTabAttr === '$0') {
            // qualifier tab stop is final, put final tabstop to primitive value attribute (if exists)
            if (valueAttrName) {
                snippet.attributes[valueAttrName].value = '$0';
            }
            delete snippet.attributes[qualifierTabAttr];
        }
        if (qualifierTabAttr && attrNames.includes('Term')) {
            // add tab stop for qualifier if it was found in snippet
            snippet.attributes['Term'].value += hasValue ? ' $1' : ' $0';
        }
    }
}

function nodeMatcherWithPosition(position: Position): (node: Node) => boolean {
    return (node: Node): boolean => positionContained(node.range, position);
}

export function findNodeWithMatchingPosition<T extends Node>(nodes: T[], position: Position): T | undefined {
    return nodes.find(nodeMatcherWithPosition(position));
}

export const wrapWithExclamationSquareBrackets = (text: string, includeAtSymbol?: boolean): string => {
    return `![${includeAtSymbol ? '@' : ''}${text}]`;
};

export function getContainingAnnotationDetails(
    path: AnnotationNode[]
): { termName: string; termQualifier?: string } | undefined {
    for (let index = path.length - 1; index >= 0; index--) {
        const node = path[index];
        if (node.type === 'annotation') {
            const groupName = index === 2 && path[0].type === ANNOTATION_GROUP_TYPE ? path[0].name.value : undefined;
            const termName = node.term.value;
            const termQualifier = node?.qualifier?.value;
            return {
                termName: [groupName, termName].filter((value) => !!value).join('.'),
                termQualifier
            };
        }
    }
}

export function fixApplyTabStops(snippet: Element): void {
    if (!snippet.content) {
        return;
    }
    const labeledElement = snippet.content[1];
    if (!labeledElement) {
        return;
    }
    if (labeledElement.type === ELEMENT_TYPE) {
        if (labeledElement.attributes && labeledElement.attributes['$0']) {
            delete labeledElement.attributes['$0'];
        }
        if (labeledElement.attributes && labeledElement.attributes['Name']) {
            labeledElement.attributes['Name'].value = '$0';
        }
        labeledElement.content = [
            {
                type: TEXT_TYPE,
                text: '$2'
            }
        ];
    }
}
