import type { AttributeName, AttributeValue, Element, ElementName, TextValue } from '@sap-ux/odata-annotation-core';
import type { MarkupContent, Range } from 'vscode-languageserver-types';

export enum CompletionItemCategory {
    // OData kinds ?
    Term = 'Term',
    EnumerationMember = 'EnumerationMember',
    EntityContainer = 'EntityContainer',
    EntitySet = 'EntitySet',
    EntityType = 'EntityType',
    NavigationProperty = 'NavigationProperty',
    ComplexType = 'ComplexType',
    Property = 'Property',
    Function = 'Function',
    FunctionImport = 'FunctionImport',
    Parameter = 'Parameter',
    ReturnType = 'ReturnType',
    Action = 'Action',
    ActionImport = 'ActionImport',
    // Name space categories
    OwnNamespace = 'OwnNamespaceName',
    VocabularyNamespace = 'VocabularyNamespace',
    MetadataNamespace = 'MetadataNamespaceName',
    // OData Expressions
    ConstantExpressionName = 'ConstantExpressionName',
    DynamicExpressionName = 'DynamicExpressionName',
    // elements
    ValueElement = 'ValueElement',
    ValueElementSet = 'ValueElementSet',
    PathKind = 'PathKind',
    Annotation = 'Annotation',
    Path = 'Path',
    Qualifier = 'Qualifier',
    Apply = 'Apply',

    Unknown = 'Unknown'
}

export enum CommitCharacter {
    Dot = '.',
    ForwardSlash = '/'
}

export enum CompletionItemType {
    Regular = 'Regular',
    Snippet = 'Snippet'
}

interface SortingProperties {
    isAlias?: boolean;
    isUIVocabulary?: boolean;
    isRelativePath?: boolean;
    isAbsolutePath?: boolean;
    isAnnotationPath?: boolean;
    isAssociation?: boolean;
    isGroup?: boolean; //group among siblings with same flags
    isNotMandatory?: boolean;
}

export interface CompletionItem {
    name: string; // used to eliminate duplicates (in simple cases: the completed string)
    text: string; // text to be applied (via insert or replace)
    affectedRange?: Range; // in replace mode: range to be replaced (if replace or not will be decided centrally)
    category?: CompletionItemCategory; // enum member for possible categories; will be mapped to LSP kind centrally
    id?: string; // together with category: provide basis for generation of documentation
    commitCharacters?: string[];
    commitCharacterRequired?: boolean; // item only valid if followed by one of the commit characters
    sorting?: SortingProperties;
    documentation?: string | MarkupContent;
    deprecated?: boolean;
    type?: CompletionItemType;
    detail?: string;
    sortText?: string;
    insertText?: string;
    data?: any;
    filterText?: string;
}

export type CompletionItemMap = { [name: string]: CompletionItem };

export const ACTION_FUNCTION_NAME_OBJECT_TYPE = 'ACTION_FUNCTION_NAME';

export interface ActionFunctionNameValue {
    kind: typeof ACTION_FUNCTION_NAME_OBJECT_TYPE;
    name: string;
    namespace: string;
    entityContainer?: string;
    toString: () => string;
    forCompletion?: boolean;
    targetKind: string;
}

export interface Property {
    name: ElementName | AttributeName;
    nameRange: Range;
    value: AttributeValue | TextValue | Element;
    isStringValue: boolean;
    valueRange: Range;
}
