import type { FileUri } from '@sap-ux/odata-annotation-core';
import type { Project } from '@sapux/project-spec';
import type { ServiceName } from '../types';

export interface AnnotationFileDescriptor {
    fileUri: FileUri;
    readonly: boolean;
}
export type GetProjectFilesResult = {
    annotationFiles: AnnotationFileDescriptor[]; // for EDMX: includes metadata file on first position
    metadataXmlFileUri?: FileUri;
};

export function getProjectFiles(project: Project, serviceName: ServiceName, appName?: string): GetProjectFilesResult {
    const result: GetProjectFilesResult = { annotationFiles: [] };

    // find app - use first app if no appName is provided
    const app = project.apps[appName || Object.keys(project.apps)[0]];
    const service = app?.services[serviceName];

    // EDMX: local copies of metadata file and backend annotation file
    let backendAnnotationFileUri = '';
    if (service?.local) {
        result.metadataXmlFileUri = service.local;
        result.annotationFiles.push({ fileUri: result.metadataXmlFileUri, readonly: true });
    }
    if (service?.annotations?.local) {
        backendAnnotationFileUri = service.annotations.local;
    }
    // EDMX/CDS: annotation files (for CDS all relevant cds files)
    if (app?.annotations?.[serviceName]) {
        for (const [, file] of app.annotations[serviceName].entries()) {
            const fileUri = file;
            const readonly = fileUri === backendAnnotationFileUri;
            result.annotationFiles.push({ fileUri, readonly });
        }
    }
    return result;
}

/**
 * Returns service file properties
 * @param project - project object
 * @param serviceName - service name
 * @param fileUri - service file Uri as string
 * @param appName - app name
 */
export function getFileProperties(
    project: Project,
    serviceName: ServiceName,
    fileUri: FileUri,
    appName?: string
): { readOnly: boolean; containsMetadata: boolean } | undefined {
    const result = getProjectFiles(project, serviceName, appName);
    const file = result.annotationFiles.find(
        (entry) =>
            (entry && entry.fileUri === fileUri) || entry.fileUri.replace(/\\/g, '/') === fileUri.replace(/\\/g, '/')
    );
    if (file) {
        const containsMetadata = result.metadataXmlFileUri
            ? result.metadataXmlFileUri === fileUri.replace(/\\/g, '/')
            : true;
        const isCsnFile = file.fileUri.endsWith('.csn');
        return { readOnly: file.readonly || isCsnFile, containsMetadata };
    } else {
        return undefined;
    }
}
