import type { MetadataElement } from '@sap-ux/odata-annotation-core-types';
import type { CdsCompilerFacade } from '..';

export const RETURN_PARAM_NAME = '$Return';
export const TYPE_NAME_OF_BINDING_PARAMETER = '$self';

export const IS_ACTIVE_ENTITY_ELEM_NAME = 'IsActiveEntity';
export const HAS_ACTIVE_ENTITY_ELEM_NAME = 'HasActiveEntity';

export const ENTITY_PREFIX_LOCALIZED = 'localized.'; // prefix of generated entity to support localization of texts
export const ASSOCIATION_NAME_LOCALIZED = 'localized'; // generated associations to localized entity

export interface MetadataElementWithParentKey {
    node: MetadataElement;
    parentKey?: string; // contains key to find parent node in MetadataCollector.metadataElementMap
}

/**
 * Map representing already collected metadata
 * Key string represents "cds-path" (e.g. "AdminService.SafetyIncidents/ID")
 *  - segments are separated by '/'
 *  - first segment is fully qualified name of entity or (unbound) action/function
 *  - followup segments can represent element names, names of (bound) actions/function, and their parameter names (including "in" and "$Return")
 *  - segments representing actions/functions have postfix "()" to avoid name collisions (e.g. "OrderService.cancelOrder()")
 */
export type MetadataElementMap = Map<string, MetadataElementWithParentKey>;

/**
 * Used to build up metadata in a lazy way
 * If metadataElementMap does not contain a metadata element, it is build up (including all parents) based on facade methods
 */
export interface MetadataCollector {
    metadataElementMap: MetadataElementMap;
    facade?: CdsCompilerFacade;
    draftNodesPerService: Map<string, Set<string>>; // draft node entity names per service name
}

/**
 * Create MetadataCollector instance
 * @param metadataElementMap
 * @param facade
 */
export const createMetadataCollector = (
    metadataElementMap?: MetadataElementMap,
    facade?: CdsCompilerFacade
): MetadataCollector => {
    const metadataCollector = getMetadataCollector(metadataElementMap);
    if (facade) {
        metadataCollector.facade = facade;
    }
    return metadataCollector;
};

/**
 * Get MetadataCollector instance
 * @param metadataElementMap
 */
export function getMetadataCollector(metadataElementMap?: MetadataElementMap): MetadataCollector {
    return {
        metadataElementMap: metadataElementMap || new Map(),
        draftNodesPerService: new Map()
    };
}

/**
 * Get array of metadata elements (to be handed over to generic component)
 * @param metadataElementMap
 */
export const getMetadataElementsFromMap = (metadataElementMap: MetadataElementMap): MetadataElement[] => {
    // only entries without parent are relevant; remaining entries are in contained in their content[]
    const result: (MetadataElement | undefined)[] = [...metadataElementMap.keys()]
        .filter((key) => !metadataElementMap?.get(key)?.parentKey)
        .map((key) => metadataElementMap?.get(key)?.node);
    return result.filter((val): val is MetadataElement => val !== undefined);
};
