import { VocabularyService } from '@sap-ux/odata-vocabularies';
import { createMetadataCollector } from '@sap/ux-cds-compiler-facade';
import type { MetadataElementMap } from '@sap/ux-cds-compiler-facade';
import { toAnnotationFile, toTargetMap, adjustCdsTermNames } from '@sap/ux-cds-odata-annotation-converter';
import type { Expression } from '@sap-ux/cds-annotation-parser';
import { ENUM_TYPE, EXPRESSION_TYPES, containsIncorrectExpressions, parse } from '@sap-ux/cds-annotation-parser';

import { prepareAnnotationService } from '../annotationService';
import type { CdsHover, CdsHoverParams } from '../lspTypes';

import { Position } from '@sap-ux/odata-annotation-core';
import { getPathToNode } from '../utils/pointer';

const vocabularyService = new VocabularyService(true);

export const getHover = ({ cursorPosition, annotation, index }: CdsHoverParams): CdsHover | undefined => {
    const { position, textDocument } = cursorPosition;
    // build dummy metadata containing all targets of annotation file (as entities)
    // hover does not depend much on metadata, only target path for current position must exist as metadata element
    const metadataElementMap: MetadataElementMap = new Map();
    const cdsAnnotationFile = toTargetMap(index.forUri(textDocument.uri), textDocument.uri, vocabularyService);
    cdsAnnotationFile.targetMap.forEach((target) =>
        metadataElementMap.set(target.name, {
            node: {
                kind: 'entity',
                path: target.name,
                isEntityType: true,
                isCollectionValued: true,
                isComplexType: false,
                isAnnotatable: true,
                name: target.name,
                content: [],
                targetKinds: ['EntityType']
            }
        })
    );

    const metadataCollector = createMetadataCollector(metadataElementMap);
    const {
        file: annotationFile,
        pointer,
        nodeRange
    } = toAnnotationFile(textDocument.uri, vocabularyService, cdsAnnotationFile, metadataCollector, position);

    // suppress any hover in CDS expressions, except for enum values in correct expressions
    const startPosition = Position.create(annotation.line, annotation.character);
    const assignment = adjustCdsTermNames(parse(annotation.text, startPosition), vocabularyService.cdsVocabulary);
    if (assignment) {
        const pathToNode = getPathToNode(assignment, position);
        const outermostExpression = pathToNode.find((node) => EXPRESSION_TYPES.includes(node.type));
        if (outermostExpression) {
            const targetNode = pathToNode[pathToNode.length - 1];
            if (containsIncorrectExpressions(outermostExpression as Expression) || targetNode.type !== ENUM_TYPE) {
                return;
            }
        }
    }

    // let generic annotation service evaluate the hover
    const genericAnnotationService = prepareAnnotationService(
        vocabularyService,
        index,
        textDocument.uri,
        annotationFile,
        metadataCollector,
        { includeDependencies: false }
    );

    const hover = genericAnnotationService.hover(textDocument.uri, position, pointer);
    if (hover) {
        // if range is omitted, CDS LSP seems to set the range for the content for the target
        hover.range = nodeRange || hover.range || { start: position, end: position };
    }
    return hover as CdsHover;
};
