import { Position, Range } from 'vscode-languageserver';

import type { AnnotationNode, Path } from '@sap-ux/cds-annotation-parser';
import {
    PATH_TYPE,
    ANNOTATION_TYPE,
    ANNOTATION_GROUP_ITEMS_TYPE,
    ANNOTATION_GROUP_TYPE
} from '@sap-ux/cds-annotation-parser';
import { positionContained } from '@sap-ux/odata-annotation-core';

import { nodeHasComma } from '../../../utils/hasComma';
import type {
    AnnotationGroupContainerContext,
    CompletionContextResolverArgs,
    NestedAnnotationTermNameContext,
    PropertyNameContext,
    TermNameContext
} from '../types';

export function termNameResolver({
    pathToNode,
    position,
    targetNode
}: CompletionContextResolverArgs): PropertyNameContext | TermNameContext | NestedAnnotationTermNameContext | undefined {
    if (
        pathToNode.length !== 2 ||
        targetNode.type !== PATH_TYPE ||
        pathToNode[0].type !== ANNOTATION_TYPE ||
        pathToNode[0].term !== targetNode
    ) {
        return;
    }
    const termSegmentIdx = targetNode.segments.findIndex((s) => positionContained(s.range, position));
    const termSegment = targetNode.segments[termSegmentIdx];
    const isQuoted = termSegment?.quoted ?? false;

    if (targetNode.segments.length > 2) {
        // flattened annotation
        const targetIndex = targetNode.segments.findIndex((segment) => positionContained(segment.range, position));
        if (targetIndex > 1) {
            return buildContextFlattened(targetNode, targetIndex, pathToNode, isQuoted);
        }
    }

    // If namespace segment is out of quotes, then it remains unchanged (considered as group name)
    const annotationGroupName =
        isQuoted && termSegmentIdx > 0 && !targetNode.segments[termSegmentIdx - 1].quoted
            ? targetNode.segments[termSegmentIdx - 1].value
            : undefined;
    const proposedReplacementRange = annotationGroupName
        ? Range.create(
              Position.create(termSegment.range.start.line, termSegment.range.start.character - 2),
              targetNode.range.end
          )
        : targetNode.range;
    return {
        type: 'key',
        kind: 'term-name',
        pathToNode,
        isQuoted,
        annotationGroupName,
        proposedReplacementRange
    };
}

function buildContextFlattened(
    targetNode: Path,
    targetIndex: number,
    pathToNode: AnnotationNode[],
    isQuoted: boolean
): PropertyNameContext | NestedAnnotationTermNameContext {
    const propertyNameNode = targetNode.segments[targetIndex];
    const propertyNameNodePrev = targetNode.segments[targetIndex - 1];
    let context: PropertyNameContext | TermNameContext | NestedAnnotationTermNameContext;
    if (propertyNameNode.value.startsWith('@') || propertyNameNodePrev.value.startsWith('@')) {
        const propertyNameNodeEnd = targetNode.segments[targetIndex + 1] || propertyNameNode;
        const proposedReplacementRange: Range = propertyNameNode.value.startsWith('@')
            ? { start: propertyNameNode.range.start, end: propertyNameNodeEnd.range.end }
            : { start: propertyNameNodePrev.range.start, end: propertyNameNode.range.end };
        context = {
            type: 'key',
            kind: 'nested-term-name',
            pathToNode,
            flattened: true,
            isQuoted,
            proposedReplacementRange
        };
    } else {
        context = {
            type: 'key',
            kind: 'property-name',
            pathToNode,
            proposedReplacementRange: propertyNameNode.range,
            isQuoted: propertyNameNode.quoted ?? false,
            flattened: true,
            propertyName: propertyNameNode.value
        };
    }
    return context;
}

export function termNameInGroupResolver({
    pathToNode,
    position,
    targetNode
}: CompletionContextResolverArgs): TermNameContext | PropertyNameContext | AnnotationGroupContainerContext | undefined {
    if (pathToNode.length !== 4) {
        return;
    }
    if (
        pathToNode[0].type === ANNOTATION_GROUP_TYPE &&
        pathToNode[1].type === ANNOTATION_GROUP_ITEMS_TYPE &&
        pathToNode[2].type === ANNOTATION_TYPE &&
        pathToNode[3] === pathToNode[2].term
    ) {
        const groupNode = pathToNode[0];
        const segmentIdx = pathToNode[3].segments.findIndex((s) => positionContained(s.range, position));
        const segment = pathToNode[3].segments[segmentIdx];
        const isQuoted = segment?.quoted ?? false;
        if (segmentIdx > 0) {
            return {
                type: 'key',
                kind: 'property-name',
                isQuoted,
                pathToNode,
                proposedReplacementRange: segment.range,
                flattened: true,
                propertyName: segment.value
            };
        } else {
            if (pathToNode[2].value !== undefined) {
                return {
                    type: 'key',
                    kind: 'term-name',
                    pathToNode,
                    annotationGroupName: groupNode.name.value,
                    isQuoted,
                    proposedReplacementRange: pathToNode[3].range
                };
            } else {
                return {
                    type: 'container',
                    kind: 'annotation-group',
                    pathToNode,
                    position,
                    groupName: groupNode.name.value,
                    proposedReplacementRange: targetNode.range,
                    hasComma: nodeHasComma(pathToNode, position)
                };
            }
        }
    }
}
