import type { VocabularyType } from '@sap-ux/odata-vocabularies';
import { Snippet } from './snippet';
import type { SnippetHandlingContext } from '.';
import { Edm } from '@sap-ux/odata-annotation-core';
import { createCollectionSnippet } from './collection';

/**
 * Generates LabeledElement snippet
 * @param snippetContext
 * @param vocabularyType
 * @param name
 * @param initialTabStopId
 * @param addFinalTabstop
 */
export function createLabeledElementSnippet(
    snippetContext: SnippetHandlingContext,
    vocabularyType: VocabularyType,
    name?: string,
    initialTabStopId = 1,
    addFinalTabstop = false
): Snippet {
    const labeledElement = new Snippet(Edm.LabeledElement, snippetContext.useSnippets, initialTabStopId);
    if (name) {
        labeledElement.setAttribute(Edm.Name, name);
    }
    labeledElement.addMandatoryAttributesWithTabStops();
    if (snippetContext.type.asCollection) {
        const collection = createCollectionSnippet(
            { ...snippetContext, type: { ...snippetContext.type, asCollection: false } },
            vocabularyType,
            initialTabStopId,
            addFinalTabstop
        );
        labeledElement.tabStopId = collection.getNextTabStopId();
        labeledElement.appendContent(collection);
    } else if (vocabularyType && vocabularyType.kind === Edm.ComplexType) {
        // TODO: support records as parameters
    } else {
        // adding value providing attribute tabstop
        labeledElement.setAttributeAsTabStop(addFinalTabstop ? 0 : labeledElement.getNextTabStopId());
    }
    return labeledElement;
}
