/**
 * paths
 * url://docs.oasis-open.org/odata/odata-csdl-xml/v4.01/cs01/odata-csdl-xml-v4.01-cs01.html#sec_BuiltInTypesfordefiningVocabularyTer
 */

export interface PathType {
    name: FullyQualifiedName;
    defaultExpressionName: ElementName | AttributeName;
    isAbstract: boolean;
    validNonAbstractPathTypes?: FullyQualifiedName[]; // required if isAbstract = true
}

/**
 * Map containing all path expressions (which can be used for specifying a path type)
 * http://docs.oasis-open.org/odata/odata-csdl-xml/v4.01/cs01/odata-csdl-xml-v4.01-cs01.html#sec_PathExpressions
 * All path expressions can be provided in element or attribute notation
 */
export const pathExpressionMap: {
    [name: string]: {
        supportedTypes: { [type: string]: true };
        defaultType: FullyQualifiedName;
        isInstancePath: boolean;
    };
} = {
    // for Path: no map of supported types and no default type!
    Path: { supportedTypes: null, defaultType: null, isInstancePath: true }
};

function asPathType(
    name: FullyQualifiedName,
    isAbstract: boolean,
    defaultExpressionName: ElementName | AttributeName,
    validNonAbstractPathTypes?: FullyQualifiedName[], // required if isAbstract = true
    defaultTypeForExpressionName?: FullyQualifiedName
): PathType {
    if (defaultExpressionName) {
        if (!pathExpressionMap[defaultExpressionName]) {
            pathExpressionMap[defaultExpressionName] = { supportedTypes: {}, defaultType: null, isInstancePath: false };
        }
        pathExpressionMap[defaultExpressionName].supportedTypes[name] = true;
        pathExpressionMap[defaultExpressionName].defaultType = defaultTypeForExpressionName;
    }
    return {
        name: name,
        defaultExpressionName: defaultExpressionName,
        isAbstract: isAbstract,
        validNonAbstractPathTypes: validNonAbstractPathTypes
    };
}

/**
 * Map containing all path types
 * http://docs.oasis-open.org/odata/odata-csdl-xml/v4.01/cs01/odata-csdl-xml-v4.01-cs01.html#sec_BuiltInTypesfordefiningVocabularyTer
 */
export const pathTypeMap: { [typeName: string]: PathType } = {
    'Edm.AnnotationPath': asPathType(EdmType.AnnotationPath, false, Edm.AnnotationPath),
    'Edm.ModelElementPath': asPathType(EdmType.ModelElementPath, true, Edm.ModelElementPath, [
        EdmType.PropertyPath,
        EdmType.NavigationPropertyPath,
        EdmType.AnnotationPath
    ]),
    'Edm.NavigationPropertyPath': asPathType(EdmType.NavigationPropertyPath, false, Edm.NavigationPropertyPath),
    'Edm.PropertyPath': asPathType(EdmType.PropertyPath, false, Edm.PropertyPath),
    'Edm.AnyPropertyPath': asPathType(EdmType.AnyPropertyPath, true, EdmType.PropertyPath, [
        EdmType.PropertyPath,
        EdmType.NavigationPropertyPath
    ])
};
export const TEMPLATE_KIND = 'Template';
export const LABELED_ELEMENT_KIND = 'LabeledElement';

export type TypeDefinitionKind = typeof TEMPLATE_KIND | typeof LABELED_ELEMENT_KIND;

/**
 * Function parameter type or result type definition
 */
export interface TypeDefinition {
    // Edm type name
    name: string;

    // Optional type kind characterizing specific handling of the value having this type
    // mostly suitable for function parameters
    kind?: TypeDefinitionKind;

    // collection-valued type flag
    isCollection?: boolean;

    // parameter type to be used in function snippets by default
    // meaningful if there are multiple types possible
    //
    // NOTE: if multiple parameter types are possible and no one is marked as defult then this parameter will NOT be included in snippet
    useInSnippet?: boolean;
}

export type Type = string | TypeDefinition | (string | TypeDefinition)[];

/**
 * Function parameter definition interface
 */
export interface Parameter {
    // function parameter type
    type: Type;

    // mandatory parameter flag
    isMandatory: boolean;

    // parameter may be specified multiple times for one function
    isVariadic?: boolean;
}

/**
 * Function signature definition interface
 */
export interface Signature {
    parameters: Parameter[];
    resultType: string | TypeDefinition;
}

export type FunctionName = 'odata.concat' | 'odata.fillUriTemplate' | 'odata.uriEncode' | 'odata.matchesPattern';

