export interface DynamicExpressionTypeConstraints {
    // Type should be comparable with the type of dynamic expression parameter which is referenced by that numeric index
    comparableTypeParameterIndex?: number;

    // Type should be compatible with the value type expected from the dynamic expression (requested type)
    compatibleWithRequestedType?: boolean;

    // Optional in collection. There is one exception, if the edm:If expression is a
    // direct child of edm:Collection element the third child element MAY be omitted
    optionalWithInParent?: Edm[];

    // type restriction constraints
    noComplexTypeSupported?: boolean;
    noEnumTypeSupported?: boolean;
    noCollectionsSupported?: boolean;
}

/**
 * Dynamic expression type definition interface
 */
export interface DynamicExpressionType {
    name: EdmType;
    isCollection?: boolean;
    constraints?: DynamicExpressionTypeConstraints;
}

/**
 * Dynamic expression parameter definition interface
 */
export interface DynamicExpressionParameter {
    type: EdmType | DynamicExpressionType;
    isMandatory: boolean;
    name?: string; // parameter name (if attribute)
}

/**
 * Dynamic expression signature interface
 */
export interface DynamicExpressionSignature {
    parameters: DynamicExpressionParameter[];
    resultType: EdmType | DynamicExpressionType;
    metadata?: {
        comparisonOperator?: boolean;
        strictEqualityComparison?: boolean;
    };
}

/**
 * Dynamic Expressions in OData < 14.4 Dynamic Expression >
 *
 * All must be written in element notation (exception: UrlRef)
 * None can get a value using attribute notation (exception: Labeled Element)
 *
 * Each dynamic expression is represented by it's XML node name associated with an object representing
 *  - its attributes (e.g. for IsOf: @Type)
 *  - its subnodes (parameters property)
 *  - information about required types (per attribute subnode) and returned type (resultType).
 * This information is needed when a value of specific type (requestedType) needs to be defined (code completion) or checked (diagnostics).
 *
 */
export const dynamicExpressionSignatureMap = new Map<Edm, DynamicExpressionSignature>()

    .set(Edm.If, {
        parameters: [
            { type: EdmType.Boolean, isMandatory: true },
            { type: { name: EdmType.Untyped, constraints: { compatibleWithRequestedType: true } }, isMandatory: true },
            {
                type: {
                    name: EdmType.Untyped,
                    constraints: { compatibleWithRequestedType: true, optionalWithInParent: [Edm.Collection] }
                },
                isMandatory: true
            }
        ],
        resultType: { name: EdmType.Untyped, constraints: { compatibleWithRequestedType: true } }
    })

    .set(Edm.Not, {
        parameters: [{ type: EdmType.Boolean, isMandatory: true }],
        resultType: EdmType.Boolean
    })

    .set(Edm.And, {
        parameters: [
            { type: EdmType.Boolean, isMandatory: true },
            { type: EdmType.Boolean, isMandatory: true }
        ],
        resultType: EdmType.Boolean
    })

    .set(Edm.Or, {
        parameters: [
            { type: EdmType.Boolean, isMandatory: true },
            { type: EdmType.Boolean, isMandatory: true }
        ],
        resultType: EdmType.Boolean
    })

    .set(Edm.Eq, {
        parameters: [
            {
                type: {
                    name: EdmType.Untyped,
                    constraints: {
                        noComplexTypeSupported: true,
                        noEnumTypeSupported: true,
                        noCollectionsSupported: true
                    }
                },
                isMandatory: true
            },
            {
                type: {
                    name: EdmType.Untyped,
                    constraints: {
                        comparableTypeParameterIndex: 0,
                        noComplexTypeSupported: true,
                        noCollectionsSupported: true
                    }
                },
                isMandatory: true
            }
        ],
        resultType: EdmType.Boolean,
        metadata: {
            comparisonOperator: true,
            strictEqualityComparison: true
        }
    });

dynamicExpressionSignatureMap
    .set(Edm.Ne, dynamicExpressionSignatureMap.get(Edm.Eq))
    .set(Edm.Gt, { ...dynamicExpressionSignatureMap.get(Edm.Eq), metadata: { comparisonOperator: true } })
    .set(Edm.Ge, dynamicExpressionSignatureMap.get(Edm.Gt))
    .set(Edm.Lt, dynamicExpressionSignatureMap.get(Edm.Gt))
    .set(Edm.Le, dynamicExpressionSignatureMap.get(Edm.Gt));

dynamicExpressionSignatureMap.set(Edm.In, {
    parameters: [
        { type: { name: EdmType.PrimitiveType, constraints: { noEnumTypeSupported: true } }, isMandatory: true },
        {
            type: { name: EdmType.PrimitiveType, isCollection: true, constraints: { comparableTypeParameterIndex: 0 } },
            isMandatory: true
        }
    ],
    resultType: EdmType.Boolean,
    metadata: { comparisonOperator: true, strictEqualityComparison: true }
});

