/**
 * Standard aggregation methods to be used in @Analytics.AggregatedProperty/AggregationMethod
 * (see url://docs.oasis-open.org/odata/odata-data-aggregation-ext/v4.0/cs01/odata-data-aggregation-ext-v4.0-cs01.html#_Toc378326293)
 */
let standardAggregationMethods: Map<string, string>;
export function getStandardAggregationMethods(): Map<string, string> {
    if (!standardAggregationMethods) {
        standardAggregationMethods = new Map<string, string>()
            .set('sum', i18n.t('Sum'))
            .set('min', i18n.t('Minimum'))
            .set('max', i18n.t('Maximum'))
            .set('average', i18n.t('Average'))
            .set('countdistinct', i18n.t('CountDistinct'));
    }
    return standardAggregationMethods;
}
