import type { AnnotationNode, Record } from '@sap-ux/cds-annotation-parser';
import {
    RECORD_TYPE,
    RECORD_PROPERTY_TYPE,
    PATH_TYPE,
    STRING_LITERAL_TYPE,
    nodeRange,
    COLLECTION_TYPE,
    EMPTY_VALUE_TYPE
} from '@sap-ux/cds-annotation-parser';
import { positionContained, isBefore } from '@sap-ux/odata-annotation-core';
import type { Position } from 'vscode-languageserver';

import { nodeHasComma } from '../../../utils/hasComma';
import type {
    CompletionContextResolverArgs,
    JsonAttributeContentContext,
    JsonAttributeNameContext,
    JsonAttributeValueContext,
    JsonContentContext,
    JsonElementContentType,
    JsonElementNameContext,
    PropertyNameContext
} from '../types';

export function jsonElementResolver({
    pathToNode
}: CompletionContextResolverArgs): JsonElementNameContext | JsonAttributeNameContext | undefined {
    if (pathToNode.length < 3) {
        return;
    }
    const [record, property, target] = pathToNode.slice(-3);
    if (record.type === RECORD_TYPE && property.type === RECORD_PROPERTY_TYPE && target.type === PATH_TYPE) {
        if (property.name !== target || property.name.value === '$edmJson') {
            // TODO: move property logic to here for edm json?
            return;
        }
        if (target.value.startsWith('$')) {
            const propertyIndex = record.properties
                .filter((prop) => prop.name.value.startsWith('$'))
                .findIndex((prop) => prop === property);
            if (propertyIndex === 0) {
                return {
                    type: 'edm-json',
                    kind: 'element-name',
                    proposedReplacementRange: property.name.range
                };
            } else if (propertyIndex > 0) {
                return {
                    type: 'edm-json',
                    kind: 'attribute-name',
                    proposedReplacementRange: property.name.range
                };
            }
        }
    }
}
export function jsonAttributeValueResolver({
    pathToNode,
    position
}: CompletionContextResolverArgs):
    | JsonElementNameContext
    | JsonAttributeValueContext
    | PropertyNameContext
    | undefined {
    if (pathToNode.length < 3) {
        return;
    }
    const [record, property, target] = pathToNode.slice(-3);
    if (record.type === RECORD_TYPE && property.type === RECORD_PROPERTY_TYPE) {
        if (property.value !== target && target.type === PATH_TYPE && property.name.value === '$edmJson') {
            return {
                type: 'key',
                kind: 'property-name',
                pathToNode,
                proposedReplacementRange: target.range,
                isQuoted: (target.segments[0].quoted && positionContained(target.segments[0].range, position)) ?? false,
                flattened: false,
                propertyName: target.segments[0].value
            };
        }
        const propertyIndex = record.properties
            .filter((prop) => prop.name.value.startsWith('$'))
            .findIndex((prop) => prop === property);

        if (property.name.value.startsWith('$') && propertyIndex > 0) {
            const isStringLiteral = property.value.type === STRING_LITERAL_TYPE;
            return {
                type: 'edm-json',
                kind: 'attribute-value',
                proposedReplacementRange: isStringLiteral ? nodeRange(property.value, false) : property.value.range,
                isStringLiteral,
                attributeName: property.name.value.substring(1)
            };
        }
    }
}

const isTargetRecord = (param: AnnotationNode): param is Record =>
    param.type === RECORD_TYPE && param.properties.length > 0;
export function jsonContentResolver({
    pathToNode,
    position,
    targetNode
}: CompletionContextResolverArgs): JsonContentContext | undefined {
    const hasComma = nodeHasComma(pathToNode, position);
    if (pathToNode.length < 3) {
        return;
    }
    const [record, property, target] = pathToNode.slice(-3);

    if (
        record.type === RECORD_TYPE &&
        property.type === RECORD_PROPERTY_TYPE &&
        [RECORD_TYPE, EMPTY_VALUE_TYPE, COLLECTION_TYPE, STRING_LITERAL_TYPE].includes(targetNode.type)
    ) {
        const propertyIndex = record.properties
            .filter((prop) => prop.name.value.startsWith('$'))
            .findIndex((prop) => prop === property);

        if (propertyIndex > 0) {
            // not an element content value
            return;
        }

        if (isTargetRecord(target)) {
            return resolveAttributeContent(target, position, hasComma);
        }

        const contentType = getContentType(target);

        if (contentType) {
            return {
                type: 'edm-json',
                kind: 'content',
                contentType,
                position,
                hasComma
            };
        }
    }
    if (
        target.type === STRING_LITERAL_TYPE &&
        property.type === COLLECTION_TYPE &&
        record.type === RECORD_PROPERTY_TYPE
    ) {
        return {
            type: 'edm-json',
            kind: 'content',
            contentType: 'text',
            position,
            hasComma
        };
    }
    if (isTargetRecord(target)) {
        return resolveAttributeContent(target, position, hasComma);
    }
}

function resolveAttributeContent(
    target: Record,
    position: Position,
    hasComma: boolean
): JsonAttributeContentContext | undefined {
    if (target.properties[0].range && isBefore(target.properties[0].range.end, position)) {
        return {
            type: 'edm-json',
            kind: 'content',
            contentType: 'attribute',
            position,
            hasComma
        };
    }
    // only one element can be defined as a record and in this case it already exists
}

function getContentType(node: AnnotationNode): JsonElementContentType | undefined {
    switch (node.type) {
        case EMPTY_VALUE_TYPE:
            return 'empty';
        case STRING_LITERAL_TYPE:
            return 'text';
        case RECORD_TYPE:
            return 'single-element';
        case COLLECTION_TYPE:
            return 'multiple-element';
        default:
            return undefined;
    }
}
