import type { AliasInformation, Context } from '../types/context';
import type { NamespaceString } from '@sap-ux/odata-annotation-core';
import { resolveName } from '@sap-ux/odata-annotation-core';
import type { Vocabulary, VocabularyService } from '@sap-ux/odata-vocabularies';

/**
 * get segment without alias
 * @param segment
 * @param aliasInfo
 */
export function getGuessedQualifiedName(segment: string, aliasInfo: AliasInformation): string {
    let segmentWithoutAlias = '';
    const reverseAlias = aliasInfo.reverseAliasMap;
    const indexAt = segment.indexOf('@');
    if (indexAt >= 0) {
        segment = segment.slice(indexAt + 1);
    }

    const parts = segment.trim().split('.');
    const name = parts.pop();
    const NSAlias = parts.join('.').toUpperCase();
    for (const namesapce in reverseAlias) {
        if (NSAlias === namesapce.toUpperCase() || NSAlias === reverseAlias[namesapce].toUpperCase()) {
            segmentWithoutAlias = indexAt >= 0 ? `@${namesapce}.${name}` : `${namesapce}.${name}`;
            break;
        }
    }

    return segmentWithoutAlias;
}

/**
 * Replace term alias with default alias
 * @param termValue - Term with alias
 * @param aliasInfo - Alias information
 * @param vocabularyService - Vocabulary Service
 */
export function replaceWithDefaultAlias(
    termValue: string,
    aliasInfo: AliasInformation,
    vocabularyService: VocabularyService
): string {
    const resolvedName = resolveName(termValue, aliasInfo.aliasMap);
    if (resolvedName && resolvedName.namespace) {
        const defaultAlias = vocabularyService.getVocabularies().get(resolvedName.namespace).defaultAlias;
        termValue = defaultAlias + '.' + resolvedName.name;
    }
    return termValue;
}

export function getNamespaceAndAlias(
    namespace: NamespaceString,
    aliasInfo: AliasInformation,
    context: Context
): string[] {
    let alias;
    if (namespace) {
        alias = aliasInfo.reverseAliasMap[namespace];
        if (!alias) {
            const vocabulary: Vocabulary = context.vocabularies.getVocabularies().get(namespace);
            alias = vocabulary ? vocabulary.defaultAlias : null;
        }
    }
    return [alias, namespace].filter((item) => !!item);
}
