import type { CompletionItem, Range } from 'vscode-languageserver';
import { CompletionItemKind, TextEdit } from 'vscode-languageserver';

import type { CompletionContext, MonolithicCompletionHandler, VocabularyAliasContext } from '../types';

import { basicItemProvider, getAliasesFromTermCompletionItems } from '../utils';

function vocabularyAliasGate(context: CompletionContext): boolean {
    return context.type === 'key' && context.kind === 'vocabulary-alias';
}

function vocabularyAliasAdapter(context: VocabularyAliasContext, items: CompletionItem[]): CompletionItem[] {
    const range: Range = context?.pathToNode?.slice(-1)[0].range;
    const aliases = getAliasesFromTermCompletionItems(items);
    return aliases.map((alias) => ({
        label: alias,
        kind: CompletionItemKind.Module,
        textEdit: TextEdit.replace(range, alias)
    }));
}

export const vocabularyAliasHandler: MonolithicCompletionHandler = {
    name: 'vocabulary-alias',
    type: 'monolithic',
    gate: vocabularyAliasGate,
    providers: [basicItemProvider],
    adapter: vocabularyAliasAdapter
};
