import { getBuiltInTypeViaUnderlyingType } from '../vocabulary/access';

export function handleFunctionName(valueHandlingContext: ValueHandlingContext, type: ValueType): CompletionItem[] {
    const allowedFunctionNames = getFunctionNamesForValueType(type, valueHandlingContext);
    return allowedFunctionNames.map((name) => ({
        name,
        text: name,
        category: CompletionItemCategory.ValueElement,
        documentation: {
            kind: MarkupKind.Markdown,
            value: getFunctionDocumentation(name).join('\n')
        }
    }));
}

/**
 * Returns array of function names which return required value type
 * @param type
 */
export function getFunctionNamesForValueType(
    requiredTypeOrig: ValueType,
    valueHandlingContext?: ValueHandlingContext
): FunctionName[] {
    const requiredType = { ...requiredTypeOrig };
    if (!requiredType.name.startsWith('Edm.') && valueHandlingContext) {
        // resolve TypeDefinition to Edm primitive type
        const context = valueHandlingContext.context;
        const vocabularyType = context.vocabularies.getType(requiredType.name);
        const buildInType = vocabularyType ? getBuiltInTypeViaUnderlyingType(context, vocabularyType, true) : '';
        if (buildInType && buildInType !== requiredType.name) {
            requiredType.name = buildInType;
        }
    }
    return [...functionSignatures]
        .filter((entry) => {
            // TODO: support multiple overloads
            const functionResultTypes: ValueType[] = getFunctionResultTypes(entry[0]);
            return functionResultTypes.some((resultType) => {
                let typeMatch = resultType.name === requiredType.name;
                // TODO: enum and complex type handling
                if (!typeMatch && resultType.name === EdmType.PrimitiveType) {
                    typeMatch = !!primitiveTypeMap[requiredType.name];
                }
                if (!typeMatch && requiredType.name === EdmType.PrimitiveType) {
                    typeMatch = !!primitiveTypeMap[resultType.name];
                }
                typeMatch = typeMatch && !!requiredType.asCollection === !!resultType.asCollection;
                return typeMatch;
            });
        })
        .map((entry) => entry[0]);
}

/**
 * Function returns an array of maps (for every function overload)
 * containing names of elements providing value for function parameter(s)
 * @param valueHandlingContext
 * @param applyElement - Apply element object
 * @param parameterIndex - function parameter index
 */
export function getPropertyNamesProvidingFunctionParameters(
    valueHandlingContext: ValueHandlingContext,
    getPropertyNamesProvidingValueForType: GetPropertyNamesProvidingValueForTypeCallback,
    applyElement: Element,
    parameterIndex: number
): { [key: string]: CompletionItemCategory }[] {
    const result: { [key: string]: CompletionItemCategory }[] = [];
    const functionName = getElementAttributeValue(applyElement, Edm.Function);
    if (functionName) {
        const overloads: Signature | Signature[] = functionSignatures.get(functionName as FunctionName);
        if (overloads) {
            (Array.isArray(overloads) ? overloads : [overloads]).forEach((signature) => {
                let targetParameterDefinition: Parameter;
                const variadicParameter = signature.parameters.find((p) => p.isVariadic);

                if (parameterIndex >= 0) {
                    if (parameterIndex < signature.parameters.length) {
                        targetParameterDefinition = signature.parameters[parameterIndex];
                    } else if (variadicParameter) {
                        targetParameterDefinition = variadicParameter;
                    }
                    if (targetParameterDefinition) {
                        result.push(
                            getPropertyNamesProvidingValueForParameter(
                                valueHandlingContext,
                                getPropertyNamesProvidingValueForType,
                                targetParameterDefinition
                            )
                        );
                    }
                }
            });
        }
    }
    return result;
}

/**
 * Returns result value types for all function overloads
 * @param functionName
 */
export function getFunctionResultTypes(functionName: string): ValueType[] {
    const definitions: Signature | Signature[] = functionSignatures.get(functionName as FunctionName);
    const result: ValueType[] = [];
    if (definitions) {
        const overloads = Array.isArray(definitions) ? definitions : [definitions];
        overloads.forEach((signature) => {
            result.push(convertParameterTypeToValueType(signature.resultType));
        });
    }
    return result;
}

export function isParameterOfStringTemplateKind(applyElement: Element, nodeIndex: number): boolean {
    const parameterIndex = getChildElementPosition(nodeIndex, applyElement);
    return isParameterOfSpecificKind(applyElement, parameterIndex, TEMPLATE_KIND);
}

export function isParameterOfSpecificKind(
    applyElement: Element,
    parameterIndex: number,
    kind: TypeDefinitionKind
): boolean {
    const functionName = (getElementAttributeValue(applyElement, Edm.Function) || '') as FunctionName;
    if (!functionSignatures.has(functionName)) {
        return false;
    }
    // TODO: support multiple overloads
    const param = getFunctionParameterDefinitions(functionName, parameterIndex)[0];
    if (!param) {
        return false;
    }
    const paramType = (param && Array.isArray(param.type) ? param.type[0] : param.type) as TypeDefinition;
    if (typeof paramType === 'object' && paramType.kind === kind) {
        return kind === TEMPLATE_KIND ? paramType.name === EdmType.String : true;
    } else {
        return false;
    }
}

/**
 * Function returns parameter definitions for all function overloads
 * @param functionName - function name
 * @param parameterIndex - parameter index
 */
export function getFunctionParameterDefinitions(functionName: string, parameterIndex: number): Parameter[] {
    const result: Parameter[] = [];
    const overloads: Signature | Signature[] = functionSignatures.get(functionName as FunctionName);
    if (overloads) {
        (Array.isArray(overloads) ? overloads : [overloads]).forEach((signature) => {
            let targetParameterDefinition: Parameter;
            const variadicParameter = signature.parameters.find((p) => p.isVariadic);
            if (parameterIndex < signature.parameters.length) {
                targetParameterDefinition = signature.parameters[parameterIndex];
            } else if (variadicParameter) {
                targetParameterDefinition = variadicParameter;
            }
            result.push(targetParameterDefinition || null);
        });
    }

    return result;
}

/**
 * Function returns parameter type(s) definitions for all function overloads
 * @param functionName - function name
 * @param parameterIndex - parameter index
 */
export function getFunctionParameterTypeDefinitions(
    functionName: string,
    parameterIndex: number
): (string | TypeDefinition)[][] {
    const result: (string | TypeDefinition)[][] = [];
    const overloads: Signature | Signature[] = functionSignatures.get(functionName as FunctionName);
    if (overloads) {
        (Array.isArray(overloads) ? overloads : [overloads]).forEach((signature) => {
            const overloadResult: (string | TypeDefinition)[] = [];
            let targetParameterDefinition: Parameter;
            const variadicParameter = signature.parameters.find((p) => p.isVariadic);
            if (parameterIndex < signature.parameters.length) {
                targetParameterDefinition = signature.parameters[parameterIndex];
            } else if (variadicParameter) {
                targetParameterDefinition = variadicParameter;
            }

            if (targetParameterDefinition) {
                overloadResult.push(
                    ...(Array.isArray(targetParameterDefinition.type)
                        ? targetParameterDefinition.type
                        : [targetParameterDefinition.type])
                );
            }
            result.push(overloadResult);
        });
    }
    return result;
}

export function handleTemplateVariableCompletion(
    element: Element,
    templateElement: Element,
    startsString: string
): CompletionItem[] {
    const existingLabeledElelments = (element.content || []).filter(
        (node) => node.type === ELEMENT_TYPE && node.name === Edm.LabeledElement
    );
    const labeledElementNamesMap: { [name: string]: boolean } = {};
    existingLabeledElelments.forEach((element) => {
        const name = getElementAttributeValue(element as Element, Edm.Name);
        if (name) {
            labeledElementNamesMap[name] = true;
        }
    });
    const textNode = (templateElement.content || []).find((child) => child.type === TEXT_TYPE);
    const cursorPosition: Position = {
        ...textNode.range.start,
        character: textNode.range.start.character + startsString.length
    };
    const variables = getTemplateVariablePositions((textNode as TextNode).text, textNode.range);
    const allRanges: Range[] = [].concat(...variables.values());
    const replacementRange = allRanges.find((range) => positionContained(range, cursorPosition));
    return Object.keys(labeledElementNamesMap).map((key) => {
        const text = replacementRange ? key : `{${key}}`;
        return {
            name: text,
            text,
            filterText: text,
            affectedRange: replacementRange || Range.create(cursorPosition, cursorPosition),
            category: CompletionItemCategory.ValueElement
        };
    });
}

export function getTemplateVariableNames(applyElement: Element, parameterIndex: number): string[] {
    let result: string[] = [];
    const template = getTemplateTextNode(applyElement, parameterIndex)?.text;
    if (template) {
        result = (template.match(/({\w*})/g) || []).map((item) => item.replace(/[{}]/g, ''));
    }
    return result;
}

/**
 * Returns map of variable names with arrays containing corresponding placeholder ranges
 * @param templateText - template text
 * @param templateTextRange - template text range (if not provided then empty arrays returned)
 */
export function getTemplateVariablePositions(templateText: string, templateTextRange?: Range): Map<string, Range[]> {
    const result: Map<string, Range[]> = new Map();
    const line = templateTextRange?.start.line;
    const character = templateTextRange?.start.character;
    if (templateText) {
        const varPlaceholders = templateText.match(/({\w*})/g) || [];
        (varPlaceholders || []).forEach((placeholder) => {
            const varName = placeholder.replace(/[{}]/g, '');
            result.set(varName, []);
            if (templateTextRange) {
                let offset = 0;
                while (offset >= 0) {
                    offset = templateText.indexOf(placeholder, offset);
                    if (offset >= 0) {
                        const placeholderRange = Range.create(
                            Position.create(line, character + offset + 1),
                            Position.create(line, character + offset + placeholder.length - 1)
                        );
                        result.get(varName).push(placeholderRange);
                        offset += placeholder.length;
                    }
                }
            }
        });
    }
    return result;
}

export function getTemplateTextNode(applyElement: Element, parameterIndex: number): TextNode | undefined {
    const parameterElement = getChildElementForPosition(parameterIndex, applyElement);
    if (parameterElement?.name === Edm.String) {
        return (parameterElement.content || []).find((child) => child.type === TEXT_TYPE) as TextNode;
    }
    return undefined;
}

export function findTemplateParameterIndex(functionName: string): (number | undefined)[] {
    const result: (number | undefined)[] = [];
    const overloads: Signature | Signature[] = functionSignatures.get(functionName as FunctionName);
    if (overloads) {
        (Array.isArray(overloads) ? overloads : [overloads]).forEach((signature) => {
            result.push(
                signature.parameters.findIndex((p) => {
                    const type = Array.isArray(p.type) ? p.type[0] : p.type;
                    return typeof type === 'object' && type.kind === TEMPLATE_KIND;
                })
            );
        });
    }
    return result;
}

export function convertParameterTypeToValueType(type: string | TypeDefinition): ValueType {
    if (typeof type === 'string') {
        return convertValueTypeFromString(type);
    } else {
        return {
            name: type.name,
            asCollection: type.isCollection
        };
    }
}

/**
 * Function returns map of element names providing value for parameter based on its type(s)
 * @param valueHandlingContext
 * @param parameter - parameter definition object
 */
function getPropertyNamesProvidingValueForParameter(
    valueHandlingContext: ValueHandlingContext,
    getPropertyNamesProvidingValueForType: GetPropertyNamesProvidingValueForTypeCallback,
    parameter: Parameter
): { [key: string]: CompletionItemCategory } {
    let result: { [key: string]: CompletionItemCategory } = {};
    if (parameter) {
        const parameterTypes = Array.isArray(parameter.type) ? parameter.type : [parameter.type];
        parameterTypes.forEach((type) => {
            const parameterTypeName: string = typeof type === 'object' ? type.name : type;
            if (typeof type === 'object' && type.kind === Edm.LabeledElement) {
                result[Edm.LabeledElement] = CompletionItemCategory.ValueElement;
            } else {
                result = {
                    ...result,
                    ...getPropertyNamesProvidingValueForType(valueHandlingContext, {
                        name: parameterTypeName,
                        asCollection: typeof type === 'object' && type.isCollection
                    })
                };
            }
        });
    }
    return result;
}

function checkParameters(parameters: Parameter[], values: MarkdownString[]) {
    (parameters || []).forEach((parameter, index) => {
        let text = '';
        const type = Array.isArray(parameter.type) ? parameter.type[0] : parameter.type;
        const typeDefinition = typeof type === 'object' ? type : null;
        let typeText = typeof type === 'string' ? type : typeDefinition.name;
        if (typeDefinition && typeDefinition.isCollection) {
            typeText = 'Collection(' + typeText + ')';
        }

        text += 'Type: ' + typeText;
        if (parameter?.isMandatory) {
            text += '. Mandatory';
        }
        if (parameter?.isVariadic) {
            text += '. Variadic';
        }
        if (typeDefinition?.kind) {
            text += '. Kind: ' + typeDefinition?.kind;
        }
        values.push(`**Argument ${index + 1}:** ${text} \n`);
    });
    return values;
}

/**
 * Get function documentation (used for hover and code completion)
 * (no translation required - we also don't have it for vocabulary based documentation)
 * @param functionName
 */
export function getFunctionDocumentation(functionName: FunctionName): MarkdownString[] {
    const functionSignature = functionSignatures.get(functionName);
    const functionDocumentation: { description: string; note?: string } = functionDocumentations.get(functionName);
    if (!functionSignature || !functionDocumentation) {
        return null;
    }

    let values: MarkdownString[] = [];

    values.push(`**Name:** ${functionName} \n`);
    values.push(`**Description:** ${functionDocumentation.description} \n`);

    if (functionDocumentation.note) {
        values.push(`**Note:** ${functionDocumentation.note} \n`);
    }

    const overloads: Signature | Signature[] = functionSignatures.get(functionName);
    const signature: Signature = overloads && Array.isArray(overloads) ? overloads[0] : (overloads as Signature);
    values = checkParameters(signature?.parameters, values);
    const resultType = getFunctionResultTypes(functionName)[0];
    if (resultType) {
        values.push(`**ReturnType:** ${convertValueTypeToString(resultType)} \n`);
    }

    return values;
}

/**
 * Check if element representing Apply contains a supported function (case insensitive)
 * @param element
 */
export function isSupportedFunction(element: Element): boolean {
    if (element.name !== Edm.Apply) {
        return false;
    }
    const functionName = getElementAttributeValue(element, Edm.Function);
    if (!functionName) {
        return true;
    } // no function name yet - we check and provide code completion -> true
    if (functionSignatures.has(functionName as FunctionName)) {
        return true;
    }
    // eslint-disable-next-line sonarjs/prefer-single-boolean-return
    if (
        [...functionSignatures.keys()].findIndex(
            (entry) => (entry as string).toUpperCase() === functionName.toUpperCase()
        ) >= 0
    ) {
        return true; // only wrong case
    }
    return false;
}

/**
 * Check Function Name for Value Type
 * @param type
 * @param attribute
 */
export function checkFunctionNameForValueType(
    type: ValueType,
    attribute: Attribute,
    valueHandlingContext?: ValueHandlingContext
): Diagnostic[] {
    const messages: Diagnostic[] = [];
    const functionName: FunctionName = attribute.value as FunctionName;
    if (!functionSignatures.has(functionName)) {
        // must be a case issue because all other function names are handled by message
        // "Function_0_and_its_subElements_are_not_validated_by_XML_annotation_language_server"
        const message = i18n.t('Unknown_Function_0', { functionName });
        const caseCheck: CaseCheck = { value: functionName, lookupPath: ['functions'] };
        messages.push({
            message,
            severity: DiagnosticSeverity.Error,
            data: { caseCheck: caseCheck },
            range: attribute.valueRange
        });
    } else {
        const functionNamesForValueType = getFunctionNamesForValueType(type, valueHandlingContext);
        if (!functionNamesForValueType.includes(functionName)) {
            const message = i18n.t('Function_0_not_allowed_here_required_result_type_1', {
                functionName,
                resultType: convertValueTypeToString(type)
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: attribute.valueRange,
                rule: 'odata-function-wrong-return-type',
                data: {
                    name: functionName,
                    type
                }
            });
        }
    }
    return messages;
}

/**
 * Check Apply Function has all mandatory parameters
 * @param element: element representing Apply Function expression
 * @param properties: attributes and sub elements
 */
export function checkApplyFunctionMandatoryParameters(
    element: Element,
    properties: Array<Element | Attribute>
): Diagnostic[] {
    const messages: Diagnostic[] = [];
    const functionName = getElementAttributeValue(element, Edm.Function);
    let functionSignature = functionSignatures.get(functionName as FunctionName);
    if (Array.isArray(functionSignature)) {
        functionSignature = functionSignature[0];
    }
    if (!functionSignature) {
        return messages;
    }
    const paramProperties = properties.filter((property) => property.type === ELEMENT_TYPE);
    (functionSignature.parameters || []).forEach((parameter, index) => {
        if (parameter.isMandatory && !paramProperties[index]) {
            messages.push({
                message: i18n.t('Function_Parameter_index_0_not_provided', { functionName, index: index + 1 }),
                severity: DiagnosticSeverity.Error,
                range: element.contentRange || element.range
            });
        }
    });
    return messages;
}

// labeled element should exist for each variable (as child of apply function element)
function checkExistenceOfLabelledElement(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    property: Element | Attribute,
    variables: Map<string, Range[]>,
    messages: Diagnostic[]
): Diagnostic[] {
    const labeledElementNames: Set<string> = new Set();
    (element.content || [])
        .filter((subNode) => subNode.type === ELEMENT_TYPE && subNode.name === Edm.LabeledElement)
        .forEach((labeledElement: Element) =>
            labeledElementNames.add(getElementAttributeValue(labeledElement, Edm.Name))
        );
    for (const entry of variables) {
        const varName = entry[0];
        const varRanges: Range[] = entry[1].length ? entry[1] : [(property as Element).contentRange || property.range];
        if (!labeledElementNames.has(varName)) {
            // only do case check if LOCAL labeled element exist with same name ignoring case
            let caseCheck: CaseCheck = null;
            labeledElementNames.forEach((name) => {
                if (name.toUpperCase() === varName.toUpperCase()) {
                    caseCheck = {
                        value: varName,
                        lookupPath: ['labeledElements', valueHandlingContext.aliasInfo.currentFileNamespace]
                    };
                }
            });
            varRanges.forEach((variableRange) => {
                const diagnostic: Diagnostic = {
                    message: i18n.t('Template_variable_0_not_defined', { varName }),
                    severity: DiagnosticSeverity.Error,
                    range: variableRange || (property as Element).contentRange || property.range
                };
                if (caseCheck) {
                    diagnostic.data = { caseCheck: caseCheck };
                }
                messages.push(diagnostic);
            });
        }
    }
    return messages;
}

function checkTemplate(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    property: Element | Attribute,
    parameterIndex: number
): Diagnostic[] {
    const templateTextNode = getTemplateTextNode(element, parameterIndex);
    const templateText = templateTextNode?.text;
    const variables = templateText ? getTemplateVariablePositions(templateText, templateTextNode.range) : new Map();
    let messages: Diagnostic[] = [];
    if (!templateText) {
        // empty string not allowed
        messages.push({
            message: i18n.t('Template_must_not_be_empty'),
            severity: DiagnosticSeverity.Error,
            range: property.range || property.nameRange
        });
    } else if (!variables.size) {
        // should contain variables
        messages.push({
            message: i18n.t('Template_value_0_contains_no_variables', {
                templateText,
                interpolation: { escapeValue: false }
            }),
            severity: DiagnosticSeverity.Error,
            range: (property as Element).contentRange || property.range
        });
    } else if (variables.has('')) {
        // should have no empty variable
        const varRange: Range = variables.get('')[0];
        if (varRange) {
            varRange.start.character--;
            varRange.end.character++;
        }
        messages.push({
            message: i18n.t('Template_value_0_variables_must_no_be_empty', {
                templateText,
                interpolation: { escapeValue: false }
            }),
            severity: DiagnosticSeverity.Error,
            range: varRange || (property as Element).contentRange || property.range
        });
    } else {
        messages = checkExistenceOfLabelledElement(valueHandlingContext, element, property, variables, messages);
    }
    return messages;
}

/**
 * Check Apply Function properties (i.e. attributes and subnodes)
 * @param valueHandlingContext
 * @param type: type which should be returned by Apply Function expression
 * @param element: element representing Apply Function expression
 * @param property: attribute (only 'Function') or sub element (representing function parameters)
 * @param parameterIndex: >=0 ? parameter index
 * @param checkTrace
 * @param logger
 */
export function checkApplyFunctionProperty(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    property: Element | Attribute,
    parameterIndex: number,
    checkCallback: CheckCallback,
    checkTrace: CheckTrace,
    logger: Logger
): Diagnostic[] {
    let messages: Diagnostic[] = [];

    if (property?.type !== ELEMENT_TYPE || parameterIndex < 0) {
        return messages;
    } // the only attribute (Function) is checked elsewhere

    const functionName: FunctionName = getElementAttributeValue(element, Edm.Function) as FunctionName;
    const parTypeDefinitionsOverloads = getFunctionParameterTypeDefinitions(functionName, parameterIndex);
    const parTypeDefinitions = parTypeDefinitionsOverloads?.length > 0 ? parTypeDefinitionsOverloads[0] : null; // take first overload
    const parTypeDefinition: string | TypeDefinition = parTypeDefinitions?.length > 0 ? parTypeDefinitions[0] : null; // take first of union types
    if (!parTypeDefinition) {
        return messages;
    }

    const kind = typeof parTypeDefinition === 'object' ? parTypeDefinition.kind : '';
    if (kind === TEMPLATE_KIND && property.name === Edm.String) {
        messages = checkTemplate(valueHandlingContext, element, property, parameterIndex);
    } else if (kind === LABELED_ELEMENT_KIND) {
        // checks of labeled element (specific to usage of it in apply function)
        // labeled element name occurs in template, template is assumed to be first parameter of apply function
        const variableNames = getTemplateVariableNames(element, 0);
        const nameAttribute = getElementAttribute(property, Edm.Name);
        const name = nameAttribute && nameAttribute.value ? nameAttribute.value : '';
        if (name && !variableNames.includes(name)) {
            messages.push({
                message: i18n.t('Labeled_element_0_not_used_in_template', { name }),
                severity: DiagnosticSeverity.Warning,
                range: nameAttribute.valueRange || nameAttribute.range || property.range
            });
        }
    }
    // check property as sub element correctly represents expected type
    const parDefinitions = getFunctionParameterDefinitions(functionName, parameterIndex);
    const parDefinition = parDefinitions?.length > 0 ? parDefinitions[0] : null; // take first of overloads
    const isMandatory = parDefinition ? parDefinition.isMandatory : false;
    const parameterValueType = convertParameterTypeToValueType(parTypeDefinition);
    if (parameterValueType) {
        if (isMandatory) {
            parameterValueType.facets = parameterValueType.facets || {};
            parameterValueType.facets.isNullable = false;
        }
        messages.push(
            ...checkCallback(valueHandlingContext, [parameterValueType], property, element, checkTrace, logger)
        );
    }
    return messages;
}

/**
 * Function returns template variable locations to be used for displaying references of a specific LabeledElement
 * LabeledElement name is obtained using cursor context's Apply element and path to target
 *
 * NOTE: Function returns undefined if cursor position is irrelevant to LabeledElement referencing
 */
export function getTemplateVariableLocations(cursorContext: CursorContext): Location[] | undefined {
    const parameter = getPathTargetInElement(cursorContext.applyContext.path, cursorContext.applyContext.apply);
    if (parameter.element?.name !== Edm.LabeledElement) {
        return;
    }
    const target = getPathTargetInElement(parameter.remainingPathForElement, parameter.element);
    if (hasTargetAttribute(target)) {
        const name = getElementAttributeValue(parameter.element, Edm.Name);
        if (!name) {
            return [];
        }
        const functionName = getElementAttributeValue(cursorContext.applyContext.apply, Edm.Function) || '';
        // TODO: support multiple overloads
        const templateIndex = findTemplateParameterIndex(functionName)[0];
        if (templateIndex > 0) {
            return [];
        }
        const templateNode = getTemplateTextNode(cursorContext.applyContext.apply, templateIndex);
        if (!templateNode) {
            return [];
        }
        const variables = getTemplateVariablePositions(templateNode.text, templateNode.range);
        if (!variables.get(name)) {
            return [];
        }
        const uri = cursorContext.fileUri;
        return variables.get(name).map((range: Range) => Location.create(uri, range));
    }
}

function hasTargetAttribute(target: PathTargetInElement): boolean {
    return (
        !target.element &&
        (target.isName ||
            (target.attribute &&
                (target.isAttributeName || target.isAttributeValue) &&
                target.attribute.name === Edm.Name))
    );
}
