import { getCompletionItems } from './services/completion/complete';
import type { Diagnostic, CompletionItem, Location, CodeActionParams } from 'vscode-languageserver';
import { getDefinition } from './services/definition';
import { getReferences } from './services/references';
import { initI18n as initI18nAnnotationService } from '@sap/ux-annotation-service';
import { initI18n as initI18nCdsAnnotationAdapter } from '@sap/ux-cds-annotation-adapter';
import { initI18n as initI18nCdsAnnotationConverter } from '@sap/ux-cds-odata-annotation-converter';
import { cdsLogger } from './log';
import type {
    CdsDefinitionParams,
    CdsDiagnosticParams,
    CdsHoverParams,
    CdsCompletionParams,
    ContributionContext,
    CdsQuickfix,
    CdsSemanticTokensParams,
    SemanticToken,
    CdsHover,
    CdsIndexingParams,
    CdsAnnotationIndex
} from './lspTypes';
import { getHover } from './services/hover';
import { getDiagnostics } from './services/diagnostics';
import { getQuickFix } from './services/quickFix';
import { getSemanticTokens } from './services/semanticToken';
import { getWhereUsedIndex } from './services/whereUsedIndex';

let contributionContext: ContributionContext;

module.exports = {
    cdsLspContributionKind: 'annotation',
    indexAnnotationIdentifiers: (params: CdsIndexingParams): Promise<CdsAnnotationIndex> =>
        Promise.resolve(getWhereUsedIndex(params)),
    fetchCompletions: (params: CdsCompletionParams): Promise<CompletionItem[]> =>
        Promise.resolve(getCompletionItems(params, contributionContext)),
    fetchHover: (params: CdsHoverParams): Promise<CdsHover | undefined> => Promise.resolve(getHover(params)),
    fetchDefinition: (params: CdsDefinitionParams): Promise<Location | Location[] | undefined> =>
        Promise.resolve(getDefinition(params)),
    fetchReferences: (params: CdsDefinitionParams): Promise<Location[]> => Promise.resolve(getReferences(params)),
    fetchDiagnostics: (params: CdsDiagnosticParams): Promise<Map<string, Diagnostic[]> | Diagnostic[]> =>
        getDiagnostics(params, contributionContext),
    fetchQuickfixes: (params: CodeActionParams): Promise<CdsQuickfix[]> => Promise.resolve(getQuickFix(params)),
    fetchSemanticTokens: (params: CdsSemanticTokensParams): Promise<SemanticToken[]> =>
        getSemanticTokens(params, contributionContext),
    initialize: async (context: ContributionContext): Promise<void> => {
        cdsLogger.initialize(context);
        contributionContext = context;
        await Promise.all([
            initI18nAnnotationService(),
            initI18nCdsAnnotationAdapter(),
            initI18nCdsAnnotationConverter()
        ]);
    }
};
