import type { Position } from 'vscode-languageserver-types';
import { Location, Range } from 'vscode-languageserver-types';

import type { GenericToken } from './types';

export class GenericTokenImpl implements GenericToken {
    constructor(
        public readonly uri: string,
        public readonly tokenIndex: number,
        public readonly text: string,
        public readonly line: number, // zero-based
        public readonly character: number, // zero-based
        public annotationValue?: string
    ) {}

    public toString(): string {
        return `${this.text}@${this.line}:${this.character}`;
    }

    public get range(): Range {
        return Range.create(this.line, this.character, this.line, this.character + this.text.length);
    }

    public get location(): Location {
        return Location.create(this.uri, this.range);
    }

    public compare(position: Position): number {
        let res = this.line - position.line; // We are dealing with single-line tokens only, thus no care for end line
        if (res === 0) {
            res = position.character - this.character;
            if (res < 0) {
                return 1;
            }
            // Token covers also if cursor is right after text (no two identifiers are consecutive)
            if (res <= this.text.length) {
                return 0;
            }
            return -1;
        }
        return Math.sign(res);
    }
}
