import { Snippet } from './snippet';
import type { CompletionItem } from '../types/general';
import { CompletionItemCategory } from '../types/general';
import type { CursorContext } from '../utils/path';
import { getValueTypeFromTerm } from '../utils/path';
import { adjustEmbeddedAnnotationCursorContext } from '../value-handling';
import type { AliasInformation, ValueType, Context } from '../types/context';
import {
    getTargetInfoFromCursorContext,
    getTermsForCompletion,
    getAnnotationCompletionContext
} from '../utils/annotationService';
import { getVocabularyType } from '../vocabulary/access';
import type { SnippetHandlingContext } from '.';
import { ATTRIBUTE_TYPE, Edm, ELEMENT_TYPE } from '@sap-ux/odata-annotation-core';
import { EdmType } from '../specification';
import { createRecordSnippets, createCollectionSnippet, getElementNamesProvidingValue } from './collection';
import type { Logger } from '@sap/ux-annotation-utils';
import type { VocabularyType } from '@sap-ux/odata-vocabularies';
import { ENTITY_TYPE_KIND } from '@sap-ux/odata-annotation-core-types';
import { removeDynamicExpressionsFromMap } from './util';
import type { CompleteComplexAnnotationSnippetCallback } from '../utils/general';
import type { TermDataForCompletion } from '../types/annotationService';

interface LocalSnippetContext {
    snippetContext: SnippetHandlingContext;
    snippet: Snippet;
    embedded: boolean;
    omitValueAttribute: boolean;
    setTabstopForQualifier: boolean;
}

// =========================================
// Help functions
const geSnippetSemaphores = (
    context: Context,
    targetKinds: string[],
    termData: TermDataForCompletion,
    vocabularyType: VocabularyType
): { omitValueAttribute: boolean; setTabstopForQualifier: boolean } => {
    const term = termData.term;
    const isCdsTerm = context.vocabularies.cdsVocabulary.namespace === termData.namespace;
    const isBooleanValueType = [term.type, vocabularyType?.underlyingType].includes(EdmType.Boolean);
    const omitValueAttribute = isBooleanValueType && term.defaultValue === true;
    const isForEntityType = targetKinds.includes(Edm.EntityType);
    const defaultAppliesTo = isForEntityType ? [ENTITY_TYPE_KIND] : [];
    const setTabstopForQualifier =
        !isBooleanValueType &&
        isForEntityType &&
        !isCdsTerm &&
        (term.appliesTo || defaultAppliesTo).includes(ENTITY_TYPE_KIND);
    return { omitValueAttribute, setTabstopForQualifier };
};

const appendTabStopFactory = (final: boolean) => (ct: LocalSnippetContext) => {
    if (ct.setTabstopForQualifier) {
        final ? ct.snippet.setAttributeAsFinalTabStop() : ct.snippet.setAttributeAsTabStop();
    }
};
const appendTabStopForQualifier = appendTabStopFactory(false);
const appendFinalTabStopForQualifier = appendTabStopFactory(true);

const buildSnippetForUnresolvedTerm = (ct: LocalSnippetContext) => {
    if (ct.embedded) {
        ct.snippet.setAttributeAsFinalTabStop();
    } else {
        appendTabStopForQualifier(ct);
        ct.snippet.appendFinalTabStopToContent();
    }
};

const buildSnippetWithPrimitiveValue = (ct: LocalSnippetContext) => {
    const snippet = ct.snippet;
    const valueElementMap = getElementNamesProvidingValue(ct.snippetContext);
    removeDynamicExpressionsFromMap(valueElementMap);
    const valueElements = Object.keys(valueElementMap);
    if (valueElements.length === 1) {
        if (!ct.omitValueAttribute) {
            snippet.setAttribute(
                valueElements[0],
                snippet.getTabStopText(ct.setTabstopForQualifier ? snippet.getNextTabStopId() : 0)
            );
        }
        appendFinalTabStopForQualifier(ct);
    } else if (valueElements.length === 2 && valueElements.includes(Edm.Path)) {
        if (!ct.omitValueAttribute) {
            snippet.setAttribute(
                valueElements.filter((item) => item !== Edm.Path)[0],
                snippet.getTabStopText(ct.setTabstopForQualifier ? snippet.getNextTabStopId() : 0)
            );
        }
        appendFinalTabStopForQualifier(ct);
    } else if (ct.embedded) {
        snippet.setAttributeAsFinalTabStop();
    } else {
        appendTabStopForQualifier(ct);
        snippet.appendFinalTabStopToContent();
    }
};
// ==============================================

const convertSnippetToCompletionItem = (snippet: Snippet, termData: TermDataForCompletion): CompletionItem => {
    const item = snippet.toCompletionItem(null, null, CompletionItemCategory.Annotation);
    item.name = termData.name;
    item.text = termData.truncatedName || termData.name;
    item.insertText = termData.name;
    item.filterText = termData.name;
    if (termData.term.deprecated) {
        item.deprecated = termData.term.deprecated;
    }
    item.sorting = {
        isUIVocabulary: termData.namespace === 'com.sap.vocabularies.UI.v1'
    };
    item.sorting.isAlias = termData.term.name !== termData.name;
    item.data.documentation = termData.documentation;
    return item;
};

/**
 * Term element (Annotation) snippet with nested complex structure completion handler
 * @param cursorContext - cursor context object
 * @param context - context object
 * @param aliasInfo - alias information object
 * @param embedded - embedded annotation flag (false for regular target annotations, true for embedded ones)
 */
export const completeComplexAnnotationSnippet: CompleteComplexAnnotationSnippetCallback = (
    cursorContext: CursorContext,
    context: Context,
    aliasInfo: AliasInformation,
    logger: Logger,
    embedded = false,
    applicableTermsConstraint?: string[]
): CompletionItem[] => {
    const completionItems: CompletionItem[] = [];
    const useSnippets: boolean = context.useSnippets;

    if (embedded) {
        adjustEmbeddedAnnotationCursorContext(
            context,
            aliasInfo,
            cursorContext.annotation,
            cursorContext.elementContext.parentElement,
            cursorContext,
            logger
        );
    }

    const { targetKinds, targetType, targetTypeAssocKey } = getTargetInfoFromCursorContext(
        cursorContext,
        context,
        aliasInfo
    );
    if (targetKinds.length) {
        const terms = getTermsForCompletion(
            context,
            targetKinds,
            targetType,
            targetTypeAssocKey,
            aliasInfo,
            applicableTermsConstraint
        );
        terms.forEach((termData) => {
            const term = termData.term;
            const valueType: ValueType = getValueTypeFromTerm(context, term);
            const vocabularyType = getVocabularyType(context, term.type);

            const cursorContextForTerm: CursorContext = {
                ...cursorContext,
                embeddedIn: null,
                embeddedType: '',
                annotation: {
                    name: Edm.Annotation,
                    nameRange: null,
                    type: ELEMENT_TYPE,
                    attributes: {
                        Term: {
                            name: 'Term',
                            nameRange: null,
                            type: ATTRIBUTE_TYPE,
                            value: termData.name,
                            valueRange: null
                        }
                    },
                    content: []
                }
            };

            // complex snippet root element
            const snippet = new Snippet(Edm.Annotation, useSnippets)
                .setAttribute('Term', termData.name)
                .addMandatoryAttributesWithTabStops();

            cursorContextForTerm.annotation = snippet.generic;
            cursorContextForTerm.path = `$['content'][0]['text']`;
            const annotationCompletionContext = getAnnotationCompletionContext(
                context,
                cursorContextForTerm,
                aliasInfo,
                logger,
                true
            );

            if (context.vocabularies.cdsVocabulary.reverseNameMap.has(termData.name)) {
                termData.name = context.vocabularies.cdsVocabulary.reverseNameMap.get(termData.name);
                termData.truncatedName = termData.name;
                snippet.setAttribute('Term', termData.name);
            }

            annotationCompletionContext.valueType.asCollection = false; // collection members inherit value type from collection itself
            const snippetContext: SnippetHandlingContext = {
                useSnippets,
                type: annotationCompletionContext.valueType,
                valueHandlingContext: annotationCompletionContext.valueHandlingContext
            };

            const { omitValueAttribute, setTabstopForQualifier } = geSnippetSemaphores(
                context,
                targetKinds,
                termData,
                vocabularyType
            );
            const localContext: LocalSnippetContext = {
                snippet,
                snippetContext,
                embedded,
                omitValueAttribute,
                setTabstopForQualifier
            };

            if (!annotationCompletionContext.resolvedTerm) {
                buildSnippetForUnresolvedTerm(localContext);
            } else if (valueType.asCollection) {
                // annotation with collection kind value
                appendTabStopForQualifier(localContext);
                const collection = createCollectionSnippet(
                    snippetContext,
                    vocabularyType,
                    snippet.getNextTabStopId(),
                    true
                );
                snippet.appendContent(collection);
            } else if (vocabularyType?.kind === Edm.ComplexType) {
                // annotation with complex type value
                appendTabStopForQualifier(localContext);
                const recordSnippet = createRecordSnippets(
                    snippetContext,
                    vocabularyType,
                    false,
                    snippet.getNextTabStopId(),
                    false,
                    true
                )[0].snippet;
                snippet.appendContent(recordSnippet);
            } else {
                // annotation with primitive type value
                buildSnippetWithPrimitiveValue(localContext);
            }

            // prepare snippet completion item
            completionItems.push(convertSnippetToCompletionItem(snippet, termData));
        });
    }
    return completionItems;
};
