function getProperties(
    element: Element,
    dynamicExpressionMetadata: DynamicExpressionSpecial,
    propertyNames: { [p: string]: any }
): { properties: Array<Element | Attribute>; messages: Diagnostic[] } {
    const messages: Diagnostic[] = [];
    const properties: Array<Element | Attribute> = [];
    Object.keys(element.attributes || {}).forEach((attrName) => {
        const attribute: Attribute = element.attributes[attrName];
        let isAttributeAllowed = true;
        if (dynamicExpressionMetadata) {
            isAttributeAllowed =
                dynamicExpressionMetadata.hasAttributes &&
                [
                    ...(dynamicExpressionMetadata.mandatoryAttributes || []),
                    ...(dynamicExpressionMetadata.optionalAttributes || []),
                    ...(dynamicExpressionMetadata.valueAttributes && propertyNames['@' + attrName] ? [attrName] : [])
                ].includes(attrName);
        } else {
            isAttributeAllowed = propertyNames['@' + attrName];
        }

        if (isAttributeAllowed) {
            properties.push(attribute);
        } else {
            const message = i18n.t('Attribute_not_allowed_here_0', {
                attribute: attrName
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: attribute.nameRange,
                rule: 'attribute-not-allowed-here',
                data: {
                    name: attrName
                }
            });
        }
    });
    return { properties: properties, messages: messages };
}

function processNode(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    properties: Array<Element | Attribute>,
    propertyNames: { [p: string]: any },
    messages: Diagnostic[]
) {
    return (node, idx) => {
        let isUnknownFunction = false;
        let propNamesForNode: { [p: string]: any };
        if (element.name === Edm.Apply) {
            isUnknownFunction = !functionSignatures.has(
                getElementAttributeValue(element, Edm.Function) as FunctionName
            );
            propNamesForNode = {};
            if (node.type === ELEMENT_TYPE) {
                const parameterIndex = getChildElementPosition(idx, element);
                propNamesForNode =
                    getPropertyNamesProvidingFunctionParameters(
                        valueHandlingContext,
                        getPropertyNamesProvidingValueForType,
                        element,
                        parameterIndex
                    )[0] || {};
            }
        } else {
            propNamesForNode = propertyNames;
        }

        if (node.type === ELEMENT_TYPE) {
            const childElement: Element = node;
            if (propNamesForNode[childElement.name]) {
                properties.push(childElement);
            } else if (unsupportedDynamicExpressionMap[childElement.name]) {
                const message = i18n.t(
                    'Element_0_and_its_subElements_are_not_validated_by_XML_annotation_language_server',
                    {
                        element: element.name
                    }
                );
                messages.push({
                    message: message,
                    severity: DiagnosticSeverity.Information,
                    range: element.nameRange
                });
            } else if (childElement.name !== Edm.Annotation || !isAnnotationAllowed(element)) {
                // omit messages for apply function (with invalid function name due to case issue)
                if (!isUnknownFunction) {
                    const message = i18n.t('Element_not_allowed_here_0', {
                        element: childElement.name
                    });
                    messages.push({
                        message: message,
                        severity: DiagnosticSeverity.Error,
                        range: childElement.nameRange || childElement.range,
                        rule: 'record-collection-path-not-allowed',
                        data: {
                            name: childElement.name,
                            type
                        }
                    });
                }
            } else if (childElement.name === Edm.Annotation) {
                properties.push(childElement);
            }
        }
    };
}

function checkDynamicExpressionAttrAndSubNodeNames(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    dynamicExpressionMetadata: DynamicExpressionSpecial,
    propertyNames: { [p: string]: any },
    type: ValueType
): { properties: Array<Element | Attribute>; messages: Diagnostic[] } {
    let messages: Diagnostic[] = [];
    let properties: Array<Element | Attribute> = [];
    ({ properties, messages } = getProperties(element, dynamicExpressionMetadata, propertyNames));
    let isUnknownFunction = false;

    if (dynamicExpressionMetadata) {
        // check for mandatory attributes of dynamic expression
        const missingAttrNames = (dynamicExpressionMetadata.mandatoryAttributes || []).filter(
            (attr) => !element.attributes[attr]
        );
        if (missingAttrNames.length) {
            const message = i18n.t('Attributes_required_0', {
                attribute: missingAttrNames.join(',')
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: element.range
            });
        }
    }

    // check sub node names and collect values for allowed sub nodes
    (element.content || [])
        .filter((node) => {
            return !!node.type;
        })
        // .forEach(processNode(valueHandlingContext, element, properties, propertyNames, messages));
        .forEach((node, idx) => {
            let propNamesForNode: { [p: string]: any };
            if (element.name === Edm.Apply) {
                isUnknownFunction = !functionSignatures.has(
                    getElementAttributeValue(element, Edm.Function) as FunctionName
                );
                propNamesForNode = {};
                if (node.type === ELEMENT_TYPE) {
                    const parameterIndex = getChildElementPosition(idx, element);
                    propNamesForNode =
                        getPropertyNamesProvidingFunctionParameters(
                            valueHandlingContext,
                            getPropertyNamesProvidingValueForType,
                            element,
                            parameterIndex
                        )[0] || {};
                }
            } else {
                propNamesForNode = propertyNames;
            }

            if (node.type === ELEMENT_TYPE) {
                const childElement: Element = node;
                if (propNamesForNode[childElement.name]) {
                    properties.push(childElement);
                } else if (unsupportedDynamicExpressionMap[childElement.name]) {
                    const message = i18n.t(
                        'Element_0_and_its_subElements_are_not_validated_by_XML_annotation_language_server',
                        {
                            element: element.name
                        }
                    );
                    messages.push({
                        message: message,
                        severity: DiagnosticSeverity.Information,
                        range: element.nameRange
                    });
                } else if (childElement.name !== Edm.Annotation || !isAnnotationAllowed(element)) {
                    // omit messages for apply function (with invalid function name due to case issue)
                    if (!isUnknownFunction) {
                        const message = i18n.t('Element_not_allowed_here_0', {
                            element: childElement.name
                        });
                        messages.push({
                            message: message,
                            severity: DiagnosticSeverity.Error,
                            range: childElement.nameRange || childElement.range,
                            rule: 'record-collection-path-not-allowed',
                            data: {
                                name: childElement.name,
                                type
                            }
                        });
                    }
                } else if (childElement.name === Edm.Annotation) {
                    properties.push(childElement);
                }
            }
        });

    return { properties, messages };
}

function processSingleTextNode(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    allowedTypes: ValueType[],
    singleTextNode: TextNode,
    primitiveValueExpression: {
        supportedTypes: {
            [typeName: string]: true;
        };
        defaultType: string;
    },
    pathExpression: {
        supportedTypes: {
            [type: string]: true;
        };
        defaultType: string;
        isInstancePath: boolean;
    },
    messages: Diagnostic[]
) {
    const value = singleTextNode ? singleTextNode.text : '';
    const multilineType = singleTextNode ? singleTextNode.multilineType : null;
    const range = singleTextNode ? singleTextNode.range : element.nameRange || element.contentRange;
    if (element.name === Edm.String && valueHandlingContext.nodeContext?.sideEffectsTargetProperties) {
        // check property path represented as string
        const property = {
            name: Edm.PropertyPath,
            nameRange: element.nameRange,
            value: value,
            isStringValue: true,
            valueRange: range
        };

        valueHandlingContext.nodeContext.allowWildCardInPath = true;
        messages.push(
            ...checkValueForVariantType(
                valueHandlingContext.context,
                [{ ...allowedTypes[0], name: EdmType.PropertyPath }],
                [],
                property.valueRange,
                (type) => checkPathExpressions(valueHandlingContext, type, property)
            )
        );
        valueHandlingContext.nodeContext.allowWildCardInPath = false;
    } else if (primitiveValueExpression) {
        const nodeValueTypes = getTypesForElement(valueHandlingContext, element, valueHandlingContext.pathBase);
        messages.push(...checkStrictComparableTypes(valueHandlingContext, nodeValueTypes, element.range));
        // check primitive types
        messages.push(
            ...checkValueForVariantType(
                valueHandlingContext.context,
                allowedTypes,
                nodeValueTypes,
                element.range,
                (type) => checkPrimitiveValue(valueHandlingContext, type, element.name, value, range, multilineType),
                !valueHandlingContext.nodeContext?.dataFieldValueProperty
            )
        );
    } else if (element.name === Edm.EnumMember) {
        // check enum types
        const ranges = singleTextNode?.fragmentRanges;
        const nodeValueTypes = getTypesForElement(valueHandlingContext, element, valueHandlingContext.pathBase);
        // Makes no sense to check Edm.Int compatible primitive types because they aren't defined in vocabularies and ignored in check procedure
        // Empty diagnostic result shades real enum expression problems (in case of variant types)
        const intCompatibleTypes = expandWithCompatibleTypes(valueHandlingContext.context, [
            { name: EdmType.Int16 }
        ]).map((t) => t.name);
        const applicableTypes = allowedTypes.filter((t) => !intCompatibleTypes.includes(t.name));
        messages.push(
            ...checkValueForVariantType(
                valueHandlingContext.context,
                applicableTypes,
                nodeValueTypes,
                range,
                (type) => handleEnumValue(valueHandlingContext, type, value, range, false, '', ranges) as Diagnostic[]
            )
        );
    } else if (pathExpression) {
        // check path expressions
        const property = {
            name: element.name,
            nameRange: element.nameRange,
            value: value,
            isStringValue: true,
            valueRange: range
        };

        const pathExpressionValueType = getTypeOfPathExpression(value, valueHandlingContext);
        messages.push(...checkStrictComparableTypes(valueHandlingContext, [pathExpressionValueType], range));
        messages.push(
            ...checkValueForVariantType(
                valueHandlingContext.context,
                allowedTypes,
                pathExpressionValueType ? [pathExpressionValueType] : [],
                property.valueRange,
                (type) => checkPathExpressions(valueHandlingContext, type, property),
                !valueHandlingContext.nodeContext?.dataFieldValueProperty
            )
        );
    }
}

/**
 * check value
 * @param valueHandlingContext
 * @param type - value needs to comply to this type
 * @param element - value to be checked
 * @param checkTrace
 * @returns Diagnostic[]
 */
export const checkValue: CheckCallback = (
    valueHandlingContext: ValueHandlingContext,
    types: ValueType[],
    element: Element,
    parentElement: Element,
    checkTrace: CheckTrace,
    logger: Logger
): Diagnostic[] => {
    // TODO find out if value is required based on type (facets, default Value...)
    const allowedTypes = adjustRequestedTypes(types, valueHandlingContext);
    try {
        // value is only required if isNullable is explicitly set to false and type is not a collection or a path expression
        const valueRequired = allowedTypes.some(
            (type) => type.facets && type.facets.isNullable === false && !type.asCollection && !pathTypeMap[type.name]
        );
        const messages: Diagnostic[] = [];
        // find appropriate check based on element name
        const pathExpression = pathExpressionMap[element.name];
        const primitiveValueExpression = primitiveValueConstantExpressionMap[element.name];
        const dynamicExpressionMetadata = dynamicExpressionSpecialMap[element.name];
        const dynamicExpressionSignature = dynamicExpressionSignatureMap.get(element.name as Edm);

        if (primitiveValueExpression || element.name === Edm.EnumMember || pathExpression) {
            // element must have single text node as child - no attributes or sub elements allowed!
            const singleTextNode = checkSingleTextNode(element, messages);
            if (!singleTextNode && valueRequired) {
                if (element.name !== Edm.String) {
                    // empty string element is considered as empty string
                    const message = i18n.t('Value_required_in_node_0', {
                        element: element.name
                    });
                    messages.push({
                        message: message,
                        severity: DiagnosticSeverity.Error,
                        range: element.nameRange,
                        rule: 'value-required',
                        data: {
                            name: element.name
                        }
                    });
                } else if (valueHandlingContext.nodeContext?.sideEffectsTargetProperties) {
                    const message = i18n.t('Empty_property_path_as_string');
                    messages.push({
                        message: message,
                        severity: DiagnosticSeverity.Error,
                        range: element.nameRange
                    });
                }
            } else {
                processSingleTextNode(
                    valueHandlingContext,
                    element,
                    allowedTypes,
                    singleTextNode,
                    primitiveValueExpression,
                    pathExpression,
                    messages
                );
            }
        } else if (dynamicExpressionMetadata) {
            // check 'special' dynamic expressions: Annotation, Collection, Record, PropertyValue, ...
            messages.push(
                ...checkDynamicExpressionSpecial(
                    valueHandlingContext,
                    allowedTypes,
                    element,
                    dynamicExpressionMetadata,
                    valueRequired,
                    checkTrace,
                    logger
                )
            );
        } else if (dynamicExpressionSignature) {
            // check other dynamic expressions
            // For dynamic expression local context is needed to process Null-valued parameters in a special way
            const localContext = {
                ...valueHandlingContext,
                nodeContext: {
                    ...(valueHandlingContext.nodeContext ?? {}),
                    nullExpressionParameterFound: false,
                    ignoreValueType: false,
                    nestedNodesMessages: []
                } as NodeContext
            };
            // Collect messages of current node paramters validation
            const result = checkDynamicExpression(
                localContext,
                allowedTypes,
                element,
                parentElement,
                dynamicExpressionSignature,
                adjustRequestedTypes,
                getPropertyNamesProvidingValueForType,
                checkValue,
                checkTrace,
                logger
            ).filter((message) => {
                // Filter out messages related to type validation in case of strict comparison with Null
                // Parameters handler sets nullExpressionParameterFound context flag to true when Null is found
                return !(
                    message.rule === 'incomplete-path-with-type' &&
                    [Edm.Eq, Edm.Ne].includes(element.name as Edm) &&
                    localContext.nodeContext.nullExpressionParameterFound
                );
            });
            // Merge messages collected on deeply nested levels
            result.push(...localContext.nodeContext.nestedNodesMessages);

            // If parent node is dynamic expression which has Null value in parameters, which potentially enables any type values
            // then current node messages are returned via node context, to avoid filtering out (on parent level) type related validation errors coming from nested levels
            if (valueHandlingContext.nodeContext?.nullExpressionParameterFound) {
                valueHandlingContext.nodeContext.nestedNodesMessages =
                    valueHandlingContext.nodeContext.nestedNodesMessages ?? [];
                valueHandlingContext.nodeContext.nestedNodesMessages.push(...result);
            } else {
                messages.push(...result);
            }
        } else if (element.name === Edm.Null && valueHandlingContext.nodeContext?.strictEqualityComparison) {
            // all Null to be used in EQ expressions
        } else {
            const message = i18n.t('Element_not_allowed_here_0', {
                element: element.name
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: element.nameRange || element.range,
                rule: 'record-collection-path-not-allowed',
                data: {
                    name: element.name,
                    type: types[0]
                }
            });
        }
        return messages;
    } catch (exceptionTerm) {
        let message = allowedTypes.map((type) => convertValueTypeToString(type)).join(', ');
        message = `AnnotationService: error checking element "${
            element.name
        }" for types "${message}", path to element: ${checkTrace.getPath()}`;
        logger.error(message);
    }
};

function checkPropertyValue(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    subElement: Element,
    checkedRecordType: ValueType,
    property: Element | Attribute,
    checkTrace: CheckTrace,
    logger: Logger
) {
    const nodeContext = valueHandlingContext.nodeContext
        ? { ...valueHandlingContext.nodeContext, dataFieldValueProperty: false }
        : {};
    let valueHandlingContextForProp: ValueHandlingContext = { ...valueHandlingContext, nodeContext };
    const currentPropertyName = getElementAttributeValue(property as Element, Edm.Property);
    if (
        valueHandlingContext.currentStructureProperty &&
        valueHandlingContext.currentStructureProperty.propertyPathSegments
    ) {
        // update identification of current structure property (CDS split annotation support)
        const propertyPathSegmentsForProp = [
            ...valueHandlingContext.currentStructureProperty.propertyPathSegments,
            currentPropertyName
        ];
        valueHandlingContextForProp = {
            aliasInfo: valueHandlingContext.aliasInfo,
            context: valueHandlingContext.context,
            pathBase: valueHandlingContext.pathBase,
            currentFileUri: valueHandlingContext.currentFileUri,
            currentStructureProperty: {
                targetPath: valueHandlingContext.currentStructureProperty.targetPath,
                term: valueHandlingContext.currentStructureProperty.term,
                qualifier: valueHandlingContext.currentStructureProperty.qualifier,
                propertyPathSegments: propertyPathSegmentsForProp
            }
        };
    }
    if (isCommonValueListRecord(checkedRecordType.name) && currentPropertyName === PropertyNamesSpecial.Parameters) {
        const currentEntitySetName = getValueListCollectionPathValue(element);
        valueHandlingContextForProp.nodeContext = {
            valueListProps: {
                currentEntitySetName
            }
        };
    }
    if (isValueListParameterRecord(checkedRecordType.name)) {
        const dataPropertyPath = getValueListLocalDataPropertyPath(element);
        if (valueHandlingContext.nodeContext?.valueListProps) {
            valueHandlingContextForProp.nodeContext = {
                ...valueHandlingContext.nodeContext
            };
            valueHandlingContextForProp.nodeContext.valueListProps.currentLocalDataPropertyPath = dataPropertyPath;
        }
    }
    if (isSideEffectsRecord(checkedRecordType.name) && currentPropertyName === PropertyNamesSpecial.TargetProperties) {
        valueHandlingContextForProp.nodeContext = {
            sideEffectsTargetProperties: true
        };
    }

    if (isDataFieldValueProperty(checkedRecordType.name, currentPropertyName)) {
        valueHandlingContextForProp.nodeContext = {
            dataFieldValueProperty: true,
            noCollectionsSupported: true
        };
    }
    return checkPropertyValueElement(
        valueHandlingContextForProp,
        subElement,
        checkedRecordType,
        checkValue,
        checkTrace,
        logger
    );
}

function checkCollection(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    subElement: Element,
    type: ValueType,
    idx: number,
    checkTrace: CheckTrace,
    logger: Logger
): Diagnostic[] {
    const allowedEntryTypes = adjustRequestedTypes([{ ...type, asCollection: false }], valueHandlingContext).map(
        (t) => ({
            name: t.name,
            asCollection: false,
            facets: type.facets,
            constraints: type.constraints
        })
    );
    checkTrace.registerElement(element, idx);
    checkTrace.push();
    checkTrace.registerElement(subElement);
    // no need to identify structure properties inside (no CDS splitting inside collections)
    let valueHandlingContextColl: ValueHandlingContext = valueHandlingContext;
    if (valueHandlingContext.currentStructureProperty) {
        valueHandlingContextColl = {
            ...valueHandlingContext,
            currentStructureProperty: {
                ...valueHandlingContext.currentStructureProperty,
                propertyPathSegments: null
            }
        };
    }
    const propertyMessages = checkValue(
        valueHandlingContextColl,
        allowedEntryTypes,
        subElement,
        element,
        checkTrace,
        logger
    );
    checkTrace.pop();

    return propertyMessages;
}

function checkRequiredValues(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    valueCount: number,
    valueRequired: boolean,
    messages: Diagnostic[]
): Diagnostic[] {
    if (valueCount === 0 && valueRequired) {
        let requiredFor = element.name;
        if (valueHandlingContext.context.supportSplit && element.name === Edm.PropertyValue) {
            const propName = getElementAttributeValue(element, Edm.Property);
            requiredFor = propName || requiredFor;
        }
        const message = i18n.t('Value_required_for_0', {
            element: requiredFor
        });
        const errorRange = element.nameRange || element.contentRange || element.range;
        messages.push({
            message: message,
            severity: DiagnosticSeverity.Error,
            range: errorRange
        });
    }
    return messages;
}

function checkAttribute(
    valueHandlingContext: ValueHandlingContext,
    property: Attribute,
    type: ValueType,
    providesValue: boolean,
    firstValuePath: string,
    propertyMessages: Diagnostic[]
): { providesValue: boolean; firstValuePath: string; propertyMessages: Diagnostic[] } {
    propertyMessages.push(
        ...checkValueForVariantType(
            valueHandlingContext.context,
            [type],
            [],
            property.valueRange,
            (typeToCheck) => {
                const { messages: msgs, providesValue: isValue } = checkAttributeValue(
                    valueHandlingContext,
                    property,
                    typeToCheck
                );

                providesValue = providesValue || isValue;
                return msgs;
            },
            !valueHandlingContext.nodeContext?.dataFieldValueProperty
        )
    );

    if (providesValue && property.name === 'Path' && !firstValuePath) {
        firstValuePath = property.value;
    }
    return { providesValue: providesValue, firstValuePath: firstValuePath, propertyMessages: propertyMessages };
}

function checkElement(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    property: Element,
    type: ValueType,
    firstValuePropertyName: string,
    firstValuePath: string,
    idx: number,
    checkedRecordType: ValueType,
    propertyNamesProvidingValue: {
        [key: string]: CompletionItemCategory;
    },
    checkTrace: CheckTrace,
    logger: Logger,
    targetTermMap: Map<string, boolean> = new Map(),
    providesValue: boolean,
    applyFunctionParameterIndex: number,
    messages: Diagnostic[],
    propertyMessages: Diagnostic[]
) {
    checkTrace.push();
    // check sub node: determine type for sub node and delegate to new check() call
    const subElement = property;
    if (property.name === Edm.Annotation) {
        // embedded annotation - build targetKinds and targetType
        const targetKinds = [element.name];
        if (type.asCollection) {
            targetKinds.push(Edm.Collection);
        }
        let targetType = convertValueTypeToString(type);
        if (element.name === Edm.Record && getElementAttribute(element, Edm.Type)) {
            targetType = getFullyQualifiedNameByAttribute(element, valueHandlingContext.aliasInfo.aliasMap, Edm.Type);
        } else if (firstValuePropertyName) {
            targetType =
                findTypeForPropertyName(valueHandlingContext, firstValuePropertyName, firstValuePath) || targetType;
        }
        propertyMessages = checkAnnotationValue(
            valueHandlingContext.context,
            subElement,
            valueHandlingContext.pathBase,
            null,
            '',
            valueHandlingContext.aliasInfo,
            targetTermMap,
            checkTrace,
            logger,
            type.constraints?.applicableTerms,
            targetKinds,
            targetType
        );
    } else if (element.name === Edm.Collection) {
        providesValue = true;
        const collectionMessages = checkCollection(
            valueHandlingContext,
            element,
            subElement,
            type,
            idx,
            checkTrace,
            logger
        );
        propertyMessages = propertyMessages.concat(collectionMessages);
    } else if (element.name === Edm.Record && property.name === Edm.PropertyValue) {
        // only allowed sub element is PropertyValue
        if (checkedRecordType) {
            providesValue = true;
            const propValueMessages = checkPropertyValue(
                valueHandlingContext,
                element,
                subElement,
                checkedRecordType,
                property,
                checkTrace,
                logger
            );
            propertyMessages = propertyMessages.concat(propValueMessages);
        }
    } else if (element.name === Edm.Apply) {
        // check parameter node for Apply Function
        if (property.type === ELEMENT_TYPE) {
            ++applyFunctionParameterIndex;
        }
        messages.push(
            ...checkApplyFunctionProperty(
                { ...valueHandlingContext, nodeContext: {} },
                element,
                property,
                applyFunctionParameterIndex,
                checkValue,
                checkTrace,
                logger
            )
        );
    } else if (propertyNamesProvidingValue[property.name]) {
        // check all value providing sub elements
        providesValue = true;
        if (property.name !== Edm.Collection) {
            checkTrace.registerElement(property);
        }
        propertyMessages = checkValue(valueHandlingContext, [type], subElement, element, checkTrace, logger);
    }
    checkTrace.pop();
    return {
        messages: messages,
        propertyMessages: propertyMessages,
        providesValue: providesValue,
        applyFunctionParameterIndex: applyFunctionParameterIndex
    };
}

// check all properties (only allowed attributes and sub nodes are left)
function checkProperties(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    dynamicExpressionMetadata: DynamicExpressionSpecial,
    type: ValueType,
    properties: (Element | Attribute)[],
    checkTrace: CheckTrace,
    checkedRecordType: ValueType,
    propertyNamesProvidingValue: {
        [key: string]: CompletionItemCategory;
    },
    logger: Logger,
    messages: Diagnostic[]
): { messages: Diagnostic[]; valueCount: number } {
    let firstValuePropertyName = '';
    let firstValuePath = '';
    const targetTermMap: Map<string, boolean> = new Map();
    let applyFunctionParameterIndex = -1;
    let valueCount = 0;

    properties.forEach((property, idx) => {
        let propertyMessages: Diagnostic[] = [];
        let providesValue = false;
        if (property.type === ATTRIBUTE_TYPE) {
            // check attribute
            ({ providesValue, firstValuePath, propertyMessages } = checkAttribute(
                valueHandlingContext,
                property,
                type,
                providesValue,
                firstValuePath,
                propertyMessages
            ));
        } else if (property.type === ELEMENT_TYPE) {
            ({ messages, propertyMessages, providesValue, applyFunctionParameterIndex } = checkElement(
                valueHandlingContext,
                element,
                property,
                type,
                firstValuePropertyName,
                firstValuePath,
                idx,
                checkedRecordType,
                propertyNamesProvidingValue,
                checkTrace,
                logger,
                targetTermMap,
                providesValue,
                applyFunctionParameterIndex,
                messages,
                propertyMessages
            ));
        }
        if (providesValue) {
            // count number of values provided, remember where first value came from
            firstValuePropertyName = firstValuePropertyName || property.name;
            valueCount++;
        }
        // add property messages unless value is not allowed
        if (!dynamicExpressionMetadata.multipleValuesAllowed && valueCount > 1) {
            const message = i18n.t('No_additional_value_possible_Value_provided_already_via_0', {
                property: firstValuePropertyName
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: property.nameRange
            });
        } else {
            messages.push(...propertyMessages);
        }
    });

    return { messages: messages, valueCount: valueCount };
}

/**
 * check special dynamic expression (Annotation, Collection, Record, PropertyValue)
 * @param valueHandlingContext
 * @param type
 * @param element
 * @param dynamicExpressionMetadata
 * @param messages
 * @param valueRequired
 */
function checkDynamicExpressionSpecial(
    valueHandlingContext: ValueHandlingContext,
    types: ValueType[],
    element: Element,
    dynamicExpressionMetadata: DynamicExpressionSpecial,
    valueRequired: boolean,
    checkTrace: CheckTrace,
    logger: Logger
): Diagnostic[] {
    const nodeValueTypes = getTypesForElement(valueHandlingContext, element, valueHandlingContext.pathBase);

    return checkValueForVariantType(
        valueHandlingContext.context,
        adjustRequestedTypes(types, valueHandlingContext),
        nodeValueTypes,
        element.range,
        (type) => {
            let messages: Diagnostic[] = [];
            // check optional/allowed attributes, collect valid attributes and sub nodes as 'properties'
            let propertyNamesProvidingValue: { [key: string]: CompletionItemCategory } = {};
            if (element.name === Edm.Record) {
                propertyNamesProvidingValue[Edm.PropertyValue] = CompletionItemCategory.ValueElement; // only sub node 'PropertyValue' can provide a value
            } else if (element.name === Edm.Apply) {
                // for Apply allowed prop names depend on node index
            } else {
                const typeForValue = element.name !== Edm.Collection ? type : { name: type.name, asCollection: false };
                if (type.asCollection) {
                    const adjustedTypesForValue = adjustRequestedTypes([typeForValue], valueHandlingContext);
                    adjustedTypesForValue.forEach((t) => {
                        propertyNamesProvidingValue = {
                            ...propertyNamesProvidingValue,
                            ...getPropertyNamesProvidingValueForType(valueHandlingContext, t)
                        };
                    });
                } else {
                    propertyNamesProvidingValue = getPropertyNamesProvidingValueForType(
                        valueHandlingContext,
                        typeForValue
                    );
                }
            }

            const unsupportedDynamicExpression = hasUnsupportedDynamicExpression(element, valueHandlingContext);
            let valueCount = 0;
            let applyFunctionProperties = null;
            if (unsupportedDynamicExpression) {
                messages.push(generateUnsupportedElementWarning(valueHandlingContext, element));
                valueRequired = false;
            } else {
                const { properties, messages: dynamicExpressionMessages } = checkDynamicExpressionAttrAndSubNodeNames(
                    valueHandlingContext,
                    element,
                    dynamicExpressionMetadata,
                    propertyNamesProvidingValue,
                    type
                );

                messages.push(...dynamicExpressionMessages);

                let checkedRecordType: ValueType = null;
                if (element.name === Edm.Record) {
                    checkedRecordType = checkAndExtractTypeForRecord(valueHandlingContext, type, element, messages);
                    adjustApplicableTermsConstraint(type, checkedRecordType?.constraints);
                } else if (element.name === Edm.Apply) {
                    applyFunctionProperties = properties;
                }

                ({ messages, valueCount } = checkProperties(
                    valueHandlingContext,
                    element,
                    dynamicExpressionMetadata,
                    type,
                    properties,
                    checkTrace,
                    checkedRecordType,
                    propertyNamesProvidingValue,
                    logger,
                    messages
                ));
            }
            if (element.name === Edm.Apply && !!applyFunctionProperties) {
                // check Apply Function has all mandatory parameters
                messages.push(...checkApplyFunctionMandatoryParameters(element, applyFunctionProperties));
            } else if (valueCount === 0 && valueRequired) {
                messages = checkRequiredValues(valueHandlingContext, element, valueCount, valueRequired, messages);
            }

            return messages;
        },
        !valueHandlingContext.nodeContext?.dataFieldValueProperty
    );
}
