import type { Term } from '@sap-ux/odata-vocabularies';
import type { Element, ElementChild, FileUri } from '@sap-ux/odata-annotation-core';
import { Edm, ELEMENT_TYPE, resolveName } from '@sap-ux/odata-annotation-core';
import type { AliasMap, Context, TermOrPropertyMap } from '../types/context';

/**
 * An element is considered to be structure if it has any of the following child
 * a. Annotation
 * b. PropertyValue
 * c. Record
 * @param element
 */
const isStructure = (elements: ElementChild[] = []): boolean => {
    return elements.some(
        (elm) => elm.type === ELEMENT_TYPE && [Edm.Annotation, Edm.PropertyValue, Edm.Record].includes(elm.name as Edm)
    );
};

class VisitElement {
    visit(
        element: ElementChild,
        termMap: TermOrPropertyMap,
        context: Context,
        aliasMap: AliasMap,
        uri: FileUri,
        parent: Element
    ): void {
        if (element.type === ELEMENT_TYPE) {
            if (this[element.name]) {
                this[element.name](element, termMap, context, aliasMap, uri, parent);
            }
        }
    }
    Annotation(
        element: Element,
        currentMap: TermOrPropertyMap,
        context: Context,
        aliasMap: AliasMap,
        uri: FileUri,
        parent: Element
    ): void {
        // resolve type for term
        const termValue = element.attributes[Edm.Term] ? element.attributes[Edm.Term].value || '' : '';
        const resolvedTermName = resolveName(termValue, aliasMap);
        const term: Term = context.vocabularies.getTerm(resolvedTermName.qName);
        if (!term) {
            return;
        }
        const qualifier = element.attributes[Edm.Qualifier] ? element.attributes[Edm.Qualifier].value || '' : '';
        let termKey = `${parent && parent.name !== Edm.Record ? '$Element' : ''}@${resolvedTermName.qName}`;
        termKey = qualifier ? `${termKey}#${qualifier}` : termKey;
        let childMap;
        if (currentMap[termKey]) {
            // duplicate
            if (isStructure(element.content)) {
                if (!currentMap[termKey]['$Self']) {
                    currentMap[termKey] = { $Self: currentMap[termKey] || new Set<FileUri>() };
                }
                const self = currentMap[termKey]['$Self'] as Set<FileUri>;
                self.add(uri);
            } else {
                const prop = currentMap[termKey] as Set<FileUri>;
                if (prop.add) {
                    prop.add(uri);
                }
            }
            childMap = currentMap[termKey];
        } else {
            const set = new Set<FileUri>();
            set.add(uri);
            if (isStructure(element.content)) {
                childMap = currentMap[termKey] = {
                    $Self: set
                };
            } else {
                childMap = currentMap[termKey] = set;
            }
        }
        for (let i = 0; element.content?.length > i; i++) {
            const subElement = element.content[i];
            // split logic ends for collections - i.e. CDS does not combine split parts for an entry in a collection
            if (!(subElement.type === ELEMENT_TYPE && subElement.name === Edm.Collection)) {
                this.visit(subElement, childMap, context, aliasMap, uri, element);
            }
        }
    }
    Record(element: Element, currentMap: TermOrPropertyMap, context: Context, aliasMap: AliasMap, uri: FileUri): void {
        const attr = element.attributes;
        if (attr && attr[Edm.Type] && attr[Edm.Type].valueRange) {
            // Type is only present in CDS source if valueRange is filled
            if (currentMap['$Type']) {
                // duplicate
                const type = currentMap['$Type'] as Set<FileUri>;
                type.add(uri);
            } else {
                currentMap['$Type'] = new Set<FileUri>().add(uri);
            }
        }
        for (let i = 0; element.content?.length > i; i++) {
            this.visit(element.content[i], currentMap, context, aliasMap, uri, element);
        }
    }
    PropertyValue(
        element: Element,
        currentMap: TermOrPropertyMap,
        context: Context,
        aliasMap: AliasMap,
        uri: FileUri
    ): void {
        const attr = element.attributes;
        let value = '';
        let childMap = currentMap;
        if (attr && attr[Edm.Property]) {
            const propAttr = attr[Edm.Property];
            value = propAttr.value;

            if (currentMap[value]) {
                // duplicate
                if (isStructure(element.content)) {
                    const self = currentMap[value]['$Self'] as Set<FileUri>;
                    self.add(uri);
                    childMap = currentMap[value] as TermOrPropertyMap;
                } else {
                    const prop = currentMap[value] as Set<FileUri>;
                    prop.add(uri);
                }
            } else {
                const set = new Set<FileUri>();
                set.add(uri);
                if (isStructure(element.content)) {
                    currentMap[value] = {
                        $Self: set
                    };
                    childMap = currentMap[value] as TermOrPropertyMap;
                } else {
                    currentMap[value] = set;
                }
            }
        }
        for (let i = 0; element.content?.length > i; i++) {
            const elm = element.content[i] as Element;
            if (elm.name === Edm.Record || elm.name === Edm.Annotation) {
                childMap = currentMap[value] as TermOrPropertyMap;
            }
            this.visit(element.content[i], childMap, context, aliasMap, uri, element);
        }
    }
}
const visitor = new VisitElement();

export const addSplitAnnotationKeys = (
    uri: FileUri,
    target: string,
    terms: Element[],
    context: Context,
    aliasMap: AliasMap
): void => {
    if (!context.supportSplit) {
        return;
    }
    if (!context.splitAnnotationKeys[target]) {
        context.splitAnnotationKeys[target] = {};
    }
    const termMap = context.splitAnnotationKeys[target];
    for (let i = 0; terms.length > i; i++) {
        visitor.visit(terms[i], termMap, context, aliasMap, uri, null);
    }
    if (Object.keys(context.splitAnnotationKeys[target]).length === 0) {
        // delete target with empty data
        delete context.splitAnnotationKeys[target];
    }
};
