import type { Range } from 'vscode-languageserver-types';
import { createErrorDiagnosticWithRule } from './ruleFactories';
import { i18n } from '../i18n';
import type { Alias, NameCasePathValueDiagnostic, NamespaceString } from '@sap-ux/odata-annotation-core';
import { NAME_CASE_ISSUE_PATH_VALUE } from '@sap-ux/odata-annotation-core';

export function createNameCasePathValueDiagnostic(
    unknown: NamespaceString | Alias,
    known: NamespaceString | Alias,
    range: Range
): NameCasePathValueDiagnostic {
    const message = i18n.t('0_is_unknown_Do_you_mean_1', {
        unknown: unknown,
        known: known
    });
    const diagnostic: NameCasePathValueDiagnostic = createErrorDiagnosticWithRule(
        NAME_CASE_ISSUE_PATH_VALUE,
        message,
        range
    );

    diagnostic.data = {
        wrong: unknown,
        correct: known
    };
    return diagnostic;
}
