import type { XsnCompileModel } from '@sap/cds-compiler';
import { $lsp } from '@sap/cds-compiler';
import { join } from 'path';

export type FileContent = string;
export interface File {
    fileUri: string;
    fileContent: FileContent;
}

/**
 * get CDS 'compile model'
 *  - we are using an internal cds compiler call (from a fixed version of cds compiler package)!
 * @param project
 * @param files
 */
export const compile = async (root: string, files: string[], cache?: Map<string, File>): Promise<XsnCompileModel> => {
    try {
        const fileCache = [...(cache?.entries() || [])].reduce((acc, [uri, file]) => {
            acc[join(root, uri)] = file.fileContent;
            return acc;
        }, {});
        const options = { fallbackParser: 'cds', attachValidNames: true, attachTokens: true, smart: {}, messages: [] };
        const compileModel = await ($lsp?.compile)(files, root, options, fileCache);
        compileModel.compiler = { getArtifactName: $lsp.getArtifactName };
        return compileModel;
    } catch (error) {
        const { model } = error;
        model.compiler = { getArtifactName: $lsp.getArtifactName };
        return model;
    }
};
