import { fileURLToPath, pathToFileURL } from 'url';
import type { XsnCompileModel } from '@sap/cds-compiler';
import { createFileIndexFromSource } from './fileIndex';
import type { AutoCreationMode, BlitzIndex, FileIndex } from './types';
import { toggleCase } from './cdsSource';

const copy = (source: Iterable<string>): { into: (target: Hull<string>) => void } => ({
    into: (target: Hull<string>): void => {
        for (const t of source) {
            target.add(t);
        }
    }
});

const getUriIndex = (model: XsnCompileModel): [Map<string, FileIndex>, string[]] => {
    const files = new Map<string, FileIndex>();
    const builtUris: string[] = [];
    const sourcePaths = Object.keys(model.sources || {});
    for (const sourcePath of sourcePaths) {
        const source = model.sources[sourcePath];
        const sourceUri = pathToFileURL(source.realname).toString();
        const index = createFileIndexFromSource(sourceUri, source, model.compiler);
        files.set(sourceUri, index);
        builtUris.push(sourceUri);
    }
    return [files, builtUris];
};

const forUri =
    (files: Map<string, FileIndex>) =>
    (uri: string, create?: AutoCreationMode): FileIndex => {
        let fileIndex: FileIndex | undefined = undefined;
        fileIndex = files.get(uri);

        // for windows, some NodeJS methods will output uppercase drive letters, some in lowercase
        if (!fileIndex && process.platform === 'win32') {
            const parsedUri = fileURLToPath(uri);
            uri = pathToFileURL(parsedUri).toString();
            fileIndex = files.get(uri); // sometimes uri contains escaped characters
            if (!fileIndex) {
                uri = toggleCase(parsedUri.charAt(0)) + parsedUri.slice(1); // sometimes drive letter case differs
                uri = pathToFileURL(uri).toString();
                fileIndex = files.get(uri);
            }
        }

        if (fileIndex) {
            return fileIndex;
        }

        if (create !== undefined) {
            throw new Error('Create parameter is not supported.');
        }

        throw new Error('File index not found.');
    };
export function createIndex(model: XsnCompileModel): BlitzIndex {
    const _transitiveDependencies = new Map<string, Hull<string>>();
    const builtUris: string[] = [];
    const [newFiles, newUris] = getUriIndex(model);
    const files = new Map([...newFiles]);
    builtUris.push(...newUris);

    function getTransitiveDependencies(source: string): Set<string> {
        let result = _transitiveDependencies.get(source) ?? calculateTransitiveDependencies([source])[0];
        if (result.isShared) {
            result = new Set(result); // clone - this is a shared hull of a cycle and we must remove the given uri
            result.delete(source);
            _transitiveDependencies.set(source, result);
        }
        return result;
    }

    function calculateTransitiveDependencies(sources: string[]): Hull<string>[] {
        function followAndCollect(ownUri: string): Hull<string> {
            const alreadyCalculated = _transitiveDependencies.get(ownUri);
            if (alreadyCalculated) {
                return alreadyCalculated;
            }

            let ownHull = new Set<string>();
            _transitiveDependencies.set(ownUri, ownHull);

            const directDependentUris = files.get(ownUri)?.directDependentUris ?? [];
            copy(directDependentUris).into(ownHull); // add all directs first
            for (const dependencyUri of directDependentUris) {
                const foreignHull = followAndCollect(dependencyUri);
                if (foreignHull.has(ownUri)) {
                    // cycle. maybe not complete yet. share hulls
                    copy(ownHull).into(foreignHull);
                    ownHull = foreignHull;
                    _transitiveDependencies.set(ownUri, ownHull);
                    foreignHull.isShared = true;
                } else {
                    copy(foreignHull).into(ownHull);
                }
            }
            return ownHull;
        }

        return sources.map((uri) => followAndCollect(uri));
    }

    return Object.freeze({
        builtUris,
        getTransitiveDependencies,
        forUri: forUri(files)
    });
}

type Hull<T> = Set<T> & { isShared?: boolean };
