import type { Page } from './pages';
import type { FlexibleColumnLayoutType, ViewTypes } from './webapp/manifest';

export enum FioriElementsVersion {
    v2 = 'v2',
    v4 = 'v4'
}
export enum OdataVersion {
    v2 = 'v2',
    v4 = 'v4'
}
export interface Target {
    fioriElements: FioriElementsVersion;
    odata: OdataVersion;
}

export interface Pages {
    [key: string]: Page;
}

export enum PageHeaderType {
    Dynamic = 'Dynamic'
}
export interface AppSettings {
    forceGlobalRefresh?: boolean;
    objectPageHeaderType?: PageHeaderType;
    showDraftToggle?: boolean;
    flexibleColumnLayout?: FlexibleColumnLayout;
    pageTitle?: string;
    appDescription?: string;
    appSubTitle?: string;
    viewPath?: string;
    path?: string;
    viewType?: ViewTypes;
    controllerExtensions?: ControllerExtensions;
}

export interface Application {
    $schema?: string;
    id: string;
    pages: Pages;
    home: string;
    target: Target;
    settings?: AppSettings;
}

export enum RootIntent {
    listReportV2 = 'masterDetail-display',
    listReportV4 = 'fe-lrop-v4',
    ovp = 'OVP-display'
}

export interface FlexibleColumnLayout {
    defaultTwoColumnLayoutType?: FlexibleColumnLayoutType;
    defaultThreeColumnLayoutType?: FlexibleColumnLayoutType;
}

export const enum AppType {
    FioriElement = 'SAP Fiori elements',
    UI5Freestyle = 'SAPUI5 freestyle',
    UI5Extension = 'SAPUI5 Extension',
    Reuse = 'Fiori Reuse',
    Adaptation = 'Fiori Adaptation'
}

export const AppPomXmlArtifactIdPlaceholder = `\${project.artifactId}`;

export interface ControllerExtension {
    controllerNames?: string[];
    controllerName?: string;
}

export interface ControllerExtensions {
    [key: string]: ControllerExtension;
}
