import type { CompletionItem } from 'vscode-languageserver';
import { EMPTY_VALUE_TYPE, PATH_TYPE } from '@sap-ux/cds-annotation-parser';
import type { CompletionItemAdapterParams, CompletionItemAdapterWithGate } from '../types';

function gate({ context, originalItem, lastItem }: CompletionItemAdapterParams): boolean {
    return (
        context.type === 'value' &&
        (context.valueType === PATH_TYPE || context.valueType === EMPTY_VALUE_TYPE) &&
        !!lastItem &&
        originalItem.commitCharacters?.length > 0
    );
}

function adapter({ lastItem }: CompletionItemAdapterParams): CompletionItem | undefined {
    return {
        ...lastItem,
        commitCharacters: ['.']
    };
}

/**
 * Converts commit characters to CDS path segment delimiter
 */
export const pathCommitCharacterAdapter: CompletionItemAdapterWithGate = {
    gate,
    adapter
};
