import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, Range, TextEdit } from 'vscode-languageserver';

import type { Element } from '@sap-ux/odata-annotation-core';
import { Edm } from '@sap-ux/odata-annotation-core';

import type {
    AnnotationGroupContainerContext,
    CompletionContext,
    CompletionHandlerArgs,
    CompletionItemAdapterParams,
    ModularCompletionHandler,
    ProviderResult
} from '../types';
import { updatePlaceholder } from '../utils';
import { print } from '@sap/ux-cds-odata-annotation-converter';
import { textArrangementAdapter } from '../adapters/textArrangement';

function annotationGroupGate(context: CompletionContext): boolean {
    return context.type === 'container' && context.kind === 'annotation-group';
}

function annotationGroupItemProvider(
    { proposedReplacementRange }: AnnotationGroupContainerContext,
    { getCompletionItems, file, pointer, position }: CompletionHandlerArgs
): ProviderResult {
    // When we have some text value in group, pointer is resolved to term name, but we need to get snippets
    // TODO: check if this should be fixed in pointer resolution logic
    const adaptedPointer =
        proposedReplacementRange && pointer.endsWith('value') ? pointer.split('/').slice(0, 3).join('/') : pointer;
    const segments = adaptedPointer.split('/').slice(1);
    const isTargetContext = segments.length === 2 && segments[0] === 'targets';
    const items = getCompletionItems(file, position, isTargetContext, adaptedPointer);
    return {
        itemsForAdapter: items,
        completionItems: []
    };
}

function termSnippetAdapter({
    context: { position, groupName, proposedReplacementRange, hasComma },
    originalItem
}: CompletionItemAdapterParams<AnnotationGroupContainerContext>): CompletionItem | undefined {
    if (originalItem?.data?.generic === undefined) {
        return;
    }
    const [alias, termName] = originalItem.data.generic.name.split('.');
    if (alias !== groupName) {
        return;
    }
    const snippet: Element = JSON.parse(JSON.stringify(originalItem.data.generic.data));
    updatePlaceholder(snippet, false);
    const attrNames = Object.keys(snippet.attributes ?? {});
    if (attrNames.includes(Edm.Term)) {
        snippet.attributes[Edm.Term].value = snippet.attributes[Edm.Term].value.replace(`${groupName}.`, '');
    }

    const text = `${print(snippet)}${hasComma ? '' : ','}`;
    const range = proposedReplacementRange ?? Range.create(position, position);
    return {
        label: termName,
        insertTextFormat: InsertTextFormat.Snippet,
        kind: CompletionItemKind.Class,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        filterText: termName,
        textEdit: TextEdit.replace(range, text)
    };
}

export const annotationGroupHandler: ModularCompletionHandler = {
    name: 'annotation-group',
    type: 'modular',
    gate: annotationGroupGate,
    providers: [annotationGroupItemProvider],
    mappers: [],
    adapters: [textArrangementAdapter, termSnippetAdapter]
};
