import type { CompletionItem } from 'vscode-languageserver';
import type { CompletionItemAdapterParams, CompletionItemAdapterWithGate } from '../types';

function gate({ lastItem }: CompletionItemAdapterParams): boolean {
    return lastItem && !!process.env['THEIA_PARENT_PID'];
}

function adapter({ lastItem }: CompletionItemAdapterParams): CompletionItem | undefined {
    return {
        ...lastItem,
        deprecated: false
    };
}

export const theiaDeprecatedAdapter: CompletionItemAdapterWithGate = {
    gate,
    adapter
};
