/**
 * remove all path expression cached content involving a specific namespace
 * @param context
 * @param namespace
 */
export function removeOutdatedCacheContent(context: Context, fileUri: FileUri): void {
    delete context.navigationSourceMap[fileUri];
    delete context.pathExpressions.targetPath[fileUri];

    const cachesToUpdate = [
        context.labeledElements,
        context.referenceLocations,
        context.metadataReferenceLocations,
        context.pathExpressions.annotationPath,
        context.pathExpressions.path,
        context.pathExpressions.pathCc,
        context.pathExpressions.annotationPathCc,
        context.pathExpressions.propertyPathCc
    ];
    cachesToUpdate.forEach((pathCachePart) => {
        Object.keys(pathCachePart)
            .filter((fileUrisConcat) => fileUrisConcat.split('|').includes(fileUri))
            .forEach((invalidatedUrl) => {
                delete pathCachePart[invalidatedUrl];
            });
    });
}
type ReferenceInAnnotation = {
    /** real value of path/string (i.e.attributes/subNodes of type "Path", "PropertyPath", "AnnotationPath", "NavigationPropertyPath") which are either absolute or relative to annotation target */
    value: string;
    /** filled always, used to generate metadata references */
    valueRange: Range;
    /** artificial absolute path for string value representing metadata references (use // as separator to actual string value i.e. "/service.EntityContainer/entitySet//propertyNameAsStringValue") */
    absolutePath?: string;
    /** only filled for paths to annotations (i.e. containing term cast segment), used to generate annotation references */
    termCastRange?: Range;
};

/**
 * Add annotation references (e.g. term cast segments of paths used in annotation value) to cache
 * Also fills context with information about labeled elements
 * @param context
 * @param fileUri
 * @param fileUrisConcat
 * @param annotation
 * @param targetPath
 * @param aliasInfo
 */
function addAnnotationReferencesToCache(
    context: Context,
    fileUri: string,
    fileUrisConcat: string,
    annotation: Element,
    targetPath: PathValue,
    aliasInfo: AliasInformation
): void {
    // recursively find all "*Path" and strings containing references (in attributes or subnodes)
    const references: ReferenceInAnnotation[] = [];
    const term = annotation.attributes?.[Edm.Term]?.value || '';
    collectReferencesInElement(annotation, references, context, aliasInfo, fileUrisConcat, { term });
    if (references.length === 0) {
        return;
    }
    // remove aliases from target path
    const targetPathResolved = resolvePath(targetPath, aliasInfo);
    const realFileUri = fileUri.startsWith(GHOST_FILENAME_PREFIX) ? fileUri.substring(1) : fileUri;
    references.forEach((reference) => {
        let hiddenPath = '';
        let visiblePath = '';
        if (reference.absolutePath) {
            if (reference.absolutePath.indexOf('//') > 0) {
                [hiddenPath, visiblePath] = reference.absolutePath.split('//'); // only path segments after  "//" separator are visible
            } else {
                visiblePath = reference.absolutePath; // string value represents absolute path (e.g. entity/action name)
            }
        } else {
            hiddenPath = targetPathResolved;
            visiblePath = reference.value;
        }
        // remove aliases from relative path
        const visiblePathResolved = resolvePath(visiblePath, aliasInfo);
        // only consider part before first @ character
        const [visiblePathResolvedBeforeAt, visiblePathAfterAt] = visiblePathResolved.split('@');
        handlePathBeforeAtSymbol(
            context,
            visiblePathResolvedBeforeAt,
            realFileUri,
            hiddenPath,
            reference.value,
            reference.valueRange,
            fileUrisConcat
        );
        handlePathAfterAtSymbol(
            context,
            visiblePathResolvedBeforeAt,
            realFileUri,
            targetPathResolved,
            visiblePathAfterAt,
            reference,
            fileUrisConcat
        );
    });
}
function handlePathBeforeAtSymbol(
    context: Context,
    visiblePath: string,
    fileUri: string,
    hiddenPath: string,
    visiblePathOrig: string,
    visiblePathRange: Range,
    fileUrisConcat: string
) {
    if (!visiblePath) {
        return;
    }
    // fill metadata references for each segment of relative path
    // (could actually be absolute path e.g. for Action property containing action name as string value)
    let currentMdElement = hiddenPath ? getPathBaseMetadataElement(context.metadata, hiddenPath) : null;
    const segments = visiblePath.split('/');
    const segmentsOrig = visiblePathOrig.split('/');
    for (const [index, segment] of segments.entries()) {
        const path = currentMdElement
            ? `${currentMdElement?.structuredType || currentMdElement?.path}/${segment}`
            : segment;
        currentMdElement = context.metadata.getMetadataElement(path);
        if (!currentMdElement) {
            break;
        }
        const segmentOrig = segmentsOrig[index];
        const offset = visiblePathOrig.search(new RegExp(`\\b${segmentOrig}\\b`));
        const { line, character } = visiblePathRange.start;
        const range: Range = {
            start: { line: line, character: character + offset },
            end: { line: line, character: character + offset + segmentOrig.length }
        };
        const location: Location = { range, uri: fileUri };
        const locationKey = location.range.start.line + ',' + location.range.start.character;
        const mdPathName = currentMdElement.path;
        context.metadataReferenceLocations[fileUrisConcat] = context.metadataReferenceLocations[fileUrisConcat] || {};
        context.metadataReferenceLocations[fileUrisConcat][mdPathName] =
            context.metadataReferenceLocations[fileUrisConcat][mdPathName] || new Map();
        context.metadataReferenceLocations[fileUrisConcat][mdPathName].set(locationKey, location);
    }
}

function handlePathAfterAtSymbol(
    context: Context,
    relativePathResolvedBeforeAt: string,
    fileUri: string,
    targetPathResolved: string,
    relativePathAfterAt: string,
    relativePath: ReferenceInAnnotation,
    fileUrisConcat: string
): void {
    if (relativePathAfterAt) {
        // build full path from base path and relative path, normalize it
        const rawPath = relativePathResolvedBeforeAt.startsWith('/')
            ? relativePathResolvedBeforeAt
            : relativePathResolvedBeforeAt
            ? targetPathResolved + '//' + relativePathResolvedBeforeAt
            : targetPathResolved;
        // build location and add it to the cache
        const location: Location = { range: relativePath.termCastRange, uri: fileUri };
        const termQualifierName = relativePathAfterAt.split('/')[0];
        if (!location?.range) {
            return;
        } // TODO this happens if onFileChanged is called from Annotation API (getMissingRefs())
        const locationKey = location.range.start.line + ',' + location.range.start.character;
        context.referenceLocations[fileUrisConcat] = context.referenceLocations[fileUrisConcat] || {};
        context.referenceLocations[fileUrisConcat][termQualifierName] =
            context.referenceLocations[fileUrisConcat][termQualifierName] || {};
        context.referenceLocations[fileUrisConcat][termQualifierName][rawPath] =
            context.referenceLocations[fileUrisConcat][termQualifierName][rawPath] || new Map();
        context.referenceLocations[fileUrisConcat][termQualifierName][rawPath].set(locationKey, location);
    }
}

function getEntityContainerMdElement(metadataService: MetadataService): MetadataElement {
    for (const [rootName, rootMdElement] of metadataService.getRootMetadataElements()) {
        const rootTargetKinds = metadataService.getEdmTargetKinds(rootName);
        if (rootTargetKinds.includes(Edm.EntityContainer)) {
            return rootMdElement;
        }
    }
}
function collectReferencesInElement(
    element: Element,
    references: ReferenceInAnnotation[],
    context: Context,
    aliasInfo: AliasInformation,
    fileUrisConcat: string,
    options?: { collectionRootEntityType?: string; term?: string }
): void {
    // collect labeled elements
    if (element.name === Edm.LabeledElement) {
        handleLabeledElement(element, context, aliasInfo, fileUrisConcat);
    }

    // @Common.ValueList annotation? add entity set from 'CollectionRoot' property and keep it in options
    const optionsEnhanced = { ...options };
    if (options?.term.endsWith('ValueList') && !optionsEnhanced.collectionRootEntityType) {
        const collectionRoot = findValueListCollectionRoot(element);
        optionsEnhanced.collectionRootEntityType = addValueListCollectionRoot(context, collectionRoot, references);
    }
    // @Common.SideEffects/TargetProperties? is collection of string values representing relative paths (its string because can end with wildcard '*')
    if (
        options?.term.endsWith('SideEffects') &&
        element.name === Edm.PropertyValue &&
        element.attributes[Edm.Property]?.value === 'TargetProperties'
    ) {
        addSideEffectsTargetProperties(element, references);
    }

    // collect path attributes
    collectReferencesInAttributes(element, references);

    // collect path elements
    collectReferencesInContent(element, references, context, aliasInfo, fileUrisConcat, optionsEnhanced);

    // handle remaining string properties containing metadata references
    collectStringReferencesPerRecordType(element, references, options?.collectionRootEntityType);
}

function addSideEffectsTargetProperties(element: Element, references: ReferenceInAnnotation[]) {
    const collectionElement = element.content.find(
        (subElement) => subElement.type === ELEMENT_TYPE && subElement.name === Edm.Collection
    ) as Element;
    (collectionElement?.content || [])
        .filter((entry) => entry.type === ELEMENT_TYPE && entry.name === Edm.String)
        .forEach((stringElement) => {
            const textNode = stringElement ? getSingleTextNode(stringElement as Element) : null;
            if (textNode?.text && textNode?.range) {
                references.push({ value: textNode.text, valueRange: textNode.range });
            }
        });
}

function collectReferencesInAttributes(element: Element, relativePaths: ReferenceInAnnotation[]): void {
    Object.keys(element.attributes || {})
        .filter((attrName) => attrName.indexOf('Path') >= 0)
        .map((pathAttrName) => element.attributes[pathAttrName])
        .filter((attribute) => !!attribute.value && !!attribute.valueRange)
        .forEach((attribute) => {
            relativePaths.push({
                value: attribute.value,
                valueRange: attribute.valueRange, // for metadata references
                termCastRange:
                    attribute.value.indexOf('@') >= 0
                        ? getTermCastRange(attribute.value, attribute.valueRange) || attribute.valueRange
                        : null
            });
        });
}

function collectReferencesInContent(
    element: Element,
    references: ReferenceInAnnotation[],
    context: Context,
    aliasInfo: AliasInformation,
    fileUrisConcat: string,
    options?: { collectionRootEntityType?: string; term?: string }
): void {
    (element.content || [])
        .filter((subElement) => subElement.type === ELEMENT_TYPE)
        .forEach((subElement: Element) => {
            if (subElement.name?.indexOf('Path') >= 0) {
                // path element (always has string value)
                const textNode = getSingleTextNode(subElement);
                if (textNode?.text && textNode?.range) {
                    let range: Range = null;
                    if (textNode.text.indexOf('@') >= 0) {
                        const segmentIndexAt = textNode.text
                            .split('/')
                            .findIndex((segment) => segment.indexOf('@') >= 0);
                        const segmentRange =
                            segmentIndexAt >= 0 && textNode.fragmentRanges
                                ? textNode.fragmentRanges[segmentIndexAt]
                                : getTermCastRange(textNode.text, textNode.range);
                        range = segmentRange || textNode.range;
                    }
                    references.push({ value: textNode.text, valueRange: textNode.range, termCastRange: range });
                }
            } else {
                // other element - do recursive call
                collectReferencesInElement(subElement, references, context, aliasInfo, fileUrisConcat, options);
            }
        });
}

function getTermCastRange(path: string, range: Range): Range {
    // calculate range of first term cast segment occuring in path
    const valueFromAt = path.slice(path.indexOf('@'));
    const valueFromSlash = valueFromAt.indexOf('/') >= 0 ? valueFromAt.slice(valueFromAt.indexOf('/')) : '';
    if (range) {
        return {
            start: { line: range.start.line, character: range.start.character + path.indexOf('@') },
            end: { line: range.end.line, character: range.end.character - valueFromSlash.length }
        };
    }
}

function handleLabeledElement(element, context: Context, aliasInfo: AliasInformation, fileUrisConcat: string): void {
    // add entry in labeled element cache
    const name = getElementAttributeValue(element, 'Name');
    if (!name) {
        return;
    }
    const namespace = aliasInfo.currentFileNamespace;
    context.labeledElements[fileUrisConcat] = context.labeledElements[fileUrisConcat] || {};
    context.labeledElements[fileUrisConcat][namespace] = context.labeledElements[fileUrisConcat][namespace] || {
        countMap: new Map(),
        upperCaseMap: new Map()
    };
    const { upperCaseMap, countMap } = context.labeledElements[fileUrisConcat][namespace];
    upperCaseMap.set(name.toUpperCase(), name);
    countMap.set(name, (countMap.get(name) || 0) + 1);
}

/**
 * recursively add type specific entries for element to provided map
 * @param context
 * @param fileUrisConcat
 * @param annotation
 * @param targetPath
 * @param aliasInfo
 */
function addAnnotationToPathExpressionCache(
    context: Context,
    fileUrisConcat: string,
    annotation: Element,
    targetPath: PathValue,
    aliasInfo: AliasInformation,
    addSupportForCodeCompletion?: boolean
): void {
    function handleElement(element: Element, path: PathValue, valueType: ValueType, map: any, noDrill?: boolean): void {
        // add entry in path cache (map)
        const typeName = convertValueTypeToString(valueType);
        map[typeName] = map[typeName] || {};
        addPathToObject(map[typeName], path);
        // additional entry for corresponding abstract type (Collection, EntityType, ComplexType, PrimitiveType)
        const abstractType = getAbstractTypeName(context, typeName);
        if (abstractType && abstractType !== valueType.name) {
            map[abstractType] = map[abstractType] || {};
            addPathToObject(map[abstractType], path);
        }
        if (noDrill) {
            return;
        }
        // drill into content only where it complies with type
        if (valueType.asCollection) {
            if (element.name === 'Annotation') {
                // annotation value provided via attribute, e.g. path: no more cache entries
            } else if (element.name === 'Collection') {
                // loop over collection entries
                let index = 0;
                (element.content || []).forEach((subElement: Element) => {
                    if (subElement.type === ELEMENT_TYPE) {
                        if (subElement.name === 'Annotation') {
                            addAnnotationToPathExpressionCache(context, fileUrisConcat, subElement, path, aliasInfo);
                        } else {
                            const valueTypeEntry = Object.assign({}, valueType);
                            valueTypeEntry.asCollection = false;
                            handleElement(subElement, path + '/' + String(index++), valueTypeEntry, map);
                        }
                    }
                });
            } else {
                // e.g. Path as sub node: no more cache entries
            }
        } else {
            let typeObject: VocabularyType = null;
            if (!valueType.name.startsWith('Edm.')) {
                typeObject = getVocabularyType(context, valueType.name);
            }
            if (typeObject && typeObject.kind === Edm.ComplexType) {
                let recordTypeName = valueType.name;
                if (element.name === 'Record' && getElementAttribute(element, 'Type')) {
                    // specific type specified in Record
                    recordTypeName = element.attributes['Type'].value || recordTypeName;
                    recordTypeName = resolveName(recordTypeName, aliasInfo.aliasMapVocabulary).qName;
                }
                if (element.name === 'Annotation' || element.name === 'Record') {
                    // get all possible properties of record type
                    const structuredTypeDefinition: ExpandedComplexType =
                        context.vocabularies.getComplexType(recordTypeName);
                    const properties: Map<string, ComplexTypeProperty> =
                        (structuredTypeDefinition && structuredTypeDefinition.properties) || new Map();

                    const propNameMap: { [propertyName: string]: FullyQualifiedTypeName } = {};
                    properties.forEach((property) => (propNameMap[property.name] = property.type));

                    // handle all sub nodes representing properties
                    (element.content || []).forEach((subElement: Element) => {
                        if (subElement.name === 'Annotation') {
                            addAnnotationToPathExpressionCache(context, fileUrisConcat, subElement, path, aliasInfo);
                        } else if (subElement.name === 'PropertyValue') {
                            const propName = getElementAttributeValue(subElement, Edm.Property) || '';
                            if (propName) {
                                let property = properties.get(propName);
                                if (propName && !property && context.supportSplit) {
                                    // split supported: record type might be coming from somewhere else - try to find any valid property for base type
                                    const derivedTypeNames = [
                                        ...context.vocabularies.getDerivedTypeNames(valueType.name)
                                    ];
                                    for (let i = 0; i < derivedTypeNames.length && !property; i++) {
                                        property = context.vocabularies.getComplexTypeProperty(
                                            derivedTypeNames[i],
                                            propName
                                        );
                                    }
                                }
                                if (property) {
                                    // valid property
                                    delete propNameMap[propName];
                                    const valueTypeEntry: ValueType = {
                                        name: property.type,
                                        asCollection: property.isCollection
                                    };
                                    handleElement(subElement, path + '/' + propName, valueTypeEntry, map);
                                }
                            }
                        }
                    });

                    if (!context.supportSplit) {
                        // add cache entries for remaining properties
                        // (not when split is supported: we don't know the correct type)
                        Object.keys(propNameMap).forEach((propName) => {
                            const propTypeName = propNameMap[propName];
                            map[propTypeName] = map[propTypeName] || {};
                            addPathToObject(map[propTypeName], path + '/' + propName);
                            const abstractType = getAbstractTypeName(context, typeName);
                            if (abstractType && abstractType !== valueType.name) {
                                map[abstractType] = map[abstractType] || {};
                                addPathToObject(map[abstractType], path);
                            }
                        });
                    }
                }
            }
        }
    }
    // resolve type for term
    const termAttributeValue = annotation.attributes['Term'] ? annotation.attributes['Term'].value || '' : '';
    const resolvedTermName = resolveName(termAttributeValue, aliasInfo.aliasMapVocabulary);
    const term: Term = context.vocabularies.getTerm(resolvedTermName.qName);
    if (!term || resolvedTermName.namespace === context.vocabularies.cdsVocabulary.namespace) {
        return;
    }
    const valueType = getValueTypeFromTerm(context, term, true);
    // determine qualifier
    const qualifier = annotation.attributes['Qualifier'] ? annotation.attributes['Qualifier'].value || '' : '';
    // add term specific path to annotationPath cache (for specific term and for group containing all terms)
    if (!context.completionOnly) {
        context.pathExpressions.annotationPath[fileUrisConcat] =
            context.pathExpressions.annotationPath[fileUrisConcat] || {};
        context.pathExpressions.annotationPath[fileUrisConcat][resolvedTermName.qName] =
            context.pathExpressions.annotationPath[fileUrisConcat][resolvedTermName.qName] || {};
        context.pathExpressions.annotationPath[fileUrisConcat][cacheKeyAnyTermName] =
            context.pathExpressions.annotationPath[fileUrisConcat][cacheKeyAnyTermName] || {};
    }
    if (addSupportForCodeCompletion) {
        // also add annotation path to annotationPathCc for code completion
        context.pathExpressions.annotationPathCc[fileUrisConcat] =
            context.pathExpressions.annotationPathCc[fileUrisConcat] || {};
        context.pathExpressions.annotationPathCc[fileUrisConcat][resolvedTermName.qName] =
            context.pathExpressions.annotationPathCc[fileUrisConcat][resolvedTermName.qName] || {};
        context.pathExpressions.annotationPathCc[fileUrisConcat][cacheKeyAnyTermName] =
            context.pathExpressions.annotationPathCc[fileUrisConcat][cacheKeyAnyTermName] || {};
    }

    let separator = '/';
    let path = '';
    if (!context.completionOnly || addSupportForCodeCompletion) {
        // find out target type (different handling for NavigationProperty)
        const targetElement = lookupTarget(context, targetPath, aliasInfo).metadataElement;
        const targetKinds = targetElement ? targetElement.targetKinds : [];
        // annotations on navigation properties require segments like /toCurrency@Capabilities.InsertRestrictions
        // and are only supported by model paths (i.e. not suitable for path cache)
        // url://docs.oasis-open.org/odata/odata-csdl-xml/v4.01/csprd06/odata-csdl-xml-v4.01-csprd06.html#sec_PathSyntax
        if (targetKinds.includes(Edm.NavigationProperty)) {
            // CDS associations have both target kinds: NavigationProperty and Property, if possible assign term to property
            if (
                !targetKinds.includes(Edm.Property) ||
                ((term.appliesTo || []).length && !term.appliesTo.includes(PROPERTY_KIND))
            ) {
                // term must be applied to navigation property - need to be referenced without separator
                separator = '';
            }
        }
        path = targetPath + separator + '@' + resolvedTermName.qName + (qualifier ? '#' + qualifier : '');
    }
    if (!context.completionOnly) {
        addPathToObject(context.pathExpressions.annotationPath[fileUrisConcat][resolvedTermName.qName], path);
        addPathToObject(context.pathExpressions.annotationPath[fileUrisConcat][cacheKeyAnyTermName], path);
    }
    if (addSupportForCodeCompletion && separator) {
        // annotations on navigation properties should not appear in cc
        addPathToObject(context.pathExpressions.annotationPathCc[fileUrisConcat][resolvedTermName.qName], path);
        addPathToObject(context.pathExpressions.annotationPathCc[fileUrisConcat][cacheKeyAnyTermName], path);
    }
    // add schema level entry for path cache
    if (!context.completionOnly) {
        context.pathExpressions.path[fileUrisConcat] = context.pathExpressions.path[fileUrisConcat] || {};
    }
    if (addSupportForCodeCompletion) {
        context.pathExpressions.pathCc[fileUrisConcat] = context.pathExpressions.pathCc[fileUrisConcat] || {};
    }
    if (valueType.name.split('.').pop() === 'AggregatedPropertyType') {
        const props = getVirtualProperties(annotation);
        props.forEach((propertyName) => {
            const path = targetPath + separator + propertyName;
            if (!context.completionOnly) {
                context.pathExpressions.path[fileUrisConcat][EdmType.VirtualProperty] =
                    context.pathExpressions.path[fileUrisConcat][EdmType.VirtualProperty] || {};
                addPathToObject(context.pathExpressions.path[fileUrisConcat][EdmType.VirtualProperty], path);
            }
            if (addSupportForCodeCompletion) {
                context.pathExpressions.pathCc[fileUrisConcat][EdmType.VirtualProperty] =
                    context.pathExpressions.pathCc[fileUrisConcat][EdmType.VirtualProperty] || {};
                addPathToObject(context.pathExpressions.pathCc[fileUrisConcat][EdmType.VirtualProperty], path);
                // virtual property should be available for property path code completion
                context.pathExpressions.propertyPathCc[fileUrisConcat] =
                    context.pathExpressions.propertyPathCc[fileUrisConcat] || {};
                context.pathExpressions.propertyPathCc[fileUrisConcat][EdmType.VirtualProperty] =
                    context.pathExpressions.propertyPathCc[fileUrisConcat][EdmType.VirtualProperty] || {};
                addPathToObject(context.pathExpressions.propertyPathCc[fileUrisConcat][EdmType.VirtualProperty], path);
            }
        });
    }

    // try to find sub element of annotation carrying the value
    let valueNodeFound = false;
    let isPrimitiveValueType = !!primitiveTypeMap[valueType.name] || !!pathTypeMap[valueType.name];
    if (!isPrimitiveValueType) {
        isPrimitiveValueType = context.vocabularies.getType(valueType.name)?.kind === Edm.EnumType;
    }
    (annotation.content || []).forEach((subNode) => {
        if (subNode.type === ELEMENT_TYPE) {
            if (subNode.name === 'Annotation') {
                if (!context.completionOnly) {
                    // annotation directly embedded in this annotation
                    const annoPath = targetPath + '/@' + resolvedTermName.qName;
                    addAnnotationToPathExpressionCache(context, fileUrisConcat, subNode, annoPath, aliasInfo);
                }
            } else if (!valueNodeFound) {
                // only take first value node
                valueNodeFound = true;
                if (!context.completionOnly) {
                    handleElement(subNode, path, valueType, context.pathExpressions.path[fileUrisConcat]);
                }
                if (addSupportForCodeCompletion && separator && !isPrimitiveValueType) {
                    handleElement(subNode, path, valueType, context.pathExpressions.pathCc[fileUrisConcat], true);
                }
            }
        }
    });
    if (!valueNodeFound) {
        // value could be provided via attribute notation
        if (!context.completionOnly) {
            handleElement(annotation, path, valueType, context.pathExpressions.path[fileUrisConcat]);
        }
        if (addSupportForCodeCompletion && separator && !isPrimitiveValueType) {
            handleElement(annotation, path, valueType, context.pathExpressions.pathCc[fileUrisConcat], true);
        }
    }
}

/**
 * add content of annotation file to context (invalidate/fill all affected caches)
 * @param context
 * @param annotationFile
 * @param aliasInfo
 */
export function addAnnotationFileToContext(
    context: Context,
    annotationFile: AnnotationFile,
    aliasInfo: AliasInformation,
    currentFileUri: string
): Context {
    // loop over all annotations tags content
    annotationFile.targets.forEach((targetEntry) => {
        // remove aliases from target; collect all involved namespaces
        const fileUriMap: { [fileUri: string]: true } = {};
        fileUriMap[currentFileUri] = true;
        const targetSegments = targetEntry.name
            .split('/')
            .filter((segment) => !!segment)
            .map((segment) => {
                let segmentWithoutAlias = segment;
                if (segmentWithoutAlias.indexOf('.') > 0) {
                    const resolvedName = resolveName(segmentWithoutAlias, aliasInfo.aliasMapMetadata);
                    const fileUriFromNamespace = context.namespaceFileUriMap.metadata[resolvedName.namespace];
                    fileUriMap[fileUriFromNamespace] = true;
                    segmentWithoutAlias = resolvedName.qName;
                }
                return segmentWithoutAlias;
            });
        const targetPath = targetSegments.length ? targetSegments.join('/') : '';
        const fileUrisConcat: string = Object.keys(fileUriMap).join('|');
        // handle all annotations for target
        targetEntry.terms.forEach((annotation) => {
            if (targetPath) {
                addAnnotationToPathExpressionCache(context, fileUrisConcat, annotation, targetPath, aliasInfo, true);
                addAnnotationReferencesToCache(
                    context,
                    currentFileUri,
                    fileUrisConcat,
                    annotation,
                    targetPath,
                    aliasInfo
                );
            }
        });
        if (context.supportSplit) {
            addSplitAnnotationKeys(currentFileUri, targetPath, targetEntry.terms, context, aliasInfo.aliasMap);
        } else {
            // to support where used also for target paths (handled by CDS-LSP for cds --> only needed for EDMX)
            addTargetPathReferencesToCache(context, currentFileUri, targetEntry, aliasInfo);
        }
    });
    return context;
}
function addTargetPathReferencesToCache(
    context: Context,
    fileUri: string,
    targetEntry: Target,
    aliasInfo: AliasInformation
): void {
    const { name: targetPath, nameRange: targetRange } = targetEntry;
    const originalSegments = targetPath.split('/');
    const segments = originalSegments.map((segment) => getSegmentWithoutAlias(aliasInfo, segment));
    let currentMdElement: MetadataElement = null;
    const fileUriMap: { [fileUri: string]: true } = {};
    fileUriMap[fileUri] = true;
    for (const [index, segment] of segments.entries()) {
        if (!segment) {
            continue;
        }
        const originalSegment = originalSegments[index];
        if (segment.includes('.')) {
            const resolvedName = resolveName(segment, aliasInfo.aliasMapMetadata);
            const fileUriFromNamespace = context.namespaceFileUriMap.metadata[resolvedName?.namespace || ''];
            fileUriMap[fileUriFromNamespace] = true;
        }
        const offset = targetPath.search(new RegExp(`\\b${originalSegment}\\b`));
        const { line, character } = targetRange.start;
        const range: Range = {
            start: { line: line, character: character + offset },
            end: { line: line, character: character + offset + originalSegment.length }
        };
        const location: Location = { range, uri: fileUri };
        const path = currentMdElement
            ? `${currentMdElement.structuredType || currentMdElement.path}/${segment}`
            : segment;
        currentMdElement = context.metadata.getMetadataElement(path);
        if (!currentMdElement) {
            break;
        }
        const locationKey = location.range.start.line + ',' + location.range.start.character;
        const mdPathName = currentMdElement.path;
        const fileUrisConcat: string = Object.keys(fileUriMap).join('|');
        context.metadataReferenceLocations[fileUrisConcat] = context.metadataReferenceLocations[fileUrisConcat] || {};
        context.metadataReferenceLocations[fileUrisConcat][mdPathName] =
            context.metadataReferenceLocations[fileUrisConcat][mdPathName] || new Map();
        context.metadataReferenceLocations[fileUrisConcat][mdPathName].set(locationKey, location);
    }
}
function findValueListCollectionRoot(element: Element): ReferenceInAnnotation | undefined {
    // handle @Common.ValueList/CollectionPath
    if (element.name !== Edm.Record) {
        return;
    }
    const collectionPathElement = element.content.find(
        (entry): entry is Element =>
            entry.type === ELEMENT_TYPE &&
            entry.name === Edm.PropertyValue &&
            entry.attributes[Edm.Property]?.value === 'CollectionPath'
    );
    if (collectionPathElement) {
        return getReferenceFromStringValue(collectionPathElement);
    }
}
function addValueListCollectionRoot(
    context: Context,
    collectionPath: ReferenceInAnnotation,
    relativePaths: { value: string; valueRange: Range; range?: Range }[]
): string {
    if (!collectionPath?.value) {
        return '';
    }
    const entityContainer = getEntityContainerMdElement(context.metadata)?.name || '';
    const entitySetMdElement = context.metadata.getMetadataElement(`${entityContainer}/${collectionPath.value}`);
    if (entityContainer && entitySetMdElement) {
        // collectionPath points to valid entitySet
        collectionPath.absolutePath = `${entityContainer}//${collectionPath.value}`; // add absolute path to entity set
        relativePaths.push(collectionPath);
        return entitySetMdElement.structuredType;
    }
    // for CDS, @Common.ValueList might be annotated on db layer where no service is yet defined
    // try to find entity type based on common namespace
    const valueListEntityType = [...context.metadata.getRootMetadataElements().keys()].find((key) =>
        key.endsWith(collectionPath.value)
    );
    if (valueListEntityType) {
        collectionPath.absolutePath = valueListEntityType; // add absolute path to entity type
        relativePaths.push(collectionPath);
    }
    return valueListEntityType || '';
}
function collectStringReferencesPerRecordType(
    element: Element,
    references: ReferenceInAnnotation[],
    collectionRootEntityType?: string
): void {
    // string references are identified by specific record types containing specific property names
    const stringRefsRecordTypesMap = new Map([
        ['DataFieldForAction', 'Action'],
        ['DataFieldWithAction', 'Action'],
        ['ValueListParameterInOut', 'ValueListProperty'],
        ['ValueListParameterIn', 'ValueListProperty'],
        ['ValueListParameterOut', 'ValueListProperty'],
        ['ValueListParameterDisplayOnly', 'ValueListProperty'],
        ['ValueListParameterFilterOnly', 'ValueListProperty'],
        ['ValueListParameterConstant', 'ValueListProperty']
    ]);

    const recordTypeSimpleName = (element.attributes[Edm.Type]?.value || '').split('.').pop();
    if (element.name !== Edm.Record || !stringRefsRecordTypesMap.has(recordTypeSimpleName)) {
        return;
    }
    const propertyName = stringRefsRecordTypesMap.get(recordTypeSimpleName);
    const propElement = element.content.find(
        (entry): entry is Element =>
            entry.type === ELEMENT_TYPE &&
            entry.name === Edm.PropertyValue &&
            entry.attributes[Edm.Property]?.value === propertyName
    );
    if (!propElement) {
        return;
    }
    const reference = getReferenceFromStringValue(propElement);
    if (!reference.value) {
        return;
    }
    if (propertyName === 'Action') {
        reference.absolutePath = reference.value; // provide action name as absolute path
    } else if (collectionRootEntityType) {
        reference.absolutePath = `${collectionRootEntityType}//${reference.value}`; // provide value list property as absolute path
    }
    references.push(reference);
}
function getReferenceFromStringValue(element: Element): ReferenceInAnnotation | undefined {
    if (element.attributes[Edm.String]) {
        const attribute = element.attributes[Edm.String];
        return { value: attribute?.value, valueRange: attribute?.valueRange };
    } else {
        const stringElement = element.content.find(
            (subElement): subElement is Element => subElement.type === ELEMENT_TYPE && subElement.name === Edm.String
        );
        const textNode = stringElement ? getSingleTextNode(stringElement) : null;
        return { value: textNode?.text, valueRange: textNode?.range };
    }
}
