import type { Facets } from '@sap-ux/odata-annotation-core-types';
export type PrimitiveType =
    | 'Edm.Binary'
    | 'Edm.Boolean'
    | 'Edm.Byte'
    | 'Edm.Date'
    | 'Edm.DateTimeOffset'
    | 'Edm.Decimal'
    | 'Edm.Double'
    | 'Edm.Duration'
    | 'Edm.Guid'
    | 'Edm.Int16'
    | 'Edm.Int32'
    | 'Edm.Int64'
    | 'Edm.SByte'
    | 'Edm.Single'
    | 'Edm.Stream'
    | 'Edm.String'
    | 'Edm.TimeOfDay';
type PrimitiveTypeWithRangeCheck =
    | 'Edm.Byte'
    | 'Edm.Date'
    | 'Edm.DateTimeOffset'
    | 'Edm.Int16'
    | 'Edm.Int32'
    | 'Edm.Int64'
    | 'Edm.SByte';
type ValidationRegexPattern = { [primitiveType: string]: string };

/**
 * Validation for values of primitive types - Singleton
 */
export class ValidationPrimitiveTypeImpl {
    private static instance: ValidationPrimitiveTypeImpl;
    private static pattern: ValidationRegexPattern;

    protected constructor() {
        ValidationPrimitiveTypeImpl.pattern = this.getRegexPattern();
    }

    static getInstance(): ValidationPrimitiveTypeImpl {
        if (!ValidationPrimitiveTypeImpl.instance) {
            ValidationPrimitiveTypeImpl.instance = new ValidationPrimitiveTypeImpl();
        }

        return ValidationPrimitiveTypeImpl.instance;
    }

    /**
     * Returns true if 'value' contains a valid value for primitive type 'typeName'
     *
     * Specification: see https://docs.oasis-open.org/odata/odata-csdl-xml/v4.01/csprd06/odata-csdl-xml-v4.01-csprd06.html#sec_ConstantExpression
     *
     * @param typeName - Type of value
     * @param value    - Value
     */
    public isValid(typeName: PrimitiveType, value: string, facets?: Facets): boolean {
        let result: boolean;

        const pattern = this.getRegexPattern();

        const edmType = typeName.slice(4);

        if (typeof value === 'object') {
            return false;
        } else {
            result = this.isExactMatch(value, pattern[edmType]);
            if (
                result === true &&
                [
                    'Edm.Byte',
                    'Edm.Date',
                    'Edm.DateTimeOffset',
                    'Edm.Int16',
                    'Edm.Int32',
                    'Edm.Int64',
                    'Edm.SByte'
                ].includes(typeName)
            ) {
                result = this.isValidRange(typeName as PrimitiveTypeWithRangeCheck, value);
            }
        }
        if (result && facets && facets.precision >= 0) {
            result = this.isValidPrecision(typeName, value, facets.precision);
        }

        return result;
    }

    /**
     * Returns regex pattern for validation of primitive types
     *
     * See:

     * - https://docs.oasis-open.org/odata/odata-csdl-xml/v4.01/csprd06/odata-csdl-xml-v4.01-csprd06.html#sec_ConstantExpression
     * - http://docs.oasis-open.org/odata/odata/v4.01/cs01/abnf/odata-abnf-construction-rules.txt
     */
    protected getRegexPattern(): ValidationRegexPattern {
        let pattern = ValidationPrimitiveTypeImpl.pattern;

        if (!pattern) {
            pattern = {};
            // --- C. ABNF core definitions [RFC5234] ---
            // alpha  = %x41-5A / %x61-7A
            const alpha = '[a-zA-Z]';

            // A-to-F = "A" / "B" / "C" / "D" / "E" / "F"   (case insensitive, see https://tools.ietf.org/html/rfc5234)
            const aToF = '[a-fA-F]';

            // digit  = [0-9]
            const digit = '[0-9]';
            const digit3 = `${digit}{3}`;

            // hexdig = digit / A-to-F
            const hexdig = `(${digit}|${aToF})`;
            const hexdig4 = `${hexdig}{4}`;
            const hexdig8 = `${hexdig}{8}`;
            const hexdig12 = `${hexdig}{12}`;

            // oneToNine       = "1" / "2" / "3" / "4" / "5" / "6" / "7" / "8" / "9"
            const oneToNine = '[1-9]';

            // zeroToFiftyNine = ( "0" / "1" / "2" / "3" / "4" / "5" ) digit
            const zeroToFiftyNine = `[0-5]${digit}`;

            // --- 9. Punctiation ---
            // sign   = "+" / "%2B" / "-"
            const sign = '([+-]|%2B)';

            // --- 7. Literal Data Values ---
            // base64char  = alpha / digit / "-" / "_"
            const base64char = `(${alpha}|${digit}|-|_)`;
            const base64char2 = `${base64char}{2}`;
            const base64char4 = `${base64char}{4}`;

            // base64b16   = 2base64char ( 'A' / 'E' / 'I' / 'M' / 'Q' / 'U' / 'Y' / 'c' / 'g' / 'k' / 'o' / 's' / 'w' / '0' / '4' / '8' )   [ "=" ]
            const base64b16 = `${base64char2}(A|E|I|M|Q|U|Y|c|g|k|o|s|w|0|4|8)(=)?`;

            // base64b8    = base64char ( 'A' / 'Q' / 'g' / 'w' ) [ "==" ]
            const base64b8 = `${base64char}(A|Q|g|w)(==)?`;

            // binaryValue = *(4base64char) [ base64b16  / base64b8 ]
            pattern.Binary = `(${base64char4})*(${base64b16}|${base64b8})?`;

            // booleanValue = "true" / "false"
            pattern.Boolean = 'true|false';

            // nanInfinity
            const nanInfinity = `(NaN|-INF|INF)`;

            // decimalValue = [ sign ] 1*digit [ "." 1*digit ] [ "e" [ sign ] 1*digit ] / nanInfinity
            pattern.Decimal = `${sign}?${digit}{1,}([.]{1}${digit}{1,})?(e(${sign})?${digit}{1,})?|${nanInfinity}`;

            // doubleValue  = decimalValue ; IEEE 754 binary64 floating-point number (15-17 decimal digits)
            pattern.Double = pattern.Decimal;

            // singleValue  = decimalValue ; IEEE 754 binary32 floating-point number (6-9 decimal digits)
            pattern.Single = pattern.Decimal;

            // Char	   ::=   	[#x1-#xD7FF] | [#xE000-#xFFFD] | [#x10000-#x10FFFF]	/* any Unicode character, excluding the surrogate blocks, FFFE, and FFFF. */
            // for simlicity we take everything except: double quote
            const char = `[^"]`;

            // string = char*
            pattern.String = `${char}*`;

            // year  = [ "-" ] ( "0" 3digit / oneToNine 3*digit )
            const year = `-?(0${digit3}|${oneToNine}${digit3})`;

            // month = "0" oneToNine / "1" ( "0" / "1" / "2" )
            const month = `(0${oneToNine}|1[0-2])`;

            // day   = "0" oneToNine / ( "1" / "2" ) digit / "3" ( "0" / "1" )
            const day = `(0${oneToNine}|[12]${digit}|3[01])`;

            // hour   = ( "0" / "1" ) digit / "2" ( "0" / "1" / "2" / "3" )
            const hour = `([01]${digit}|2[0-3])`;

            // minute = zeroToFiftyNine
            const minute = zeroToFiftyNine;

            // second = zeroToFiftyNine
            const second = zeroToFiftyNine;

            // fractionalSeconds = 1*12digit
            const fractionalSeconds = `${digit}{1,12}`;

            // dateValue = year "-" month "-" day
            // https://docs.oasis-open.org/odata/odata-csdl-xml/v4.01/csprd06/odata-csdl-xml-v4.01-csprd06.html#sec_Date
            pattern.Date = `${year}-${month}-${day}`;

            // dateTimeOffsetValue = year "-" month "-" day "T" hour ":" minute [ ":" second [ "." fractionalSeconds ] ] ( "Z" / sign hour ":" minute )
            pattern.DateTimeOffset = `${year}-${month}-${day}T${hour}:${minute}(:${second}(.${fractionalSeconds})?)?(Z|${sign}${hour}:${minute})`; // [:${second}[.${fractionalSeconds}]](Z)`; //| sign hour ":" minute )`;

            // durationValue = [ SIGN ] "P" [ 1*DIGIT "D" ] [ "T" [ 1*DIGIT "H" ] [ 1*DIGIT "M" ] [ 1*DIGIT [ "." 1*DIGIT ] "S" ] ]
            pattern.Duration = `${sign}?P(${digit}{1,}D)?(T(${digit}{1,}H)?(${digit}{1,}M)?(${digit}{1,}([.]{1}${digit}{1,})?S)?)?`;

            // guidValue = 8hexdig "-" 4hexdig "-" 4hexdig "-" 4hexdig "-" 12hexdig
            pattern.Guid = `${hexdig8}-${hexdig4}-${hexdig4}-${hexdig4}-${hexdig12}`;

            // byteValue  = 1*3digit           ; numbers in the range from 0 to 255
            pattern.Byte = `${digit}{1,3}`;

            // sbyteValue = [ sign ] 1*3digit  ; numbers in the range from -128 to 127
            pattern.SByte = `${sign}?${digit}{1,3}`; // ToDo: additional range check needed, s.a!

            // int16Value = [ sign ] 1*5digit  ; numbers in the range from -32768 to 32767
            pattern.Int16 = `${sign}?${digit}{1,5}`; // ToDo: additional range check needed, s.a!

            // int32Value = [ sign ] 1*10digit ; numbers in the range from -2147483648 to 2147483647
            pattern.Int32 = `${sign}?${digit}{1,10}`; // ToDo: additional range check needed, s.a!

            // int64Value = [ sign ] 1*19digit ; numbers in the range from -9223372036854775808 to 9223372036854775807
            pattern.Int64 = `${sign}?${digit}{1,19}`; // ToDo: additional range check needed, s.a!

            // timeOfDayValue = hour ":" minute [ ":" second [ "." fractionalSeconds ] ]
            pattern.TimeOfDay = `${hour}:${minute}(:${second}(.${fractionalSeconds})?)?`;
        }

        return pattern;
    }

    /**
     * Returns true if 'value' exactly matches 'expression'
     */
    private isExactMatch(value: string, expression: string): boolean {
        return RegExp(`^(${expression})$`).test(value);
    }

    /**
     * Returns true if 'value' is within correct range
     */
    protected isValidRange(
        type: 'Edm.Byte' | 'Edm.Date' | 'Edm.DateTimeOffset' | 'Edm.Int16' | 'Edm.Int32' | 'Edm.Int64' | 'Edm.SByte',
        value: string
    ): boolean {
        let result = false;

        let valueInt: number;
        let valueBigInt: bigint;

        if (type === 'Edm.Int64') {
            valueBigInt = BigInt(value);
        } else if (['Edm.Byte', 'Edm.Int16', 'Edm.Int32', 'Edm.SByte'].includes(type)) {
            valueInt = parseInt(value);
        }

        if (type === 'Edm.Byte' && 0 <= valueInt && valueInt <= 255) {
            result = true;
        }

        if (type === 'Edm.Date') {
            result = this.isValidDayOfMonth(value);
        }

        if (type === 'Edm.DateTimeOffset') {
            const date = value.slice(0, 10);
            result = this.isValidDayOfMonth(date);
        }

        if (type === 'Edm.Int16' && -32768 <= valueInt && valueInt <= 32767) {
            result = true;
        }
        if (type === 'Edm.Int32' && -2147483648 <= valueInt && valueInt <= 2147483647) {
            result = true;
        }
        if (
            type === 'Edm.Int64' &&
            BigInt('-9223372036854775808') <= valueBigInt &&
            valueBigInt <= BigInt('9223372036854775807')
        ) {
            result = true;
        }
        if (type === 'Edm.SByte' && -128 <= valueInt && valueInt <= 127) {
            result = true;
        }

        return result;
    }

    protected isValidPrecision(typeName: PrimitiveType, value: string, precision: number): boolean {
        const temporalProperty = ['Edm.DateTimeOffset', 'Edm.Duration', 'Edm.TimeOfDay'];
        let valueLenght;
        if (temporalProperty.includes(typeName) && value.indexOf('.') !== -1) {
            valueLenght = value.split('.')[1].replace(/[^0-9]+/g, '').length;
        } else if (typeName === 'Edm.Decimal') {
            valueLenght = value.toString().replace('.', '').length;
        }

        return valueLenght > precision ? false : true;
    }
    /**
     * Returns true if date contains a valid day
     *
     * see: https://www.w3.org/TR/xmlschema11-2/#date :
     * The ·day· value must be
     * - no more than 30 if ·month· is one of 4, 6, 9, or 11,
     * - no more than 28 if ·month· is 2 and ·year· is not divisible by 4, or is divisible by 100 but not by 400,
     * - and no more than 29 if ·month· is 2 and ·year· is divisible by 400, or by 4 but not by 100.
     */
    protected isValidDayOfMonth(date: string): boolean {
        let result = false;

        const [year, month, day] = date.split('-').map((item) => parseInt(item));
        if (
            !(
                ([4, 6, 9, 11].includes(month) && day > 30) ||
                (month === 2 && (year % 4 > 0 || (year % 100 === 0 && year % 400 > 0)) && day > 28) ||
                (month === 2 && (year % 400 === 0 || (year % 4 === 0 && year % 100 > 0)) && day > 29)
            )
        ) {
            result = true;
        }

        return result;
    }
}

export const ValidationPrimitiveType = ValidationPrimitiveTypeImpl.getInstance();
