import type { CdsAnnotationIndex, CdsIndexingParams } from '../lspTypes';

import { VocabularyService } from '@sap-ux/odata-vocabularies';
import type { CdsAnnotationFile } from '@sap/ux-cds-odata-annotation-converter';
import { toAnnotationFile, toTargetMap } from '@sap/ux-cds-odata-annotation-converter';
import {
    getMetadataElementsFromMap,
    createMetadataCollector,
    createCdsCompilerFacade
} from '@sap/ux-cds-compiler-facade';
import URI from 'vscode-uri';

import { MetadataService } from '@sap-ux/odata-entity-model';
import type { AnnotationServiceInterface } from '@sap/ux-annotation-service';
import { AnnotationServiceImpl } from '@sap/ux-annotation-service';

import type { ServiceAnnotationFile } from '@sap-ux/odata-annotation-core';
import { cdsLogger } from '../log';
import { getDependentFileUris } from '../utils/general';

const vocabularyService = new VocabularyService(true);

export const getWhereUsedIndex = ({ index, ast, uris }: CdsIndexingParams): CdsAnnotationIndex => {
    // instantiate metadata service and generic component
    const facade = createCdsCompilerFacade(ast);
    const metadataService = new MetadataService({ uriMap: facade.getUriMap() });
    const genericAnnotationService: AnnotationServiceInterface = new AnnotationServiceImpl(
        () => {
            console.log('diagnostic');
        },
        true,
        metadataService,
        '',
        cdsLogger,
        { supportSplit: true, completionOnly: true }
    );
    // find relevant files
    const allUris = Object.keys(ast.sources).map((astSourceKey) => URI.file(astSourceKey).toString());
    const fileUrisRequested = uris || allUris;
    const fileUris = getDependentFileUris(fileUrisRequested, index, ast);

    // convert files (collecting metadata), add ghost files
    const metadataElementMap = new Map();
    const metadataCollector = createMetadataCollector(metadataElementMap, facade);
    let annotationFiles = fileUris.reduce((annoFiles: ServiceAnnotationFile[], uri): ServiceAnnotationFile[] => {
        const targetMap: CdsAnnotationFile = toTargetMap(index.forUri(uri), uri, vocabularyService, facade);
        const content = toAnnotationFile(uri, vocabularyService, targetMap, metadataCollector).file;
        annoFiles.push({ serviceName: 'default', uri, content });
        return annoFiles;
    }, []);
    if (ast) {
        const ghostFiles = facade.getGhostFiles(annotationFiles);
        annotationFiles.splice(0, 0, ...ghostFiles);
    }
    annotationFiles = annotationFiles.filter(
        (file) => file.content && file.content.targets && file.content.targets.length
    );
    // import metadata into metadata service, load annotation files
    const metadataElementNodes = getMetadataElementsFromMap(metadataCollector.metadataElementMap);
    metadataService.import(metadataElementNodes, 'DummyMetadataFileUri');
    genericAnnotationService.loadService(annotationFiles);
    // get all metadata references and build index
    const referenceIndex = genericAnnotationService.getReferencesIndex();
    return referenceIndex.map((entry) => ({
        absoluteName: entry.name,
        definition: entry.definition,
        references: entry.references
    }));
};
