import type { Token, XsnCompileModel } from '@sap/cds-compiler';

import type {
    AnnotationFile,
    Namespace,
    Reference,
    ServiceAnnotationFile,
    CompilerMessage
} from '@sap-ux/odata-annotation-core';
import type { Project } from '@sapux/project-spec';

import { createIndex as create } from './blitzIndex';
import type { BlitzIndex, PropagatedTargetMap } from '.';

import type { Files } from './transform/ghostFiles';
import { buildGhostFiles, toPropagatedTargetMap } from './transform/ghostFiles';

import { getFileUriMap } from './cds';
import { pathToFileURL } from 'url';
import type { MetadataCollector, MetadataElementMap } from './metadata';
import {
    collectMetadataForAbsolutePath,
    collectMetadataForRelativePath,
    generateMetadata,
    Converter
} from './metadata';
import type { CdsDocument } from './cdsDocument';
import { getCdsDocument } from './cdsDocument';
import { getCompilerErrorMessages } from './cdsArtifacts';
import { getSourceByUri } from './cdsSource';
import { EdmxNameConverter } from './metadata/edmxNameConverter';

/**
 * To abstract the calls to undocumented functionalities of @sap/cds-compiler module
 *
 */
export interface CdsCompilerFacade {
    readonly blitzIndex: BlitzIndex;

    /**
     * gets tokens for a file.
     *
     * @param uri
     * @returns
     */
    getTokensForUri(uri: string): Token[];

    /**
     * Gets CDS document for the given file URI.
     *
     * @param uri
     */
    getCdsDocument(uri: string): CdsDocument | undefined;

    /**
     * gets map of transformed metadata from compile model artifacts.
     *
     * @param serviceName
     * @returns
     */
    getMetadata(serviceName?: string): MetadataElementMap;

    /**
     * gets propagated annotation targets.
     *
     * @param files
     * @returns
     */
    getGhostFiles(files: { uri: string; content: AnnotationFile }[]): ServiceAnnotationFile[];

    /**
     * gets metadataCollector instance.
     *
     * @param metadataElementMap
     * @returns
     */

    /**
     * gets compiler errors on the project.
     *
     * @param project
     * @returns
     */
    getCompilerErrors(project: Project): Map<string, CompilerMessage>;

    /**
     * gets a relative - absolute uri map.
     *
     * @param project
     * @returns
     */
    getUriMap(): Map<string, string>;

    /**
     * gets file names.
     *
     * @param serviceName
     * @returns
     */
    getFileName(serviceName: string): string | undefined;

    /**
     * gets map of propagated targets.
     *
     * @param serviceName
     * @param files
     * @returns
     */
    getPropagatedTargetMap(
        serviceName?: string | undefined,
        files?: Files[] | undefined
    ): { propagationMap: PropagatedTargetMap; sourceUris: Set<string> };

    /**
     * gets namespace and references for a given uri.
     *
     * @param project
     * @returns {{ namespace: Namespace; references: Reference[] } | undefined}
     */
    getNamespaceAndReference(uri: string): { namespace: Namespace; references: Reference[] } | undefined;

    /**
     * gets all the source uris as string collection.
     *
     * @param project
     * @returns
     */
    getAllSourceUris(): string[];

    /**
     * gets the kind of a given service.
     *
     * @param serviceName
     * @returns
     */
    getServiceKind(serviceName: string): string;

    /**
     * Collects metadata elements for absolute path (cds syntax), returns path in EDMX syntax
     *
     * @param cdsPath - path extracted from carrier e.g. AdminService.Books.title or AdminService.Books.addRating
     * @param cdsKind - cds kind, e.g. 'entity', 'element', 'action', 'function', 'param'
     * @param metadataCollector
     * @returns path in EDMX format and key for corresponding entry in MetadataCollector
     */
    collectMetadataForAbsolutePath(
        cdsPath: string,
        cdsKind: string,
        metadataCollector: MetadataCollector
    ): { edmxPath: string; collectorKey: string };

    /**
     * Collects metadata elements for relative path
     *
     * @param relativePath
     * @param baseCollectorKey - key for collector entry representing base for relative path
     * @param serviceName
     * @param metadataCollector
     */
    collectMetadataForRelativePath(
        relativePath: string,
        baseCollectorKey: string,
        serviceName: string,
        metadataCollector: MetadataCollector
    ): void;

    /**
     * convert name to edmx name (converting '.text' to '_text')
     *  - reason: generated EDMX will contain name with '_text'
     * @param name
     */
    convertNameToEdmx(name: string): string;

    /**
     * convert name from edmx name (converting '_text' to '.text')
     * @param name
     */
    convertNameFromEdmx(name: string): string | undefined;
}

/**
 * Creates a facade that calls to undocumented functionalities of @sap/cds-compiler module.
 *
 * @param XsnCompileModel
 * @returns
 */
export function createCdsCompilerFacade(compileModel: XsnCompileModel): CdsCompilerFacade {
    let blitzIndex: BlitzIndex;
    const nameConverter: EdmxNameConverter = new EdmxNameConverter(compileModel);

    return {
        get blitzIndex(): BlitzIndex {
            if (!blitzIndex) {
                blitzIndex = create(compileModel);
            }
            return blitzIndex;
        },
        getTokensForUri(uri: string): Token[] {
            const source = getSourceByUri(pathToFileURL(uri).toString(), compileModel);
            const tokens: Token[] = [];
            if (source?.tokenStream?.tokens) {
                tokens.push(...source?.tokenStream?.tokens);
            }
            return tokens;
        },
        getCdsDocument(uri: string): CdsDocument | undefined {
            return getCdsDocument(uri, compileModel);
        },
        getMetadata(serviceName?: string): MetadataElementMap {
            return generateMetadata(compileModel, this, serviceName);
        },
        getGhostFiles(files: { uri: string; content: AnnotationFile }[]): ServiceAnnotationFile[] {
            return buildGhostFiles(compileModel, files);
        },
        getCompilerErrors(project: Project): Map<string, CompilerMessage> {
            return getCompilerErrorMessages(project, compileModel);
        },
        getUriMap(): Map<string, string> {
            return getFileUriMap(compileModel);
        },
        getPropagatedTargetMap(
            serviceName?: string | undefined,
            files?: Files[] | undefined
        ): { propagationMap: PropagatedTargetMap; sourceUris: Set<string> } {
            return toPropagatedTargetMap(compileModel, serviceName, files);
        },
        getFileName(serviceName: string): string | undefined {
            return compileModel.definitions[serviceName]?.location?.file;
        },
        getNamespaceAndReference(fileUri: string): { namespace: Namespace; references: Reference[] } | undefined {
            const source = getSourceByUri(fileUri, compileModel);
            const converter = new Converter(compileModel.compiler, this);
            const references: Reference[] = [];
            let namespace;
            if (source) {
                references.push(...converter.convertUsingsToNamespaces(source.usings, source.dependencies));
                if (source.namespace) {
                    namespace = converter.convertNamespaceToNamespaces(source.namespace);
                }
            }
            return { references, namespace };
        },
        getAllSourceUris(): string[] {
            return Object.keys(compileModel?.sources) || [];
        },
        getServiceKind(serviceName: string): string {
            return compileModel?.definitions[serviceName]?.kind;
        },

        collectMetadataForAbsolutePath(
            cdsPath: string,
            cdsKind: string,
            metadataCollector: MetadataCollector
        ): { edmxPath: string; collectorKey: string } {
            return collectMetadataForAbsolutePath(cdsPath, cdsKind, metadataCollector, compileModel);
        },

        collectMetadataForRelativePath(
            relativePath: string,
            baseKey: string,
            serviceName: string,
            metadataCollector: MetadataCollector
        ): void {
            collectMetadataForRelativePath(relativePath, baseKey, serviceName, metadataCollector, compileModel);
        },

        convertNameToEdmx(name: string): string {
            return nameConverter.convertNameToEdmx(name);
        },

        convertNameFromEdmx(name: string): string | undefined {
            return nameConverter.convertNameFromEdmx(name);
        }
    };
}
