/**
 * Find property names (tag names or @-prefixed attribute names) which can provide value for type
 * @param type
 * @param pathBase
 * @return map of property names (tag names or @ prefixed attribute names)
 */
export const getPropertyNamesProvidingValueForType: GetPropertyNamesProvidingValueForTypeCallback = (
    valueHandlingContext: ValueHandlingContext,
    type: ValueType
): { [key: string]: CompletionItemCategory } => {
    const ccPropNames: { [p: string]: CompletionItemCategory } = {};
    if (!type.asCollection && pathTypeMap[type.name] && pathTypeMap[type.name].defaultExpressionName) {
        // model path types: only use corresponding model path expressions
        ccPropNames[pathTypeMap[type.name].defaultExpressionName] = CompletionItemCategory.PathKind;
        ccPropNames['@' + pathTypeMap[type.name].defaultExpressionName] = CompletionItemCategory.PathKind;
    } else {
        // TODO only include if path expression is possible for type ?
        ccPropNames[Edm.Path] = CompletionItemCategory.Path;
        ccPropNames['@' + Edm.Path] = CompletionItemCategory.Path;
    }
    if (type.asCollection) {
        if (!valueHandlingContext.nodeContext?.dataFieldValueProperty) {
            ccPropNames[Edm.Collection] = CompletionItemCategory.ValueElement;
        }
    } else {
        const vocabularyType = getVocabularyType(valueHandlingContext.context, type.name);
        if (vocabularyType && vocabularyType.kind === Edm.ComplexType) {
            ccPropNames[Edm.Record] = CompletionItemCategory.ValueElement;
        } else if (type.name === EdmType.PrimitiveType || type.name === EdmType.Untyped) {
            Object.keys(primitiveValueConstantExpressionMap).forEach((name) => {
                ccPropNames[name] = CompletionItemCategory.ValueElement;
                ccPropNames['@' + name] = CompletionItemCategory.ValueElement;
            });

            addDynamicExpressionsWithType(convertValueTypeFromString(EdmType.PrimitiveType), ccPropNames);
        } else if (pathTypeMap[type.name]) {
            const pathExpressionName = pathTypeMap[type.name].defaultExpressionName;
            ccPropNames[pathExpressionName] = CompletionItemCategory.PathKind;
            ccPropNames['@' + pathExpressionName] = CompletionItemCategory.PathKind;
        } else {
            // add all tags representing specific constant or dynamic expression
            handleNonStructuredValue(valueHandlingContext, type, vocabularyType, ccPropNames);
        }
    }
    if (getFunctionNamesForValueType(type, valueHandlingContext).length) {
        ccPropNames[Edm.Apply] = CompletionItemCategory.Apply;
    }
    return addDynamicExpressionsForAnyType(ccPropNames);
};

function completeElementName(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    element: Element,
    fixElementName?: ElementName
): CompletionItem[] {
    if (fixElementName) {
        return [{ text: fixElementName, name: fixElementName, category: CompletionItemCategory.ValueElement }];
    } else {
        // not in acquire mode: element name can be changed
        const propNames: { [key: string]: CompletionItemCategory } = getPropertyNamesProvidingValueForType(
            valueHandlingContext,
            type
        );
        return Object.keys(propNames)
            .filter((propName) => !propName.startsWith('@'))
            .map((propName): CompletionItem => {
                return {
                    text: propName,
                    name: propName,
                    affectedRange: element.nameRange,
                    category: propNames[propName]
                };
            });
    }
}

function getPropNameFilter(
    propNames: { [key: string]: CompletionItemCategory },
    pathTargetInElement: PathTargetInElement,
    currentAttrName: string,
    attrNamesPresent: string[],
    valueAttrNames: string[],
    notValueAttrs: string[],
    valueAttributeChange: boolean
) {
    return (entry) => {
        // filter propNames for attribute name or sub node name respectively
        let result = false;
        if (propNames[entry]) {
            if (pathTargetInElement.isAttributeName) {
                // should be attribute name
                if (entry.startsWith('@')) {
                    const optionName = entry.slice(1);
                    result =
                        // not existing or current attribute name are allowed
                        (optionName === currentAttrName || !attrNamesPresent.includes(optionName)) &&
                        // extra conditions
                        (valueAttrNames.length === 0 || // no value attributes provided or...
                            notValueAttrs.includes(optionName) || // not a value providing attribute or...
                            valueAttributeChange); // existing value attribute change is taking place
                }
            } else {
                // should be element name
                result = !entry.startsWith('@');
            }
        }
        return result;
    };
}

function getNames(
    valueHandlingContext,
    type: ValueType,
    element: Element,
    pathTargetInElement: PathTargetInElement,
    attrMetadata: DynamicExpressionSpecial,
    notValueAttrs: string[]
): { propNames: { [key: string]: CompletionItemCategory }; currentAttrName: string } {
    let currentAttrName = '';
    let propNames: { [key: string]: CompletionItemCategory } = {};
    if (pathTargetInElement.isAttributeName) {
        if (attrMetadata && attrMetadata.valueAttributes) {
            propNames = getPropertyNamesProvidingValueForType(valueHandlingContext, type);
        }
        if (attrMetadata && attrMetadata.hasAttributes) {
            notValueAttrs.forEach((attrName) => {
                if (attrName === 'Qualifier') {
                    propNames['@' + attrName] = CompletionItemCategory.Qualifier;
                } else {
                    propNames['@' + attrName] = CompletionItemCategory.ValueElement;
                }
            });
        }
        currentAttrName = pathTargetInElement.attribute.name;
    } else {
        if (element.name === Edm.Record) {
            propNames[Edm.PropertyValue] = CompletionItemCategory.ValueElement;
        } else if (element.name === Edm.Apply) {
            const parameterIndex = getChildElementPosition(pathTargetInElement.nodeIndex, element);
            propNames = getPropertyNamesProvidingFunctionParameters(
                valueHandlingContext,
                getPropertyNamesProvidingValueForType,
                element,
                parameterIndex
            )[0];
        } else {
            propNames = getPropertyNamesProvidingValueForType(valueHandlingContext, type);
        }
    }
    return { propNames: propNames, currentAttrName: currentAttrName };
}

function analyze(
    element: Element,
    propNames: { [key: string]: CompletionItemCategory },
    pathTargetInElement: PathTargetInElement,
    attrMetadata: DynamicExpressionSpecial,
    notValueAttrs: string[]
): { completionAllowed: boolean; attrNamesPresent: string[]; valueAttrNames: string[]; valueAttributeChange: boolean } {
    // take into account that only single value might be possible
    const attrNamesPresent = Object.keys(element.attributes);
    const attrNamesPresentValid = attrNamesPresent.filter((attrName) => propNames['@' + attrName]);
    const valueAttrNames = attrNamesPresentValid.filter((attrName) => !notValueAttrs.includes(attrName));

    let firstSubNodePresent = -1;
    element.content.forEach((node, index) => {
        if (firstSubNodePresent < 0 && node.type === ELEMENT_TYPE && propNames[node.name]) {
            firstSubNodePresent = index;
        }
    });
    let completionAllowed = true;
    let valueAttributeChange = false;
    if (pathTargetInElement.isAttributeName && valueAttrNames.length > 0) {
        // completion for attribute name requested - but attributes already present specifying a value
        // only allow change of already existing attribute names providing a value
        // or allow change of already existing attribute names not providing a value
        // or allow completion of non-existing attribute names not providing a value
        valueAttributeChange = valueAttrNames.includes(pathTargetInElement.attribute.name);
        completionAllowed =
            valueAttributeChange ||
            notValueAttrs.includes(pathTargetInElement.attribute.name) ||
            notValueAttrs.some((attrName) => !attrNamesPresentValid.includes(attrName));
    } else if (
        pathTargetInElement.isElementSubNodeName &&
        (firstSubNodePresent > -1 || valueAttrNames.length) &&
        (valueAttrNames.length ||
            ((!attrMetadata || !attrMetadata.multipleValuesAllowed) &&
                firstSubNodePresent > -1 && // only allow change of first sub node providing a value
                pathTargetInElement.nodeIndex > firstSubNodePresent))
    ) {
        completionAllowed = false; // no sub node to define a value if attribute already does it
    }
    return {
        completionAllowed: completionAllowed,
        attrNamesPresent: attrNamesPresent,
        valueAttrNames: valueAttrNames,
        valueAttributeChange: valueAttributeChange
    };
}

function completeAttributeOrSubNodeName(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    element: Element,
    pathTargetInElement: PathTargetInElement
): CompletionItem[] {
    // code completion for property names - find all available property names
    const attrMetadata = dynamicExpressionSpecialMap[element.name];

    const notValueAttrs =
        (attrMetadata && [...(attrMetadata.mandatoryAttributes || []), ...(attrMetadata.optionalAttributes || [])]) ||
        [];
    const { propNames, currentAttrName } = getNames(
        valueHandlingContext,
        type,
        element,
        pathTargetInElement,
        attrMetadata,
        notValueAttrs
    );
    const { completionAllowed, attrNamesPresent, valueAttrNames, valueAttributeChange } = analyze(
        element,
        propNames,
        pathTargetInElement,
        attrMetadata,
        notValueAttrs
    );
    if (!completionAllowed) {
        return [];
    } else {
        return Object.keys(propNames)
            .filter(
                getPropNameFilter(
                    propNames,
                    pathTargetInElement,
                    currentAttrName,
                    attrNamesPresent,
                    valueAttrNames,
                    notValueAttrs,
                    valueAttributeChange
                )
            )
            .map((entry) => {
                // remove '@' from entries representing properties
                return pathTargetInElement.isAttributeName ? entry.slice(1) : entry;
            })
            .map((entry) => {
                return {
                    text: entry,
                    name: entry,

                    affectedRange: pathTargetInElement.isAttributeName
                        ? pathTargetInElement.attribute.nameRange
                        : pathTargetInElement.element.nameRange,
                    category: propNames[entry] || propNames['@' + entry]
                };
            });
    }
}

function handlePropertyValuesProvidingValueForType(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    element: Element,
    property: Property,
    startString: string
): CompletionItem[] {
    let compItems: CompletionItem[] = [];
    // handle properties which provide a value (of type type)

    if (property.name === Edm.Bool) {
        // primitive type boolean
        compItems.push({ text: 'true', name: 'true', affectedRange: property.valueRange });
        compItems.push({ text: 'false', name: 'false', affectedRange: property.valueRange });
    } else if (primitiveValueConstantExpressionMap[property.name]) {
        // no completion support for other primitive types

        // CC for i18n
        if (property.name === Edm.String && type.constraints && type.constraints.isLanguageDependent) {
            const i18nEntries = valueHandlingContext.context.i18n;
            i18nEntries.forEach((item) => {
                compItems.push({
                    name: `{@i18n>${item.key.value}}`,
                    text: `{@i18n>${item.key.value}}`,
                    insertText: `{@i18n>${item.key.value}}`,
                    documentation: {
                        kind: MarkupKind.Markdown,
                        value: geI18ntDocumentation(item)
                    }
                });
            });
        } else if (type.constraints && type.constraints.allowedValues) {
            // For Allowed Value
            compItems = handleAllowedValueConstraint(type, property.valueRange);
        } else if (valueHandlingContext.nodeContext?.sideEffectsTargetProperties && property.name === Edm.String) {
            // Special case: Common.SideEffects/TargetProperties
            valueHandlingContext.nodeContext.allowWildCardInPath = true;
            compItems = completePathExpressions(
                valueHandlingContext,
                { ...type, name: EdmType.PropertyPath },
                Edm.PropertyPath,
                startString
            );
        }
    } else if (property.name === 'EnumMember') {
        compItems = handleEnumValue(
            valueHandlingContext,
            type,
            property.value as string,
            property.valueRange,
            true,
            startString
        ) as CompletionItem[];
    } else if (pathExpressionMap[property.name]) {
        compItems = completePathExpressions(valueHandlingContext, type, property.name as PathKind, startString);
    } else if (property.name === Edm.Collection) {
        // cc for collection item
        const itemType = Object.assign({}, type);
        itemType.asCollection = false;
        const propNames: { [key: string]: CompletionItemCategory } = getPropertyNamesProvidingValueForType(
            valueHandlingContext,
            itemType
        );
        Object.keys(propNames)
            .filter((name) => !name.startsWith('@'))
            .forEach((entry) => compItems.push({ text: entry, name: entry, category: propNames[entry] }));
    } else if (primitiveValueConstantExpressionMap[element.name]) {
        // TODO check if allowedValue is present, create compItem for each allowed value
    }
    return compItems;
}

function handleAttributesNotProvidingAValue(
    valueHandlingContext: ValueHandlingContext,
    element: Element,
    prop: Property,
    type: ValueType
): CompletionItem[] {
    let result: CompletionItem[] = [];
    if (
        element.name === Edm.Record &&
        prop.name === 'Type' &&
        !valueHandlingContext.nodeContext?.noComplexTypeSupported
    ) {
        result = handleRecordType(valueHandlingContext, type) as CompletionItem[];
        if (prop.valueRange) {
            for (const item of result) {
                item.affectedRange = prop.valueRange;
            }
        }
    }
    return result;
}

function completeAttributeOrSubNodeValue(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    element: Element,
    pathTargetInElement: PathTargetInElement,
    startString: string,
    path: JsonPath
): CompletionItem[] {
    // code completion for attribute or sub node value (commonly handled in the following as 'prop'erty)
    let compItems: CompletionItem[] = [];
    const prop = extractProperty(pathTargetInElement, element);
    if (element.name === Edm.Record && prop.name === Edm.PropertyValue) {
        // handle PropertyValue as sub node of Record (since type for PropertyValue is unclear)
        compItems = handleRecordPropertyValue(valueHandlingContext, type, element, path);
    } else if (element.name === Edm.Apply && prop.name === Edm.Function) {
        // function names completion
        compItems = handleFunctionName(valueHandlingContext, type);
    } else if (element.name === Edm.Apply && prop.name === Edm.LabeledElement) {
        // LabeledElement attributes completion
        compItems = handleLabeledElementNameValue(element, path);
    } else if (
        element.name === Edm.Apply &&
        typeof prop.value === 'object' &&
        prop.value.type === ELEMENT_TYPE &&
        prop.name === Edm.String &&
        getPathTargetInElement(pathTargetInElement.remainingPathForElement, pathTargetInElement.element)
            .isTextSubNode &&
        isParameterOfStringTemplateKind(element, pathTargetInElement.nodeIndex)
    ) {
        // Template variable name completion
        compItems = handleTemplateVariableCompletion(element, prop.value, startString);
    } else if (
        dynamicExpressionSpecialMap[element.name] &&
        ((dynamicExpressionSpecialMap[element.name].mandatoryAttributes || []).includes(prop.name) ||
            (dynamicExpressionSpecialMap[element.name].optionalAttributes || []).includes(prop.name))
    ) {
        compItems = handleAttributesNotProvidingAValue(valueHandlingContext, element, prop, type);
    } else {
        // handle attributes or sub nodes providing a value
        compItems = handlePropertyValuesProvidingValueForType(valueHandlingContext, type, element, prop, startString);
    }
    return compItems;
}

/**
 * complete value
 * @param type - value needs to comply to this type
 * @param element - value to be completed
 * @param fixElementName - element name must not be changed
 * @param startString: when forCompletion - only return items with this start string
 * @param path
 * @returns CompletionItem[]
 */
function complete(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    element: Element,
    startString: string,
    path: JsonPath,
    fixElementName?: ElementName
): CompletionItem[] {
    const elementsSuppSnippetForSubNodes = [
        Edm.Annotation,
        Edm.Collection,
        Edm.Record,
        Edm.PropertyValue,
        Edm.Apply,
        Edm.LabeledElement
    ];
    elementsSuppSnippetForSubNodes.push(...dynamicExpressionSignatureMap.keys());
    const pathTargetInElement = getPathTargetInElement(path, element);
    if (pathTargetInElement.isName) {
        return completeElementName(valueHandlingContext, type, element, fixElementName);
    } else if (
        (pathTargetInElement.isTextSubNode || pathTargetInElement.isWhitespacePosition) &&
        elementsSuppSnippetForSubNodes.includes(element.name as Edm)
    ) {
        return handleSnippets(valueHandlingContext, type, element, path);
    } else if (pathTargetInElement.isAttributeName || pathTargetInElement.isElementSubNodeName) {
        return completeAttributeOrSubNodeName(valueHandlingContext, type, element, pathTargetInElement);
    } else {
        return completeAttributeOrSubNodeValue(
            valueHandlingContext,
            type,
            element,
            pathTargetInElement,
            startString,
            path
        );
    }
}

export const adjustRequestedTypes: AdjustRequestedTypesCallback = (
    types: ValueType[],
    valueHandlingContext: ValueHandlingContext,
    forCompletion = false
): ValueType[] => {
    let result: ValueType[] = [];
    if (!valueHandlingContext.nodeContext?.restrictedTypes) {
        result.push(...types);
    } else {
        const vocabularyTypes = valueHandlingContext.nodeContext.restrictedTypes.map((t) =>
            valueHandlingContext.context.vocabularies.getType(t)
        );
        result = types.reduce((acc, type) => {
            if (type.asCollection) {
                // collections as such are not restricted
                acc.push(type);
            } else if (
                valueHandlingContext.nodeContext.restrictedTypes.includes(type.name as EdmType) ||
                vocabularyTypes.find((vt) => vt && convertType(vt, valueHandlingContext) === type.name)
            ) {
                acc.push(type);
            } else if (type.name === EdmType.PrimitiveType) {
                acc.push(...vocabularyTypes.filter((t) => t?.kind === 'EnumType').map((t) => ({ name: t.name })));
                acc.push(
                    ...Object.keys(primitiveTypeMap)
                        .filter(
                            (key) =>
                                valueHandlingContext.nodeContext.restrictedTypes.includes(key as EdmType) ||
                                vocabularyTypes.find((vt) => vt && convertType(vt, valueHandlingContext) === key)
                        )
                        .map((name) => ({ ...type, name }))
                );
            }
            return acc;
        }, result);
    }

    result = getResolvedUntypedValueTypes(result);

    if (forCompletion) {
        result = adjustComparableTypes(valueHandlingContext, result);
    }

    result = expandWithCompatibleTypes(valueHandlingContext.context, result);

    return result;
};

/**
 * find type for property name
 *
 * used only to find restricting type for RequiresType constraint on term
 * supported vocabularies only use (non abstract) primitive types and complex types
 *  - complex types are determined separately via Record element
 *  -> only primitive types needed
 *
 * @param valueHandlingContext
 * @param propertyName - name of attribute/element which provides the name
 * @param pathValue - in case propertyName is 'Path': path value
 */
export function findTypeForPropertyName(
    valueHandlingContext: ValueHandlingContext,
    propertyName: AttributeName | ElementName,
    pathValue?: PathValue
): FullyQualifiedTypeName {
    let providedValueType: FullyQualifiedTypeName = '';
    if (primitiveValueConstantExpressionMap[propertyName]) {
        providedValueType = primitiveValueConstantExpressionMap[propertyName].defaultType;
    } else if (pathExpressionMap[propertyName]) {
        if (propertyName === 'Path' && pathValue) {
            // find type by resolving path expression
            if (!pathValue.startsWith('/')) {
                pathValue = valueHandlingContext.pathBase.path + '/' + pathValue;
            }
            // TODO extend this to paths which include term cast segments
            //  (currently only paths into metadata are supported - i.e. all supported target paths)
            const lookupResult = lookupTarget(valueHandlingContext.context, pathValue, valueHandlingContext.aliasInfo);
            if (lookupResult && lookupResult.metadataElement) {
                const valueType = getValueTypeForMetadataElement(lookupResult.metadataElement);
                if (valueType.name) {
                    providedValueType = convertValueTypeToString(valueType);
                }
            }
        } else {
            providedValueType = pathExpressionMap[propertyName].defaultType;
        }
    }
    return providedValueType;
}

function hoverPropertyValue(
    valueHandlingContext: ValueHandlingContext,
    valueType: ValueType,
    element: Element,
    path: JsonPath
): Hover {
    let hover: Hover;
    const propValue = getPathTargetInElement(path, element);
    const target = getPathTargetInElement(propValue.remainingPathForElement, propValue.element);
    if (target.attribute && target.isAttributeValue && target.attribute.name === Edm.Property) {
        let typeValue = getSplitStructureType(
            valueHandlingContext.context,
            valueHandlingContext.currentStructureProperty
        );
        if (!typeValue) {
            typeValue =
                element.attributes.Type && element.attributes.Type.value
                    ? element.attributes.Type.value
                    : valueType.name;
        }
        const aliasInfo = valueHandlingContext.aliasInfo;
        const aliasMap = aliasInfo.aliasMap;
        const namespace = resolveName(typeValue, aliasMap).namespace;
        const type = typeValue.split('.').pop() || '';
        const fullyQualifiedName = `${namespace}.${type}`;
        hover = {
            contents: {
                kind: MarkupKind.Markdown,
                value: valueHandlingContext.context.vocabularies
                    .getDocumentation(fullyQualifiedName, target.attribute.value, aliasInfo)
                    .join('\n')
            },
            range: target.attribute.valueRange
        };
    }
    return hover;
}

/**
 * hover over annotation value
 * @param valueHandlingContext
 * @param valueType
 * @param element
 * @param path
 * @param position
 */
function hoverAnnotationValue(
    valueHandlingContext: ValueHandlingContext,
    valueType: ValueType,
    element: Element,
    path: JsonPath,
    position: Position
): Hover {
    let hover: Hover;
    const pathTargetInElement = getPathTargetInElement(path, element);
    const prop = extractProperty(pathTargetInElement, element);
    if (element.name === Edm.Record && prop.name === 'Type') {
        hover = hoverRecordType(valueHandlingContext, pathTargetInElement);
    } else if (prop.name === Edm.PropertyValue) {
        hover = hoverPropertyValue(valueHandlingContext, valueType, element, path);
    } else if (prop.name === 'EnumMember') {
        hover = enumHover(valueHandlingContext, valueType, prop.value as string, prop.valueRange, position);
    } else if (prop.name === 'Function') {
        const documentation = getFunctionDocumentation(prop.value as FunctionName);
        if (documentation?.length) {
            hover = {
                contents: {
                    kind: MarkupKind.Markdown,
                    value: documentation.join('\n')
                },
                range: prop.valueRange
            };
        }
    } else if (dynamicExpressionSignatureMap.has(prop.name as Edm)) {
        const documentation = getDynamicExpressionDocumentation(prop.name as Edm);
        if (documentation?.length) {
            hover = {
                contents: {
                    kind: MarkupKind.Markdown,
                    value: documentation.join('\n')
                },
                range: prop.valueRange
            };
        }
    }

    return hover;
}

export function isAnnotationAllowed(element: Element): boolean {
    if (element && element.name) {
        const metadata = dynamicExpressionSpecialMap[element.name];
        return (
            !(metadata && metadata.noAnnotationsAllowed) &&
            !pathExpressionMap[element.name] &&
            element.name !== Edm.EnumMember &&
            !primitiveValueConstantExpressionMap[element.name]
        );
    } else {
        return false;
    }
}

// in soft comparison operator context (i.e. Lt, Le, Gt, Ge) we should filter out types which intended to be strict compared (boolean, guid, etc.)
export function adjustComparableTypes(valueHandlingContext: ValueHandlingContext, types: ValueType[]): ValueType[] {
    if (
        valueHandlingContext.nodeContext?.comparisonOperator &&
        !valueHandlingContext.nodeContext?.strictEqualityComparison
    ) {
        const suitableTypes: ValueType[] = types.reduce((acc, t) => {
            if (!t.asCollection) {
                if (t.name === EdmType.PrimitiveType) {
                    acc.push(
                        ...Object.keys(primitiveTypeMap)
                            .filter((key) => !primitiveTypeMap[key].strictEqualityComparable)
                            .map((name) => ({ ...t, name }))
                    );
                } else if (!primitiveTypeMap[t.name] || !primitiveTypeMap[t.name].strictEqualityComparable) {
                    acc.push(t);
                }
            } else {
                acc.push(t);
            }
            return acc;
        }, []);
        return suitableTypes;
    } else {
        return types;
    }
}

export function checkStrictComparableTypes(
    valueHandlingContext: ValueHandlingContext,
    types: string[],
    range: Range
): Diagnostic[] {
    if (
        valueHandlingContext.nodeContext?.comparisonOperator &&
        !valueHandlingContext.nodeContext?.strictEqualityComparison
    ) {
        const strictComparableTypes = types.filter((t) => {
            const vType = valueHandlingContext.context.vocabularies.getType(t);
            const convertedType = (vType && convertType(vType, valueHandlingContext)) || t;
            return primitiveTypeMap[convertedType] && primitiveTypeMap[convertedType].strictEqualityComparable;
        });
        if (strictComparableTypes.length) {
            return [
                {
                    message: i18n.t('The_value_of_types_0_is_for_strict_comparison_only', {
                        types: strictComparableTypes.join(', ')
                    }),
                    range: range,
                    severity: DiagnosticSeverity.Warning,
                    rule: 'invalid-type'
                }
            ];
        }
    }
    return [];
}

