import type { SnippetHandlingContext } from '.';
import type { ComplexType, ComplexTypeProperty, VocabularyType } from '@sap-ux/odata-vocabularies';
import { Snippet } from './snippet';
import { EdmType } from '../specification';
import type { ResolvedName } from '@sap-ux/odata-annotation-core';
import { Edm, resolveName } from '@sap-ux/odata-annotation-core';
import type { ValueHandlingContext, ValueType } from '../types/context';
import {
    getPossibleTypes,
    getPropertyDescriptorsForRecord,
    getPropertyNamesProvidingValueForType
} from '../value-handling';
import type { CompletionItem } from '../types/general';
import { CompletionItemCategory } from '../types/general';
import { appendNameToDocumentationAndTruncate } from '../utils/annotationService';
import type { FullyQualifiedTypeName } from '../types/baseTypes';
import { getVocabularyType, getValueTypeForComplexTypeProperty } from '../vocabulary/access';
import { removeDynamicExpressionsFromMap } from './util';

/**
 * Returns <name,category> map of the elements providing value for type
 * records not included
 * @param context - snippet handling context object
 */
export function getElementNamesProvidingValue(context: SnippetHandlingContext): {
    [key: string]: CompletionItemCategory;
} {
    const propNames = getPropertyNamesProvidingValueForType(context.valueHandlingContext, context.type);

    // filter propNames for subnode name
    Object.keys(propNames).forEach((key) => {
        if (!propNames[key] || key.startsWith('@') || key === Edm.Record) {
            delete propNames[key];
        }
    });
    return propNames || {};
}

function appendSimpleValueSnippet(
    snippet: Snippet,
    valueElementMap: { [key: string]: CompletionItemCategory },
    omitValueAttribute: boolean,
    addFinalTabStop: boolean
) {
    // simple value snippet
    removeDynamicExpressionsFromMap(valueElementMap);
    const valueElements = Object.keys(valueElementMap);
    if (valueElements.length === 1) {
        if (!omitValueAttribute) {
            snippet.setAttribute(
                valueElements[0],
                snippet.getTabStopText(addFinalTabStop ? 0 : snippet.getNextTabStopId())
            );
        }
    } else if (valueElements.length === 2 && valueElements.includes(Edm.Path)) {
        if (!omitValueAttribute) {
            snippet.setAttribute(
                valueElements.filter((item) => item !== Edm.Path)[0],
                snippet.getTabStopText(addFinalTabStop ? 0 : snippet.getNextTabStopId())
            );
        }
    } else if (addFinalTabStop) {
        snippet.setAttributeAsFinalTabStop();
    } else {
        snippet.setAttributeAsTabStop(snippet.getNextTabStopId());
    }
}

/**
 * PropertyValue snippet constructor
 * ----------------------------------
 * @param context - snippet handling context object
 * @param prop - property descriptor object
 * @param addFinalTabStop - flag, determining if final tabstop should be added to the snippet
 * @param initialTabStop - initial tabstop number for snippet
 * @param stopValuePropagation - flag, determining if nested records should be added (truthy flag disables nested records)
 * @param [_createRecordSnippets = createRecordSnippets] - dependency injection (for testing purpose, only)
 * @param [_createCollectionSnippet = createCollectionSnippet] - dependency injection (for testing purpose, only)
 * @param [_getElementNamesProvidingValue = getElementNamesProvidingValue] - dependency injection (for testing purpose, only)
 */
export function createPropertyValueSnippet(
    context: SnippetHandlingContext,
    prop: ComplexTypeProperty,
    addFinalTabStop = true,
    initialTabStop = 1,
    stopValuePropagation = false,
    _createRecordSnippets = createRecordSnippets,
    _createCollectionSnippet = createCollectionSnippet,
    _getElementNamesProvidingValue = getElementNamesProvidingValue
): Snippet {
    const vocabularyType = getVocabularyType(context.valueHandlingContext.context, prop.type);
    const propValueType: ValueType = getValueTypeForComplexTypeProperty(
        context.valueHandlingContext.context,
        context.type.name,
        prop.name
    );
    if (vocabularyType?.kind === Edm.ComplexType && vocabularyType?.isAbstract) {
        propValueType.name = vocabularyType.name;
    }
    propValueType.asCollection = false; // for collection members

    const snippet = new Snippet(Edm.PropertyValue, context.useSnippets, initialTabStop)
        .setAttribute(Edm.Property, prop.name)
        .addMandatoryAttributesWithTabStops();

    if (prop.isCollection) {
        // collection property value
        const collection = _createCollectionSnippet(
            { ...context, type: propValueType },
            vocabularyType,
            snippet.getNextTabStopId(),
            addFinalTabStop,
            stopValuePropagation
        );
        snippet.appendContent(collection);
        snippet.tabStopId = collection.getNextTabStopId();
    } else if (!stopValuePropagation && vocabularyType?.kind === Edm.ComplexType) {
        // complex property value, adding child if only single record type possible
        const recordSnippets = _createRecordSnippets(
            { ...context, type: propValueType },
            vocabularyType,
            false,
            snippet.tabStopId,
            true,
            addFinalTabStop
        );
        if (recordSnippets.length === 1) {
            snippet.appendContent(recordSnippets[0].snippet);
            snippet.tabStopId = recordSnippets[0].snippet.getNextTabStopId();
        } else {
            if (addFinalTabStop) {
                snippet.appendFinalTabStopToContent();
            } else {
                snippet.appendNextTabStopToContent();
            }
        }
    } else {
        const valueElementMap = _getElementNamesProvidingValue({ ...context, type: propValueType }) || {};
        const omitValueAttribute =
            [prop.type, vocabularyType?.underlyingType].includes(EdmType.Boolean) && prop.defaultValue === true;
        appendSimpleValueSnippet(snippet, valueElementMap, omitValueAttribute, addFinalTabStop);
    }
    return snippet;
}

/**
 * Returns record snippets for completion
 * --------------------------------------
 * @param context - snippet handling context
 * @param vocabularyType - vocabulary type definition of the complex value type
 * @param addAllProperties - record content controlling flag
 * (i.e.,  false - mandatory properties only, true - all properties )
 * @param [_createPropertyValueSnippet = createPropertyValueSnippet] - dependency injection (for testing purpose, only)
 */
export function recordSnippets(
    context: SnippetHandlingContext,
    vocabularyType: ComplexType,
    addAllProperties = false,
    _createPropertyValueSnippet = createPropertyValueSnippet
): CompletionItem[] {
    return createRecordSnippets(
        context,
        vocabularyType,
        addAllProperties,
        1,
        false,
        true,
        _createPropertyValueSnippet
    ).map((item) => {
        const documentation = context.valueHandlingContext.context.vocabularies.getDocumentation(
            item.resolvedTypeName,
            undefined,
            context.valueHandlingContext.aliasInfo
        );
        appendNameToDocumentationAndTruncate(
            item.resolvedTypeName,
            documentation,
            context.valueHandlingContext.context,
            true,
            context.valueHandlingContext.aliasInfo,
            'Type'
        );

        const compItem = item.snippet.toCompletionItem(
            `Record ${addAllProperties ? '(full) ' : ''}"${item.recordTypeName}"`,
            addAllProperties,
            CompletionItemCategory.ValueElement,
            true
        );
        compItem.data.documentation = documentation;

        return compItem;
    });
}

/**
 * Record snippet constructor
 * -----------------------------
 * @param context  - snippet handling context
 * @param vocabularyType - vocabulary complex type definition object
 * @param addAllProperties - record's property list controlling flag (mandatory only or full set, mandatory - default)
 * @param [_createPropertyValueSnippet = createPropertyValueSnippet] - dependency injection (for testing purpose, only)
 */
export function createRecordSnippets(
    context: SnippetHandlingContext,
    vocabularyType: ComplexType,
    addAllProperties = false,
    initialTabStop = 1,
    stopValuePropagation = false,
    addFinalTabStop = false,
    _createPropertyValueSnippet = createPropertyValueSnippet
): { recordTypeName: string; snippet: Snippet; resolvedTypeName: FullyQualifiedTypeName }[] {
    const valueHandlingContext: ValueHandlingContext = context.valueHandlingContext;
    const resolvedTypeName: ResolvedName = resolveName(context.type.name);
    const typeMap: { [namespace: string]: { [typeName: string]: boolean } } = {};
    const typeName = context.type.name.split('.').pop();
    const alias = valueHandlingContext.aliasInfo.reverseAliasMap[resolvedTypeName.namespace];

    // possible record types
    let recordTypes: string[] = [];
    if (vocabularyType.isAbstract) {
        getPossibleTypes(valueHandlingContext.context, context.type, typeMap);
        recordTypes = Object.keys(typeMap[resolvedTypeName.namespace] || {});
    } else {
        recordTypes.push(typeName);
    }

    // create record snippets for all possible record type
    return recordTypes.map((recordTypeName) => {
        // snippet's record type for child PropValues
        const recType: ValueType = {
            name: `${alias || resolvedTypeName.namespace}.${recordTypeName}`,
            asCollection: false
        };

        const recordSnippet = new Snippet(
            Edm.Record,
            context.useSnippets,
            initialTabStop
        ).addMandatoryAttributesWithTabStops();

        const hasBaseTypes = Object.keys(typeMap[resolvedTypeName.namespace] || {}).length > 0;
        setRecordTypeAttribute(
            recordSnippet,
            recType,
            hasBaseTypes,
            context.valueHandlingContext.context.omitRedundantTypesInSnippets
        );

        const recordProps = getPropertyDescriptorsForRecord(valueHandlingContext, recType);

        const selectedProps = addAllProperties
            ? [
                  ...recordProps.all.filter((p) => recordProps.mandatory.includes(p)),
                  ...recordProps.all.filter((p) => !recordProps.mandatory.includes(p))
              ]
            : recordProps.mandatory;

        // tabstop id counter for property snippets (tabstop numbers should be consistent within the snippet structure)
        let propTabStop = recordSnippet.getNextTabStopId();

        // Record's nested PropertyValue snippets
        const recordPropSnippets = selectedProps.map((prop, idx) => {
            const snippet = _createPropertyValueSnippet(
                { ...context, type: recordProps.resolvedRecordType },
                prop,
                addFinalTabStop && idx === selectedProps.length - 1,
                propTabStop,
                stopValuePropagation
            );
            propTabStop = snippet.getNextTabStopId();
            return snippet;
        });

        recordSnippet.tabStopId = propTabStop; // to be consumed by parent snippets
        if (recordPropSnippets.length) {
            recordSnippet.appendContent(recordPropSnippets);
        } else {
            if (addFinalTabStop) {
                recordSnippet.appendFinalTabStopToContent();
            } else {
                recordSnippet.appendNextTabStopToContent();
            }
        }

        return {
            recordTypeName,
            snippet: recordSnippet,
            resolvedTypeName: `${resolvedTypeName.namespace}.${recordTypeName}`
        };
    });
}

function setRecordTypeAttribute(
    recordSnippet: Snippet,
    recType: ValueType,
    hasBaseTypes: boolean,
    omitRedundantTypesInSnippets: boolean
) {
    if (omitRedundantTypesInSnippets) {
        if (hasBaseTypes && recType.name !== 'UI.DataField') {
            recordSnippet.setAttribute(Edm.Type, recType.name);
        }
    } else {
        recordSnippet.setAttribute(Edm.Type, recType.name);
    }
}

/**
 * Collection snippet with nested elements constructor
 * ---------------------------------------------------
 * @param context - snippet handling context
 * @param vocabularyType - vocabulary value type definition object
 * @param initialTabstopId - initial tabstop number for collection snippet
 * @param addFinalTabStop - flag, determining if final tabstop should be added to the snippet
 * @param stopValuePropagation - flag, determining if nested records should be added (truthy flag disables nested records)
 * @param [_createRecordSnippets = createRecordSnippets] - dependency injection (for testing purpose, only)
 * @param [_createPropertyValueSnippet = createPropertyValueSnippet] - dependency injection (for testing purpose, only)
 * @param [_getElementNamesProvidingValue = getElementNamesProvidingValue] - dependency injection (for testing purpose, only)
 */
export function createCollectionSnippet(
    context: SnippetHandlingContext,
    vocabularyType: VocabularyType,
    initialTabstopId: number,
    addFinalTabStop: boolean,
    stopValuePropagation = false,
    _createRecordSnippets = createRecordSnippets,
    _createPropertyValueSnippet = createPropertyValueSnippet,
    _getElementNamesProvidingValue = getElementNamesProvidingValue
): Snippet {
    const useSnippets = context.useSnippets;

    const collectionSnippet = new Snippet(
        Edm.Collection,
        useSnippets,
        initialTabstopId
    ).addMandatoryAttributesWithTabStops();

    if (!(vocabularyType && vocabularyType.kind === Edm.ComplexType)) {
        // not a complex value type, adding one element to collection
        const valueElementMap = _getElementNamesProvidingValue(context) || {};
        removeDynamicExpressionsFromMap(valueElementMap);
        addSimpleElementToCollection(collectionSnippet, valueElementMap, useSnippets, addFinalTabStop);
    } else if (vocabularyType && !stopValuePropagation) {
        // complex collection members, adding one collection element if single record type possible
        const records = _createRecordSnippets(
            {
                type: context.type,
                useSnippets: useSnippets,
                valueHandlingContext: context.valueHandlingContext
            },
            vocabularyType,
            false,
            collectionSnippet.tabStopId,
            true,
            addFinalTabStop,
            _createPropertyValueSnippet
        );
        if (records.length === 1) {
            collectionSnippet.appendContent(records[0].snippet);
            if (!addFinalTabStop) {
                collectionSnippet.tabStopId = records[0].snippet.getNextTabStopId();
            }
        } else {
            finalizeSnippet(collectionSnippet, addFinalTabStop);
        }
    } else {
        finalizeSnippet(collectionSnippet, addFinalTabStop);
    }
    return collectionSnippet;
}

function addSimpleElementToCollection(
    collectionSnippet: Snippet,
    valueElementMap: { [key: string]: CompletionItemCategory },
    useSnippets: boolean,
    addFinalTabStop: boolean
) {
    let valueElement: string;
    const valueElements = Object.keys(valueElementMap);
    if (valueElements.length === 1) {
        valueElement = valueElements[0];
    } else if (valueElements.length === 2 && valueElements.includes(Edm.Path)) {
        valueElement = valueElements.filter((item) => item !== Edm.Path)[0];
    }

    if (valueElement) {
        const valueSnippet = new Snippet(valueElement as Edm, useSnippets, collectionSnippet.getNextTabStopId());
        finalizeSnippet(valueSnippet, addFinalTabStop);
        collectionSnippet.appendContent(valueSnippet);
        collectionSnippet.tabStopId = valueSnippet.getNextTabStopId();
    } else {
        finalizeSnippet(collectionSnippet, addFinalTabStop);
    }
}

function finalizeSnippet(snippet: Snippet, addFinalTabStop: boolean) {
    if (addFinalTabStop) {
        snippet.appendFinalTabStopToContent();
    } else {
        snippet.appendNextTabStopToContent();
    }
}
