import type { CompletionItem } from 'vscode-languageserver';

import type { AnnotationFile } from '@sap-ux/odata-annotation-core';

import { getTargetsbyPointer } from '../../../utils/pointer';
import type { CompletionItemAdapterParams, CompletionItemAdapterWithGate } from '../types';

function gate({ context, args: { file, pointer }, originalItem }: CompletionItemAdapterParams): boolean {
    if (originalItem.label !== 'Common.TextArrangement') {
        return false;
    }
    if (context.type === 'empty-assignment' || (context.type === 'container' && context.kind === 'annotation-group')) {
        if (!commonTextExistInTarget(file, pointer)) {
            return true;
        }
    }
    return false;
}

/**
 * Returns true if term @common.Text exist in the target
 * @param annotationFile - annotation file
 * @param pointer - position pointer
 * @returns boolean
 */
function commonTextExistInTarget(annotationFile: AnnotationFile, pointer: string): boolean {
    const targets = getTargetsbyPointer(annotationFile, pointer);
    let isExist = false;
    for (let index = 0; index < targets.length; index++) {
        const target = targets[index];
        isExist = target.terms.some((term) => term.attributes['Term'].value === 'Common.Text');
        if (isExist) {
            break;
        }
    }

    return isExist;
}

function adapter(): CompletionItem | undefined {
    return undefined;
}

export const textArrangementAdapter: CompletionItemAdapterWithGate = {
    gate,
    adapter
};
