import type { CompletionItem } from 'vscode-languageserver';

import { CompletionItemCategory } from '@sap/ux-annotation-service';

import type { CompletionItemAdapterParams, CompletionItemAdapterWithGate } from '../types';

export const dynamicExpressionAdapter: CompletionItemAdapterWithGate = {
    gate: ({ originalItem }: CompletionItemAdapterParams) =>
        originalItem.data?.generic?.category === CompletionItemCategory.DynamicExpressionName,
    adapter: (): CompletionItem | undefined => undefined
};
