import type { CompletionItem } from 'vscode-languageserver';
import { InsertTextFormat, CompletionItemKind, TextEdit } from 'vscode-languageserver';

import type { Element, AnnotationFile } from '@sap-ux/odata-annotation-core';
import { ATTRIBUTE_TYPE } from '@sap-ux/odata-annotation-core';

import type {
    CompletionContext,
    CompletionHandlerArgs,
    CompletionItemAdapterParams,
    JsonContentContext,
    ModularCompletionHandler,
    ProviderResult
} from '../types';

function jsonAttributeContentGate(context: CompletionContext): boolean {
    return context.type === 'edm-json' && context.kind === 'content' && context.contentType === 'attribute';
}
function getElementNodeFromPointer(pointer: string, file: AnnotationFile): Element {
    return pointer
        .split('/')
        .slice(1, -1)
        .reduce((accumulator, segment) => accumulator[segment], file);
}

function attributeItemProvider(
    context: CompletionContext,
    { getCompletionItems, file, pointer, position }: CompletionHandlerArgs
): ProviderResult {
    const segments = pointer.split('/').slice(1);
    const newPointer = [...segments, '', 'name'].join('/');
    const newFile = JSON.parse(JSON.stringify(file));
    const element = getElementNodeFromPointer(pointer, newFile);
    if (!element.attributes) {
        element.attributes = {};
    }
    element.attributes[''] = {
        type: ATTRIBUTE_TYPE,
        name: '',
        nameRange: null,
        value: '',
        valueRange: null
    };
    const items = getCompletionItems(newFile, position, false, newPointer);
    return {
        itemsForAdapter: items,
        completionItems: []
    };
}

function attributeAdapter({
    context: { hasComma, position },
    originalItem
}: CompletionItemAdapterParams<JsonContentContext>): CompletionItem | undefined {
    const name = `$${originalItem.label}`;
    const text = `\\${name} : '$0'${hasComma ? '' : ','}`;

    return {
        label: name,
        insertTextFormat: InsertTextFormat.Snippet,
        kind: CompletionItemKind.Property,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        textEdit: TextEdit.insert(position, text),
        filterText: name
    };
}
export const jsonAttributeContentHandler: ModularCompletionHandler = {
    name: 'json-attribute-content',
    type: 'modular',
    gate: jsonAttributeContentGate,
    providers: [attributeItemProvider],
    mappers: [],
    adapters: [attributeAdapter]
};
