import { EMPTY_VALUE_TYPE, PATH_TYPE, RECORD_PROPERTY_TYPE } from '@sap-ux/cds-annotation-parser';
import { VALUE_ADAPTERS } from '../adapters';

import { annotationFilterAdapter } from '../adapters/annotationFilter';
import { CHILD_NODE_MAPPERS } from '../childNodeMappers';
import type { CompletionContext, ModularCompletionHandler } from '../types';
import { basicItemProvider } from '../utils';

function propertyValueGate(context: CompletionContext): boolean {
    return (
        context.type === 'value' &&
        context.kind === 'property' &&
        !(
            context.valueType === EMPTY_VALUE_TYPE &&
            ((parent): boolean => parent.type === RECORD_PROPERTY_TYPE && parent.name.value.toLowerCase() === '$type')(
                context.pathToNode.slice(-2)[0]
            )
        ) &&
        !(context.type === 'value' && context.valueType === PATH_TYPE && context.cursorInDelimiter)
    );
}

export const propertyValueHandler: ModularCompletionHandler = {
    name: 'property-value',
    type: 'modular',
    gate: propertyValueGate,
    providers: [basicItemProvider],
    mappers: [...CHILD_NODE_MAPPERS],
    adapters: [annotationFilterAdapter, ...VALUE_ADAPTERS]
};
