import type { CompletionItem } from 'vscode-languageserver';
import { InsertTextFormat, TextEdit } from 'vscode-languageserver';

import type {
    CompletionContext,
    CompletionItemAdapterParams,
    ModularCompletionHandler,
    TermNameContext
} from '../types';
import { basicItemProvider } from '../utils';

function termNameGate(context: CompletionContext): boolean {
    return context.type === 'key' && context.kind === 'term-name';
}

function termSnippetAdapterGate({ context }): boolean {
    return context.type === 'key' && context.kind === 'term-name';
}

function termSnippetAdapter({
    context: { annotationGroupName, isQuoted, proposedReplacementRange },
    originalItem
}: CompletionItemAdapterParams<TermNameContext>): CompletionItem | undefined {
    const [alias, termName] = originalItem.label.split('.');
    if (annotationGroupName !== undefined && annotationGroupName !== alias) {
        // If we are in annotation group we want to show completion items for current annotation group
        return;
    }
    const text = annotationGroupName ? termName : originalItem.label;
    return {
        label: text,
        insertTextFormat: InsertTextFormat.PlainText,
        kind: originalItem.kind,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        filterText: isQuoted ? `![${text}]` : text,
        textEdit: TextEdit.replace(proposedReplacementRange, text)
    };
}

export const termNameHandler: ModularCompletionHandler = {
    name: 'term-name',
    type: 'modular',
    gate: termNameGate,
    providers: [basicItemProvider],
    mappers: [],
    adapters: [{ gate: termSnippetAdapterGate, adapter: termSnippetAdapter }]
};
