import type { AliasInformation } from '../types/context';

import { getUsedNamespaces, getUnusedNamespaces } from '../utils/namespace';
import type { Range } from 'vscode-languageserver-types';
import { DiagnosticSeverity } from 'vscode-languageserver-types';
import { i18n } from '../i18n';
import type {
    Alias,
    AnnotationFile,
    NamespaceString,
    NoUnusedNamespaceDiagnostic,
    Reference
} from '@sap-ux/odata-annotation-core';
import { NO_UNUSED_NAMESPACE_TYPE } from '@sap-ux/odata-annotation-core';

const getMessage = (namespace: NamespaceString, alias: Alias): string => {
    let message = '';
    if (namespace === alias) {
        message = i18n.t('Unused_namespace_0', {
            namespace: namespace
        });
    } else {
        message = i18n.t('Unused_namespace_0_with_alias_1', {
            namespace: namespace,
            alias: alias
        });
    }

    return message;
};

const getRange = (references: Reference[], namespace: NamespaceString): Range => {
    const annoFileNS = references.find((ns) => ns.name === namespace);

    return annoFileNS && annoFileNS.nameRange;
};

export const createUnusedNamespaceDiagnostic = (
    aliasInfo: AliasInformation,
    annotationFile: AnnotationFile
): NoUnusedNamespaceDiagnostic[] => {
    const usedNamespaces = getUsedNamespaces(aliasInfo, annotationFile.targets);
    const unusedNamespaces = getUnusedNamespaces(aliasInfo, usedNamespaces);
    const messages: NoUnusedNamespaceDiagnostic[] = [];

    unusedNamespaces.forEach((alias, namespace) => {
        const message = getMessage(namespace, alias);
        const range = getRange(annotationFile.references, namespace);
        messages.push({
            message,
            range,
            severity: DiagnosticSeverity.Information,
            rule: NO_UNUSED_NAMESPACE_TYPE,
            data: {
                alias,
                namespace
            }
        });
    });

    return messages;
};
