export type PathKind = Edm.Path | Edm.NavigationPropertyPath | Edm.PropertyPath | Edm.AnnotationPath;

function findCacheObjectBySegments(
    segments: string[],
    valueHandlingContext: ValueHandlingContext,
    currentObject: any
): { caseIssues: CaseIssue | undefined; pathFound: boolean; currentObject: any } {
    let pathFound = true;
    let caseIssues = undefined;
    (segments || []).forEach((segment, idx) => {
        if (
            idx === segments.length - 1 &&
            segment === '*' &&
            valueHandlingContext.nodeContext?.allowWildCardInPath &&
            pathFound
        ) {
            // find first key reflecting current complex type object structural property
            const key =
                typeof currentObject === 'object' &&
                Object.keys(currentObject)
                    // annotations terms in cache are ignored for wildcards
                    .filter((key) => !key.includes('@') && key !== '$Self')
                    .find(
                        (key) =>
                            (typeof currentObject[key] !== 'object' && !!currentObject[key]) ||
                            currentObject[key]['$Self'] === true
                    );
            currentObject = key ? currentObject[key] : undefined;
            pathFound = !!currentObject;
        } else if (currentObject[segment]) {
            currentObject = currentObject[segment];
        } else {
            pathFound = false;
            if (valueHandlingContext.aliasInfo) {
                caseIssues = checkPathValuesNameCase(valueHandlingContext, segment, currentObject);
            }
        }
    });
    return { pathFound, caseIssues, currentObject };
}
/** collect path ( represented by segments) results from cache entry (into accumulated results)
 * @param cacheEntry - cache entry (found for specific type or term)
 * @param segments - path segments
 * @param accumulatedResult
 */
function collectPathResultFromCacheEntry(
    cacheEntry: any,
    segments: string[],
    accumulatedResult: any,
    valueHandlingContext: ValueHandlingContext
): { pathFound: boolean; caseIssues: CaseIssue } {
    let caseIssues = undefined;
    let pathFound = false;
    let currentObject = cacheEntry;

    if (currentObject) {
        ({ pathFound, caseIssues, currentObject } = findCacheObjectBySegments(
            segments,
            valueHandlingContext,
            currentObject
        ));
        if (pathFound) {
            // accumulate result
            const result = typeof currentObject === 'object' ? currentObject : { $Self: currentObject };
            Object.keys(result).forEach((key) => {
                // make sure finishing segments are kept
                if (!accumulatedResult[key] || !accumulatedResult[key].$Self) {
                    accumulatedResult[key] = JSON.parse(JSON.stringify(result[key]));
                }
            });
        }
    }
    return { pathFound, caseIssues };
}

/**
 * Check the namescase issue in path segment by segment
 * @param valueHandlingContext
 * @param segment
 * @param currentObject
 */
function checkPathValuesNameCase(
    valueHandlingContext: ValueHandlingContext,
    segment: string,
    currentObject: any
): CaseIssue | undefined {
    let caseIssues = undefined;
    const segmentWithNameSpace = getGuessedQualifiedName(segment, valueHandlingContext.aliasInfo);
    const keys = Object.keys(currentObject);
    if (segmentWithNameSpace) {
        const key = keys.find((item) => item.toUpperCase() === segmentWithNameSpace.toUpperCase());
        if (currentObject[key]) {
            caseIssues = {
                correct: key,
                wrong: segment
            };
            currentObject = currentObject[key];
        }
        // if segment don't have alias or namespace
    } else if (!segment.includes('.')) {
        const key = keys.find((item) => item.toUpperCase() === segment.toUpperCase());
        if (currentObject[key]) {
            caseIssues = {
                correct: key,
                wrong: segment
            };
            currentObject = currentObject[key];
        }
    }

    return caseIssues;
}

/**
 * collect path results from cache
 * @param lookUp
 * @param segments
 * @param existenceCheckOnly - stop after first result has been found
 * @param checkAsWholePath - stop after first result representing valid path has been found
 * @param typesOrTerms - only consider these types or terms
 * @param accumulatedResult - accumulated result
 * @param valueHandlingContext
 */
function collectPathResultsFromCache(
    lookUp: PathCache | AnnotationPathCache,
    typesOrTerms: FullyQualifiedTypeName[] | FullyQualifiedName[],
    segments: string[],
    existenceCheckOnly: boolean,
    checkAsWholePath: boolean,
    accumulatedResult: any,
    valueHandlingContext: ValueHandlingContext
): { found: boolean; caseIssues?: CaseIssue } {
    let found = false;
    let done = false;
    let caseIssues = undefined;
    Object.keys(lookUp).forEach((namespaces) => {
        if (done) {
            return;
        }
        for (let i = 0; i < typesOrTerms.length && !done; i++) {
            const cacheEntryForTypeOrTerm = typesOrTerms[i] ? lookUp[namespaces][typesOrTerms[i]] : lookUp[namespaces];
            if (cacheEntryForTypeOrTerm) {
                const path = collectPathResultFromCacheEntry(
                    cacheEntryForTypeOrTerm,
                    segments,
                    accumulatedResult,
                    valueHandlingContext
                );
                found = found || path.pathFound;
                caseIssues = path.caseIssues ? path.caseIssues : caseIssues;
                if (existenceCheckOnly) {
                    if (checkAsWholePath) {
                        done = !!accumulatedResult.$Self; // valid as whole path only if $Self is present
                    } else {
                        done = Object.keys(accumulatedResult).length > 0;
                    }
                }
            }
        }
    });
    return { found, caseIssues };
}

/**
 * Check if path segments represent navigation to other schema child name
 * @param valueHandlingContext
 * @param segments
 */
function getNavTarget(
    valueHandlingContext: ValueHandlingContext,
    segments: string[],
    isCollectionAllowed: boolean
): { schemaChildByNav: FullyQualifiedName; schemaChildByNavCaseIssue: CaseIssue; isCollection: boolean } {
    // last segment is navigation property name, first segments represent path identifying metadata element which contains navigation property
    let schemaChildByNav = '';
    let schemaChildByNavCaseIssue = undefined;
    let isCollection = false;
    const segmentsCopy = [...segments];
    const navPropertyName = segmentsCopy.pop();
    const sourcePath = segmentsCopy.join('/');
    const navSourceMap = valueHandlingContext.context.navigationSourceMap;
    Object.keys(navSourceMap || {}).forEach((fileUri) => {
        Object.keys(navSourceMap[fileUri][sourcePath] || {}).forEach((targetEntry) => {
            if (!schemaChildByNav) {
                if (navSourceMap[fileUri][sourcePath][targetEntry][navPropertyName]) {
                    isCollection = !!navSourceMap[fileUri][sourcePath][targetEntry][navPropertyName].isCollection;
                    if (!isCollection || isCollectionAllowed) {
                        schemaChildByNav = targetEntry;
                    }
                } else {
                    const keys = Object.keys(navSourceMap[fileUri][sourcePath][targetEntry]);
                    const key = keys.find((item) => item.toUpperCase() === navPropertyName.toUpperCase());
                    if (navSourceMap[fileUri][sourcePath][targetEntry][key]) {
                        isCollection = !!navSourceMap[fileUri][sourcePath][targetEntry][key].isCollection;
                        if (!isCollection || isCollectionAllowed) {
                            schemaChildByNavCaseIssue = {
                                wrong: navPropertyName,
                                correct: key
                            };
                        }
                    }
                }
            }
        });
    });
    return { schemaChildByNav, isCollection, schemaChildByNavCaseIssue };
}
type NavigationMap = {
    [navSourceType: string]: { [navTargetType: string]: { [navPropName: string]: { isCollection: boolean } } };
};
function existsNavPath(
    navigationMap: NavigationMap,
    sourcePath: string,
    targetType: string,
    ignoreTypes: { [type: string]: boolean },
    pathLength: number
): { navigationPath: string; navigationTargetType: string } {
    let navigationPath = '';
    let navigationTargetType = '';
    for (const type of Object.keys(navigationMap[sourcePath] || {})) {
        if (!ignoreTypes[type]) {
            if (type === targetType) {
                navigationPath = Object.keys(navigationMap[sourcePath][type])[0];
                navigationTargetType = targetType;
            } else if (pathLength <= 3) {
                const ignoreExtend = {};
                ignoreExtend[sourcePath] = true;
                ({ navigationPath, navigationTargetType } = existsNavPath(
                    navigationMap,
                    type,
                    targetType,
                    Object.assign(ignoreExtend, ignoreTypes),
                    pathLength + 1
                ));
                if (navigationPath) {
                    navigationPath += Object.keys(navigationMap[sourcePath][type])[0] + '/';
                }
            }
            if (navigationPath) {
                break;
            }
        }
    }
    return { navigationPath, navigationTargetType };
}

/**
 * Add navigation segments
 * @param valueHandlingContext
 * @param sourcePath - name of potential navigation source
 * @param lookUp
 * @param typesOrTerms
 * @param accumulatedResult - accumulate navigation segments here
 */
function addNavSegments(
    valueHandlingContext: ValueHandlingContext,
    sourcePath: PathValue,
    lookUp: PathCache | AnnotationPathCache,
    typesOrTerms: FullyQualifiedTypeName[] | FullyQualifiedName[],
    isCollectionAllowed: boolean,
    accumulatedResult
): boolean {
    let added = false;
    if (typesOrTerms.length === 1 && typesOrTerms[0] === '') {
        // no restriction regarding types or terms - allow all navigation properties as next nav segments
        const navSourceMap = valueHandlingContext.context.navigationSourceMap;
        Object.keys(navSourceMap || {}).forEach((fileUri) => {
            Object.keys(navSourceMap[fileUri][sourcePath] || {}).forEach((targetName) => {
                Object.keys(navSourceMap[fileUri][sourcePath][targetName] || {}).forEach((navigationProperty) => {
                    if (navigationProperty) {
                        // value of accumulated result entry should represent lookup result for navigation property target
                        const value = {};
                        collectPathResultsFromCache(
                            lookUp,
                            typesOrTerms,
                            [targetName],
                            false,
                            false,
                            value,
                            valueHandlingContext
                        );
                        addPathToObject(accumulatedResult, navigationProperty, value);
                        added = true;
                    }
                });
            });
        });
    } else {
        // build map of available target types per source type
        const navSourceMapOrig = valueHandlingContext.context.navigationSourceMap;
        const navigationMap: NavigationMap = {};
        Object.keys(navSourceMapOrig || {}).forEach((fileUri) => {
            Object.keys(navSourceMapOrig[fileUri]).forEach((navSourceType) => {
                Object.keys(navSourceMapOrig[fileUri][navSourceType] || {}).forEach((navTargetType) => {
                    Object.keys(navSourceMapOrig[fileUri][navSourceType][navTargetType]).forEach((navPropName) => {
                        const isCollection =
                            navSourceMapOrig[fileUri][navSourceType][navTargetType][navPropName]['isCollection'];
                        if (!isCollection || isCollectionAllowed) {
                            const path = [navSourceType, navTargetType, navPropName].join('/');
                            const value = navSourceMapOrig[fileUri][navSourceType][navTargetType][navPropName];
                            addPathToObject(navigationMap, path, value);
                        }
                    });
                });
            });
        });

        // get all targets which have paths leading to correct types or terms
        const targetNames = {};
        collectPathResultsFromCache(lookUp, typesOrTerms, [], false, false, targetNames, valueHandlingContext);
        // add navPropNames of source type which lead to supported target type
        Object.keys(navigationMap[sourcePath] || {}).forEach((navTargetType) => {
            let include = false;
            let navigationPath = '';
            let navigationTargetType = '';
            if (navTargetType === sourcePath) {
                // don't include nav properties pointing to same entity
            } else if (targetNames[navTargetType]) {
                // nav target type already is supporting correct types or terms
                include = true;
            } else {
                for (const targetName of Object.keys(targetNames)) {
                    // check if from current navTargetType, a type can be reached that supports correct types or terms
                    const ignoreTypes: { [type: string]: boolean } = {};
                    ignoreTypes[sourcePath] = true;
                    ignoreTypes[navTargetType] = true;
                    ({ navigationPath, navigationTargetType } = existsNavPath(
                        navigationMap,
                        navTargetType,
                        targetName,
                        ignoreTypes,
                        0
                    ));
                    if (navigationPath) {
                        include = true;
                        break;
                    }
                }
            }
            if (include) {
                // add all navigation properties leading to that navTargetType as path segments
                Object.keys(navigationMap[sourcePath][navTargetType]).forEach((navPropertyName) => {
                    if (navPropertyName) {
                        if (typeof targetNames[navTargetType] === 'object') {
                            // add next segments as path - otherwise navPropertyName itself becomes a valid last segment in path
                            Object.keys(targetNames[navTargetType]).forEach((nextSegment) => {
                                const value = targetNames[navTargetType][nextSegment];
                                addPathToObject(accumulatedResult, [navPropertyName, nextSegment].join('/'), value);
                            });
                        } else if (navigationPath) {
                            const path = [navPropertyName, navigationPath.split('/')].join('/');
                            addPathToObject(accumulatedResult, path, navigationTargetType);
                        }
                        added = true;
                    }
                });
            }
        });
    }
    return added;
}

export enum SegmentUsage {
    asLastSegmentOnly = 'Last',
    asIntermediateSegmentOnly = 'Intermediate',
    asLastOrIntermediateSegment = 'LastOrIntermediate'
}

export type NextPossibleSegment = { name: string; kind: string; usages: SegmentUsage };
interface GetPathInfoResult {
    value: boolean | string; // value stored for this path in path cache (in case sub segments exist: value of $Self)
    nextPossibleSegments: NextPossibleSegment[];
    validPath: boolean;
    invalidSegmentIndex: number;
    caseIssues: CaseIssue;
    isCollection: boolean;
}

/**
 * Function transforms all Collection(...) types into type of that collection members, i.e. Collection(Edm.String) => Edm.String
 */
function normalizeTypes(types: FullyQualifiedTypeName[], doNormalize: boolean): FullyQualifiedTypeName[] {
    return doNormalize
        ? types.map((t) => (t.startsWith('Collection(') ? t.slice('Collection('.length, t.length - 1) : t))
        : types;
}

/**
 * get path info
 * @param valueHandlingContext
 * @param segments - segments of absolute path (all finished segments, all aliases replaced)
 * @param types - name of types
 * @param terms - name of terms
 * @param forCheck - true: check validity of whole path; false: collect cache results for path
 */

export function getPathInfo(
    valueHandlingContext: ValueHandlingContext,
    segments: string[],
    types: FullyQualifiedTypeName[],
    terms: FullyQualifiedName[],
    forCheck: boolean,
    baseSegmentsCount = 0
): GetPathInfoResult {
    const pathInfo: GetPathInfoResult = {
        value: true,
        nextPossibleSegments: [],
        validPath: true,
        invalidSegmentIndex: -1,
        caseIssues: undefined,
        isCollection: false
    };

    // determine cache to look at and types or terms to consider
    // TODO for Edm.ModelElementPath we could have types and terms in parallel
    const isPropertyPath = types.includes(EdmType.VirtualProperty); // VirtualProperty is only requested for propertyPath
    const isNavigationPropertyPath =
        types.length === 2 && types.includes(EdmType.EntityType) && types.includes(EdmType.EntityTypeCollection);
    let lookupProperty = '';
    if (forCheck) {
        lookupProperty = types.length ? 'path' : terms.length ? 'annotationPath' : 'targetPath';
    } else if (isPropertyPath) {
        lookupProperty = 'propertyPathCc';
    } else {
        lookupProperty = types.length ? 'pathCc' : terms.length ? 'annotationPathCc' : 'targetPath';
    }
    // 1:n associations in paths are only allowed for "model" but not for "instance" paths
    // TODO: support mixture of collection like and single-tone types ?
    // use cases for types = [Collection(Edm.<SomeType>)]:
    // * type UI.DataField/Value
    //   - supports Edm.PrimitiveType or Collection(Edm.String) or Collection(Edm.Integer) or ...
    //   - 1:n associations can be followed to find primitive type, but also primitive type without 1:n associations would be fine
    // * @Common.Messages
    //   - is typed Collection(Edm.ComplexType) - is expected to be filled by path pointing to property of Collection(Edm.ComplexType) (no 1:n associations shall be followed)
    // * not supported by current logic:
    //   - e.g. Collection(Edm.String) to be filled by path pointing to property of Collection(Edm.ComplexType) (no 1:n associations shall be followed)
    // A more strict implementation to support Collection(SomeType) would either
    //   - look for property of type Collection(SomeType) without any 1:n association OR
    //   - look for property of type SomeType with exactly ine 1:n association
    const isTypesSupportingToMany = types.every(
        (t) => t.startsWith('Collection(') && t !== 'Collection(Edm.ComplexType)'
    );
    const isToManyAssociationAllowed =
        isNavigationPropertyPath ||
        isPropertyPath ||
        !lookupProperty.startsWith('path') ||
        isTypesSupportingToMany ||
        types.includes(EdmType.PrimitiveCollection); // used e.g. for UI.DataField/Value
    const lookup = valueHandlingContext.context.pathExpressions[lookupProperty];
    const termsOrTypes = types.length ? normalizeTypes(types, isTypesSupportingToMany) : terms.length ? terms : [''];
    let lookupResult: any;

    // for path and annotationPath expressions in code completion: remove cache content pointing to current annotation
    const removeCurrentAnnotationFromCache =
        valueHandlingContext.targetTermQualifier &&
        (lookupProperty === 'pathCc' || lookupProperty === 'annotationPathCc');
    const removedPaths: Map<string, Map<string, any>> = new Map();
    let lookupBackup: string;
    try {
        if (removeCurrentAnnotationFromCache) {
            lookupBackup = JSON.stringify(lookup);
            Object.keys(lookup).forEach((fileUris) => {
                termsOrTypes.forEach((termOrType) => {
                    if (!lookup[fileUris][termOrType]) {
                        return;
                    }

                    const cacheValue = removePathFromObject(
                        lookup[fileUris][termOrType],
                        valueHandlingContext.targetTermQualifier
                    );
                    if (cacheValue !== null) {
                        removedPaths.set(
                            fileUris,
                            (removedPaths.get(fileUris) || new Map()).set(termOrType, cacheValue)
                        );
                    }
                });
            });
        }

        if (segments.length === 0) {
            // no segments so far - get/check availability of start segments
            lookupResult = {};
            collectPathResultsFromCache(
                lookup,
                termsOrTypes,
                [],
                forCheck,
                forCheck,
                lookupResult,
                valueHandlingContext
            );
        } else if (
            segments[0].indexOf('.') < 0 &&
            valueHandlingContext.context.metadata &&
            valueHandlingContext.context.metadata.getMetadataElement &&
            !valueHandlingContext.context.metadata.getMetadataElement(segments[0])
        ) {
            // invalid: if no namespace is used, at least first segment needs to be valid root element in metadata service
            pathInfo.invalidSegmentIndex = 0;
        } else {
            // a branch represents a way to follow a path, i.e.
            // Container/entitySet/ could be followed by annotations of entitySet or corresponding entity type
            const branches: string[][] = [[]];
            // check availability segment by segment
            for (let i = 0; i < segments.length; i++) {
                const isLastSegment = segments.length - 1 === i;
                const checkExistenceOnly = !isLastSegment;
                branches.forEach((branch) => branch.push(segments[i]));
                lookupResult = {};
                const deleteIndices: number[] = [];
                for (let j = 0; j < branches.length; j++) {
                    const currentSegments: string[] = branches[j];
                    // if path represents navigation to something else: append new branch
                    const { schemaChildByNav, schemaChildByNavCaseIssue, isCollection } = getNavTarget(
                        valueHandlingContext,
                        currentSegments,
                        isToManyAssociationAllowed || i < baseSegmentsCount
                    );
                    if (schemaChildByNav) {
                        branches.push([schemaChildByNav]);
                    }
                    if (
                        (isLastSegment && forCheck && lookupResult.$Self) ||
                        (checkExistenceOnly && Object.keys(lookupResult).length)
                    ) {
                        break; // already found what we were looking for
                    }
                    // collect results from all segments for branch
                    const { found, caseIssues } = collectPathResultsFromCache(
                        lookup,
                        termsOrTypes,
                        currentSegments,
                        checkExistenceOnly,
                        forCheck,
                        lookupResult,
                        valueHandlingContext
                    );
                    let navSegmentAdded = false;
                    if (currentSegments.length && (!found || (isLastSegment && !checkExistenceOnly))) {
                        navSegmentAdded = addNavSegments(
                            valueHandlingContext,
                            currentSegments.join('/'),
                            lookup,
                            termsOrTypes,
                            isToManyAssociationAllowed || i < baseSegmentsCount - 1,
                            lookupResult
                        );
                    }
                    if (!found && !navSegmentAdded) {
                        deleteIndices.push(j);
                    }

                    if (caseIssues) {
                        pathInfo.caseIssues = caseIssues;
                    }
                    if (schemaChildByNavCaseIssue) {
                        pathInfo.caseIssues = schemaChildByNavCaseIssue;
                    }
                    if (schemaChildByNav && isCollection) {
                        pathInfo.isCollection = true;
                    }
                }
                if (Object.keys(lookupResult).length === 0) {
                    // no cache entries found starting with current segment
                    pathInfo.invalidSegmentIndex = i;
                    break;
                }
                // remove branches which are not needed anymore
                let j = deleteIndices.length;
                while (j--) {
                    branches.splice(deleteIndices[j], 1);
                }
            }
        }

        if (pathInfo.invalidSegmentIndex < 0) {
            pathInfo.value = lookupResult.$Self;
            if (forCheck) {
                pathInfo.validPath = !!lookupResult.$Self;
            }
            Object.keys(lookupResult).forEach((segmentName) => {
                if (segmentName !== '$Self') {
                    const subSegments =
                        typeof lookupResult[segmentName] === 'object' ? Object.keys(lookupResult[segmentName]) : [];
                    const subSegmentFound = subSegments.some((item) => item !== '$Self');
                    let usage: SegmentUsage = SegmentUsage.asLastOrIntermediateSegment;
                    if (!lookupResult[segmentName].$Self) {
                        usage = SegmentUsage.asIntermediateSegmentOnly;
                    }
                    if (!subSegmentFound) {
                        usage = SegmentUsage.asLastSegmentOnly;
                    }
                    pathInfo.nextPossibleSegments.push({
                        name: segmentName,
                        kind: lookupResult[segmentName].$Kind,
                        usages: usage
                    });
                }
            });
            if (
                valueHandlingContext.nodeContext?.allowWildCardInPath &&
                pathInfo.nextPossibleSegments.some((item) => item.usages === SegmentUsage.asLastSegmentOnly)
            ) {
                pathInfo.nextPossibleSegments.push({
                    name: '*',
                    kind: undefined,
                    usages: SegmentUsage.asLastSegmentOnly
                });
            }
        } else {
            // invalid segment found
            pathInfo.validPath = false;
        }

        if (removeCurrentAnnotationFromCache) {
            removedPaths.forEach((termTypeMap, fileUris) => {
                termTypeMap.forEach((value, termType) => {
                    lookup[fileUris][termType] = lookup[fileUris][termType] || {};
                    addPathToObject(lookup[fileUris][termType], valueHandlingContext.targetTermQualifier, value);
                });
            });
        }
    } catch (e) {
        // safety belt so path cache is not altered in case of exceptions during removing and later adding content for current annotation
        if (lookupBackup) {
            valueHandlingContext.context.pathExpressions[lookupProperty] = JSON.parse(lookupBackup);
        }
    }
    return pathInfo;
}

/**
 * determine array of types and/or array of terms to be used for lookup in path cache
 * @param valueType
 * @param pathKind
 */
function determineTermsTypesForCacheLookup(
    valueHandlingContext: ValueHandlingContext,
    valueType: ValueType,
    pathKind: PathKind
): { types: FullyQualifiedTypeName[]; terms: FullyQualifiedName[] } {
    // determine cache (type based/term based) and list of types/terms to consider
    const types: FullyQualifiedTypeName[] = [];
    let terms: FullyQualifiedName[] = [];
    const valueTypeAsString = convertValueTypeToString(valueType);
    const derivedTypes: Set<FullyQualifiedName> = valueHandlingContext.context.vocabularies.getDerivedTypeNames(
        valueType.name
    );
    const typeDefinition = valueHandlingContext.context.vocabularies.getType(valueType.name);
    if (typeDefinition && typeDefinition.kind === Edm.TypeDefinition && typeDefinition.underlyingType) {
        derivedTypes.add(typeDefinition.underlyingType);
    }

    if (pathKind === Edm.Path) {
        types.push(valueTypeAsString);
        const vocabularyType = getVocabularyType(valueHandlingContext.context, valueType.name);
        if (
            (vocabularyType && vocabularyType.kind === Edm.EnumType) ||
            ([EdmType.Decimal, EdmType.Double] as string[]).includes(valueType.name)
        ) {
            // add all integer types as well
            Object.keys(primitiveTypeMap)
                .filter((primitiveType) => primitiveTypeMap[primitiveType].constantExpressionName === Edm.Int)
                .forEach((typeName) =>
                    types.push(convertValueTypeToString({ name: typeName, asCollection: valueType.asCollection }))
                );
        } else {
            // add derived types
            derivedTypes.forEach((type) => {
                types.push(convertValueTypeToString({ name: type, asCollection: valueType.asCollection }));
            });
        }

        if (vocabularyType?.kind === Edm.EnumType) {
            // add string type as well
            types.push(EdmType.String);
        }
    } else {
        const pathTypes = (pathTypeMap[valueTypeAsString] &&
            pathTypeMap[valueTypeAsString].validNonAbstractPathTypes) || [valueTypeAsString];
        (pathTypes || []).forEach((nonAbstractType) => {
            switch (nonAbstractType) {
                case EdmType.PropertyPath:
                    types.push(
                        EdmType.PrimitiveType,
                        EdmType.ComplexType,
                        EdmType.NonEntityTypeCollection,
                        EdmType.VirtualProperty
                    );
                    break;
                case EdmType.NavigationPropertyPath:
                    types.push(EdmType.EntityType, EdmType.EntityTypeCollection);
                    break;
                case EdmType.AnnotationPath:
                    if (valueType.constraints && valueType.constraints.allowedTerms.length > 0) {
                        terms = terms.concat(valueType.constraints.allowedTerms); // allow restricted terms only
                    }
                    if (!terms.length) {
                        terms.push(cacheKeyAnyTermName); // allow any term
                    }
                    break;
            }
        });
    }
    return { types, terms };
}

/**
 * determine array of segments (replacing aliases with namespaces) from path (converted to absolute path)
 * @param path
 * @param valueHandlingContext
 * @param forCompletion
 */
export function determineSegmentsFromPath(
    path,
    valueHandlingContext: ValueHandlingContext,
    forCompletion?: boolean
): { segments: string[]; originalSegments: string[]; lastSegment: string; baseSegmentsCount: number } {
    let absolutePath = path;
    let baseSegmentsCount = 0;
    if (!path.startsWith('/')) {
        absolutePath = '/' + valueHandlingContext.pathBase.path;
        absolutePath += path ? `/${path}` : '';
        baseSegmentsCount = valueHandlingContext.pathBase.path.split('/').length;
    }
    absolutePath = absolutePath.slice(1);
    const originalSegments = absolutePath.split('/');
    // for completion? separate completed segments from (maybe unfinished) last segment, remove aliases from completed segments
    const lastSegment = forCompletion && path ? originalSegments.pop() : '';
    const segments = originalSegments.map((originalSegment) => {
        return getSegmentWithoutAlias(valueHandlingContext.aliasInfo, originalSegment);
    });
    return { segments, originalSegments, lastSegment, baseSegmentsCount };
}

/**
 * complete path expressions
 * @param valueHandlingContext
 * @param valueType
 * @param pathKind
 * @param startString
 */
export function completePathExpressions(
    valueHandlingContext: ValueHandlingContext,
    valueType: ValueType,
    pathKind: PathKind,
    startString: string
): CompletionItem[] {
    const completionItems: CompletionItem[] = [];
    // determine array of segments (replacing aliases with namespaces) from path (converted to absolute path)
    const path = (startString || '').trim();
    if (valueHandlingContext.context.supportSplit && path.startsWith('/')) {
        return [];
    } // no support of absolute paths in CDS
    const { segments, baseSegmentsCount } = determineSegmentsFromPath(path, valueHandlingContext, true);
    // determine array of types and/or array of terms to be used for lookup in path cache
    const { types, terms } = determineTermsTypesForCacheLookup(valueHandlingContext, valueType, pathKind);

    // build namespace to alias map including default vocabulary aliases
    const namespaceToAlias: AliasMap = Object.assign({}, valueHandlingContext.aliasInfo.reverseAliasMap);
    valueHandlingContext.context.vocabularies.getVocabularies().forEach((vocabulary) => {
        if (!namespaceToAlias[vocabulary.namespace]) {
            namespaceToAlias[vocabulary.namespace] = vocabulary.defaultAlias;
        }
    });

    // read the cache
    const pathInfo = getPathInfo(valueHandlingContext, segments, types, terms, false, baseSegmentsCount);
    if (pathInfo.validPath) {
        pathInfo.nextPossibleSegments.forEach((segment) => {
            let completionText = segment.name;
            // convert namespaces to alias
            if (completionText.includes('.')) {
                const indexTerm = completionText.indexOf('@') + 1;
                if (indexTerm) {
                    let termName = completionText.slice(indexTerm);
                    termName = getAliasQualifiedNameDefVoc(termName, namespaceToAlias);
                    completionText = completionText.slice(0, indexTerm) + termName;
                } else {
                    completionText = toAliasQualifiedName(completionText, valueHandlingContext.aliasInfo);
                }
            }

            const documentation: string[] = [];
            let truncatedText: string;
            if (completionText.includes('.')) {
                const indexAt = completionText.indexOf('@');
                const qualifiedName = indexAt >= 0 ? completionText.slice(indexAt + 1) : completionText;
                truncatedText = appendNameToDocumentationAndTruncate(
                    qualifiedName,
                    documentation,
                    valueHandlingContext.context,
                    true,
                    valueHandlingContext.aliasInfo
                );
                truncatedText = completionText.replace(qualifiedName, truncatedText);
            } else if (completionText === '*') {
                truncatedText = appendNameToDocumentationAndTruncate(
                    completionText,
                    documentation,
                    valueHandlingContext.context,
                    false,
                    null,
                    'Item'
                );
                documentation.push(`**Description:** ${i18n.t('Wildcard_path_segment_description')}`);
            } else {
                truncatedText = appendNameToDocumentationAndTruncate(
                    completionText,
                    documentation,
                    valueHandlingContext.context,
                    false,
                    null,
                    'Item'
                );
            }

            if (completionText) {
                completionItems.push({
                    text: truncatedText,
                    filterText: completionText,
                    name: completionText,
                    insertText: completionText,
                    commitCharacters: segment.usages === SegmentUsage.asLastSegmentOnly ? [] : ['/'],
                    commitCharacterRequired: segment.usages === SegmentUsage.asIntermediateSegmentOnly,
                    category: segment.kind as CompletionItemCategory,
                    sorting: {
                        isAnnotationPath: pathKind === 'AnnotationPath'
                    },
                    documentation: { kind: MarkupKind.Markdown, value: documentation.join('\n') }
                });
            }
        });
    }

    return completionItems;
}
function isPropertyPath(metadataElement: MetadataElement): boolean {
    // also exclude functions/actions
    return !metadataElement.isEntityType && !metadataElement.name.includes('(');
}
function hasSubSegments(metadataElement: MetadataElement): boolean {
    return metadataElement.isEntityType || metadataElement.isComplexType || metadataElement.name.includes('(');
}

interface PathInfoForMessageGeneration {
    validPath: boolean;
    hasNextPossibleSegments: boolean;
    invalidSegmentIndex: number;
    caseIssues: CaseIssue;
    isCollection: boolean;
}

function quickPathCheck(
    valueHandlingContext: ValueHandlingContext,
    valueType: ValueType,
    segments: string[]
): PathInfoForMessageGeneration | null {
    // check preconditions for quick check
    if (valueType.name !== EdmType.NavigationPropertyPath && valueType.name !== EdmType.PropertyPath) {
        return null;
    }
    if (valueType.constraints?.requiresType) {
        return null;
    }
    if (!segments.length || !segments[segments.length - 1]) {
        return null; // no segments or empty last segment
    }
    const metadataElement = getMdElementForMdPath(segments.join('/'), valueHandlingContext.context.metadata);
    if (!metadataElement) {
        return null; // path could not be resolved
    }
    // build result (will be evaluated only to generate error message in getMessagesFromPathInfo())
    const validPath =
        (valueType.name === EdmType.NavigationPropertyPath && metadataElement.isEntityType) ||
        (valueType.name === EdmType.PropertyPath && isPropertyPath(metadataElement));

    return {
        validPath,
        hasNextPossibleSegments: hasSubSegments(metadataElement),
        invalidSegmentIndex: -1, // if quick check has result full path was valid -> no segment specific issues possible
        caseIssues: undefined, // if quick check has result there can be no case issues
        isCollection: metadataElement.isCollectionValued
    };
}
/**
 * check path expressions
 * @param valueHandlingContext
 * @param valueType
 * @param property
 */
export function checkPathExpressions(
    valueHandlingContext: ValueHandlingContext,
    valueType: ValueType,
    property: Property
): Diagnostic[] {
    const messages: Diagnostic[] = [];

    const pathExpression = pathExpressionMap[property.name];
    if (pathExpression.supportedTypes && !pathExpression.supportedTypes[valueType.name]) {
        // error: wrong (path) expression for (path) type
        const aliasedName = toAliasQualifiedName(valueType.name, valueHandlingContext.aliasInfo);
        const message = i18n.t('Element_0_cannot_provide_type_1', {
            element: property.name,
            type: aliasedName
        });
        messages.push({
            message: message,
            severity: DiagnosticSeverity.Error,
            range: property.nameRange
        });
    } else {
        // determine array of segments (replacing aliases with namespaces) from path (converted to absolute path)
        const path = ((property.value as string) || '').trim();
        if (valueHandlingContext.context.supportSplit && path.startsWith('/')) {
            return []; // no support of absolute paths in CDS
        }
        const { segments, originalSegments, baseSegmentsCount } = determineSegmentsFromPath(path, valueHandlingContext);
        const pathInfoForMessageGeneration = quickPathCheck(valueHandlingContext, valueType, segments);
        if (pathInfoForMessageGeneration) {
            const { compatibleTypes, primitiveType } = getCompatibleTypesData(valueHandlingContext.context, valueType);
            messages.push(
                ...getMessagesFromPathInfo(
                    pathInfoForMessageGeneration,
                    originalSegments,
                    property,
                    segments,
                    valueHandlingContext,
                    valueType,
                    {
                        compatibleTypes,
                        expressionName: primitiveType?.constantExpressionName
                    }
                )
            );
            return messages;
        }
        // make sure vocabulary references are present for all term cast segments
        segments
            .filter((segment) => segment.indexOf('@') >= 0)
            .forEach((segment) => {
                const indexAt = segment.indexOf('@');
                const resolvedName = resolveName(segment.substr(indexAt + 1), valueHandlingContext.aliasInfo.aliasMap);
                const term = resolvedName.qName;
                const vocabularyNamespace = valueHandlingContext.context.vocabularies.getVocabularyNamespace(term);
                if (vocabularyNamespace && vocabularyNamespace !== resolvedName.namespace) {
                    const indexSegment = (property.value as string).indexOf(segment);
                    const range = {
                        start: {
                            line: property.valueRange.start.line,
                            character: property.valueRange.start.character + indexSegment + indexAt + 1
                        },
                        end: {
                            line: property.valueRange.start.line,
                            character: property.valueRange.start.character + indexSegment + segment.length
                        }
                    };
                    const unknownValue = term.startsWith(vocabularyNamespace)
                        ? vocabularyNamespace
                        : !resolvedName.namespace
                        ? term.split('.')[0]
                        : resolvedName.namespace;
                    messages.push(
                        createUnknownVocabularyDiagnostic(
                            unknownValue,
                            vocabularyNamespace,
                            range,
                            valueHandlingContext.context.vocabularies
                        )
                    );
                }
            });
        // make sure metadata references are present for all complete path
        const metadataUri = valueHandlingContext.context.metadataUri;
        if (metadataUri && path.startsWith('/') && segments && segments[0]) {
            const resolvedName = resolveName(segments[0], valueHandlingContext.aliasInfo.aliasMap);
            if (resolvedName && !resolvedName.namespace) {
                const metadataNamespace = resolveName(segments[0]).namespace;
                if (valueHandlingContext.context.metadata.getNamespaces().has(metadataNamespace)) {
                    const range = {
                        start: {
                            line: property.valueRange.start.line,
                            character: property.valueRange.start.character + 1
                        },
                        end: {
                            line: property.valueRange.start.line,
                            character: property.valueRange.start.character + segments[0].length + 1
                        }
                    };
                    messages.push(createUnknownMetadataDiagnostic(metadataNamespace, range, metadataUri));
                }
            }
        }
        // complete
        if (messages.length) {
            return messages;
        }

        // determine array of types and/or array of terms to be used for lookup in path cache
        const { types, terms } = determineTermsTypesForCacheLookup(
            valueHandlingContext,
            valueType,
            property.name as PathKind
        );
        // read the cache
        const pathInfo = getPathInfo(valueHandlingContext, segments, types, terms, true, baseSegmentsCount);
        const vocabularies = valueHandlingContext.context.vocabularies;
        const vocabObj = vocabularies.getType(valueType.name);
        const expectedTypeName =
            vocabObj?.kind === 'EnumType'
                ? i18n.t('numeric_primitive_value')
                : vocabObj?.underlyingType
                ? vocabObj?.underlyingType
                : valueType.name;

        const expectedType = { ...valueType, name: expectedTypeName };
        const { compatibleTypes, primitiveType } = getCompatibleTypesData(valueHandlingContext.context, expectedType);
        messages.push(
            ...getMessagesFromPathInfo(
                { ...pathInfo, hasNextPossibleSegments: !!pathInfo?.nextPossibleSegments.length },
                originalSegments,
                property,
                segments,
                valueHandlingContext,
                expectedType,
                { compatibleTypes, expressionName: primitiveType?.constantExpressionName }
            )
        );
    }
    return messages;
}

function getMessagesFromPathInfo(
    pathInfo: PathInfoForMessageGeneration,
    originalSegments: string[],
    property: Property,
    segments: string[],
    valueHandlingContext: ValueHandlingContext,
    expectedType: ValueType,
    compatibleTypesData: { compatibleTypes: ValueType[]; expressionName: string | undefined }
): Diagnostic[] {
    if (pathInfo.validPath) {
        return [];
    }
    const messages: Diagnostic[] = [];
    if (pathInfo.invalidSegmentIndex >= 0) {
        const originalSegment = originalSegments[pathInfo.invalidSegmentIndex];
        let range = property.valueRange;
        const searchString = originalSegment + (pathInfo.invalidSegmentIndex < segments.length - 1 ? '/' : '');
        const startIndex = (property.value as string).indexOf(searchString);
        if (startIndex > 0) {
            range = JSON.parse(JSON.stringify(property.valueRange));
            range.start.character += startIndex;
        }
        if (pathInfo.caseIssues) {
            let correctCase = pathInfo.caseIssues.correct;
            if (correctCase.includes('.')) {
                // Replace fully qualified name with alias, if original segment is alias.
                if (originalSegment.toUpperCase() !== correctCase.toUpperCase()) {
                    const fullyQualifierName = correctCase.replace('@', '').trim();
                    const aliasQualifiedName = toAliasQualifiedName(fullyQualifierName, valueHandlingContext.aliasInfo);
                    correctCase = originalSegment.includes('@') ? `@${aliasQualifiedName}` : aliasQualifiedName;
                }
            }
            range.end.character = range.start.character + originalSegment.length;
            const nameCaseDiagnostic = createNameCasePathValueDiagnostic(originalSegment, correctCase, range);
            // add caseCheck as quick fixt depends on it.
            (nameCaseDiagnostic.data as CaseCheckBase).caseCheck = {
                lookupPath: [],
                value: originalSegment,
                isNamespacedValue: false,
                proposedValue: correctCase
            };
            messages.push(nameCaseDiagnostic);
        } else {
            let mesg1 = '';
            const segments = String(property.value).split('@');
            const { metadataType, vocabularyType } = getAbstractTypeFromPathValue(valueHandlingContext, segments);
            const abstractName = vocabularyType || metadataType;
            if (
                originalSegments[pathInfo.invalidSegmentIndex] === '' ||
                (originalSegments.join('/').indexOf('@') < 0 && abstractName)
            ) {
                messages.push(
                    compatibleTypesData.compatibleTypes.length
                        ? {
                              message: getPathErrorMessageForCompatibleTypes(
                                  property,
                                  abstractName,
                                  [expectedType, ...compatibleTypesData.compatibleTypes].map((t) =>
                                      convertValueTypeToString(t)
                                  ),
                                  compatibleTypesData.expressionName,
                                  expectedType.asCollection
                              ),
                              severity: DiagnosticSeverity.Error,
                              range: range,
                              rule: 'incomplete-path-with-compatible-types',
                              data: {
                                  pathValue: String(property.value),
                                  abstractName,
                                  expectedType: expectedType.name,
                                  expressionName: compatibleTypesData.expressionName,
                                  isCollection: expectedType.asCollection
                              }
                          }
                        : {
                              message: getPathErrorMessage(
                                  property,
                                  abstractName,
                                  convertValueTypeToString(expectedType)
                              ),
                              severity: DiagnosticSeverity.Error,
                              range: range,
                              rule: 'incomplete-path-with-type',
                              data: {
                                  pathValue: String(property.value),
                                  abstractName: abstractName,
                                  expectedType: expectedType.name
                              }
                          }
                );
            } else if (pathInfo.invalidSegmentIndex >= 0) {
                mesg1 = i18n.t('path_does_not_exist');
                // CDS ? for performance reasons we don't have all metadata - so leave out hint about failing segment
                const additionalInfo =
                    originalSegment && !valueHandlingContext.context.supportSplit
                        ? i18n.t('Check_0', {
                              segment: originalSegment
                          })
                        : '';
                const message = additionalInfo ? `${mesg1} ${additionalInfo}` : `${mesg1}`;
                messages.push({
                    message: message,
                    severity: DiagnosticSeverity.Error,
                    range: range,
                    rule: INVALID_PATH_EXPRESSION,
                    data: {
                        name: property.name,
                        value: originalSegment
                    }
                });
            }
        }
    } else if (!property.value && pathInfo.hasNextPossibleSegments) {
        // when the path value is empty
        if (valueHandlingContext.nodeContext?.sideEffectsTargetProperties) {
            const message = i18n.t('Empty_property_path_as_string');
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: property.valueRange
            });
        } else {
            const message = i18n.t('path-value_is_required', {
                element: property.name
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: property.valueRange,
                rule: 'value-required',
                data: {
                    name: property.name
                }
            });
        }
    } else if (pathInfo.invalidSegmentIndex === -1 && pathInfo.hasNextPossibleSegments) {
        // OData specification: the operand of Eq need not be primitive value
        if (valueHandlingContext.context.supportSplit) {
            const segments = String(property.value).split('@');
            const { metadataType, vocabularyType } = getAbstractTypeFromPathValue(valueHandlingContext, segments);
            const abstractName = vocabularyType || metadataType || 'unknown';
            messages.push(
                compatibleTypesData.compatibleTypes.length
                    ? {
                          message: getPathErrorMessageForCompatibleTypes(
                              property,
                              abstractName,
                              [expectedType, ...compatibleTypesData.compatibleTypes].map((t) =>
                                  convertValueTypeToString(t)
                              ),
                              compatibleTypesData.expressionName,
                              expectedType.asCollection
                          ),

                          severity: DiagnosticSeverity.Error,
                          range: property.valueRange,
                          rule: 'incomplete-path-with-compatible-types',
                          data: {
                              pathValue: String(property.value),
                              abstractName: abstractName,
                              expectedType: expectedType.name,
                              expressionName: compatibleTypesData.expressionName,
                              isCollection: expectedType.asCollection
                          }
                      }
                    : {
                          message: getPathErrorMessage(property, abstractName, convertValueTypeToString(expectedType)),
                          severity: DiagnosticSeverity.Error,
                          range: property.valueRange,
                          rule: 'incomplete-path-with-type',
                          data: {
                              pathValue: String(property.value),
                              abstractName: abstractName,
                              expectedType: expectedType.name
                          }
                      }
            );
        } else {
            const message = i18n.t('Incomplete0_Add_slash_and_select_the_next_segment', {
                path: property.name
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: property.valueRange,
                rule: 'incomplete-expression-forward-slash',
                data: {
                    name: property.name
                }
            });
        }
    } else {
        const message = i18n.t('Invalid_path_for_0_expression', {
            expression: property.name
        });
        messages.push({
            message: message,
            severity: DiagnosticSeverity.Error,
            range: property.valueRange
        });
    }
    return messages;
}

function getPathErrorMessage(property: Property, abstractName: string, typeExpected: string): string {
    return i18n
        .t('Path_0_leads_to_1_The_path_should_lead_to_type_2', {
            value: String(property.value),
            abstractType: abstractName || 'unknown',
            typeExpected
        })
        .split('&#x2F;')
        .join('/');
}

function getPathErrorMessageForCompatibleTypes(
    property: Property,
    abstractName: string,
    typesExpected: string[],
    expressionName: string,
    isCollection: boolean
): string {
    return i18n
        .t(
            isCollection
                ? 'Path_0_leads_to_1_The_path_should_lead_to_a_collection_representing_2'
                : 'Path_0_leads_to_1_The_path_should_lead_to_type_representing_2_3',
            {
                value: String(property.value),
                abstractType: abstractName || 'unknown',
                expressionName,
                typeExpected: typesExpected[0]
            }
        )
        .split('&#x2F;')
        .join('/');
}

function getAbstractTypeFromPathValue(
    valueHandlingContext: ValueHandlingContext,
    segments: string[]
): { metadataType: string; vocabularyType: string } {
    let metadataType = '';
    let vocabularyType = '';
    let mdElementPath = '';
    let term = '';
    let qualifier = '';
    let remSegments = [];
    const isCDSContext = valueHandlingContext.context.supportSplit;
    if (segments[0]) {
        if (segments[0].indexOf('/') === 0) {
            mdElementPath = segments[0].substr(1, segments[0].length);
        } else {
            mdElementPath = `${valueHandlingContext.pathBase.path}/${segments[0]}`;
        }
        const lookupResult = lookupTarget(
            valueHandlingContext.context,
            mdElementPath.replace(/\/$/, ''),
            valueHandlingContext.aliasInfo
        );
        if (lookupResult.metadataElement) {
            metadataType = getMetadataType(
                valueHandlingContext,
                lookupResult.metadataElement,
                lookupResult.isCollection
            );
        }
        mdElementPath = lookupResult.metadataElement?.structuredType || lookupResult.metadataElement?.path;
    }
    const target = segments.shift().split('/');
    const pathSegments = segments.join('@') ? segments.join('@').split('/') : segments;
    metadataType = isCDSContext && !target[target.length - 1] && pathSegments.length < 1 ? 'unknown' : metadataType;
    for (let i = 0; i < pathSegments.length; i++) {
        let segment = pathSegments[i];
        const aliasMapVocabulary = valueHandlingContext.aliasInfo.aliasMapVocabulary;
        const pathLength = pathSegments.length;
        remSegments = i === pathLength - 1 ? pathSegments.slice(1, pathLength) : pathSegments.slice(1, i + 1);
        if (segment && (i === 0 || segment.startsWith('@'))) {
            segment = segment.startsWith('@') ? segment.substr(1) : segment;
            const resolvedName = resolveName(segment, aliasMapVocabulary);
            const qName = resolvedName?.qName || '';
            [term, qualifier] = qName.split('#');
            vocabularyType = valueHandlingContext.context.vocabularies.getTerm(term)?.type || 'Edm.String';
        } else if (segment && isNaN(parseInt(pathSegments[i]))) {
            vocabularyType = !vocabularyType.startsWith('Edm')
                ? valueHandlingContext.context.vocabularies.getComplexTypeProperty(vocabularyType, segment)?.type ||
                  'Edm.String'
                : vocabularyType;
        } else if (!segment && isCDSContext) {
            vocabularyType = 'unknown';
            break;
        }

        if (!vocabularyType.startsWith('Edm')) {
            const newType = valueHandlingContext.context.vocabularies.getType(vocabularyType);
            if (newType && newType.kind === 'ComplexType' && newType.isAbstract) {
                const recordType = getTypeFromAnnotationFile(
                    valueHandlingContext,
                    mdElementPath || valueHandlingContext.pathBase.path,
                    term,
                    qualifier,
                    remSegments
                );
                vocabularyType = recordType || vocabularyType;
            }
        }
    }
    return { vocabularyType, metadataType };
}

function getMetadataType(
    valueHandlingContext: ValueHandlingContext,
    metadataElement: MetadataElement,
    isCollection?: boolean
): string {
    let metadataType = '';
    const valueType = getValueTypeForMetadataElement(metadataElement);
    if (valueType.name) {
        const metadataTypeName = convertValueTypeToString(valueType);
        metadataType = metadataTypeName.startsWith('Edm.')
            ? metadataTypeName
            : getAbstractTypeName(valueHandlingContext.context, metadataTypeName);
    }
    metadataType = metadataType || metadataElement?.kind;
    if (isCollection) {
        metadataType = `Collection(${metadataType})`;
    }
    return metadataType;
}

function getTypeFromAnnotationFile(
    valueHandlingContext: ValueHandlingContext,
    path: string,
    term: string,
    qualifier: string,
    remainingSegments: string[]
): string {
    let type = '';
    for (let index = 0; index < valueHandlingContext.context.annotationFileSequence.length; index++) {
        const fileUri = valueHandlingContext.context.annotationFileSequence[index];
        const file = valueHandlingContext.context.fileCache[fileUri];
        const { annotationFound, elements } = findElementsForPath(
            valueHandlingContext.context,
            file.serviceFile.content,
            path,
            term,
            qualifier || '',
            remainingSegments.filter((value) => value)
        );
        if (annotationFound && elements[0].name === 'Record') {
            type = elements[0]?.attributes?.Type?.value;
            type = resolveName(type, valueHandlingContext.aliasInfo.aliasMap).qName;
            break;
        }
    }

    return type;
}

/**
 * find embedded annotation
 * @param annotation - host annotation
 * @param segments - path segments pointing to embedded annotation
 * @param aliasInfo
 */
function findEmbeddedElement(annotation: Element, segments: string[], aliasInfo: AliasInformation): Element {
    // segments can be either string (properties of a record or embedded annotation) or numbers (indices of a collection)
    let currentElement: Element = annotation;
    (segments || []).forEach((segment) => {
        if (currentElement) {
            if (segment.indexOf('@') === 0) {
                // term cast segment: find Annotation with correct term and qualifier
                const [term, qualifier] = segment.slice(1).split('#');
                const matches = (currentElement.content || []).filter((subElement) => {
                    if (subElement.type !== ELEMENT_TYPE || subElement.name !== Edm.Annotation) {
                        return false;
                    } else {
                        let termValue = getElementAttributeValue(subElement, Edm.Term);
                        termValue = resolveName(termValue, aliasInfo.aliasMap).qName;
                        const qualifierValue = getElementAttributeValue(subElement, Edm.Qualifier);
                        return term === termValue && ((!qualifier && !qualifierValue) || qualifier === qualifierValue);
                    }
                });
                currentElement = matches && matches.length ? (matches[0] as Element) : null;
            } else if (RegExp(`^\\d+$`).test(segment)) {
                // index segment: find entry in collection with correct index
                const index = parseInt(segment, 10);
                let collections: Element[];
                if (currentElement.name === Edm.Collection) {
                    collections = [currentElement];
                } else {
                    collections = (currentElement.content || []).filter(
                        (subElement) => subElement.type === ELEMENT_TYPE && subElement.name === Edm.Collection
                    ) as Element[];
                }
                currentElement = null;
                const collection = collections && collections.length ? collections[0] : null;
                if (collection) {
                    let counter = -1;
                    (collection.content || []).forEach((subElement) => {
                        if (subElement.type === ELEMENT_TYPE) {
                            ++counter;
                        }
                        if (!currentElement && counter === index) {
                            currentElement = subElement as Element;
                        }
                    });
                }
            } else {
                // segment represents structural property: find Record containing property value with name = segment
                let records: Element[];
                if (currentElement.name === Edm.Record) {
                    records = [currentElement];
                } else {
                    records = (currentElement.content || []).filter(
                        (subElement) => subElement.type === ELEMENT_TYPE && subElement.name === Edm.Record
                    ) as Element[];
                }
                const recordContent = records && records.length ? records[0].content : [];
                const matches = (recordContent || []).filter((subElement) => {
                    if (subElement.type !== ELEMENT_TYPE || subElement.name !== Edm.PropertyValue) {
                        return false;
                    } else if (getElementAttributeValue(subElement, Edm.Property) !== segment) {
                        return false;
                    }
                    return true;
                });
                currentElement = matches && matches.length ? (matches[0] as Element) : null;
            }
        }
    });
    return currentElement;
}

/**
 * find annotation for path
 * @param context
 * @param annotationFile - annotation file to search
 * @param annotatedMetadataElementPath - id of annotatede metadata element
 * @param term
 * @param qualifier
 * @param remainingSegments - segments pointing inside the annotation value (for embedded annotations)
 */

export function findElementsForPath(
    context: Context,
    annotationFile: AnnotationFile,
    annotatedMetadataElementPath: PathValue,
    term: FullyQualifiedName,
    qualifier?: Name, // when not provided: search for all qualifiers
    remainingSegments?: string[]
): { annotationFound: boolean; elements: Element[] } {
    const elements: Element[] = [];
    let annotationFound = false;
    annotationFile.targets.forEach((targetEntry) => {
        // find annotated metadata element
        const namespaces = getAllNamespacesAndReferences(annotationFile?.namespace, annotationFile.references);
        const aliasInfo: AliasInformation = getAliasInformation(namespaces, context.metadata.getNamespaces());
        // remove aliases from target; collect all involved namespaces
        const targetSegments = targetEntry.name
            .split('/')
            .filter((segment) => !!segment)
            .map((segment) => {
                let segmentWithoutAlias = segment;
                if (segmentWithoutAlias.indexOf('.') > 0) {
                    segmentWithoutAlias = resolveName(segmentWithoutAlias, aliasInfo.aliasMapMetadata).qName;
                }
                return segmentWithoutAlias;
            });
        const targetPath = targetSegments.length ? targetSegments.join('/') : '';
        const lookupResult = lookupTarget(context, targetPath, aliasInfo);
        if (lookupResult.metadataElement && lookupResult.metadataElement.path === annotatedMetadataElementPath) {
            // annotated metadata element found!
            targetEntry.terms.forEach((currentTerm) => {
                const qualifierValue = getElementAttributeValue(currentTerm, Edm.Qualifier);
                let termValue = getElementAttributeValue(currentTerm, Edm.Term);
                termValue = resolveName(termValue, aliasInfo.aliasMap).qName;
                if (
                    termValue === term &&
                    (qualifier === undefined || (!qualifierValue && !qualifier) || qualifierValue === qualifier)
                ) {
                    const element = findEmbeddedElement(currentTerm, remainingSegments || [], aliasInfo);
                    // term/qualifier found!
                    if (element) {
                        annotationFound = true;
                        elements.push(element);
                    }
                }
            });
        }
    });
    return { annotationFound: annotationFound, elements: elements };
}

export function findRangesForPropertyPath(
    context: Context,
    aliasInfo: AliasInformation,
    annotationFile: AnnotationFile,
    metadataElementPath: PathValue,
    virtualPropertyName: string
): Range[] {
    const getNestedPropertyPathElements = (element: Element): Element[] => {
        const elements: Element[] = [];
        (element.content || [])
            .filter((child) => child.type === ELEMENT_TYPE)
            .forEach((child: Element) => {
                const attribute = getElementAttribute(child, Edm.PropertyPath);
                const attributeValue = attribute?.value;
                if (attributeValue && attributeValue.includes(virtualPropertyName)) {
                    elements.push({
                        type: ELEMENT_TYPE,
                        name: Edm.PropertyPath,
                        nameRange: child.nameRange,
                        content: [{ type: TEXT_TYPE, text: attributeValue, range: attribute.valueRange }]
                    } as Element);
                }
                if (child.name === Edm.PropertyPath && getSingleTextNode(child)?.text.includes(virtualPropertyName)) {
                    elements.push(child);
                } else {
                    elements.push(...getNestedPropertyPathElements(child));
                }
            });
        return elements;
    };

    const result: Range[] = [];
    annotationFile.targets.forEach((targetEntry) => {
        const pathBase = getPathBaseMetadataElement(context.metadata, targetEntry.name, aliasInfo);
        const valueHandlingContext = { context, aliasInfo, pathBase };
        const elements: Element[] = [];
        targetEntry.terms.forEach((currentTerm) => {
            const attribute = getElementAttribute(currentTerm, Edm.PropertyPath);
            const attributeValue = attribute?.value;
            if (attributeValue && attributeValue.includes(virtualPropertyName)) {
                elements.push({
                    type: ELEMENT_TYPE,
                    name: Edm.PropertyPath,
                    nameRange: attribute.nameRange,
                    content: [{ type: TEXT_TYPE, text: attributeValue, range: attribute.valueRange }]
                } as Element);
            } else {
                elements.push(...getNestedPropertyPathElements(currentTerm));
            }
        });
        const virtualPropRanges: Range[] = elements.reduce((acc, entry) => {
            const textNode = getSingleTextNode(entry);
            const { segments } = determineSegmentsFromPath(textNode.text, valueHandlingContext);
            const idx = segments.lastIndexOf(virtualPropertyName);
            if (idx > -1) {
                const mdPathValue = segments.slice(0, idx).join('/');
                const targetMdElement = lookupTarget(context, mdPathValue, aliasInfo)?.metadataElement;
                if (
                    targetMdElement &&
                    (metadataElementPath === targetMdElement.name ||
                        metadataElementPath === targetMdElement.structuredType)
                ) {
                    const startStringLength = textNode.text.lastIndexOf(virtualPropertyName);
                    const offset = textNode.range.start.character + startStringLength;
                    acc.push({
                        start: {
                            ...textNode.range.start,
                            character: offset
                        },
                        end: {
                            ...textNode.range.start,
                            character: offset + virtualPropertyName.length
                        }
                    });
                }
            }
            return acc;
        }, []);
        result.push(...virtualPropRanges);
    });
    return result;
}
