export type JsonPath = string; // JsonPath in this form $['<stringSegment1>'][<indexSegment>['<stringSegment2>']
export type PathSegment = string | number;

export interface ResolveObjectResult {
    object: any; // resolved object
    errorMessage: string; // error message in case object could not be resolved
    resolvedPath: JsonPath; // part of the path which could be resolved
}

/**
 * get path segments as array of strings or indices
 * @param path - JSON path // TODO introduce type for JSON path
 */
export function getPathSegments(path: JsonPath): PathSegment[] {
    const cleanedPath: JsonPath = (path || '$').substring(1);
    let segments: string[] = [];
    if (cleanedPath) {
        segments = cleanedPath.split('][');
        const lastIndex = segments.length - 1;
        segments[0] = segments[0].substring(1);
        segments[lastIndex] = segments[lastIndex].substring(0, segments[lastIndex].length - 1);
    }
    const pathSegments: PathSegment[] = [];
    segments.forEach((segment) => {
        let pathSegment: PathSegment;
        if (segment.indexOf("'") === 0) {
            pathSegment = segment.substring(1, segment.length - 1);
        } else {
            pathSegment = parseInt(segment, 10);
        }
        pathSegments.push(pathSegment);
    });
    return pathSegments;
}

/**
 * build path from segments
 * @param pathSegments - array of string or index entries
 */
export function buildPathFromSegments(pathSegments: PathSegment[]): JsonPath {
    const segments: string[] = [];
    pathSegments.forEach((pathSegment) => {
        segments.push(typeof pathSegment === 'string' ? "'" + pathSegment + "'" : String(pathSegment));
    });
    return pathSegments.length ? '$[' + segments.join('][') + ']' : '$';
}

export interface PathTargetInElement {
    isName: boolean; // path points to element name
    isAttributeName: boolean; // path points to attribute name
    isAttributeValue: boolean; // path points to attribute value
    attribute: Attribute;
    isSubNode: boolean; // path points to entry in content
    nodeIndex: number; // if isSubNode: index of subnode
    isTextSubNode: boolean; // path points to entry in content (text)
    textNode: TextNode;
    isElementSubNode: boolean; // path points to entry in content (element)
    isElementSubNodeName: boolean; // path points to element subnodes name
    isWhitespacePosition: boolean; // path points to position in whitespace, i.e. segment '$1' : before sub node with index 1
    beforeSubNodeIndex: number; // only present if is whitespace position
    element: Element;
    remainingPathForElement: JsonPath;
}

/**
 * Reusable in tests
 */
export function getEmptyPathTargetInElement(): PathTargetInElement {
    return {
        isName: false,
        isAttributeName: false,
        isAttributeValue: false,
        attribute: null,
        isSubNode: false,
        nodeIndex: -1,
        isTextSubNode: false,
        textNode: null,
        isElementSubNode: false,
        isElementSubNodeName: false,
        isWhitespacePosition: false,
        beforeSubNodeIndex: -1,
        element: null,
        remainingPathForElement: ''
    };
}

/**
 * analyze where path is pointing to in context of an element
 * @param path
 * @param element
 */
export function getPathTargetInElement(path: JsonPath, element: Element): PathTargetInElement {
    const result: PathTargetInElement = getEmptyPathTargetInElement();
    const segments = getPathSegments(path);
    if (segments.length && segments[0] === 'name') {
        result.isName = true;
    } else if (segments.length > 1 && segments[0] === 'attributes') {
        result.isAttributeName = segments[2] === 'name';
        result.isAttributeValue = segments[2] === 'value';
        result.attribute = element ? element.attributes[segments[1]] : null;
    } else if (segments.length > 1 && segments[0] === 'content') {
        result.isSubNode = true;
        if (typeof segments[1] === 'number') {
            result.nodeIndex = segments[1];
            if (element && element.content.length > result.nodeIndex && element.content[result.nodeIndex]) {
                const node: Node = element.content[result.nodeIndex];
                if (node.type === ELEMENT_TYPE) {
                    result.isElementSubNode = true;
                    result.element = node as Element;
                    result.remainingPathForElement = buildPathFromSegments(segments.slice(2));
                    if (segments.length > 2 && segments[2] === 'name') {
                        result.isElementSubNodeName = true;
                    }
                } else if (node.type === TEXT_TYPE) {
                    result.isTextSubNode = true;
                    result.textNode = node as TextNode;
                }
            }
        }
    } else if (segments.length === 1 && typeof segments[0] === 'string' && segments[0].startsWith('$')) {
        result.isWhitespacePosition = true;
        result.beforeSubNodeIndex = parseInt(segments[0].substr(1), 10);
    }
    return result;
}

/**
 * get position of node with index nodeIndex (ignoring text nodes and 'Annotation' elements)
 * @param nodeIndex
 * @param element
 */
export function getChildElementPosition(nodeIndex: number, element: Element, considerTextNode = false): number {
    let elementPosition = -1;
    for (let index = 0; index <= nodeIndex; index++) {
        const node = element.content[index];
        if (node) {
            if (node.type === ELEMENT_TYPE) {
                const element = node;
                if (element.name !== Edm.Annotation) {
                    elementPosition++;
                }
            } else if (considerTextNode && node.type === TEXT_TYPE && index === nodeIndex) {
                elementPosition++;
            }
        }
    }
    return elementPosition;
}

/**
 * get child element with given index (ignoring text nodes and 'Annotation' elements)
 * @param elementIndex
 * @param element
 */
export function getChildElementForPosition(elementIndex: number, element: Element): Element {
    let currentElementIndex = -1;
    let resultElement: Element = null;
    element.content.forEach((node) => {
        if (!resultElement && node.type === ELEMENT_TYPE) {
            const childElement = node;
            if (childElement.name !== Edm.Annotation) {
                currentElementIndex++;
                if (currentElementIndex === elementIndex) {
                    resultElement = childElement;
                }
            }
        }
    });
    return resultElement;
}

/**
 * create element (with single text node) from attribute
 * @param attribute
 */
export function createElementFromAttribute(attribute: Attribute): Element {
    const textNode: TextNode = { type: TEXT_TYPE, text: attribute.value, range: attribute.valueRange };
    return {
        type: ELEMENT_TYPE,
        name: attribute.name,
        nameRange: attribute.nameRange,
        attributes: {},
        content: [textNode],
        contentRange: attribute.valueRange
    };
}

