export interface CursorContext {
    fileUri?: FileUri; // file Uri of current file, needed for completion with splitSupport
    targetPath: PathValue;
    newTarget: boolean; // completion requested in targets region (in between of existing)
    embeddedIn: string; // for embedded annotation: embedding element name, else empty
    embeddedType: string; // embedded element type. else empty
    embeddedApplicableTerms?: string[]; // constraint restricting ambedded annotation terms
    annotation: Element; // element representing the annotation tag
    path: JsonPath; // path within annotation pointing to position where completion is requested
    elementContext: {
        parentElement: Element; // parent element relative to completion position (current element for attributes, parent for element names and text nodes)
        path?: JsonPath; // path within parent element
        attributeArea: boolean; // true for positions in attributes area
    };
    applyContext?: {
        apply: Element; // nearest to the current position parent Apply element
        path?: JsonPath; // path within Apply element
    };
}

