/**
 * Get fully qualified name for attribute term or type
 * @param element - Element
 * @param aliasMap - Alias Map
 * @param attributeName - string 'Term' or 'Type'
 */
export function getFullyQualifiedNameByAttribute(
    element: Element,
    aliasMap: AliasMap,
    attributeName: string
): FullyQualifiedName {
    let fullyQualifiedName = '';

    if (element && element.attributes && element.attributes[attributeName] && element.attributes[attributeName].value) {
        const value = element.attributes[attributeName].value;
        const lastSegment = value.split('.').pop() || '';
        const namespace = resolveName(value, aliasMap).namespace;
        fullyQualifiedName = `${namespace}.${lastSegment}`;
    }

    return fullyQualifiedName;
}

export function getValueTypeFromTerm(context: Context, term: Term, resolveTypeDef?: boolean): ValueType {
    if (!term) {
        // default type
        return {
            name: 'Edm.String',
            asCollection: false
        };
    }
    // combine facets/constraints from type (only TypeDefinition can provide additional facets/constaints)
    const { facets, constraints } = getFacetsAndConstraints(context, term);
    const valueType: ValueType = { name: term.type, asCollection: !!term.isCollection };
    if (resolveTypeDef && !term.type.startsWith('Edm.')) {
        // resolve TypeDefinition to Edm primitive type
        const vocabularyType = context.vocabularies.getType(term.type);
        const buildInType = getBuiltInTypeViaUnderlyingType(context, vocabularyType, true);
        if (buildInType && buildInType !== term.type) {
            valueType.name = buildInType;
        }
    }
    if (Object.keys(facets).length) {
        valueType.facets = facets;
    }

    if (Object.keys(constraints).length) {
        valueType.constraints = constraints;
    }

    return valueType;
}

export function isSideEffectsRecord(resolvedRecordType: FullyQualifiedName): boolean {
    return resolvedRecordType.startsWith('com.sap.vocabularies.Common.v1.SideEffectsType');
}

export function isConnectedFieldsRecord(resolvedRecordType: FullyQualifiedName): boolean {
    return resolvedRecordType.startsWith('com.sap.vocabularies.UI.v1.ConnectedFieldsType');
}

export function isTemplateProperty(resolvedRecordType: string, propertyName: string): boolean {
    return isConnectedFieldsRecord(resolvedRecordType) && propertyName === PropertyNamesSpecial.Template;
}

export function isDataFieldValueProperty(resolvedRecordType: string, propertyName: string): boolean {
    return resolvedRecordType.startsWith('com.sap.vocabularies.UI.v1.DataField') && propertyName === 'Value';
}
