import type {
    ICdsCompiler,
    XsnArtifact,
    XsnCompileModel,
    XsnElement,
    XsnFinalEffectiveType,
    XsnNamedObject
} from '@sap/cds-compiler';
import { getNameObj } from '../utils';

function isToMany(finalType: XsnFinalEffectiveType): boolean {
    let isToMany = false;
    let artifact: XsnArtifact;
    // cds-compiler v2*
    artifact = finalType as any as XsnArtifact;
    if (!artifact.cardinality) {
        if ((artifact._origin as XsnArtifact)?.cardinality) {
            artifact = artifact._origin as XsnArtifact;
        } else if ((artifact.type?._artifact as XsnArtifact)?.cardinality) {
            artifact = artifact?.type?._artifact as XsnArtifact;
        }
    }

    if (artifact?.cardinality?.targetMax) {
        const targetMax = artifact.cardinality.targetMax;
        isToMany = targetMax.literal === 'string' && targetMax.val === '*';
    }
    return isToMany;
}

export function getAssociation(
    element: XsnElement | undefined,
    compiler?: ICdsCompiler
): { target: string; isToMany: boolean; isComposition: boolean } {
    let result;
    function isComposition(element: XsnElement, compiler?: ICdsCompiler): boolean {
        if (element?.type?._artifact) {
            const namedObj = getNameObj(element.type?._artifact, compiler);
            return namedObj.absolute === 'cds.Composition';
        } else {
            return false;
        }
    }
    if (element) {
        const finalEffectiveType = element?._effectiveType;
        let targetNamed: XsnNamedObject;
        if (finalEffectiveType?.kind === 'element') {
            targetNamed = finalEffectiveType?.target?._artifact as XsnNamedObject;
            if (targetNamed?.name && ['entity', 'view'].includes(targetNamed?.kind)) {
                result = {
                    target: getNameObj(targetNamed, compiler).absolute,
                    isToMany: isToMany(finalEffectiveType),
                    isComposition: isComposition(element, compiler)
                };
            }
        }
    }
    return result;
}

export const getServiceNameForEntity = (entity: XsnNamedObject, compileModel?: XsnCompileModel): string => {
    let serviceFound = false;
    const segments = getNameObj(entity, compileModel?.compiler).absolute.split('.');
    segments.pop();
    let serviceName = '';
    for (let i = 0; i < segments.length && !serviceFound; i++) {
        serviceName += serviceName ? '.' + segments[i] : segments[i];
        serviceFound = compileModel?.definitions[serviceName].kind === 'service';
    }
    return serviceFound ? serviceName : '';
};
