import type { CompletionItem } from 'vscode-languageserver';
import type { CompletionItemAdapterParams, CompletionItemAdapterWithGate } from '../types';

function gate({ lastItem }: CompletionItemAdapterParams): boolean {
    return !!lastItem;
}

function adapter({ originalItem, lastItem }: CompletionItemAdapterParams): CompletionItem | undefined {
    return {
        ...lastItem,
        deprecated: originalItem.deprecated,
        documentation: originalItem.documentation
    };
}

/**
 * Preserves fields from original item that are always needed.
 */
export const defaultFieldAdapter: CompletionItemAdapterWithGate = {
    gate,
    adapter
};
