/**
 * Build up map for case checks of labeled elements
 * @param labeledElementsCache
 */
export function getLabeledElementsCaseCheckMap(
    labeledElementsCache: LabeledElementsCache
): Map<string, Map<string, string>> {
    const caseCheckMap: Map<string, Map<string, string>> = new Map();
    Object.keys(labeledElementsCache).forEach((fileUris) => {
        const labeledElements = labeledElementsCache[fileUris];
        Object.keys(labeledElements || {}).forEach((namespace) => {
            caseCheckMap.set(namespace.toUpperCase(), labeledElements[namespace].upperCaseMap);
        });
    });
    return caseCheckMap;
}

export function convertValueTypeToString(valueType: ValueType): FullyQualifiedTypeName {
    return valueType && valueType.asCollection ? 'Collection(' + valueType.name + ')' : valueType.name || '';
}

export function convertValueTypeFromString(type: FullyQualifiedTypeName): ValueType {
    type = type || '';
    const valueType: ValueType = { name: type.trim() };
    valueType.asCollection = type.startsWith('Collection(');
    if (valueType.asCollection) {
        valueType.name = valueType.name.slice(11, -1);
    }
    return valueType;
}

export function getValueTypeForMetadataElement(element: MetadataElement): ValueType {
    let name: FullyQualifiedName = '';
    if (element.edmPrimitiveType) {
        name = element.edmPrimitiveType;
    } else if (element.isEntityType) {
        name = EdmType.EntityType;
    } else if (element.isComplexType) {
        name = EdmType.ComplexType;
    }
    if (name) {
        return { name, asCollection: element.isCollectionValued };
    } else {
        return { name: '' };
    }
}

/**
 * Get metadata element for a (metadata only) path
 *
 * @param path - must not contain alias names, can contain any number of navigation property segments
 * @param metadata
 */
export function getMdElementForMdPath(path: string, metadata: MetadataService): MetadataElement | undefined {
    const segments = path.split('/').filter((segment) => !!segment);
    if (segments.length < 3) {
        // up to two segments: no resolution of complex types needed (e.g. navigation segments)
        return metadata.getMetadataElement(segments.join('/'));
    }
    const remainingSegments = [...segments];
    const baseSegments = remainingSegments.splice(0, 2);
    let metadataElement = metadata.getMetadataElement(baseSegments.join('/'));
    for (const segment of remainingSegments) {
        const path = metadataElement?.structuredType ? `${metadataElement.structuredType}/${segment}` : '';
        metadataElement = path ? metadata.getMetadataElement(path) : undefined;
        if (!metadataElement) {
            break;
        }
    }
    return metadataElement;
}
/**
 * Checks if paths are matching
 *
 * @param context
 * @param targetPath
 * @param trialPath - path (metadata only, e.g. target path of an annotation, will be reduced to base path)
 * @param trialRelativePath - relative path (metadata only, e.g. metadata part of a path expression in annotation value)
 */
export function isMatchingPath(
    context: Context,
    targetPaths: string[],
    trialPath: string,
    trialRelativePath?: string
): boolean {
    // find base path
    const trialPathMdElement = getMdElementForMdPath(trialPath, context.metadata);
    if (!trialPathMdElement) {
        return false;
    }
    const trialPathBaseMdElement = getPathBaseMetadataElement(context.metadata, trialPathMdElement.path);
    if (!trialPathBaseMdElement) {
        return false;
    }
    // no relative path? try base path
    if (!trialRelativePath) {
        return (
            targetPaths.includes(trialPathBaseMdElement.path) ||
            targetPaths.includes(trialPathBaseMdElement.structuredType)
        );
    }
    // build fully path by adding relative path
    const targetIsNavProperty = !trialRelativePath.endsWith('/'); // e.g. if original path was 'toSupplier@UI.Hidden'
    const trialPathFull = trialPathBaseMdElement.path + '/' + trialRelativePath;
    const trialPathFullMdElement = getMdElementForMdPath(trialPathFull, context.metadata);
    if (!trialPathFullMdElement) {
        return false;
    }
    // try full path
    if (targetIsNavProperty) {
        return targetPaths.includes(trialPathFullMdElement.path);
    } else {
        return (
            targetPaths.includes(trialPathFullMdElement.path) ||
            targetPaths.includes(trialPathFullMdElement.structuredType)
        );
    }
}

export function isEmptyText(text: string): boolean {
    return (text || '').replace(/[\n\t\s]/g, '').length === 0;
}

export function isValidSimpleIdentifier(name: string): boolean {
    return !!name && /^[A-Za-z_]\w{0,127}$/.test(name) === true;
}
/**
 * Get Hint for Case Issues
 * @param context
 * @param caseCheck
 */
export function getHintForCaseIssues(context: Context, caseCheck: CaseCheck, messageData?: any): string {
    let hint = '';
    // we can provide nested maps for looking up correct case names based on all upper case names
    let lookupResult: string | Map<string, string | Map<string, string | Map<string, string>>> = null;
    if (caseCheck && caseCheck.lookupPath?.length) {
        switch (caseCheck.lookupPath[0]) {
            case 'vocabularies':
                lookupResult = context.vocabularies['upperCaseNameMap'];
                break;
            case 'functions':
                lookupResult = new Map();
                [...functionSignatures.keys()].forEach((key) => {
                    (lookupResult as Map<string, string>).set(key.toUpperCase(), key);
                });
                break;
            case 'labeledElements':
                lookupResult = getLabeledElementsCaseCheckMap(context.labeledElements);
                break;
        }
    }
    if (lookupResult) {
        const lookupPath = [...caseCheck.lookupPath.slice(1), caseCheck.value];
        if (caseCheck.isNamespacedValue) {
            // merge last two entries
            const name = lookupPath.pop();
            const fqName = lookupPath.pop() + '.' + name;
            lookupPath.push(fqName);
        }
        lookupPath.forEach((entry) => {
            if (entry.toUpperCase() === '$TYPE') {
                lookupResult = '$Type';
                return;
            }
            const entryUpperCase = entry.toUpperCase();
            lookupResult = lookupResult && typeof lookupResult !== 'string' ? lookupResult.get(entryUpperCase) : null;
        });
        if (caseCheck.isNamespacedValue && typeof lookupResult === 'string') {
            lookupResult = lookupResult.split('.').pop(); // extract name back from fully qualified name
        }
        if (caseCheck.isNamespacedValue && typeof lookupResult === 'object') {
            lookupResult = lookupResult.get('$Self') as string;
            lookupResult = lookupResult.split('.').pop(); // extract name back from fully qualified name
        }
    }
    if (
        lookupResult &&
        typeof lookupResult === 'string' &&
        caseCheck.value.toUpperCase() === lookupResult.toUpperCase()
    ) {
        caseCheck.proposedValue = caseCheck.isNamespacedValue
            ? `${messageData.alias ?? messageData.namespace}.${lookupResult}`
            : lookupResult;
        hint = i18n.t('Did_you_mean_0', {
            proposedValue: caseCheck.proposedValue
        });
    }
    return hint;
}

/**
 * Returns map of available EntitySet names and their properties
 * @param metadataService - metadata service object
 * @param entitySetToOmit - if provided this EntitySet will be omitted in result map
 * @returns map where keys are Entity Set names and values are maps of properties and their types
 *  represented as corresponding constant expression names
 */
export function getAvailableEntitySetProperties(
    metadataService: MetadataService,
    entitySetToOmit?: SimpleName
): { entitySetPropertyMap: Map<SimpleName, Map<SimpleName, string>>; serviceNameSpaceMap: Map<string, string> } {
    const entitySetPropertyMap: Map<SimpleName, Map<SimpleName, string>> = new Map();
    const serviceNameSpaceMap: Map<string, string> = new Map();
    let entityContainerName = '';
    [...metadataService.getRootMetadataElements().keys()]
        .filter((key) => metadataService.getEdmTargetKinds(key).includes(Edm.EntityContainer))
        .forEach((key) => {
            serviceNameSpaceMap.set(resolveName(key).namespace, key);
            entityContainerName = key;
        });
    if (serviceNameSpaceMap.size === 1 && entityContainerName && !metadataService.isCds) {
        // for EDMX: let all namespaces point to single EntityContainer (to support multiple schemas)
        for (const namespace of metadataService.getNamespaces()) {
            serviceNameSpaceMap.set(namespace, entityContainerName);
        }
    }
    for (const entityContainerName of serviceNameSpaceMap.values()) {
        const entityContainerMdElement = metadataService.getMetadataElement(entityContainerName);
        (entityContainerMdElement?.content ?? [])
            .filter(
                (metadataElement) =>
                    (entitySetToOmit ? metadataElement.name !== entitySetToOmit : true) &&
                    metadataService
                        .getEdmTargetKinds(entityContainerMdElement.path + '/' + metadataElement.name)
                        .includes(Edm.EntitySet) &&
                    !metadataElement.name.endsWith('_texts')
            )
            .forEach((metadataElement) => {
                const entitySet = metadataService.getMetadataElement(
                    entityContainerMdElement.name + '/' + metadataElement.name
                );
                if (entitySet?.structuredType) {
                    const propertySet: Map<SimpleName, string> = new Map();
                    const entityType = metadataService.getMetadataElement(entitySet?.structuredType);
                    for (const propMdElement of entityType.content) {
                        const primitiveType = primitiveTypeMap[propMdElement.edmPrimitiveType];
                        const managedProperty =
                            managedProperties.includes(propMdElement.name) &&
                            propMdElement?.location?.uri === commonNodeModulePath; // TODO: fix the comparison
                        if (!managedProperty && primitiveType?.constantExpressionName) {
                            propertySet.set(propMdElement.name, primitiveType.constantExpressionName);
                        }
                    }
                    entitySetPropertyMap.set(entitySet.path, propertySet); // also empty property set is allowed! (properties are not collected if not used yet)
                }
            });
    }
    return { entitySetPropertyMap, serviceNameSpaceMap };
}

/**
 * Searches for Entity Container by given Entity Set name
 * @param metadataService
 * @param entitySetName
 * @param targetPath : target of annotation containing entitySet as string value (used for fallback logic if no entity container is present)
 * @returns metadata element object of found container
 */
export function getMdElementPathForEntitySet(
    metadataService: MetadataService,
    entitySetName: string,
    targetPath: string
): string {
    // try to find entity container containing entitySet
    const [, entityContainerMdElement] = [...metadataService.getRootMetadataElements().entries()].find(
        ([key, mdElement]) => {
            const isContainer = metadataService.getEdmTargetKinds(key).includes(Edm.EntityContainer);
            const entitySet = (mdElement?.content ?? []).find((element) => element.name === entitySetName);
            return isContainer && (entitySet?.kind === 'entitySet' || entitySet?.kind === Edm.EntitySet);
        }
    ) ?? [undefined, undefined];
    if (entityContainerMdElement) {
        return `${entityContainerMdElement.path}/${entitySetName}`;
    }
    // @Common.ValueList might be applied on db layer - try entityType build from namespace of target combined with entitySetName
    const targetNamespace = resolveName(targetPath.split('/')[0])?.namespace;
    if (metadataService.getMetadataElement(`${targetNamespace}.${entitySetName}`)) {
        return `${targetNamespace}.${entitySetName}`;
    }
    // find any entity with simple name matching collectionPath
    return (
        [...metadataService.getRootMetadataElements().keys()].find(
            (key) => key === entitySetName || key.endsWith(`.${entitySetName}`)
        ) || ''
    );
}

/**
 * Check if element has single child element containing value, which is not a Record
 * (relevant for starting/ending $value notation in CDS)
 * @param element - element to be checked
 * @returns
 */
export const hasValueAsSingleNonRecordChildElement = (
    element: Element
): { result: boolean; embeddedAnnotationsCount?: number; singleValueElement?: Element } => {
    let singleValueElement: Element;
    let embeddedAnnotationsCount = 0;
    const childElements = (element?.content || []).filter((entry) => entry.type === ELEMENT_TYPE) as Element[];
    for (const childElement of childElements) {
        if (childElement.name === Edm.Annotation) {
            embeddedAnnotationsCount++;
        } else if (childElement.name !== Edm.Record && childElement.name !== Edm.PropertyValue && !singleValueElement) {
            singleValueElement = childElement;
        } else {
            // has more than a single value element
            return { result: false };
        }
    }
    if (singleValueElement) {
        return { result: true, embeddedAnnotationsCount, singleValueElement };
    } else {
        return { result: false };
    }
};

/**
 * Expands the provided list of value types with compatible types, based on the matching constant expression name
 * @param types - array with value types
 * @returns - array containing input value types and types which are compatible with them
 */
export function expandWithCompatibleTypes(context: Context, types: ValueType[]): ValueType[] {
    const result: ValueType[] = [...types];
    types.forEach((type) => {
        const { compatibleTypes } = getCompatibleTypesData(context, type);
        if (compatibleTypes.length) {
            const missingCompatibleTypeNames = compatibleTypes.filter(
                (ct) => !result.find((t) => t.name === ct.name && !!t.asCollection === !!ct.asCollection)
            );
            result.push(...missingCompatibleTypeNames);
        }
    });

    return result;
}

export function getCompatibleTypesData(
    context: Context,
    type: ValueType
): {
    compatibleTypes: ValueType[];
    primitiveType: PrimitiveType | undefined;
} {
    const primitiveType = primitiveTypeMap[type.name];
    let compatibleTypeNames = context.compatiblePrimitiveTypesMap?.[type.name];
    if (!compatibleTypeNames) {
        const constantExpressionName = primitiveTypeMap[type.name]?.constantExpressionName;
        compatibleTypeNames = Object.keys(primitiveTypeMap).filter(
            (key) => key !== type.name && primitiveTypeMap[key].constantExpressionName === constantExpressionName
        );
    }
    const compatibleTypes = compatibleTypeNames.map((name) => ({ ...type, name }));
    if (!context.compatiblePrimitiveTypesMap) {
        context.compatiblePrimitiveTypesMap = {};
    }
    context.compatiblePrimitiveTypesMap[type.name] = compatibleTypeNames;
    return { compatibleTypes, primitiveType };
}

/**
 * Adjusts given type's applicableTerms constraint based on new context constraints.
 *
 * @param type value type
 * @param contextConstraints current context type constraints
 */
export function adjustApplicableTermsConstraint(
    type: ValueType | null | undefined,
    contextConstraints?: Constraints
): void {
    if (!type) {
        return;
    }
    const applicableTerms = contextConstraints?.applicableTerms;
    if (applicableTerms) {
        type.constraints = type.constraints ?? {};
        type.constraints.applicableTerms = applicableTerms;
    } else if (type.constraints?.applicableTerms) {
        delete type.constraints.applicableTerms;
    }
}
