import { pathToFileURL } from 'url';
import { DiagnosticSeverity } from 'vscode-languageserver-types';
import type { XsnCompileModel } from '@sap/cds-compiler';

export const severityMap = {
    Debug: DiagnosticSeverity.Hint,
    Error: DiagnosticSeverity.Error,
    Warning: DiagnosticSeverity.Warning,
    Info: DiagnosticSeverity.Information
};
export function getFileUriMap(ast: XsnCompileModel): Map<string, string> {
    const fileUriMap: Map<string, string> = new Map();
    if (!ast?.sources) {
        return fileUriMap;
    }
    Object.keys(ast.sources).forEach((sourceUri) => {
        const relativeUri = ast.sources[sourceUri].location?.file;
        const absoluteUri = pathToFileURL(sourceUri).toString();
        if (relativeUri) {
            fileUriMap.set(relativeUri, absoluteUri.toString());
        }
    });
    return fileUriMap;
}
