import type { ComplexType } from '@sap-ux/odata-vocabularies';
import type { CompletionItem } from '../types/general';
import { CompletionItemCategory } from '../types/general';
import { dynamicExpressionSignatureMap, EdmType } from '../specification';
import type { Element } from '@sap-ux/odata-annotation-core';
import { Edm } from '@sap-ux/odata-annotation-core';
import { recordSnippets, createCollectionSnippet } from './collection';
import { snippetsForElementsProvidingValue } from './simpleValues';
import type { SnippetHandlingContext } from '.';
import { Snippet } from '..';
import type { JsonPath } from '../utils/path';
import { getChildElementForPosition, getChildElementPosition, getPathTargetInElement } from '../utils/path';
import {
    addDynamicExpressionsForAnyType,
    convertDynamicExpressionTypeToValueType,
    getComparableTypes,
    getTypesForElement,
    adjustComparableTypes
} from '../value-handling';
import { convertValueTypeFromString } from '../utils/general';
import type { ValueHandlingContext, ValueType } from '../types/context';
import { getApplyFunctionSnippets } from './applyFunction';

export function snippetsForDynamicExpressionParameters(
    snippetContext: SnippetHandlingContext,
    element: Element,
    path: JsonPath,
    complexType?: ComplexType
): CompletionItem[] {
    const result: CompletionItem[] = [];
    const target = getPathTargetInElement(path, element);
    const parameterIndex = getChildElementPosition(target.nodeIndex, element, true);
    const signature = dynamicExpressionSignatureMap.get(element.name as Edm);
    const parameter = signature && signature.parameters[parameterIndex];
    const newValueHandlingContext: ValueHandlingContext = {
        ...snippetContext.valueHandlingContext,
        nodeContext: {
            comparisonOperator: signature.metadata?.comparisonOperator,
            strictEqualityComparison: signature.metadata?.strictEqualityComparison
        }
    };
    if (parameter) {
        const parameterType = parameter.type;
        const valueType = convertDynamicExpressionTypeToValueType(parameterType);
        if (valueType.name === EdmType.Untyped) {
            valueType.name = EdmType.PrimitiveType;
        }
        if (typeof parameterType === 'object' && parameterType.constraints?.compatibleWithRequestedType) {
            // snippets for requested type
            result.push(...getSnippetsForRequestedType(snippetContext, complexType));
        } else if (
            typeof parameterType === 'object' &&
            parameterType.constraints?.comparableTypeParameterIndex !== undefined
        ) {
            // snippets for type that is comparable to other parameter type
            const elementToCompare = getChildElementForPosition(
                parameterType.constraints?.comparableTypeParameterIndex,
                element
            );
            result.push(
                ...getSnippetsForComparableType(snippetContext, newValueHandlingContext, valueType, elementToCompare)
            );
        } else {
            // snippets for parameter type
            if (valueType.asCollection) {
                return getSnippetsForCollectionContext({
                    ...snippetContext,
                    type: { ...valueType, asCollection: false },
                    valueHandlingContext: newValueHandlingContext
                });
            } else {
                const possibleTypes = adjustComparableTypes(newValueHandlingContext, [valueType]);
                appendSnippetsByTypes(possibleTypes, snippetContext, newValueHandlingContext, result);
            }
        }
    }
    return result;
}

/**
 * Snippets of dynamic expressions for any value
 * @param context - snippet handling context object
 */
export function snippetsForDynamicExpressionsForAnyType(context: SnippetHandlingContext): CompletionItem[] {
    const propNames: { [key: string]: CompletionItemCategory } = {};
    addDynamicExpressionsForAnyType(propNames);
    const compItems = Object.keys(propNames)
        .filter((entry) => ![Edm.Apply, Edm.LabeledElement].includes(entry as Edm))
        .map((entry) => {
            return new Snippet(entry as Edm, context.useSnippets)
                .addMandatoryAttributesWithTabStops()
                .appendFinalTabStopToContent()
                .toCompletionItem(null, null, propNames[entry]);
        });
    if (propNames[Edm.Apply]) {
        compItems.push(...getApplyFunctionSnippets(context));
    }
    return compItems;
}

function getSnippetsForCollectionContext(snippetContext: SnippetHandlingContext): CompletionItem[] {
    return [
        createCollectionSnippet(snippetContext, null, 1, true).toCompletionItem(),
        new Snippet(Edm.Path, snippetContext.useSnippets)
            .appendFinalTabStopToContent()
            .toCompletionItem(null, null, CompletionItemCategory.Path),
        ...snippetsForDynamicExpressionsForAnyType(snippetContext)
    ];
}

function getSnippetsForRequestedType(
    snippetContext: SnippetHandlingContext,
    complexType?: ComplexType
): CompletionItem[] {
    if (snippetContext.type.asCollection) {
        return getSnippetsForCollectionContext({
            ...snippetContext,
            type: { ...snippetContext.type, asCollection: false }
        });
    } else if (complexType) {
        return [
            ...recordSnippets(snippetContext, complexType),
            ...recordSnippets(snippetContext, complexType, true),
            ...snippetsForElementsProvidingValue(snippetContext)
        ];
    } else {
        return snippetsForElementsProvidingValue(snippetContext);
    }
}

function getSnippetsForComparableType(
    snippetContext: SnippetHandlingContext,
    newValueHandlingContext: ValueHandlingContext,
    valueType: ValueType,
    elementToCompare: Element
): CompletionItem[] {
    const possibleTypesStr = getComparableTypes(
        getTypesForElement(
            snippetContext.valueHandlingContext,
            elementToCompare,
            snippetContext.valueHandlingContext.pathBase
        )
    );
    if (valueType.asCollection) {
        newValueHandlingContext.nodeContext.restrictedTypes = possibleTypesStr as EdmType[];
        return getSnippetsForCollectionContext({
            ...snippetContext,
            type: { ...valueType, asCollection: false },
            valueHandlingContext: newValueHandlingContext
        });
    } else {
        const result: CompletionItem[] = [];
        const possibleTypes: ValueType[] = adjustComparableTypes(
            newValueHandlingContext,
            possibleTypesStr.map((t) => convertValueTypeFromString(t))
        );
        // TODO: translate each possible type to list of comparable types
        appendSnippetsByTypes(possibleTypes, snippetContext, newValueHandlingContext, result);
        return result;
    }
}

function appendSnippetsByTypes(
    possibleTypes: ValueType[],
    snippetContext: SnippetHandlingContext,
    valueHandlingContext: ValueHandlingContext,
    result: CompletionItem[]
) {
    (possibleTypes || []).forEach((type) => {
        const typeSnippets = snippetsForElementsProvidingValue({
            ...snippetContext,
            type,
            valueHandlingContext
        });
        typeSnippets.forEach((typeSnippet) => {
            if (result.findIndex((entry: CompletionItem) => entry.name === typeSnippet.name) < 0) {
                result.push(typeSnippet);
            }
        });
    });
}
