import type { Alias, Element, NamespaceString, Target } from '@sap-ux/odata-annotation-core';
import { ELEMENT_TYPE, TEXT_TYPE, resolveName } from '@sap-ux/odata-annotation-core';
import { pathExpressionMap } from '../specification';
import type { AliasInformation, AliasMap } from '../types/context';

const addUsedNamespaceForElement = (
    aliasMapVocabulary: AliasMap,
    usedNamespaces: Set<NamespaceString>,
    elements: Element[]
): void => {
    function addNamespacesFromPath(value: string) {
        const segments = (value || '').split('/');
        segments
            .filter((segment) => segment.indexOf('@') >= 0)
            .forEach((segment) => {
                const indexAt = segment.indexOf('@');
                const resolvedName = resolveName(segment.substr(indexAt + 1), aliasMapVocabulary);
                if (resolvedName.namespace) {
                    usedNamespaces.add(resolvedName.namespace);
                }
            });
    }
    for (let i = 0; elements.length > i; i++) {
        const element = elements[i];
        const attributes = element.attributes;
        if (attributes) {
            Object.keys(attributes).forEach((attr) => {
                const value = attributes[attr].value;
                if (pathExpressionMap[attr]) {
                    addNamespacesFromPath(value);
                } else {
                    const resolvedName = resolveName(value, aliasMapVocabulary);
                    if (resolvedName.namespace) {
                        usedNamespaces.add(resolvedName.namespace);
                    }
                }
            });
        }
        const subElements: Element[] = [];
        (element.content || []).forEach((entry) => {
            if (entry.type === ELEMENT_TYPE) {
                subElements.push(entry);
            } else if (entry.type === TEXT_TYPE) {
                if (pathExpressionMap[element.name]) {
                    addNamespacesFromPath(entry.text);
                } else {
                    const resolvedName = resolveName(entry.text, aliasMapVocabulary);
                    if (resolvedName.namespace) {
                        usedNamespaces.add(resolvedName.namespace);
                    }
                }
            }
        });
        if (subElements.length) {
            addUsedNamespaceForElement(aliasMapVocabulary, usedNamespaces, subElements);
        }
    }
};

export const getUsedNamespaces = (aliasInfo: AliasInformation, targets: Target[]): Set<NamespaceString> => {
    const usedNamespaces = new Set<NamespaceString>();
    // add current file annotation namespace to used namespace
    usedNamespaces.add(aliasInfo.currentFileNamespace);

    const aliasMap = aliasInfo.aliasMapVocabulary;
    targets.forEach((target) => {
        const name = target.name;
        const resolvedName = resolveName(name, aliasMap);
        if (resolvedName.namespace) {
            usedNamespaces.add(resolvedName.namespace);
        }
        addUsedNamespaceForElement(aliasMap, usedNamespaces, target.terms);
    });
    return usedNamespaces;
};

export const getUnusedNamespaces = (
    aliasInfo: AliasInformation,
    usedNamespaces: Set<NamespaceString>
): Map<NamespaceString, Alias | NamespaceString> => {
    const unusedNamespaces = new Map<NamespaceString, Alias>();
    Object.keys(aliasInfo.aliasMapVocabulary).forEach((NSAlias) => {
        // only unused namespace and no aliase
        if (!usedNamespaces.has(NSAlias) && aliasInfo.reverseAliasMap[NSAlias]) {
            unusedNamespaces.set(NSAlias, aliasInfo.reverseAliasMap[NSAlias]);
        }
    });

    return unusedNamespaces;
};
