import type { Context } from '../types/context';
import { convertValueTypeFromString, convertValueTypeToString, getValueTypeForMetadataElement } from '../utils/general';
import { EdmType } from '../specification';
import { getVocabularyType, lookupMetadataService } from '../vocabulary/access';
import { Edm as EdmVocabulary } from '../types/edm';
import type { MetadataElement } from '@sap-ux/odata-annotation-core-types';
import type { FileUri, FullyQualifiedName, FullyQualifiedTypeName, PathValue } from '@sap-ux/odata-annotation-core';
import { resolveName } from '@sap-ux/odata-annotation-core';

export function addPathToObject(object: any, path: PathValue, value?: any): void {
    if (typeof object === 'object') {
        const segments = path.split('/');
        const lastIndex = segments.length - 1;
        let currentObject = object;
        segments.forEach((segment, index) => {
            if (segment) {
                if (currentObject[segment]) {
                    if (index === lastIndex) {
                        if (typeof currentObject[segment] === 'object') {
                            // object exists already for deeper path: set $Self property for path ending here
                            currentObject[segment]['$Self'] = value || true;
                        } else {
                            // primitive target existed already - try to preserve it as $Self
                            let selfValue = currentObject[segment];
                            if (typeof value === 'object') {
                                if (
                                    typeof selfValue === 'boolean' ||
                                    (value.$Self && typeof value.$Self !== 'boolean')
                                ) {
                                    selfValue = value.$Self || true; // use non boolean (string) value if present
                                }
                                currentObject[segment] = Object.assign({}, value, { $Self: selfValue });
                            } else if (typeof selfValue === 'boolean' || (value && typeof value !== 'boolean')) {
                                currentObject[segment] = value || true; // preserve non boolean (string) value
                            }
                        }
                    }
                } else {
                    currentObject[segment] = index === lastIndex ? value || true : {};
                }
                if (index < lastIndex && typeof currentObject[segment] !== 'object') {
                    // prepare for deeper nesting: save primitive value in $Self attribute
                    currentObject[segment] = { $Self: currentObject[segment] };
                }
                currentObject = currentObject[segment];
            }
        });
    }
}

/**
 * remove path from object tree (representing all available paths)
 * @param object
 * @param path
 */
export function removePathFromObject(object: any, path: PathValue): any {
    if (path && typeof object === 'object') {
        const segments = path.split('/');
        const siblingSegmentsCount: number[] = [];
        let currentValue = object;
        // get current value for path, remember number of sibling segments for each traversed segment
        segments.forEach((segment) => {
            if (segment && typeof currentValue === 'object' && currentValue !== null) {
                siblingSegmentsCount.push(Object.keys(currentValue).length);
                currentValue = currentValue[segment] || null;
            } else {
                currentValue = null;
            }
        });
        if (currentValue !== null) {
            // find last segment for which path cache contained an alternative
            let lastSegmentWithAlternatives = 0;
            siblingSegmentsCount.forEach((count, index) => {
                if (count > 1) {
                    lastSegmentWithAlternatives = index;
                }
            });
            // remove current path by removing segment from most specific host object which contained an alternative
            let hostObject = object;
            segments.slice(0, lastSegmentWithAlternatives).forEach((segment) => {
                if (typeof hostObject === 'object') {
                    if (hostObject[segment] && typeof hostObject[segment] === 'object') {
                        hostObject = hostObject[segment];
                    }
                }
            });
            delete hostObject[segments[lastSegmentWithAlternatives]];
        }
        return currentValue;
    }
}

export function removeActionFunctionSignatureFromPath(path: string): string {
    const partsOpen = path.split('(');
    const partsClose = path.split(')');
    return partsOpen.length > 1 && partsClose.length > 1 ? partsOpen.shift() + partsClose.pop() : path;
}

export function addPathToPathExpressions(
    context: Context,
    element: MetadataElement,
    fileUri: FileUri,
    path?: string
): void {
    const elementPath = path || element.path;

    if (element.isAnnotatable) {
        context.pathExpressions.targetPath[fileUri] = context.pathExpressions.targetPath[fileUri] || {};
        addPathToObject(context.pathExpressions.targetPath[fileUri], elementPath, elementPath);
    }

    const valueType = getValueTypeForMetadataElement(element);
    if (valueType.name) {
        const type = convertValueTypeToString(valueType);
        // add path entry for namespaces
        if (!context.completionOnly) {
            context.pathExpressions.path[fileUri] = context.pathExpressions.path[fileUri] || {};
        }
        context.pathExpressions.pathCc[fileUri] = context.pathExpressions.pathCc[fileUri] || {};
        context.pathExpressions.propertyPathCc[fileUri] = context.pathExpressions.propertyPathCc[fileUri] || {};
        // add path entry for type (omit metadata types - they cannot be requested as such in annotation values)
        const resolvedTypeName = resolveName(valueType.name);
        if (
            resolvedTypeName.namespace === 'Edm' ||
            context.vocabularies.getVocabularies().has(resolvedTypeName.namespace)
        ) {
            // not a type defined in service metadata --> add to cache
            if (!context.completionOnly) {
                context.pathExpressions.path[fileUri][type] = context.pathExpressions.path[fileUri][type] || {};
                addPathToObject(context.pathExpressions.path[fileUri][type], elementPath);
            }
            context.pathExpressions.pathCc[fileUri][type] = context.pathExpressions.pathCc[fileUri][type] || {};
            addPathToObject(context.pathExpressions.pathCc[fileUri][type], elementPath);
        }
        // additional entry for corresponding abstract type (Collection, EntityType, ComplexType, PrimitiveType)
        const abstractType = getAbstractTypeName(context, type);
        if (abstractType) {
            if (abstractType !== type) {
                if (!context.completionOnly) {
                    context.pathExpressions.path[fileUri][abstractType] =
                        context.pathExpressions.path[fileUri][abstractType] || {};
                    addPathToObject(context.pathExpressions.path[fileUri][abstractType], elementPath);
                }
                context.pathExpressions.pathCc[fileUri][abstractType] =
                    context.pathExpressions.pathCc[fileUri][abstractType] || {};
                addPathToObject(context.pathExpressions.pathCc[fileUri][abstractType], elementPath);
            }
            // fill cache for property path code completion (only abstract types required)
            context.pathExpressions.propertyPathCc[fileUri][abstractType] =
                context.pathExpressions.propertyPathCc[fileUri][abstractType] || {};
            addPathToObject(context.pathExpressions.propertyPathCc[fileUri][abstractType], elementPath);
        }
    }
}

export function getAbstractTypeName(context: Context, type: FullyQualifiedName): FullyQualifiedName {
    let abstractTypeName: FullyQualifiedName = '';
    const valueType = convertValueTypeFromString(type);
    if (valueType.asCollection) {
        abstractTypeName = getTypeOfCollection(context, valueType.name); // artificial type name for cache to be able to Edm.Untyped
    } else if (type === EdmType.EntityType || type === EdmType.ComplexType || type === EdmType.PrimitiveType) {
        abstractTypeName = type; // build in abstract types (except Edm.Untyped)
    } else if (type.startsWith('Edm.')) {
        abstractTypeName = EdmType.PrimitiveType; // all other build in types
    } else {
        const typeObject = getVocabularyType(context, type);
        if (typeObject && typeObject.kind) {
            switch (typeObject.kind) {
                case EdmVocabulary.COMPLEX_TYPE_KIND:
                    abstractTypeName = EdmType.ComplexType;
                    break;
                case EdmVocabulary.TYPE_DEFINITION_KIND:
                    abstractTypeName = EdmType.PrimitiveType;
                    break;
                case EdmVocabulary.ENUM_TYPE_KIND:
                    abstractTypeName = EdmType.PrimitiveType;
                    break;
            }
        } else {
            // types coming from service metadata
            const element = lookupMetadataService(context, type);
            if (element) {
                if (element.edmPrimitiveType) {
                    abstractTypeName = EdmType.PrimitiveType;
                } else {
                    abstractTypeName = getValueTypeForMetadataElement(element).name;
                }
            }
        }
    }
    return abstractTypeName;
}

//Collection(Edm.EntityType) and Collection(Edm.NonEntityType)
export function getTypeOfCollection(context: Context, type: FullyQualifiedName): FullyQualifiedTypeName {
    let collectionTypeName: FullyQualifiedName = '';
    if (type === EdmType.EntityType) {
        // Collection could be Entity Type if type starts Collection(Edm.EntityType)
        collectionTypeName = EdmType.EntityTypeCollection;
    } else if (type.startsWith('Edm.')) {
        // Any other type which is not edm.EntityType will be considered Collection(Edm.NonEntityType)
        collectionTypeName = EdmType.NonEntityTypeCollection;
    } else {
        const typeObject = getVocabularyType(context, type);
        if (typeObject) {
            // type coming from vocabulary (cannot be entity type)
            collectionTypeName = EdmType.NonEntityTypeCollection;
        } else {
            // types coming from service metadata
            const element = lookupMetadataService(context, type);
            if (element && element.isEntityType) {
                collectionTypeName = EdmType.EntityTypeCollection;
            } else {
                collectionTypeName = EdmType.NonEntityTypeCollection;
            }
        }
    }
    return collectionTypeName;
}

export function addNavPropPathToPathExpressions(
    context: Context,
    element: MetadataElement,
    fileUri: string,
    path?: string
): void {
    let typeGroup = '';
    if (element.isEntityType) {
        typeGroup = element.isCollectionValued ? EdmType.EntityTypeCollection : EdmType.EntityType;
    } else if (element.isComplexType) {
        typeGroup = element.isCollectionValued ? EdmType.NonEntityTypeCollection : EdmType.ComplexType;
    }
    if (typeGroup) {
        const elementPath = path || element.path;
        if (!context.completionOnly) {
            context.pathExpressions.path[fileUri] = context.pathExpressions.path[fileUri] || {};
            context.pathExpressions.path[fileUri][typeGroup] = context.pathExpressions.path[fileUri][typeGroup] || {};
            addPathToObject(context.pathExpressions.path[fileUri][typeGroup], elementPath, element.structuredType);
        }
        context.pathExpressions.pathCc[fileUri] = context.pathExpressions.pathCc[fileUri] || {};
        context.pathExpressions.pathCc[fileUri][typeGroup] = context.pathExpressions.pathCc[fileUri][typeGroup] || {};
        addPathToObject(context.pathExpressions.pathCc[fileUri][typeGroup], elementPath, element.structuredType);
    }
}

export function addNavPropToNavSourceMap(
    context: Context,
    element: MetadataElement,
    fileUri: string,
    path?: string
): void {
    const segments = (path || element.path).split('/');
    const navPropName = segments.pop();
    const sourcePath = segments.join('/');
    const targetName = element.structuredType;
    context.navigationSourceMap[fileUri] = context.navigationSourceMap[fileUri] || {};
    context.navigationSourceMap[fileUri][sourcePath] = context.navigationSourceMap[fileUri][sourcePath] || {};
    context.navigationSourceMap[fileUri][sourcePath][targetName] =
        context.navigationSourceMap[fileUri][sourcePath][targetName] || {};
    context.navigationSourceMap[fileUri][sourcePath][targetName][navPropName] = {
        isCollection: element.isCollectionValued
    };
}
