export enum HAlign {
    initial = 'Initial',
    left = 'Left',
    center = 'Center',
    right = 'Right',
    begin = 'Begin',
    end = 'End'
}

export enum TableMode {
    None = 'None',
    SingleSelect = 'SingleSelect',
    SingleSelectLeft = 'SingleSelectLeft',
    SingleSelectMaster = 'SingleSelectMaster',
    MultiSelect = 'MultiSelect',
    Delete = 'Delete'
}

export interface TableColumn {
    width?: string;
    hAlign?: HAlign;
}

export interface GenericColumns {
    [key: string]: TableColumn;
}

export interface Table<COLS = GenericColumns> {
    /**
     * The showTablePersonalisation attribute can be set to false for hiding the TablePersonalisation button.
     */
    showTablePersonalisation?: boolean;
    /**
     * Display the Export to Excel button in table toolbar
     */
    useExportToExcel?: boolean;
    mode?: TableMode;
    gridTable?: boolean;
    multiSelect?: boolean;
    fixedLayout?: boolean;
    enableAutoBinding?: boolean;
    condensedTableLayout?: boolean;
    /**
     * If you have enabled harmonized variant management, by default, you cannot set a filter in the table personalization settings.
     * To enable filtering, set the enableTableFilterInPageVariant property in the manifest.
     */
    enableTableFilterInPageVariant?: boolean;
    columns?: COLS;
}
