import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, TextEdit } from 'vscode-languageserver';

import { PATH_TYPE } from '@sap-ux/cds-annotation-parser';

import type {
    CompletionContext,
    CompletionHandlerArgs,
    CompletionItemAdapterParams,
    ModularCompletionHandler,
    NestedAnnotationTermNameContext,
    PropertyNameContext,
    ProviderResult
} from '../types';
import { recordTypePropertyNameAdapter } from '../adapters/recordTypePropertyName';

function nestedTermNameGate(context: CompletionContext): boolean {
    if (context.type === 'key') {
        if (context.kind === 'nested-term-name') {
            return true;
        } else if (context.kind === 'property-name') {
            const targetNode = context.pathToNode[context.pathToNode.length - 1];
            if (targetNode.type === PATH_TYPE && targetNode.value === '') {
                return true;
            }
        }
    }
    return false;
}

function propertySnippetGate({
    originalItem
}: CompletionItemAdapterParams<PropertyNameContext | NestedAnnotationTermNameContext>): boolean {
    return ['ValueElement', 'ValueElementSet', 'Path'].includes(originalItem.data?.generic?.category);
}

function propertySnippetAdapter({
    context: { isQuoted, proposedReplacementRange: replacementRange, pathToNode },
    originalItem
}: CompletionItemAdapterParams<PropertyNameContext>): CompletionItem | undefined {
    // Remaining properties snippet, path and records are ignored
    if (
        ['ValueElementSet', 'Path'].includes(originalItem.data.generic.category) ||
        originalItem.data.generic.data.name === 'Record'
    ) {
        return undefined;
    }
    const text = originalItem.data.generic.data?.attributes?.Property?.value;
    const targetNode = pathToNode.slice(-1)[0];
    const isCurrentValueATerm =
        targetNode.type === PATH_TYPE && targetNode.segments.length && targetNode.segments[0].value.startsWith('@');
    return {
        label: text,
        insertTextFormat: InsertTextFormat.PlainText,
        kind: CompletionItemKind.Property,
        documentation: originalItem.documentation,
        // terms go first if current node value is term
        sortText: isCurrentValueATerm ? 'Z' + (originalItem.sortText || '').slice(1) : originalItem.sortText,
        filterText: isQuoted ? `![${text}]` : text,
        textEdit: TextEdit.replace(replacementRange, text),
        commitCharacters: ['.']
    };
}

function annotationSnippetGate({ originalItem }: CompletionItemAdapterParams): boolean {
    return !originalItem.data?.generic?.category || ['Annotation'].includes(originalItem.data?.generic?.category);
}

function annotationSnippetAdaAdapter({
    context: { proposedReplacementRange: replacementRange, flattened },
    originalItem
}: CompletionItemAdapterParams<NestedAnnotationTermNameContext>): CompletionItem | undefined {
    const termName =
        originalItem.data?.generic?.data?.attributes?.Term?.value ||
        originalItem.textEdit?.newText ||
        originalItem.label;
    const text = flattened ? `@${termName}` : `![@${termName}]`;
    return {
        label: text,
        insertTextFormat: InsertTextFormat.PlainText,
        kind: CompletionItemKind.Class,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        filterText: text,
        textEdit: TextEdit.replace(replacementRange, text)
    };
}

function nestedTermNameProvider(
    context: PropertyNameContext,
    { getCompletionItems, file, pointer, position }: CompletionHandlerArgs
): ProviderResult {
    let updatedPointer = pointer;
    const segments = pointer.split('/');
    if (!context.flattened && segments[segments.length - 1] !== '$0') {
        const index = segments.lastIndexOf('content');
        updatedPointer = `${segments.splice(0, index).join('/')}/$0`;
    }
    const items = getCompletionItems(file, position, false, updatedPointer);
    return {
        itemsForAdapter: items,
        completionItems: []
    };
}

export const nestedTermNameHandler: ModularCompletionHandler = {
    name: 'nested-term-name',
    type: 'modular',
    gate: nestedTermNameGate,
    providers: [nestedTermNameProvider],
    mappers: [],
    adapters: [
        { gate: propertySnippetGate, adapter: propertySnippetAdapter },
        { gate: annotationSnippetGate, adapter: annotationSnippetAdaAdapter },
        recordTypePropertyNameAdapter
    ]
};
