import { Range } from 'vscode-languageserver-types';

import { GenericTokenImpl } from './genericToken';
import type { AnnotationAssignmentToken, IdentifierToken } from './types';

export const NEWLINE_REGEX = /\r?\n/g;
export class AnnotationAssignmentTokenImpl extends GenericTokenImpl implements AnnotationAssignmentToken {
    private _range?: Range;

    constructor(
        public readonly uri: string,
        public readonly tokenIndex: number,
        public readonly text: string,

        public readonly line: number,
        public readonly character: number,

        public readonly carrierName: string,
        public readonly carrier?: IdentifierToken,
        public readonly carrierNameRange?: Range,
        public annotationValue?: string
    ) {
        super(uri, tokenIndex, text, line, character, annotationValue);
    }

    public get range(): Range {
        if (!this._range) {
            const lines = this.text.split(NEWLINE_REGEX);
            this._range = Range.create(
                this.line,
                this.character,
                this.line + lines.length - 1,
                lines.length === 1 ? this.character + this.text.length : lines.slice(-1)[0].length
            );
        }
        return this._range;
    }
}
