import type { CompletionItem } from 'vscode-languageserver';
import { InsertTextFormat, CompletionItemKind, TextEdit } from 'vscode-languageserver';

import type { Element } from '@sap-ux/odata-annotation-core';
import { CompletionItemCategory } from '@sap/ux-annotation-service';
import { printOptions, TEXT_TYPE, Edm } from '@sap-ux/odata-annotation-core';

import { printEdmJson } from '@sap/ux-cds-odata-annotation-converter';

import type {
    CompletionContext,
    CompletionItemAdapterParams,
    CompletionItemAdapterWithGate,
    JsonContentContext,
    ModularCompletionHandler
} from '../types';
import { basicItemProvider, fixApplyTabStops } from '../utils';

function jsonElementContentGate(context: CompletionContext): boolean {
    return context.type === 'edm-json' && context.kind === 'content' && context.contentType !== 'attribute';
}
function filterGate({ originalItem }: CompletionItemAdapterParams): boolean {
    return [CompletionItemCategory.Annotation, CompletionItemCategory.DynamicExpressionName].includes(
        originalItem.data?.generic?.category
    );
}

const applyFunctionAdapter: CompletionItemAdapterWithGate = {
    gate: ({ context, originalItem }: CompletionItemAdapterParams<JsonContentContext>) =>
        originalItem.data?.generic?.category === CompletionItemCategory.Apply && context.contentType !== 'text',
    adapter: ({
        context: { hasComma, position, contentType },
        originalItem
    }: CompletionItemAdapterParams<JsonContentContext>): CompletionItem | undefined => {
        const removeRootElementContainer = contentType === 'single-element';
        const snippet: Element = originalItem.data?.generic?.data;
        if (snippet) {
            const label = snippet.attributes[Edm.Function]?.value || originalItem.label;
            if (label === 'odata.fillUriTemplate') {
                fixApplyTabStops(snippet);
            }
            let text = printEdmJson(snippet, { ...printOptions, removeRootElementContainer });
            if (!hasComma) {
                text += ',';
            }
            return {
                label: label,
                insertTextFormat: InsertTextFormat.Snippet,
                kind: CompletionItemKind.Function,
                documentation: originalItem.documentation,
                sortText: originalItem?.sortText,
                textEdit: TextEdit.insert(position, text),
                filterText: label
            };
        }
    }
};

function fixLabeledElementTabStops(snippet: Element): void {
    if (snippet.attributes && snippet.attributes['$0']) {
        delete snippet.attributes['$0'];
    }
    if (snippet.attributes && snippet.attributes['Name']) {
        snippet.attributes['Name'].value = '$0';
    }
    snippet.content = [
        {
            type: TEXT_TYPE,
            text: '$1'
        }
    ];
}

const elementAdapter: CompletionItemAdapterWithGate = {
    gate: ({ context, originalItem }: CompletionItemAdapterParams<JsonContentContext>) =>
        [CompletionItemCategory.ValueElement, CompletionItemCategory.Path].includes(
            originalItem.data?.generic?.category
        ) && context.contentType !== 'text',
    adapter: ({
        context: { hasComma, position, contentType },
        originalItem
    }: CompletionItemAdapterParams<JsonContentContext>): CompletionItem | undefined => {
        const removeRootElementContainer = contentType === 'single-element';
        const snippet: Element = originalItem.data?.generic?.data;
        if (snippet) {
            if (snippet.name === Edm.LabeledElement) {
                fixLabeledElementTabStops(snippet);
            }
            let text = printEdmJson(snippet, { ...printOptions, removeRootElementContainer });
            if (!hasComma) {
                text += ',';
            }
            return {
                label: originalItem.label,
                insertTextFormat: InsertTextFormat.Snippet,
                kind: CompletionItemKind.Snippet,
                documentation: originalItem.documentation,
                sortText: originalItem?.sortText,
                textEdit: TextEdit.insert(position, text),
                filterText: originalItem.filterText
            };
        }
    }
};

export const jsonElementContentHandler: ModularCompletionHandler = {
    name: 'json-element-content',
    type: 'modular',
    gate: jsonElementContentGate,
    providers: [basicItemProvider],
    mappers: [],
    adapters: [{ gate: filterGate, adapter: (): undefined => undefined }, elementAdapter, applyFunctionAdapter]
};
