import type { AnnotationGroupItems, AnnotationNode, Collection, Record } from '@sap-ux/cds-annotation-parser';
import { ANNOTATION_GROUP_ITEMS_TYPE, COLLECTION_TYPE, RECORD_TYPE, isContainer } from '@sap-ux/cds-annotation-parser';
import { isBefore } from '@sap-ux/odata-annotation-core';
import type { Position, Range } from 'vscode-languageserver';

interface Comma {
    type: 'comma';
    range: Range;
}

interface Item {
    type: 'item';
    range: Range;
}

type Token = Comma | Item;

const createToken =
    (type: 'item' | 'comma') =>
    (range: Range): Token => ({ type, range });
const createItemToken = createToken('item');
const createCommaToken = createToken('comma');

const hasComma = (cursorPosition: Position, node: AnnotationGroupItems | Record | Collection): boolean => {
    /**
     * If we have all the tokens ordered by their position then we can search for a first token,
     * that is after cursor position and check if it has a matching comma.
     * If there is whitespace between item token, then we consider a new "item"˝
     */
    const tokens = [
        ...containerChildren(node).reduce(takeRanges, []).map(createItemToken),
        ...node.commas.reduce(takeRanges, []).map(createCommaToken)
    ].sort(compareTokensByRange);

    for (let i = 0; i < tokens.length; i++) {
        const token = tokens[i];
        if (isBefore(cursorPosition, token.range.end)) {
            if (token.type === 'comma') {
                return true;
            }
            if (i + 1 < tokens.length && isBefore(token.range.start, cursorPosition, true)) {
                const nextToken = tokens[i + 1];
                if (nextToken.type === 'comma') {
                    return true;
                }
            }
            return false;
        }
    }
    return false;
};

const comparePositions = (a: Position, b: Position): number => {
    if (a.line === b.line) {
        return a.character - b.character;
    }
    return a.line - b.line;
};
/**
 * Does not support overlapping ranges
 * @param a
 * @param b
 */
const compareTokensByRange = (a: Token, b: Token): number => comparePositions(a.range.start, b.range.start);

const takeRanges = <T extends { range?: Range }>(ranges: Range[], rangeContainer: T): Range[] =>
    rangeContainer.range ? [...ranges, rangeContainer.range] : ranges;
const containerChildren = (node: AnnotationGroupItems | Record | Collection): AnnotationNode[] => {
    switch (node.type) {
        case ANNOTATION_GROUP_ITEMS_TYPE: {
            return node.items;
        }
        case RECORD_TYPE: {
            return [...node.properties, ...(node.annotations ?? [])];
        }
        case COLLECTION_TYPE: {
            return node.items;
        }
    }
};

export const nodeHasComma = (pathToNode: AnnotationNode[], position: Position): boolean => {
    for (const node of [...pathToNode].reverse()) {
        if (isContainer(node)) {
            return hasComma(position, node);
        }
    }
    return false;
};
