import { getLineOffsets } from './lineOffsets';
import { Range } from './position';
import { rangeAt } from './positionAt';

export type PropertyList = PropertyLine[];

export type PropertyLine = KeyElementLine | CommentLine;

interface TextNode {
    type: 'text';
    value: string;
    range: Range;
}

export interface KeyElementLine {
    type: 'key-element-line';
    key: TextNode;
    element: TextNode;
    range: Range;
}

export interface CommentLine {
    type: 'comment-line';
    value: string;
    range: Range;
}

export type TokenType =
    | 'comment'
    | 'separator'
    | 'continuation-line-marker'
    | 'end-of-line'
    | 'text'
    | 'escape'
    | 'whitespace';
export interface Token {
    type: TokenType;

    /**
     * All the matched characters since last token
     */
    image: string;
    /**
     * Start offset of the token
     */
    start: number;
    /**
     * End offset of the token
     */
    end: number;
}

/**
 * Implements reading files Java properties files as described in https://docs.oracle.com/javase/10/docs/api/java/util/Properties.html
 */
export function parseProperties(text: string): PropertyList {
    const tokens = tokenize(text);
    const lineOffsets = getLineOffsets(text);
    const contentLength = text.length;

    let i = 0;
    const peek = (count?: number): Token => (count ? tokens[i + count] : tokens[i]);
    const consume = (): Token => tokens[i++];
    const eof = (): boolean => i >= tokens.length;

    function parseComment(): CommentLine {
        const comment = consume();
        return {
            type: 'comment-line',
            value: comment.image,
            range: rangeAt(lineOffsets, comment.start, comment.end, contentLength)
        };
    }

    function parseKeyElement(): KeyElementLine {
        const keyToken = consume();

        const key: TextNode = {
            type: 'text',
            value: keyToken.image,
            range: rangeAt(lineOffsets, keyToken.start, keyToken.end, contentLength)
        };

        let resetStartOffset = true;
        let start: number | undefined;
        let end: number | undefined;
        if (peek().type === 'whitespace') {
            consume();
        }

        if (peek().type === 'separator') {
            const separator = consume();
            start = end = separator.end;
            if (peek().type === 'whitespace') {
                consume();
            }
        }

        let concatenatedValue = '';
        while (!eof() && peek()?.type !== 'end-of-line') {
            while (!eof() && peek()?.type !== 'end-of-line' && peek()?.type !== 'continuation-line-marker') {
                if (peek()?.type === 'text' || peek()?.type === 'whitespace') {
                    const valueToken = consume();
                    if (resetStartOffset) {
                        start = valueToken.start;
                        resetStartOffset = false;
                    }
                    end = valueToken.end;
                    concatenatedValue += valueToken.image;
                }
            }

            if (peek()?.type === 'continuation-line-marker') {
                consume();
                if (peek().type === 'whitespace') {
                    consume();
                }
            }
        }
        const element: TextNode = {
            type: 'text',
            value: concatenatedValue,
            range: rangeAt(lineOffsets, start ?? 0, end ?? 0, contentLength)
        };

        return {
            type: 'key-element-line',
            key,
            element,
            range: Range.create(key.range.start, element.range.end)
        };
    }

    function parseList(): PropertyList {
        const list = [];

        while (!eof()) {
            const next = peek();
            if (next.type === 'comment') {
                list.push(parseComment());
            } else if (next.type === 'text') {
                list.push(parseKeyElement());
            }

            if (peek()?.type === 'end-of-line' || peek()?.type === 'whitespace') {
                consume();
            }
        }

        return list;
    }
    return parseList();
}

const SEPARATOR = /=|:/;
const COMMENT_START = /#|!/;
const END_OF_LINE = /\r|\n|\r\n/;
const WHITESPACE = /[ \t\f]+/;
const HEX_DIGIT = /[0-9a-fA-F]/;

const ELEMENT_ESCAPE_MAPPING: Record<string, string> = {
    '\\\\': '\\',
    '\\f': '\f',
    '\\n': '\n',
    '\\r': '\r',
    '\\t': '\t'
};
const KEY_ESCAPE_MAPPING: Record<string, string> = {
    ...ELEMENT_ESCAPE_MAPPING,
    '\\=': '=',
    '\\:': ':'
};
const UNICODE_CHARACTER_LENGTH = 4;

export function createToken(type: TokenType, image: string, start: number, end: number): Token {
    return {
        type,
        image,
        start,
        end
    };
}

export function tokenize(text: string): Token[] {
    const tokens: Token[] = [];
    let i = 0;
    let image = '';
    let start = 0;
    while (i < text.length) {
        let character = text[i];

        if (character === '\n') {
            tokens.push(createToken('end-of-line', '\n', start, i + 1));
            start = i + 1;
        } else if (character === '\r') {
            if (i + 1 < text.length && text[i + 1] === '\n') {
                tokens.push(createToken('end-of-line', character + text[i + 1], i, i + 2));
                start = i + 2;
                i++;
            } else {
                tokens.push({
                    type: 'end-of-line',
                    image: character,
                    start: i,
                    end: i + 1
                });
                start = i + 1;
            }
        } else if (COMMENT_START.test(character)) {
            image += character;
            while (i + 1 < text.length) {
                const next = text[i + 1];
                if (END_OF_LINE.test(next)) {
                    break;
                }
                image += next;
                i++;
            }
            tokens.push(createToken('comment', image, start, i + 1));
            image = '';
            start = i + 1;
        } else if (WHITESPACE.test(character)) {
            image += character;
            while (i + 1 < text.length) {
                const next = text[i + 1];
                if (!WHITESPACE.test(next) || END_OF_LINE.test(next)) {
                    break;
                }
                image += next;
                i++;
            }
            tokens.push(createToken('whitespace', image, start, i + 1));
            image = '';
            start = i + 1;
        } else {
            // key-element pair
            while (i < text.length) {
                character = text[i];
                if (character === '\\') {
                    const next = text[i + 1];
                    if (next !== undefined) {
                        const mappedValue = KEY_ESCAPE_MAPPING[character + next];
                        if (mappedValue !== undefined) {
                            image += mappedValue;
                            i += 2;
                        } else if (character + next === '\\u') {
                            const unicodeEscapeEnd = i + UNICODE_CHARACTER_LENGTH + 1;
                            let unicodeCharacterCode = '';
                            for (let index = i + 2; index <= unicodeEscapeEnd; index++) {
                                const c = text[index];
                                if (HEX_DIGIT.test(c)) {
                                    unicodeCharacterCode += c;
                                } else {
                                    break;
                                }
                            }
                            if (unicodeCharacterCode.length === 4) {
                                image += String.fromCharCode(parseInt(unicodeCharacterCode, 16));
                                i += 2 + UNICODE_CHARACTER_LENGTH;
                            } else {
                                // partial unicode escape sequence
                                image += '\\u' + unicodeCharacterCode;
                                i += 2 + unicodeCharacterCode.length;
                            }
                        } else {
                            i++;
                        }
                    }
                    continue;
                }
                if (WHITESPACE.test(character) || SEPARATOR.test(character) || END_OF_LINE.test(character)) {
                    break;
                }
                image += character;
                i++;
            }

            tokens.push(createToken('text', image, start, i));
            image = '';
            start = i;
            if (WHITESPACE.test(character)) {
                image += character;
                while (i + 1 < text.length) {
                    const next = text[i + 1];
                    if (!WHITESPACE.test(next) || END_OF_LINE.test(next)) {
                        break;
                    }
                    image += next;
                    i++;
                }
                tokens.push(createToken('whitespace', image, start, i + 1));
                image = '';
                start = i + 1;
                i++;
                character = text[i];
            }
            if (SEPARATOR.test(character)) {
                tokens.push(createToken('separator', character, start, i + 1));
                start = i + 1;
                i++;
                character = text[i];
            }
            if (WHITESPACE.test(character)) {
                image = character;
                while (i + 1 < text.length) {
                    const next = text[i + 1];
                    if (WHITESPACE.test(next) === false || END_OF_LINE.test(next)) {
                        break;
                    }
                    image += next;
                    i++;
                }
                tokens.push(createToken('whitespace', image, start, i + 1));
                image = '';
                start = i + 1;
                i++;
                character = text[i];
            }
            if (character === '\n') {
                tokens.push(createToken('end-of-line', '\n', start, i + 1));
                start = i + 1;
            } else if (character === '\r') {
                if (i + 1 < text.length && text[i + 1] === '\n') {
                    tokens.push(createToken('end-of-line', character + text[i + 1], i, i + 2));
                    start = i + 2;
                    i++;
                } else {
                    tokens.push({
                        type: 'end-of-line',
                        image: character,
                        start: i,
                        end: i + 1
                    });
                    start = i + 1;
                }
            } else {
                while (i < text.length) {
                    character = text[i];
                    if (character === '\\') {
                        const next = text[i + 1];
                        if (next !== undefined) {
                            const mappedValue = ELEMENT_ESCAPE_MAPPING[character + next];
                            if (mappedValue !== undefined) {
                                image += mappedValue;
                                i += 2;
                            } else if (character + next === '\\u') {
                                const unicodeEscapeEnd = i + UNICODE_CHARACTER_LENGTH + 1;
                                let unicodeCharacterCode = '';
                                for (let index = i + 2; index <= unicodeEscapeEnd; index++) {
                                    const c = text[index];
                                    if (HEX_DIGIT.test(c)) {
                                        unicodeCharacterCode += c;
                                    } else {
                                        break;
                                    }
                                }
                                if (unicodeCharacterCode.length === 4) {
                                    image += String.fromCharCode(parseInt(unicodeCharacterCode, 16));
                                    i += 2 + UNICODE_CHARACTER_LENGTH;
                                } else {
                                    // partial unicode escape sequence
                                    image += '\\u' + unicodeCharacterCode;
                                    i += 2 + unicodeCharacterCode.length;
                                }
                            } else if (next === '\n') {
                                tokens.push(createToken('text', image, start, i));
                                tokens.push(createToken('continuation-line-marker', '\\\n', i, i + 2));
                                start = i + 2;
                                i += 2;
                                image = '';
                            } else if (next === '\r') {
                                if (i + 1 < text.length && text[i + 2] === '\n') {
                                    tokens.push(createToken('text', image, start, i));
                                    tokens.push(createToken('continuation-line-marker', '\\\r\n', i, i + 3));
                                    start = i + 3;
                                    i += 3;
                                    image = '';
                                } else {
                                    tokens.push(createToken('text', image, start, i));
                                    tokens.push(createToken('continuation-line-marker', '\\\r', i, i + 2));
                                    start = i + 2;
                                    i += 2;
                                    image = '';
                                }
                            } else {
                                i++;
                            }
                        }
                        continue;
                    }
                    if (WHITESPACE.test(character)) {
                        if (image) {
                            tokens.push(createToken('text', image, start, i));
                            image = '';
                            start = i;
                        }
                        image = character;
                        while (i + 1 < text.length) {
                            const next = text[i + 1];
                            if (WHITESPACE.test(next) === false || END_OF_LINE.test(next)) {
                                break;
                            }
                            image += next;
                            i++;
                        }
                        tokens.push(createToken('whitespace', image, start, i + 1));
                        image = '';
                        start = i + 1;
                        i++;
                        character = text[i];
                        continue;
                    }
                    if (END_OF_LINE.test(character)) {
                        break;
                    }
                    image += character;
                    i++;
                }
                tokens.push(createToken('text', image, start, i));
                image = '';
                start = i;
                if (END_OF_LINE.test(character)) {
                    continue;
                }
            }
        }

        i++;
    }
    return tokens;
}
