import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, TextEdit } from 'vscode-languageserver';

import type { CompletionContext, ModularCompletionHandler, PropertyNameContext, ProviderResult } from '../types';

const VALUE_PROPERTY_NAME = '$value';

function cdsPropertyNameGate(context: CompletionContext): boolean {
    return context.type === 'key' && context.kind === 'property-name' && context.propertyName === VALUE_PROPERTY_NAME;
}

function cdsPropertyNameProvider({ proposedReplacementRange }: PropertyNameContext): ProviderResult {
    const completionItems: CompletionItem[] = [];
    completionItems.push({
        label: VALUE_PROPERTY_NAME,
        insertTextFormat: InsertTextFormat.PlainText,
        kind: CompletionItemKind.Property,
        sortText: '000000000',
        filterText: VALUE_PROPERTY_NAME,
        textEdit: TextEdit.replace(proposedReplacementRange, VALUE_PROPERTY_NAME)
    });
    return {
        itemsForAdapter: [],
        completionItems
    };
}

export const cdsPropertyNameHandler: ModularCompletionHandler = {
    name: 'cds-property-name',
    type: 'modular',
    gate: cdsPropertyNameGate,
    providers: [cdsPropertyNameProvider],
    mappers: [],
    adapters: []
};
