import { ANNOTATION_GROUP_TYPE, IDENTIFIER_TYPE } from '@sap-ux/cds-annotation-parser';

import type { CompletionContextResolverArgs, VocabularyAliasContext } from '../types';

export function vocabularyAliasResolver({
    pathToNode,
    targetNode
}: CompletionContextResolverArgs): VocabularyAliasContext | undefined {
    if (pathToNode.length < 2) {
        return;
    }
    const parent = pathToNode[pathToNode.length - 2];
    if (parent.type === ANNOTATION_GROUP_TYPE && targetNode.type === IDENTIFIER_TYPE && targetNode === parent.name) {
        return {
            type: 'key',
            kind: 'vocabulary-alias',
            pathToNode
        };
    }
}
