import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, TextEdit } from 'vscode-languageserver';
import type {
    CompletionItemAdapterWithGate,
    ValueCompletionContext,
    RecordContainerContext,
    CompletionItemAdapterParams
} from '../types';

import type { Element } from '@sap-ux/odata-annotation-core';
import { print } from '@sap/ux-cds-odata-annotation-converter';

export const valueSnippetAdapter: CompletionItemAdapterWithGate = {
    gate: ({ originalItem }: CompletionItemAdapterParams): boolean =>
        originalItem.data?.generic?.category === 'ValueElement',
    adapter: ({
        context: { position, hasComma },
        originalItem
    }: CompletionItemAdapterParams<RecordContainerContext | ValueCompletionContext>): CompletionItem | undefined => {
        const snippet: Element = JSON.parse(JSON.stringify(originalItem.data.generic.data));
        let text = `${print(snippet)}`;
        if (['Record', 'PropertyValue'].includes(snippet.name) && !hasComma && !Array.isArray(snippet)) {
            text += ',';
        }
        return {
            label: originalItem?.data?.generic.name,
            insertTextFormat: InsertTextFormat.Snippet,
            kind:
                snippet.name === 'Record'
                    ? originalItem.kind || CompletionItemKind.Snippet
                    : CompletionItemKind.Snippet,
            documentation: originalItem.documentation,
            sortText: originalItem?.sortText,
            textEdit: TextEdit.insert(position, text),
            filterText: ['Record', 'PropertyValue'].includes(snippet.name) ? originalItem.filterText : text
        };
    }
};
