import { PropertyNamesSpecial } from '..';
import type { Element } from '@sap-ux/odata-annotation-core';
import {
    Edm,
    elementsWithName,
    getElementAttributeValue,
    getElementAttribute,
    getSingleTextNode
} from '@sap-ux/odata-annotation-core';
import type { FullyQualifiedName } from '../types/baseTypes';
import { getRecordPropertyElement } from './virtualProperties';

// TODO: extend interface definitions to support other parameter types
export const VALUE_LIST_PARAM_IN_OUT = 'inOut';
export interface ValueListParameterBase {
    type: string;
    valueListProperty: string;
}
export interface ValueListParameterInOut extends ValueListParameterBase {
    type: typeof VALUE_LIST_PARAM_IN_OUT;
    localDataProperty: string;
}

export type ValueListParameter = ValueListParameterInOut;
export interface ValueListSourceData {
    collectionPath: string;
    parameters: ValueListParameter[];
}

export function isCommonValueListRecord(resolvedRecordType: FullyQualifiedName): boolean {
    return resolvedRecordType === 'com.sap.vocabularies.Common.v1.ValueListType';
}

export function isValueListParameterRecord(resolvedRecordType: FullyQualifiedName): boolean {
    // all types carrying 'ValueListProperty' derive from (and their names start with) 'com.sap.vocabularies.Common.v1.ValueListParameter'
    return resolvedRecordType.startsWith('com.sap.vocabularies.Common.v1.ValueListParameter');
}

export function isCollectionPathProperty(resolvedRecordType: FullyQualifiedName, propertyName: string): boolean {
    return isCommonValueListRecord(resolvedRecordType) && propertyName === PropertyNamesSpecial.CollectionPath;
}

export function isValueListProperty(resolvedRecordType: string, propertyName: string): boolean {
    return isValueListParameterRecord(resolvedRecordType) && propertyName === PropertyNamesSpecial.ValueListProperty;
}

export function getValueListCollectionPathValue(valueListRecordElement: Element): string {
    let collectionPath: string;
    const collectionPathProperty: Element = getRecordPropertyElement(
        valueListRecordElement,
        PropertyNamesSpecial.CollectionPath
    );
    if (collectionPathProperty) {
        const valueAttr = getElementAttribute(collectionPathProperty, Edm.String);
        if (valueAttr) {
            collectionPath = valueAttr.value;
        } else {
            const stringNodes = elementsWithName(Edm.String, collectionPathProperty);
            if (stringNodes.length) {
                collectionPath = getSingleTextNode(stringNodes[0])?.text;
            }
        }
    }
    return collectionPath;
}

export function getValueListLocalDataPropertyPath(parameterInOutRecordElement: Element): string {
    let pathValue: string;
    const prop = getRecordPropertyElement(parameterInOutRecordElement, PropertyNamesSpecial.LocalDataProperty);
    if (prop) {
        const valueAttr = getElementAttribute(prop, Edm.PropertyPath);
        if (valueAttr) {
            pathValue = valueAttr.value;
        } else {
            const pathNodes = elementsWithName(Edm.PropertyPath, prop);
            if (pathNodes.length) {
                pathValue = getSingleTextNode(pathNodes[0])?.text;
            }
        }
    }
    return pathValue;
}

export function getValueListPropertyPathValue(valueListParameterRecordElement: Element): string {
    let pathValue: string;
    const prop = getRecordPropertyElement(valueListParameterRecordElement, PropertyNamesSpecial.ValueListProperty);
    if (prop) {
        const valueAttr = getElementAttribute(prop, Edm.String);
        if (valueAttr) {
            pathValue = valueAttr.value;
        } else {
            const pathNodes = elementsWithName(Edm.String, prop);
            if (pathNodes.length) {
                pathValue = getSingleTextNode(pathNodes[0])?.text;
            }
        }
    }
    return pathValue;
}

export function extractValueListPropertiesFromAnnotation(term: Element): ValueListSourceData {
    const result: ValueListSourceData = { collectionPath: null, parameters: [] };
    try {
        const mainRecord = elementsWithName(Edm.Record, term)[0];
        if (mainRecord) {
            result.collectionPath = getValueListCollectionPathValue(mainRecord);
            const params = getRecordPropertyElement(mainRecord, PropertyNamesSpecial.Parameters);
            if (params) {
                const collection = elementsWithName(Edm.Collection, params)[0];
                if (collection) {
                    elementsWithName(Edm.Record, collection).forEach((rec) => {
                        const recType = getElementAttributeValue(rec, Edm.Type) ?? '';
                        if (recType) {
                            const valueListProperty = getValueListPropertyPathValue(rec);
                            if (recType.indexOf('ValueListParameter') >= 0) {
                                result.parameters.push({
                                    type: VALUE_LIST_PARAM_IN_OUT,
                                    localDataProperty: getValueListLocalDataPropertyPath(rec),
                                    valueListProperty
                                });
                            }
                        }
                    });
                }
            }
        }
    } catch (e) {
        // nothing to do
    }
    return result;
}

export function isTargetPropertiesOfSideEffectsPath(annotationAndPropertyPath: string): boolean {
    return (
        RegExp(/@[\w.]+\.SideEffects\/TargetProperties/).test(annotationAndPropertyPath) ||
        RegExp(/@[\w.]+\.SideEffects#[\w.]+\/TargetProperties/).test(annotationAndPropertyPath)
    );
}

export function isAnnotationPathOfCollectionPathProperty(annotationAndPropertyPath: string): boolean {
    return (
        RegExp(/@[\w.]+\.ValueList\/CollectionPath/).test(annotationAndPropertyPath) ||
        RegExp(/@[\w.]+\.ValueList#[\w.]+\/CollectionPath/).test(annotationAndPropertyPath)
    );
}

export function isAnnotationPathOfValueListProperty(annotationAndPropertyPath: string): boolean {
    return (
        RegExp(/@[\w.]+\.ValueList\/Parameters\/ValueListProperty/).test(annotationAndPropertyPath) ||
        RegExp(/@[\w.]+\.ValueList#[\w.]+\/Parameters\/ValueListProperty/).test(annotationAndPropertyPath)
    );
}
