import { Snippet } from './snippet';
import type { SnippetHandlingContext } from '.';
import type { CompletionItem } from '../types/general';
import { CompletionItemCategory } from '../types/general';
import {
    convertParameterTypeToValueType,
    findTemplateParameterIndex,
    getFunctionDocumentation,
    getFunctionNamesForValueType,
    getFunctionParameterDefinitions,
    getTemplateVariableNames
} from '../value-handling';
import type { FunctionName, Parameter, TypeDefinition } from '../specification';
import { dynamicExpressionSignatureMap, functionSignatures } from '../specification';
import type { Element } from '@sap-ux/odata-annotation-core';
import { Edm, ELEMENT_TYPE, getElementAttributeValue } from '@sap-ux/odata-annotation-core';
import { getVocabularyType } from '../vocabulary/access';
import { createLabeledElementSnippet } from './labeledElement';
import { createCollectionSnippet, getElementNamesProvidingValue } from './collection';
import type { JsonPath } from '..';
import { getChildElementPosition, getPathTargetInElement } from '../utils/path';
import { removeDynamicExpressionsFromMap } from './util';
import { MarkupKind } from 'vscode-languageserver';
import type { ValueHandlingContext, ValueType } from '../types/context';

/**
 * Returns array af Apply snippet completion items suitable for current value type.
 * @param snippetContext
 */
export function getApplyFunctionSnippets(snippetContext: SnippetHandlingContext): CompletionItem[] {
    const result: CompletionItem[] = [];
    result.push(
        ...createApplyFunctionSnippets(snippetContext).map((item) => {
            const compItem = item.snippet.toCompletionItem(`"${item.name}"`, false, CompletionItemCategory.Apply);
            compItem.documentation = {
                kind: MarkupKind.Markdown,
                value: (getFunctionDocumentation(item.name as FunctionName) || []).join('\n')
            };
            return compItem;
        })
    );
    return result;
}

function getLabeledElementSnippets(
    snippetContext: SnippetHandlingContext,
    element: Element,
    functionName: string,
    parameter: Parameter
): CompletionItem[] {
    const result: CompletionItem[] = [];
    const newValueHandlingContext: ValueHandlingContext = {
        ...snippetContext.valueHandlingContext,
        nodeContext: {}
    };
    // get all missing labeled element names
    const templateParameterIndex = findTemplateParameterIndex(functionName)[0];
    if (templateParameterIndex !== undefined) {
        const varNames = getTemplateVariableNames(element, templateParameterIndex);
        const existingLabeledElelments = (element.content || []).filter(
            (node) => node.type === ELEMENT_TYPE && node.name === Edm.LabeledElement
        );
        const missingNames = varNames.filter(
            (item) => !existingLabeledElelments.find((le) => getElementAttributeValue(le as Element, Edm.Name) === item)
        );
        if (missingNames) {
            missingNames.forEach((name) => {
                const snippet = createSnippetsForFunctionParameter(
                    { ...snippetContext, valueHandlingContext: newValueHandlingContext },
                    parameter,
                    1,
                    true,
                    false,
                    name
                )[0];
                result.push(snippet.snippet.toCompletionItem(`"${name}"`, false));
            });
        }
    }
    return result;
}

function getSnippetsForFunctionParameter(
    snippetContext: SnippetHandlingContext,
    parameter: Parameter
): CompletionItem[] {
    const newValueHandlingContext: ValueHandlingContext = {
        ...snippetContext.valueHandlingContext,
        nodeContext: {}
    };

    const data = createSnippetsForFunctionParameter(
        { ...snippetContext, valueHandlingContext: newValueHandlingContext },
        parameter,
        1,
        true,
        false
    );
    return data.map((item) => {
        const compItem = item.snippet.toCompletionItem(
            item.snippet.generic.name === Edm.Apply ? `"${item.name}"` : null,
            false
        );

        if (item.snippet.generic.name === Edm.Apply) {
            compItem.documentation = {
                kind: MarkupKind.Markdown,
                value: (getFunctionDocumentation(item.name as FunctionName) || []).join('\n')
            };
        }

        switch (item.snippet.generic.name) {
            case Edm.Path:
                compItem.category = CompletionItemCategory.Path;
                break;
            case Edm.Apply:
                compItem.category = CompletionItemCategory.Apply;
                break;
        }
        if (dynamicExpressionSignatureMap.has(item.snippet.generic.name as Edm)) {
            compItem.category = CompletionItemCategory.DynamicExpressionName;
        }
        return compItem;
    });
}

/**
 * Returns array of snippet completion items for a concrete Apply element content
 * @param snippetContext
 * @param element
 * @param path
 */
export function getSnippetsForApplyContent(
    snippetContext: SnippetHandlingContext,
    element: Element,
    path: JsonPath
): CompletionItem[] {
    const result: CompletionItem[] = [];
    const target = getPathTargetInElement(path, element);
    const parameterIndex = target.isWhitespacePosition
        ? target.beforeSubNodeIndex
        : getChildElementPosition(target.nodeIndex, element, true);
    const functionName = getElementAttributeValue(element, Edm.Function) as FunctionName;
    const overloads = functionSignatures.get(functionName);

    if (overloads) {
        // TODO: support multiple overloads
        const parameter = getFunctionParameterDefinitions(functionName, parameterIndex)[0];
        if (parameter) {
            const paramTypeDefs = parameter.type;
            const type = Array.isArray(paramTypeDefs) ? paramTypeDefs[0] : paramTypeDefs;
            if (typeof type === 'object' && type.kind === 'LabeledElement') {
                result.push(...getLabeledElementSnippets(snippetContext, element, functionName, parameter));
            }
            if (result.length === 0) {
                result.push(...getSnippetsForFunctionParameter(snippetContext, parameter));
            }
        }
    }
    return result;
}

/**
 * Generates Apply snippets and returns array of objects containing snippet and corresponding function name
 * @param snippetContext
 */
function createApplyFunctionSnippets(snippetContext: SnippetHandlingContext): { name: string; snippet: Snippet }[] {
    const functionNames = getFunctionNamesForValueType(snippetContext.type, snippetContext.valueHandlingContext);
    return functionNames.map((functionName) => {
        const functionSnippet: Snippet = new Snippet(Edm.Apply, snippetContext.useSnippets).setAttribute(
            Edm.Function,
            functionName
        );
        let tabStopId = functionSnippet.getNextTabStopId();
        const overloads = functionSignatures.get(functionName);
        // TODO: support multiple overloads
        const signature = Array.isArray(overloads) ? overloads[0] : overloads;

        // add parameter elements to function snippet
        for (let i = 0; i < signature.parameters.length; i++) {
            if (!signature.parameters[i].isMandatory) {
                break;
            }
            const data = createSnippetsForFunctionParameter(
                snippetContext,
                signature.parameters[i],
                tabStopId,
                i === signature.parameters.length - 1,
                true
            );
            if (data) {
                tabStopId = data[0].snippet.getNextTabStopId();
                functionSnippet.appendContent(data[0].snippet);
            } else {
                break;
            }
        }
        if (functionName === 'odata.concat') {
            functionSnippet.appendContent(`$${tabStopId}`);
            functionSnippet.appendFinalTabStopToContent();
        }
        if ((functionSnippet.generic.content || []).length === 0) {
            functionSnippet.appendFinalTabStopToContent();
        }
        return { name: functionName, snippet: functionSnippet };
    });
}

/**
 * Determine parameter type to be used in snippet building
 */
function getParameterTypeToUse(parameter: Parameter, isSubElementForApplySnippet: boolean): string | TypeDefinition {
    let result: string | TypeDefinition;
    if (Array.isArray(parameter.type)) {
        result = isSubElementForApplySnippet
            ? parameter.type.find((t) => typeof t === 'object' && t.useInSnippet)
            : parameter.type[0];
    } else {
        result = parameter.type;
    }
    return result;
}

/**
 * Generates snippets for Apply function parameter
 * Returns array of objects containing snippet and name (name is applicable to Apply and LabeledElement only)
 * @param snippetContext
 * @param parameter - parameter definition object
 * @param initialTabStopId - starting index for snippet tabstops
 * @param addFinalTabStop - flag if the final tabstop should be put in snippet
 * @param isSubElementForApplySnippet - flag which says that the function is called by Apply function snippet generator (in that case some limitations should be considered)
 * @param labeledElementName - name of labeled element which is set in its Name attribute (if provided)
 */
export function createSnippetsForFunctionParameter(
    snippetContext: SnippetHandlingContext,
    parameter: Parameter,
    initialTabStopId: number,
    addFinalTabStop: boolean,
    isSubElementForApplySnippet: boolean,
    labeledElementName?: string
): { name: string; snippet: Snippet }[] | undefined {
    // determine parameter type to be used in snippet building
    const parameterTypeToUse: string | TypeDefinition = getParameterTypeToUse(parameter, isSubElementForApplySnippet);
    if (parameterTypeToUse) {
        const valueType = convertParameterTypeToValueType(parameterTypeToUse);
        const vocabularyType = getVocabularyType(snippetContext.valueHandlingContext.context, valueType.name);

        if (typeof parameterTypeToUse === 'object' && parameterTypeToUse.kind === 'LabeledElement') {
            const labeledElement = createLabeledElementSnippet(
                { ...snippetContext, type: valueType },
                vocabularyType,
                labeledElementName,
                initialTabStopId,
                addFinalTabStop
            );
            return [{ name: labeledElementName, snippet: labeledElement }];
        } else if (valueType.asCollection) {
            const collection = createCollectionSnippet(
                { ...snippetContext, type: { ...valueType, asCollection: false } },
                vocabularyType,
                initialTabStopId,
                addFinalTabStop
            );
            return [{ name: null, snippet: collection }];
        } else if (vocabularyType?.kind === Edm.ComplexType) {
            // TODO: support records as parameters
            return;
        } else if (isSubElementForApplySnippet) {
            return getSubElementForApplySnippet(snippetContext, valueType, initialTabStopId, addFinalTabStop);
        } else {
            // completion within Apply content
            return getCompletionItemsWithinApplyContent(snippetContext, valueType, initialTabStopId);
        }
    }
}

function getCompletionItemsWithinApplyContent(
    snippetContext: SnippetHandlingContext,
    valueType: ValueType,
    initialTabStopId: number
): { name: string; snippet: Snippet }[] {
    const valueElementMap = getElementNamesProvidingValue({ ...snippetContext, type: valueType });
    const result: { name: string; snippet: Snippet }[] = [];
    Object.keys(valueElementMap).forEach((key) => {
        if (key === Edm.Apply) {
            // nested Apply functions
            result.push(...createApplyFunctionSnippets({ ...snippetContext, type: valueType }));
        } else {
            const valueSnippet = new Snippet(
                key as Edm,
                snippetContext.useSnippets,
                initialTabStopId
            ).appendFinalTabStopToContent();
            result.push({ name: null, snippet: valueSnippet });
        }
    });
    return result;
}

function getSubElementForApplySnippet(
    snippetContext: SnippetHandlingContext,
    valueType: ValueType,
    initialTabStopId: number,
    addFinalTabStop: boolean
): { name: string; snippet: Snippet }[] | undefined {
    const valueElementMap = getElementNamesProvidingValue({ ...snippetContext, type: valueType });
    // only single value element should be used for Apply parameter
    removeDynamicExpressionsFromMap(valueElementMap);
    if (Object.keys(valueElementMap).length > 1) {
        delete valueElementMap[Edm.Path];
    }
    if (Object.keys(valueElementMap).length === 1) {
        const valueSnippet = new Snippet(
            Object.keys(valueElementMap)[0] as Edm,
            snippetContext.useSnippets,
            initialTabStopId
        );
        valueSnippet.appendTabStopToContent(addFinalTabStop ? 0 : valueSnippet.getNextTabStopId());
        return [{ name: null, snippet: valueSnippet }];
    } else {
        return;
    }
}
