import type { AnnotationNode } from '@sap-ux/cds-annotation-parser';
import { findAnnotationNode } from '@sap-ux/cds-annotation-parser';
import type { Target, AnnotationFile, Position } from '@sap-ux/odata-annotation-core';

export const isPathValueInvolved = (annotationFile: AnnotationFile, pointer: string): boolean => {
    let isRelevant = false;
    // find most specific node and its parent node for path (e.g. /targets/3/terms/0/content/0/content/0/text/$0)
    if (pointer.startsWith('/')) {
        pointer = pointer.substring(1);
    }
    const segments = pointer.split('/');
    let currentContext = annotationFile as any;
    let previousContext = null;
    let done = false;
    do {
        const currentSegment = segments.shift();
        if (['targets', 'terms', 'content'].includes(currentSegment)) {
            previousContext = currentContext;
            currentContext = currentContext[currentSegment];
        } else if (currentSegment === parseInt(currentSegment, 10).toString() && Array.isArray(currentContext)) {
            currentContext = currentContext[parseInt(currentSegment, 10)];
        } else {
            done = true;
            if (currentSegment === 'text') {
                // e.g. /targets/3/terms/0/content/0/content/0/text/$0
                isRelevant = previousContext['name'].indexOf('Path') >= 0;
            } else if (currentSegment === 'attributes') {
                // e.g. /targets/3/terms/0/content/0/content/0/attributes/AnnotationPath/value
                isRelevant = segments.shift().indexOf('Path') > 0 && segments.shift() === 'value';
            } else if (currentSegment.startsWith('$')) {
                // e.g. /targets/3/terms/0/content/0/content/0/$0
                isRelevant = currentContext['name'] !== 'Record'; // Record cannot have child element Path
            }
        }
    } while (!done && segments.length > 0);
    return isRelevant;
};

export const getTargetTermQualifier = (
    annotationFile: AnnotationFile,
    pointer: string
): { targetName: string; termName: string; qualifier: string } => {
    if (pointer.startsWith('/')) {
        pointer = pointer.substring(1);
    }
    const segments = pointer.split('/');
    // find target, term, qualifier where pointer points into, e.g. for path = /targets/3/terms/0/content/0/content/0/text/$0
    if (segments.shift() !== 'targets' || !segments.length) {
        return null;
    }
    const targetObject = annotationFile.targets[parseInt(segments.shift(), 10)];
    if (!targetObject || segments.shift() !== 'terms' || !segments.length) {
        return null;
    }
    const termObject = targetObject.terms[parseInt(segments.shift(), 10)];
    if (!targetObject || !termObject || !termObject.attributes['Term']?.value) {
        return null;
    }
    const qualifier = termObject?.attributes['Qualifier'] ? termObject.attributes['Qualifier'].value : '';
    return {
        targetName: targetObject.name,
        termName: termObject.attributes['Term'].value,
        qualifier
    };
};
export const getTarget = (annotationFile: AnnotationFile, pointer: string): string | undefined => {
    if (pointer.startsWith('/')) {
        pointer = pointer.substring(1);
    }
    const segments = pointer.split('/');
    // find target where pointer points into, e.g. for path = /targets/3/terms/0/content/0/content/0/text/$0
    if (segments.shift() !== 'targets' || !segments.length) {
        return undefined;
    }
    const target = annotationFile.targets[parseInt(segments.shift(), 10)];
    return target.name;
};

export const getTargetsbyPointer = (annotationFile: AnnotationFile, pointer: string): Target[] => {
    if (pointer.startsWith('/')) {
        pointer = pointer.substring(1);
    }
    const segments = pointer.split('/');
    // find target, term, qualifier where pointer points into, e.g. for path = /targets/3/terms/0/content/0/content/0/text/$0
    if (segments.shift() !== 'targets' || !segments.length) {
        return null;
    }
    const targetObject = annotationFile.targets[parseInt(segments.shift(), 10)];

    return getTargetsByName(annotationFile, targetObject.name);
};

const getTargetsByName = (annotationFile: AnnotationFile, targetName: string): Target[] => {
    return annotationFile.targets.filter(function (target) {
        return target.name === targetName;
    });
};

export function getPathToNode(assignment: AnnotationNode, position: Position): AnnotationNode[] {
    const path = findAnnotationNode(assignment, { position, includeDelimiterCharacters: false });
    const { pathToNode }: { pathToNode: AnnotationNode[]; node: AnnotationNode } = path.split('/').reduce(
        (accumulator, segment, i) => {
            if (i > 0) {
                const node = accumulator.node[segment];
                accumulator.node = node;
                if (!Array.isArray(node)) {
                    accumulator.pathToNode.push(node);
                }
            }
            return accumulator;
        },
        { node: assignment, pathToNode: [assignment] }
    );
    return pathToNode;
}
