import { i18n } from './i18n';
import { Range } from './position';
import type { CommentLine } from './propertiesParser';
import { parseProperties } from './propertiesParser';
import { getI18nMaxLength, getI18nTextType } from './text';
import type { I18nAnnotation, I18nEntry, SapTextType, ValueNode } from './types';

/**
 * Get abstract syntax tree for i18n.properties file
 * @param content
 * @param filePath
 */
export const loadPropertiesTexts = (content: string, filePath = ''): I18nEntry[] => {
    const i18nEntries: I18nEntry[] = [];
    const lines = parseProperties(content);
    for (let i = 0; lines.length > i; i++) {
        const line = lines[i];
        if (line.type === 'key-element-line') {
            const commentLine = lines[i - 1];
            const entry: I18nEntry = {
                filePath,
                key: {
                    value: line.key.value,
                    range: line.key.range
                },
                value: {
                    value: line.element.value,
                    range: line.element.range
                }
            };
            if (commentLine?.type === 'comment-line') {
                const { start } = commentLine.range;
                const commaIndex = commentLine.value.indexOf(',');
                const colonIndex = commentLine.value.indexOf(':');
                entry.annotation = {
                    textType: toTextTypeNode(commentLine, commaIndex, colonIndex)
                };
                if (commaIndex !== -1) {
                    entry.annotation.maxLength = {
                        value: parseInt(
                            commentLine.value.slice(commaIndex + 1, colonIndex === -1 ? undefined : colonIndex)
                        ),
                        range: Range.create(
                            start.line,
                            start.character + commaIndex + 1,
                            start.line,
                            start.character + (colonIndex === -1 ? commentLine.value.length : colonIndex)
                        )
                    };
                }
                if (colonIndex !== -1) {
                    entry.annotation.note = {
                        value: commentLine.value.slice(colonIndex + 1),
                        range: Range.create(
                            start.line,
                            start.character + colonIndex + 1,
                            start.line,
                            start.character + commentLine.value.length
                        )
                    };
                }
            }
            i18nEntries.push(entry);
        }
    }
    return i18nEntries;
};

function toTextTypeNode(comment: CommentLine, commaIndex: number, colonIndex: number): ValueNode<SapTextType> {
    const { start } = comment.range;
    // Comments can only be single line, so start and end lines will be equal
    if (commaIndex !== -1) {
        return {
            value: comment.value.slice(1, commaIndex) as SapTextType,
            range: Range.create(start.line, start.character, start.line, start.character + commaIndex)
        };
    } else if (colonIndex !== -1) {
        return {
            value: comment.value.slice(1, colonIndex) as SapTextType,
            range: Range.create(start.line, start.character + 1, start.line, start.character + colonIndex)
        };
    }
    return {
        value: comment.value.slice(1) as SapTextType,
        range: Range.create(start.line, start.character, start.line, start.character + comment.value.length)
    };
}

/**
 * Creates annotation text in .properties file format.
 * If no annotation is not provided, default one is generated based on text.
 * @param text
 * @param annotation Context information for the text
 */
export function printPropertiesFileI18nAnnotation(text: string, annotation?: string | I18nAnnotation): string {
    if (!annotation) {
        const maxLen = getI18nMaxLength(text);
        const textType = getI18nTextType(maxLen);
        return `${textType},${maxLen}`;
    }

    if (typeof annotation === 'string') {
        const prefix = text.length <= 120 ? 'X' : 'Y';
        return `${prefix}${annotation}`;
    }

    if (typeof annotation === 'object') {
        const { textType, note, maxLength } = annotation;
        const fragments: string[] = [textType];

        if (maxLength !== undefined) {
            fragments.push(',', maxLength.toString());
        }

        if (note) {
            fragments.push(':', ' ', note.trim());
        }

        return fragments.join('');
    }
    return '';
}

/**
 * Creates text for i18n entry in .properties file format.
 * If no annotation is not present, generic default one will be generated based on the text.
 * @param key
 * @param text
 * @param annotation Context information for the text
 */
export function printPropertiesFileI18nEntry(key: string, text: string, annotation?: string | I18nAnnotation): string {
    const annotationText = printPropertiesFileI18nAnnotation(text, annotation);
    const comment = `#${annotationText}`;
    const keyValue = `${key}=${text}`;
    return `\n${comment}\n${keyValue}\n`;
}

export type MarkdownString = string;
/**
 * Get documentation for i18n entry
 */
export const geI18ntDocumentation = (entry: I18nEntry): MarkdownString => {
    const documentation: MarkdownString[] = [];
    const key = `**${i18n.t('Text_Key')}:** ${entry.key.value}`;
    const value = `**${i18n.t('Text_Value')}:** ${entry.value.value}`;
    documentation.push(key, value);
    if (entry.annotation) {
        const annotationText = printPropertiesFileI18nAnnotation(entry.value.value, {
            maxLength: entry.annotation.maxLength?.value,
            textType: entry.annotation.textType.value,
            note: entry.annotation.note?.value
        });
        documentation.push(`**${i18n.t('Additional_Information')}:** ${annotationText}`);
    }
    return documentation.join('\n\n');
};
