import { join, relative } from 'path';
import * as os from 'os';

import { DiagnosticSeverity, Range } from 'vscode-languageserver-types';

import type { XsnCompileModel, XsnMessage } from '@sap/cds-compiler';

import type { ServiceName, DiagnosticBase, CompilerMessage } from '@sap-ux/odata-annotation-core';
import type { Project } from '@sapux/project-spec';

import { createCdsCompilerFacade } from '.';
import { createIndex as create } from './blitzIndex';
import { locationToRange } from './transform';
import type { BlitzIndex, MetadataElementMap, CdsCompilerFacade } from '.';

import { severityMap } from './cds';
import type { MetadataCollector } from './metadata';
import { createMetadataCollector, generateMetadata } from './metadata';
import type { File } from './compile';
import { compile } from './compile';
import { toggleCase } from './cdsSource';

export interface CdsArtifactsType {
    fileSequence: string[];
    lspIndex?: BlitzIndex;
    metadataElementMap: MetadataElementMap;
    metadataIncluded: boolean;
    compileMessagesMap: Map<string, CompilerMessage>;
    cdsCompilerFacade?: CdsCompilerFacade;
    collector?: MetadataCollector;
}

export const getCdsArtifacts = async (
    project: Project,
    serviceName: ServiceName,
    files: string[],
    cache: Map<string, File>
): Promise<CdsArtifactsType> => {
    if (files.length) {
        const compileModel = await compile(project.root, files, cache);
        const lspIndex = create(compileModel);
        // collect map of messages from compile model ('compile messages')
        const compileMessagesMap = getCompilerErrorMessages(project, compileModel);
        // get metadata elements and namespaces
        const fileSequence = getFileSequence(compileModel).map((fileUri: string) => relative(project.root, fileUri));
        const facade = createCdsCompilerFacade(compileModel);
        const metadataElementMap = generateMetadata(compileModel, facade, serviceName);
        const metadataCollector = createMetadataCollector(metadataElementMap, facade);
        return {
            fileSequence,
            compileMessagesMap,
            lspIndex,
            metadataElementMap,
            metadataIncluded: false,
            cdsCompilerFacade: facade,
            collector: metadataCollector
        };
    } else {
        return {
            fileSequence: [],
            lspIndex: undefined,
            compileMessagesMap: new Map(),
            metadataElementMap: new Map(),
            metadataIncluded: false,
            cdsCompilerFacade: undefined
        };
    }
};

/**
 * get CDS file sequence
 * @param compileModel
 *  - each source has the property "_layerRepresentative" which is (another or the same) source representing a "layer"
 *  - a source which represents a layer has the property "_layerExtends" a dictionary of directly or indirectly dependent layer representatives
 */
function getFileSequence(compileModel: XsnCompileModel): string[] {
    // find sequence of layer representatives using topological sort (based on _layerExtends - 'edges')
    const fileSequenceOrig: string[] = Object.keys(compileModel.sources ?? {});
    const { incomingEdges, layerRepFiles, outgoingEdges } = calculateEdges(compileModel);
    const layerRepSequence: string[] = [];
    while (getNextFileNameWithNoIncomingEdge(fileSequenceOrig, incomingEdges)) {
        // next filename with no incoming edge: insert it at start
        const fileName = getNextFileNameWithNoIncomingEdge(fileSequenceOrig, incomingEdges, true);
        if (fileName) {
            layerRepSequence.unshift(fileName);
            // remove all outgoing edges for that file
            const outGoingEdge = outgoingEdges?.get(fileName);
            if (outGoingEdge) {
                for (const targetFileName of outGoingEdge) {
                    incomingEdges?.get(targetFileName)?.delete(fileName);
                }
            }
        }
    }
    // if there are still nodes with incomingEdges then graph has at least one cycle
    if (incomingEdges.size > 0) {
        return fileSequenceOrig;
    } // return old sequence

    // replace layer representative with all files of that layer
    const fileSequence: string[] = [];
    for (const layerRepFileName of layerRepSequence) {
        const layerRepFile = layerRepFiles?.get(layerRepFileName);
        if (layerRepFile) {
            fileSequence.push(...layerRepFile);
        }
    }
    return fileSequence;
}

function calculateEdges(compileModel: XsnCompileModel): {
    outgoingEdges: Map<string, Set<string>>;
    incomingEdges: Map<string, Set<string>>;
    layerRepFiles: Map<string, Set<string>>;
} {
    const outgoingEdges: Map<string, Set<string>> = new Map();
    const incomingEdges: Map<string, Set<string>> = new Map();
    const layerRepFiles: Map<string, Set<string>> = new Map();
    for (const fileName of Object.keys(compileModel.sources || {})) {
        const layerRep = compileModel.sources[fileName]._layerRepresentative;
        const layerRepFileName = layerRep?.realname;
        if (!layerRepFileName) {
            continue;
        }
        if (!layerRepFiles.has(layerRepFileName)) {
            layerRepFiles.set(layerRepFileName, new Set());
        }
        layerRepFiles?.get(layerRepFileName)?.add(fileName);
        if (!outgoingEdges.has(layerRepFileName)) {
            outgoingEdges.set(layerRepFileName, new Set());
        }
        if (!incomingEdges.has(layerRepFileName)) {
            incomingEdges.set(layerRepFileName, new Set());
        }
        const targets = Object.keys(layerRep._layerExtends || {});
        targets.forEach((target) => {
            outgoingEdges?.get(layerRepFileName)?.add(target);
            if (!incomingEdges.has(target)) {
                incomingEdges.set(target, new Set());
            }
            incomingEdges?.get(target)?.add(layerRepFileName);
        });
    }
    return { outgoingEdges, incomingEdges, layerRepFiles };
}

function getNextFileNameWithNoIncomingEdge(
    fileSequenceOrig: string[],
    incomingEdges: Map<string, Set<string>>,
    remove = false
): string | null {
    // try to follow the original file sequence
    for (let i = fileSequenceOrig.length - 1; i >= 0; i--) {
        const fileName = fileSequenceOrig[i];
        if (incomingEdges.get(fileName)?.size === 0) {
            if (remove) {
                incomingEdges.delete(fileName);
            }
            return fileName;
        }
    }
    return null; // not found
}

export function getCompilerErrorMessages(
    project: Project,
    compileModel: XsnCompileModel
): Map<string, CompilerMessage> {
    const cache = new Map<string, CompilerMessage>();
    const fileUris = Object.keys(compileModel.sources);
    let root = project.root || '';
    if (root && os.platform() === 'win32' && !fileUris.some((uri) => uri.startsWith(root.at(0)!))) {
        root = toggleCase(root.at(0)!) + root.substring(1); // adapt drive letter
    }
    for (const sourceUri of fileUris) {
        const source = compileModel.sources[sourceUri];

        const messages: ReadonlyArray<XsnMessage> = (source?.options?.messages ?? []).filter((compileMessage) => {
            const fileName = compileMessage?.$location?.file;
            return fileName && join(root, fileName) === sourceUri;
        });

        for (const message of messages) {
            const fileName = message?.$location?.file;
            if (!cache.has(fileName)) {
                cache.set(fileName, { hasSyntaxErrors: false, messages: [] });
            }
            const fileEntry = cache.get(fileName);
            const diagnostic: DiagnosticBase = {
                message: message.message,
                severity: severityMap[message.severity] ?? DiagnosticSeverity.Error,
                range: locationToRange(message.$location) || Range.create(0, 0, 0, 0)
            };
            if (diagnostic.severity === DiagnosticSeverity.Error && fileEntry) {
                fileEntry.hasSyntaxErrors = true;
            }
            fileEntry?.messages.push(diagnostic);
        }
    }
    return cache;
}
