import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, TextEdit } from 'vscode-languageserver';

import type { Element } from '@sap-ux/odata-annotation-core';
import { CompletionItemCategory } from '@sap/ux-annotation-service';
import { Edm, printOptions } from '@sap-ux/odata-annotation-core';
import { printEdmJson } from '@sap/ux-cds-odata-annotation-converter';

import type { CompletionItemAdapterParams, CompletionItemAdapterWithGate, ValueCompletionContext } from '../types';
import { fixApplyTabStops } from '../utils';

export const applyFunctionAdapter: CompletionItemAdapterWithGate = {
    gate: ({ originalItem }: CompletionItemAdapterParams) =>
        originalItem.data?.generic?.category === CompletionItemCategory.Apply,
    adapter: ({
        context: { hasComma, position },
        originalItem
    }: CompletionItemAdapterParams<ValueCompletionContext>): CompletionItem | undefined => {
        const snippet: Element = JSON.parse(JSON.stringify(originalItem.data?.generic?.data));
        if (snippet) {
            const label = snippet.attributes[Edm.Function]?.value || originalItem.label;
            if (label === 'odata.fillUriTemplate') {
                fixApplyTabStops(snippet);
            }
            let text = printEdmJson(snippet, { ...printOptions, includeEdmJson: true });
            if (!hasComma) {
                text += ',';
            }
            return {
                label: label,
                insertTextFormat: InsertTextFormat.Snippet,
                kind: CompletionItemKind.Function,
                documentation: originalItem.documentation,
                sortText: `Z${originalItem?.sortText}`,
                textEdit: TextEdit.insert(position, text),
                filterText: label
            };
        }
        return undefined;
    }
};
