import type { Range, Hover, Position } from 'vscode-languageserver-types';
import { DiagnosticSeverity, MarkupKind } from 'vscode-languageserver-types';

import type { CompletionItem } from '../types/general';
import { CompletionItemCategory } from '../types/general';

import type { Context, ValueType, ValueHandlingContext } from '../types/context';
import type { EnumType, EnumValue } from '@sap-ux/odata-vocabularies';

import { getNamespaceAndAlias } from '../utils/name';
import { i18n } from '../i18n';
import type {
    Alias,
    CaseCheckBase,
    ExtendedDiagnostic as Diagnostic,
    Name,
    NamespaceString,
    ResolvedName
} from '@sap-ux/odata-annotation-core';
import { INVALID_ENUM_MEMBER_TYPE, resolveName, toAliasQualifiedName } from '@sap-ux/odata-annotation-core';

export interface ResolvedEnumValue {
    text: string;
    prefix: NamespaceString | Alias;
    type: Name;
    name: Name;
    enumMember: EnumValue;
    caseInsensitiveEnumMember?: EnumValue;
    correctText?: string;
}

export const getEnumValueSegments = (value: string): (string | null)[] => {
    const enumRgX = new RegExp(/((?:\w{1,127}\.)+)(\w{1,127}\/)?(\w{1,127})?/g); //restrict simple identifier max-length 128
    const segments = enumRgX.exec(value) || [null, null, null, null];
    return segments.splice(1, 3);
};

const resolveCurrentValueList = (
    value: string,
    enums: EnumType,
    typeName: Name,
    possiblePrefixes: string[]
): ResolvedEnumValue[] => {
    return (value || '')
        .split(' ')
        .filter((item) => !!item)
        .map((item) => {
            const [ns, type, name] = getEnumValueSegments(item.trim());

            // find corresponding enum member
            const enumMember = (enums.values || []).find(
                (val) =>
                    possiblePrefixes.map((elm) => elm + '.').includes(ns) &&
                    typeName + '/' === type &&
                    val.name === name
            );
            const result: ResolvedEnumValue = {
                text: item,
                prefix: ns,
                type,
                name,
                enumMember
            };
            if (!enumMember && ns && type && name) {
                const caseInsensitivePossiblePrefix = possiblePrefixes.map((elm) => (elm + '.').toUpperCase());
                const caseInsensitiveEnumMember = (enums.values || []).find(
                    (val) =>
                        caseInsensitivePossiblePrefix.includes(ns.toUpperCase()) &&
                        (typeName + '/').toUpperCase() === type.toUpperCase() &&
                        val.name.toUpperCase() === name.toUpperCase()
                );
                result.caseInsensitiveEnumMember = caseInsensitiveEnumMember;
                if (caseInsensitiveEnumMember) {
                    let nsOrAlias = caseInsensitivePossiblePrefix.find((item) => item === ns.toUpperCase());
                    nsOrAlias = possiblePrefixes.find((item) => item.length === nsOrAlias.length - 1);
                    const correctText = `${nsOrAlias}.${typeName}/${caseInsensitiveEnumMember.name}`;
                    result.correctText = correctText;
                }
            }
            return result;
        });
};

const getValueFragmentRange = (valueRange: Range, offset: number, length: number): Range => {
    return {
        start: { line: valueRange.start.line, character: valueRange.start.character + offset },
        end: { line: valueRange.start.line, character: valueRange.start.character + offset + length }
    };
};

const getMultiTokenCompletionValueContext = (
    value: string,
    startString: string,
    tokenSymbolsRegexp: RegExp
): {
    completionOffset: number;
    tokenOffset: number;
    tokenHead: string;
    tokenTail: string;
} => {
    const completionOffset = (startString || '').length;
    let head = '';
    let tail = '';
    let pos = completionOffset;
    while (pos > 0 && tokenSymbolsRegexp.test(startString.substr(pos - 1, 1))) {
        head = startString.substr(pos - 1, 1) + head;
        pos--;
    }
    pos = completionOffset;
    while (tokenSymbolsRegexp.test(value.substr(pos, 1))) {
        tail += value.substr(pos, 1);
        pos++;
    }
    return {
        completionOffset: completionOffset,
        tokenOffset: completionOffset - head.length,
        tokenHead: head,
        tokenTail: tail
    };
};

const enumComplete = (
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    value: string,
    valueRange: Range,
    startString?: string
): CompletionItem[] => {
    const context: Context = valueHandlingContext.context;
    const enums = context.vocabularies.getType(type.name) as EnumType;
    const resolvedEnumType: ResolvedName = resolveName(type.name, valueHandlingContext.aliasInfo.aliasMap);
    const namespace: NamespaceString = resolvedEnumType.namespace;

    const typeName = resolvedEnumType.name;

    const completionItems: CompletionItem[] = [];

    if (enums) {
        // recognize enum value completion token
        const completionContext = getMultiTokenCompletionValueContext(value, startString, new RegExp(/[./\w]/));
        const compItemForCurrentEnum = completionContext.tokenHead + completionContext.tokenTail;
        const splittedValue = value.split(' ');
        const filteredEnumMember = splittedValue.filter((item) => item !== compItemForCurrentEnum);
        const excludedEnumMember: string[] = [];
        filteredEnumMember.forEach((item) => {
            const qName = resolveName(item, valueHandlingContext.aliasInfo.aliasMap).qName;
            excludedEnumMember.push(qName);
        });

        enums.values.forEach((item) => {
            const qualifiedName = `${namespace}.${typeName}`;
            const fullyQualifiedName = `${namespace}.${typeName}/${item.name}`;
            const aliasedName = toAliasQualifiedName(fullyQualifiedName, valueHandlingContext.aliasInfo);
            const tokenHead = completionContext.tokenHead.toUpperCase();
            // by default show alias
            let textName = aliasedName;
            if (
                !aliasedName.toUpperCase().startsWith(tokenHead) &&
                fullyQualifiedName.toUpperCase().startsWith(tokenHead)
            ) {
                // replace alias by existing namespace
                textName = fullyQualifiedName;
            }

            if (!excludedEnumMember.includes(fullyQualifiedName)) {
                const affectedRange = valueRange
                    ? getValueFragmentRange(valueRange, completionContext.tokenOffset, compItemForCurrentEnum.length)
                    : null;
                const completionItem: CompletionItem = {
                    id: qualifiedName,
                    name: textName,
                    text: textName,
                    category: CompletionItemCategory.EnumerationMember,
                    detail: item.description || '',
                    deprecated: !!enums.deprecated,
                    affectedRange
                };
                completionItems.push(completionItem);
            }
        });
    }
    return completionItems;
};

interface EnumMemberInfo {
    index: number;
    isValid: boolean;
    isCaseIssue: boolean;
    isDuplicate: boolean;
    deprecated: {
        isDeprecated: boolean;
        description: string;
    };
    experimental: { type: string; value: string };
    offset: number;
    text: string;
    correctText?: string;
}

function getReducer(
    value: string,
    enums: EnumType,
    duplicateValueMap: {
        [enumValue: string]: number;
    }
) {
    return (acc: EnumMemberInfo[], item: ResolvedEnumValue, index: number) => {
        const valid = !!item.enumMember;
        const isCaseIssue = !!item.caseInsensitiveEnumMember;
        let offset = value.indexOf(item.text);
        value = value.slice(offset + item.text.length);
        if (index !== 0) {
            const prviousOffset = acc[index - 1].offset + acc[index - 1].text.length;
            offset = prviousOffset + offset;
        }
        let experimentalValue;
        if (valid) {
            experimentalValue = item.enumMember.experimental;
        } else if (isCaseIssue) {
            experimentalValue = item.caseInsensitiveEnumMember.experimental;
        }
        const info: EnumMemberInfo = {
            index,
            isValid: valid,
            isCaseIssue,
            deprecated: { isDeprecated: enums.deprecated, description: enums.deprecatedDescription },
            experimental: {
                type: enums.experimental,
                value: experimentalValue
            },
            offset,
            isDuplicate: false,
            text: item.text,
            correctText: item.correctText
        };
        if (valid) {
            duplicateValueMap[item.text] = duplicateValueMap[item.text] ? duplicateValueMap[item.text] + 1 : 1;
        }
        acc.push(info);
        return acc;
    };
}

function processItem(
    fragmentRanges: Range[],
    valueRange: Range,
    duplicateValueMap: {
        [enumValue: string]: number;
    },
    messages: Diagnostic[]
) {
    return (item) => {
        if (item.isCaseIssue) {
            let message = i18n.t('Invalid_enum_value_0', { value: item.text });
            const hint = i18n.t('Did_you_mean_0', {
                proposedValue: item.correctText
            });
            message = `${message}. ${hint}`;
            message = message.replace(/&#x2F;/g, '/');
            const range = fragmentRanges
                ? fragmentRanges[item.index]
                : getValueFragmentRange(valueRange, item.offset, item.text.length);
            const diagnostic: Diagnostic = {
                severity: DiagnosticSeverity.Error,
                message: message,
                range: range,
                rule: INVALID_ENUM_MEMBER_TYPE,
                data: {
                    caseCheck: {
                        value: item.text,
                        proposedValue: item.correctText,
                        lookupPath: ['vocabularies', item.text],
                        isNamespacedValue: false
                    }
                } as CaseCheckBase
            };
            messages.push(diagnostic);
        }
        if (!item.isValid && !item.isCaseIssue) {
            let message = i18n.t('Invalid_enum_value_0', { value: item.text });
            message = message.replace(/&#x2F;/g, '/');
            const range = fragmentRanges
                ? fragmentRanges[item.index]
                : getValueFragmentRange(valueRange, item.offset, item.text.length);
            const diagnostic: Diagnostic = {
                severity: DiagnosticSeverity.Error,
                message: message,
                range: range,
                rule: INVALID_ENUM_MEMBER_TYPE,
                data: {
                    value: item.text
                }
            };
            messages.push(diagnostic);
        }
        if (item.isValid && duplicateValueMap[item.text] > 1) {
            const message = i18n.t('Duplicate_enum_value');
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Warning,
                range: fragmentRanges
                    ? fragmentRanges[item.index]
                    : getValueFragmentRange(valueRange, item.offset, item.text.length)
            });
        }
        if (item.deprecated.isDeprecated) {
            const deprecationDescription = item.deprecated.description ? ': ' + item.deprecated.description : '';
            const message = i18n.t('Enum_value_is_deprecated_0', {
                deprecationDescription: deprecationDescription
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Warning,
                range: fragmentRanges
                    ? fragmentRanges[item.index]
                    : getValueFragmentRange(valueRange, item.offset, item.text.length)
            });
        }
        if (!!item.experimental.type || !!item.experimental.value) {
            const info = item.experimental.type
                ? 'type: ' + item.experimental.type
                : 'value: ' + item.experimental.value;
            const message = i18n.t('Experimental_0', {
                info: info
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Information,
                range: fragmentRanges
                    ? fragmentRanges[item.index]
                    : getValueFragmentRange(valueRange, item.offset, item.text.length)
            });
        }
    };
}

const enumCheck = (
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    value: string,
    valueRange: Range,
    fragmentRanges?: Range[]
): Diagnostic[] => {
    const enums = valueHandlingContext.context.vocabularies.getType(type.name) as EnumType;
    const context: Context = valueHandlingContext.context;
    const resolvedEnumType: ResolvedName = resolveName(type.name, valueHandlingContext.aliasInfo.aliasMap);
    const namespace: NamespaceString = resolvedEnumType.namespace;
    const possiblePrefixes = getNamespaceAndAlias(namespace, valueHandlingContext.aliasInfo, context);

    const typeName = type.name.substring(type.name.lastIndexOf('.') + 1);
    const duplicateValueMap: {
        [enumValue: string]: number;
    } = {};
    const messages: Diagnostic[] = [];
    if (enums) {
        const isFlags = enums.isFlags;
        const currentEnumMembers = resolveCurrentValueList(value, enums, typeName, possiblePrefixes);
        const enumMemberInfo = currentEnumMembers.reduce(getReducer(value, enums, duplicateValueMap), []);
        if (currentEnumMembers.length > 0) {
            enumMemberInfo.forEach(processItem(fragmentRanges, valueRange, duplicateValueMap, messages));
        } else {
            const message = i18n.t('Enum_value_required');
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: valueRange
            });
        }

        if (!isFlags && enumMemberInfo.length > 1) {
            const message = i18n.t('Multiple_enum_values_not_allowed');
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: valueRange
            });
        }
    }
    return messages;
};

/**
 * handleEnumMember
 * @param type - enum meber needs to comply to valueHandlingContext type
 * @param value - current value
 * @param valueRange - LSP position information for value
 * @param forCompletion - false: check pathValue
 * @param startString: when forCompletion - only return items with this start string
 */
export function handleEnumValue(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    value: string,
    valueRange: Range,
    forCompletion?: boolean,
    startString?: string,
    fragmentRanges?: Range[]
): Diagnostic[] | CompletionItem[] {
    if (forCompletion) {
        return enumComplete(valueHandlingContext, type, value, valueRange, startString);
    } else {
        return enumCheck(valueHandlingContext, type, value, valueRange, fragmentRanges);
    }
}

export function enumHover(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    value: string,
    valueRange: Range,
    position: Position
): Hover {
    let hover: Hover;
    const enums = valueHandlingContext.context.vocabularies.getType(type.name) as EnumType;
    const resolvedEnumType: ResolvedName = resolveName(type.name, valueHandlingContext.aliasInfo.aliasMap);
    const namespace: NamespaceString = resolvedEnumType.namespace;
    const fullyQualifiedName = type.name;
    const possiblePrefixes = getNamespaceAndAlias(
        namespace,
        valueHandlingContext.aliasInfo,
        valueHandlingContext.context
    );

    if (enums) {
        const currentValueList = resolveCurrentValueList(value, enums, resolvedEnumType.name, possiblePrefixes);
        for (const currentValue of currentValueList) {
            const enumValue = currentValue.name.split('/').pop();
            const offset = value.toString().indexOf(currentValue.text);
            const range = getValueFragmentRange(valueRange, offset, currentValue.text.length);
            if (
                position.line === range.start.line &&
                position.character > range.start.character &&
                position.character < range.end.character &&
                currentValue.enumMember
            ) {
                hover = {
                    contents: {
                        kind: MarkupKind.Markdown,
                        value: valueHandlingContext.context.vocabularies
                            .getDocumentation(fullyQualifiedName, enumValue, valueHandlingContext.aliasInfo)
                            .join('\n')
                    },
                    range: range
                };
                break;
            }
        }
    }

    return hover;
}
