import type { CompletionItem } from '../types/general';
import { CompletionItemCategory, CompletionItemType } from '../types/general';
import type { Edm, Edmx, ODataNamespaceAlias } from '@sap-ux/odata-annotation-core';
import { SnippetBase } from '@sap/ux-annotation-utils';
import type { DynamicExpressionSpecial } from '../specification';

import { dynamicExpressionSpecialMap } from '../specification';

export const SNIPPET_FINAL_TABSTOP_ID = 0;

export interface SnippetPlaceholder {
    id: number;
    value: string;
    nested?: SnippetPlaceholder[];
}

export class Snippet extends SnippetBase {
    metadata: DynamicExpressionSpecial;

    constructor(
        name: Edm | Edmx,
        useSnippetSyntax: boolean,
        initialTabStopIndex = 1,
        namespaceAlias?: ODataNamespaceAlias
    ) {
        super(name, useSnippetSyntax, initialTabStopIndex, namespaceAlias);
        this.metadata = dynamicExpressionSpecialMap[name];
    }

    // adds mandatory attributes that haven't set up yet (based on metadata info)
    addMandatoryAttributesWithTabStops(): Snippet {
        ((this.metadata && this.metadata.mandatoryAttributes) || []).forEach((attr) => {
            if (!this.generic.attributes[attr]) {
                this.setAttribute(attr, this.getTabStopText(this.getNextTabStopId()));
            }
        });
        return this;
    }

    // adds both mandatory and optional attributes that haven't set up yet (based on metadata info)
    addEmptyAttributesWithTabStops(): Snippet {
        this.addMandatoryAttributesWithTabStops();
        ((this.metadata && this.metadata.optionalAttributes) || []).forEach((attr) => {
            if (!this.generic.attributes[attr]) {
                const ts1 = this.getNextTabStopId();
                const ts2 = this.getNextTabStopId();
                this.setAttribute(
                    this.getPlaceHolderText({
                        id: ts2,
                        value: `${attr}="${this.getTabStopText(ts1)}"`
                    })
                );
            }
        });
        return this;
    }
    toCompletionItem(
        labelExtension?: string,
        notMandatoryOption = false,
        category?: CompletionItemCategory,
        overrideLabel = false
    ): CompletionItem {
        const text = `${overrideLabel ? '' : this.generic.name} ${labelExtension || ''}`.trim();
        const compItem: CompletionItem = {
            text: text,
            name: text,
            insertText: text,
            filterText: text,
            category: category || CompletionItemCategory.ValueElement,
            data: this.generic,
            type: CompletionItemType.Snippet
        };
        if (notMandatoryOption) {
            compItem.sorting = { isNotMandatory: true };
        }
        return compItem;
    }
    // adds content as string nodes or nested elements
    appendContent(content: string | Snippet | (string | Snippet)[]): Snippet {
        if (!Array.isArray(content)) {
            content = [content];
        }

        content.forEach((item) => {
            if (typeof item === 'string') {
                this.generic.content.push(this.generateTextNode(item));
            } else {
                this.generic.content.push(item.generic);
            }
        });
        return this;
    }

    // redefine return type for inherited methods returning SnippetBase
    appendTabStopToContent(id?: number): Snippet {
        return super.appendTabStopToContent(id) as Snippet;
    }

    appendFinalTabStopToContent(): Snippet {
        return super.appendFinalTabStopToContent() as Snippet;
    }

    appendNextTabStopToContent(): Snippet {
        return super.appendNextTabStopToContent() as Snippet;
    }

    setAttribute(name: string, value?: string): Snippet {
        return super.setAttribute(name, value) as Snippet;
    }

    setAttributeAsTabStop(id?: number): Snippet {
        return super.setAttributeAsTabStop(id) as Snippet;
    }

    setAttributeAsFinalTabStop(): Snippet {
        return super.setAttributeAsFinalTabStop() as Snippet;
    }

    setAttributeWithPlaceholderValue(name: string, ph: SnippetPlaceholder): Snippet {
        return super.setAttributeWithPlaceholderValue(name, ph) as Snippet;
    }
}
