import type { Range } from 'vscode-languageserver-types';

import type { VocabularyService } from '@sap-ux/odata-vocabularies';

import { createErrorDiagnosticWithRule } from './ruleFactories';
import type { MetadataUri } from '../loaders/manifest';
import { i18n } from '../i18n';
import type { NoUndefinedNamespaceDiagnostic, NamespaceString, Alias } from '@sap-ux/odata-annotation-core';
import { NO_UNDEFINED_NAMESPACE_TYPE } from '@sap-ux/odata-annotation-core';

export function createUnknownVocabularyDiagnostic(
    value: NamespaceString | Alias,
    namespace: NamespaceString,
    range: Range,
    vocabularies: VocabularyService
): NoUndefinedNamespaceDiagnostic {
    let message = '';
    if (value === namespace) {
        message = i18n.t('Unknown_Vocabulary_Do_you_mean_0_namespace', {
            namespace: namespace
        });
    } else {
        message = i18n.t('Unknown_Vocabulary_Do_you_mean_alias_0_from_1_namespace', {
            alias: value,
            namespace: namespace
        });
    }
    const diagnostic: NoUndefinedNamespaceDiagnostic = createErrorDiagnosticWithRule(
        NO_UNDEFINED_NAMESPACE_TYPE,
        message,
        range,
        undefined
    );
    const guessedVocabulary = vocabularies.getVocabulary(namespace);

    if (namespace && guessedVocabulary) {
        diagnostic.data = {
            namespace: guessedVocabulary.namespace,
            alias: guessedVocabulary.defaultAlias,
            referenceUri: guessedVocabulary.defaultUri
        };
    }

    return diagnostic;
}

export function createUnknownMetadataDiagnostic(
    namespace: NamespaceString,
    range: Range,
    metadataUri: MetadataUri
): NoUndefinedNamespaceDiagnostic {
    const message = i18n.t('Unknown_Namespace_Do_you_mean_Metadata_namespace_0', {
        namespace: namespace
    });
    const diagnostic: NoUndefinedNamespaceDiagnostic = createErrorDiagnosticWithRule(
        NO_UNDEFINED_NAMESPACE_TYPE,
        message,
        range
    );
    if (namespace) {
        diagnostic.data = {
            namespace: namespace,
            referenceUri: metadataUri
        };
    }

    return diagnostic;
}
