import { Range } from '@sap-ux/odata-annotation-core-types';

import type {
    XsnArtifact,
    XsnCompileModel,
    XsnKind,
    XsnLocation,
    XsnAnnotationAssignment,
    XsnAnnotatedObject,
    XsnObject,
    XsnNamedObject,
    ICdsCompiler,
    XsnElement
} from '@sap/cds-compiler';

import type { AnnotationFile, Target, ServiceAnnotationFile } from '@sap-ux/odata-annotation-core';
import { rangeContained, GHOST_FILENAME_PREFIX } from '@sap-ux/odata-annotation-core';
import { fileURLToPath } from 'url';
import { getNameObj } from '../utils';
import { locationToRange } from './rangeConverters';
import { convertNameToEdmxInternal } from '../metadata';

const kindsForPropagation: XsnKind[] = ['element', 'entity', 'type', 'view', 'action', 'function'];

export interface PropagatedTargetMap {
    [sourceTarget: string]: {
        [target: string]: boolean;
    };
}

// cache results of findSourceTargetName()
const sourceTargetNameForLocation: Map<string, string> = new Map();

export type Files = {
    uri: string;
    content: AnnotationFile;
};

type TargetMap = {
    propTargetMap: PropagatedTargetMap;
    existingTargetMap: Set<string> | undefined;
    visitedTargetMap: { [key: string]: boolean };
    sourceUris: Set<string>;
};

const getNamespace = (fullyQualifiedName: string): string => {
    const parts = fullyQualifiedName.split('.');
    parts.pop();
    return parts.join('.');
};

/**
 * Function generates a map of propagated targets (per file), i.e.
 * original target => list of targets to which original annotations are propagated
 * The map is used to build ghost files with propagated annotations
 * @param ast - XSN compile model
 * @param serviceName - name of service for which API was instantiated (API use case)
 *      used to limit propagation data by the scope which is relevant for API consumers
 * @param files - array of source files in generic format (LSP use case)
 */
export const toPropagatedTargetMap = (
    ast: XsnCompileModel,
    serviceName?: string,
    files?: Files[]
): { propagationMap: PropagatedTargetMap; sourceUris: Set<string> } => {
    const targetMaps: TargetMap = {
        propTargetMap: {},
        existingTargetMap: undefined,
        visitedTargetMap: {},
        sourceUris: new Set()
    };

    sourceTargetNameForLocation.clear();
    if (files && files.length > 0) {
        // LSP use case, existing targets are taken from generic files
        targetMaps.existingTargetMap = new Set();
        getTargetsFromGenericFiles(ast, files, targetMaps);
    } else {
        // API use case, targets are taken from service definition artifacts
        const targetArtifacts = getTargetFromServiceDef(serviceName, ast);
        targetArtifacts.forEach((artifact) => {
            // entities, (unbound) actions/functions
            const artifactName =
                getNameObj(artifact, ast.compiler).absolute +
                (['action', 'function'].includes(artifact.kind) ? '()' : '');

            buildMapForTarget(targetMaps, ast, artifactName, [], artifact, false);

            // entity elements
            checkEntityElements(artifact, targetMaps, artifactName, ast);

            // bound actions/functions
            checkTargetsOfBoundActionAndFunction(artifact, targetMaps, artifactName, ast);

            // parameters (of unbound actions functions)
            for (const name of Object.keys(artifact.params || {})) {
                const param = artifact?.params?.[name];
                if (param) {
                    const paramName = getNameObj(param, ast.compiler).param;
                    buildMapForTarget(targetMaps, ast, artifactName, [paramName], param);
                }
            }
        });
    }

    return { propagationMap: targetMaps.propTargetMap, sourceUris: targetMaps.sourceUris };
};

function checkEntityElements(
    artifact: XsnArtifact,
    targetMaps: TargetMap,
    artifactName: string,
    ast: XsnCompileModel
): void {
    Object.keys(artifact.elements || {}).forEach((name) => {
        const element = artifact?.elements?.[name];
        if (element) {
            buildMapForTarget(targetMaps, ast, artifactName, [getNameObj(element, ast.compiler).element], element);
        }
    });
}

function checkTargetsOfBoundActionAndFunction(
    artifact: XsnArtifact,
    targetMaps: TargetMap,
    artifactName: string,
    ast: XsnCompileModel
): void {
    Object.keys(artifact.actions || {}).forEach((name) => {
        const action = artifact?.actions?.[name];
        const namespace = getNamespace(artifactName);
        if (action) {
            const actionName = getNameObj(action, ast.compiler).action;
            const actionFQName = `${namespace}.${actionName}(${artifactName})`;
            buildMapForTarget(targetMaps, ast, actionFQName, [], action);
            //  parameter of bound actions functions
            Object.keys(action.params || {}).forEach((pname) => {
                const param = action?.params?.[pname];
                if (param) {
                    buildMapForTarget(targetMaps, ast, actionFQName, [getNameObj(param, ast.compiler).param], param);
                }
            });
        }
    });
}

function buildMapForTarget(
    targetMaps: TargetMap,
    ast: XsnCompileModel,
    targetName: string,
    targetPathSegments: string[],
    targetDefinition: XsnObject,
    isPropagatedElement = false
): void {
    const fullTargetName = [targetName, ...targetPathSegments].join('/');
    // No need to process each specific target multiple times
    // because we are replicating all annotations propagated to this target at once.
    // In LSP use case propagation is taking place for existing targets only
    if (
        !targetMaps.visitedTargetMap[fullTargetName] &&
        (!targetMaps.existingTargetMap || targetMaps.existingTargetMap.has(fullTargetName))
    ) {
        targetMaps.visitedTargetMap[fullTargetName] = true;
        const propagatedAnnotationRefs = getPropogatedAnnoRefs(targetDefinition, isPropagatedElement);

        prepareMapWithTargets(ast, propagatedAnnotationRefs, fullTargetName, targetMaps);

        // propagation of annotations applied to navigation property target
        const finalType = targetDefinition._effectiveType;
        if (finalType) {
            const targetArtifact = finalType.kind === 'element' && finalType.target && finalType.target._artifact;
            if (targetArtifact && ['entity', 'view'].includes(targetArtifact.kind) && targetArtifact.name) {
                buildMapForTarget(
                    targetMaps,
                    ast,
                    getNameObj(targetArtifact, ast.compiler).absolute,
                    [],
                    targetArtifact,
                    true
                );
            }
        }

        // propagation of annotations applied to nested elements of target
        Object.keys(finalType?.elements ?? {}).forEach((key) => {
            if (finalType?.elements?.[key]) {
                buildMapForTarget(
                    targetMaps,
                    ast,
                    targetName,
                    [...targetPathSegments, key],
                    finalType.elements[key],
                    isPropagatedElement
                );
            }
        });
    }
}

function getTargetsFromGenericFiles(ast: XsnCompileModel, files: Files[], targetMaps: TargetMap) {
    const existingTargets: Target[] = [];
    files.forEach((file) => {
        existingTargets.push(...(file.content.targets ?? []));
    });
    existingTargets.forEach((t) => targetMaps?.existingTargetMap?.add(t.name));
    existingTargets.forEach((currentTarget) => {
        const path = currentTarget.name.split('/');
        const targetBaseName = path.shift() as string;
        const intermediateTargetPath: string[] = [];
        const rootDefinition = ast.definitions[targetBaseName];
        if (rootDefinition) {
            let doPropagation = false;
            // find target subelement by element path
            let definition: XsnObject = rootDefinition;
            let isPropagatedElement = false;
            while (definition && path.length) {
                // starting propagation at the outermost entity type or complex type
                doPropagation = doPropagation || kindsForPropagation.includes(definition.kind);
                if (doPropagation) {
                    buildMapForTarget(
                        targetMaps,
                        ast,
                        targetBaseName,
                        intermediateTargetPath,
                        definition,
                        isPropagatedElement
                    );
                }

                const elementName = path.shift() as string;
                definition = (definition._effectiveType?.elements ?? {})[elementName];
                if (definition) {
                    // element considered as propagated when it has $inferred in its type definition
                    // all nested elements considered as propagated as well
                    isPropagatedElement =
                        isPropagatedElement ||
                        (definition &&
                            (definition._effectiveType as any) !== definition &&
                            definition.type?.$inferred === 'prop');
                }
                intermediateTargetPath.push(elementName);
            }
            if (definition) {
                buildMapForTarget(
                    targetMaps,
                    ast,
                    targetBaseName,
                    intermediateTargetPath,
                    definition,
                    isPropagatedElement
                );
            }
        }
    });
}

function getPropogatedAnnoRefs(targetDefinition: XsnObject, isPropagatedElement: boolean): XsnObject[] {
    return Object.keys(targetDefinition)
        .filter((key) => key.startsWith('@'))
        .map((key) => targetDefinition[key])
        .filter((ann) => ann.$inferred === 'prop' || isPropagatedElement)
        .reduce((acc, current) => {
            if (Array.isArray(current)) {
                return [...acc, ...current];
            }

            return [...acc, current] as any;
        }, []);
}

function prepareMapWithTargets(
    ast: XsnCompileModel,
    propagatedAnnotationRefs: XsnObject[],
    fullTargetName: string,
    maps: TargetMap
): void {
    propagatedAnnotationRefs.forEach((ref) => {
        // look up for original annotation instance
        const location = ref.location || ref.name?.location;
        if (location) {
            const sourceTargetName = findSourceTargetName(ast, location);
            if (sourceTargetName && sourceTargetName !== fullTargetName) {
                if (location.file) {
                    maps.sourceUris.add(location.file);
                }
                const sourceTargetNameCorrected = convertNameToEdmxInternal(sourceTargetName, ast);
                const fullTargetNameCorrected = convertNameToEdmxInternal(fullTargetName, ast);
                maps.propTargetMap[sourceTargetNameCorrected] = maps.propTargetMap[sourceTargetNameCorrected] ?? {};
                maps.propTargetMap[sourceTargetNameCorrected][fullTargetNameCorrected] = true;
            }
        }
    });
}

function getTargetFromServiceDef(serviceName: string | undefined, ast: XsnCompileModel): XsnArtifact[] {
    const targetArtifacts: XsnArtifact[] = [];
    if (serviceName) {
        if (ast.definitions[serviceName]?.kind === 'service') {
            const serviceArtifacts: XsnArtifact[] = Object.keys(ast.definitions[serviceName].artifacts ?? {}).map(
                (name) => ast?.definitions?.[serviceName]?.artifacts?.[name]
            ) as XsnArtifact[];
            targetArtifacts.push(...serviceArtifacts.filter((artifact) => kindsForPropagation.includes(artifact.kind)));
        }
    } else {
        const allArtifacts = getArtifactsRecursively(
            Object.keys(ast.definitions ?? {}).map((name) => ast.definitions[name])
        );
        targetArtifacts.push(...allArtifacts.filter((artifact) => kindsForPropagation.includes(artifact.kind)));
    }
    return targetArtifacts;
}

function getArtifactsRecursively(artifacts: XsnArtifact[]): XsnArtifact[] {
    const newArtifacts: XsnArtifact[] = [];
    for (const artifact of artifacts) {
        newArtifacts.push(
            ...(Object.keys(artifact.artifacts || {}).map((name) => artifact?.artifacts?.[name]) as XsnArtifact[])
        );
    }
    if (newArtifacts.length) {
        return [...newArtifacts, ...getArtifactsRecursively(newArtifacts)];
    } else {
        return newArtifacts;
    }
}

const findAssignmentByRange = (element: XsnAnnotatedObject, range: Range): XsnAnnotationAssignment => {
    return (element.$annotations ?? []).find((a) => {
        return a?.location ? rangeContained(locationToRange(a.location) as Range, range) : false;
    }) as XsnAnnotationAssignment;
};

function getCachedResult(location: XsnLocation): string | undefined {
    const key = getCacheKey(location);
    if (sourceTargetNameForLocation.has(key)) {
        return sourceTargetNameForLocation.get(key);
    }
    return undefined;
}

function getCacheKey(location: XsnLocation): string {
    const { start, end } = locationToRange(location) || Range.create(0, 0, 0, 0);
    return `${location?.file} ${start.line}:${start.character}-${end.line}:${end.character}`;
}

const processArtifact = (
    annotatedObject: XsnAnnotatedObject,
    range: Range,
    compiler: ICdsCompiler,
    buildName: (artifact: XsnNamedObject) => string
): string => {
    const assignment = findAssignmentByRange(annotatedObject, range);
    if (assignment) {
        const carrierArtifact = annotatedObject?.name?._artifact || annotatedObject;
        const carrierArtifactName = getNameObj(carrierArtifact, compiler);
        if (carrierArtifactName?.absolute) {
            return buildName(carrierArtifact);
        }
    }
    return '';
};

function getArtifacts(ast: XsnCompileModel, location: XsnLocation): XsnArtifact[] {
    let artifacts: XsnArtifact[] = [];
    const sourceFileName = Object.keys(ast.sources).find(
        (fileName) => ast.sources[fileName].location?.file === location.file
    );
    if (sourceFileName) {
        const source = ast.sources[sourceFileName];
        artifacts = Object.keys(source.artifacts || {}).map((name) => source.artifacts[name]);
        artifacts.push(...getArtifactsRecursively(artifacts));
        if (source.extensions && source.extensions.length) {
            artifacts.push(...source.extensions);
        }
    }
    return artifacts;
}

function checkArtifactElements(ast: XsnCompileModel, artifact: XsnArtifact, annRange: Range): string {
    let result = '';
    // entity elements
    for (const name of Object.keys(artifact.elements || {})) {
        const element = artifact?.elements?.[name];
        if (element) {
            result = processArtifact(element, annRange, ast.compiler, (elementNamed: XsnNamedObject): string =>
                [getNameObj(elementNamed, ast.compiler).absolute, getNameObj(elementNamed, ast.compiler).element].join(
                    '/'
                )
            );
        }
        if (result) {
            break;
        }
    }
    return result;
}

function checkUnboundActionsFunctions(ast: XsnCompileModel, artifact: XsnArtifact, annRange: Range): string {
    let result = '';
    const buildArtifactName = (artifactNamed: XsnNamedObject): string =>
        getNameObj(artifactNamed, ast.compiler).absolute + (['action', 'function'].includes(artifact.kind) ? '()' : '');
    for (const name of Object.keys(artifact.params || {})) {
        const param = artifact?.params?.[name] as XsnElement;
        const buildParamName =
            (actionName: string) =>
            (paramNamed: XsnNamedObject): string => {
                return [actionName, getNameObj(paramNamed, ast.compiler).param].join('/');
            };
        const actionName = buildArtifactName(artifact);
        result = processArtifact(param, annRange, ast.compiler, buildParamName(actionName));
        if (result) {
            break;
        }
    }
    return result;
}

// Helper function to extract the action name
function getActionName(action: XsnNamedObject, compiler: any): string {
    return getNameObj(action, compiler).action;
}

function checkBoundActionsAndFunctions(
    name: string,
    ast: XsnCompileModel,
    artifact: XsnArtifact,
    annRange: Range
): string {
    let result = '';
    const action: XsnElement = artifact?.actions?.[name] as XsnElement;
    const actionName = getActionName(action, ast.compiler);
    if (actionName) {
        const buildArtifactName = (artifactNamed: XsnNamedObject): string =>
            getNameObj(artifactNamed, ast.compiler).absolute +
            (['action', 'function'].includes(artifact.kind) ? '()' : '');
        result = processArtifact(action, annRange, ast.compiler, buildArtifactName);

        if (!result) {
            //  parameter of bound actions functions
            for (const pname of Object.keys(action.params || {})) {
                const param = action?.params?.[pname] as XsnElement;
                result = processArtifact(param, annRange, ast.compiler, buildArtifactName);
                if (result) {
                    break;
                }
            }
        }
    }

    return result;
}

function buildEntityElement(ast: XsnCompileModel, artifact: XsnArtifact, annRange: Range): string {
    let result: string;
    // entity elements
    result = checkArtifactElements(ast, artifact, annRange);
    if (!result) {
        // bound actions/functions
        const entityName = getNameObj(artifact, ast.compiler).absolute;
        if (entityName) {
            for (const name of Object.keys(artifact.actions || {})) {
                result = checkBoundActionsAndFunctions(name, ast, artifact, annRange);
                if (result) {
                    break;
                }
            }
        }
    }
    if (!result) {
        // parameters (of unbound actions functions)
        result = checkUnboundActionsFunctions(ast, artifact, annRange);
    }
    return result;
}

function findSourceTargetName(ast: XsnCompileModel, location: XsnLocation): string {
    // try to get cached result
    let result = getCachedResult(location) || '';
    if (result) {
        return result;
    }

    const annRange = locationToRange(location) as Range;
    const artifacts = getArtifacts(ast, location);
    if (artifacts.length) {
        for (const artifact of artifacts.filter((item) => item.kind !== 'using')) {
            // entities, (unbound) actions/functions
            const buildArtifactName = (artifactNamed: XsnNamedObject): string =>
                getNameObj(artifactNamed, ast.compiler).absolute +
                (['action', 'function'].includes(artifact.kind) ? '()' : '');

            result = processArtifact(artifact, annRange, ast.compiler, buildArtifactName);
            if (!result) {
                // entity elements
                result = buildEntityElement(ast, artifact, annRange);
            }
            if (result) {
                break;
            }
        }
    }
    sourceTargetNameForLocation.set(getCacheKey(location), result);
    return result;
}

export function buildGhostFiles(
    ast: XsnCompileModel,
    files: { uri: string; content: AnnotationFile }[]
): ServiceAnnotationFile[] {
    const ghostFiles: { [uri: string]: AnnotationFile } = {};
    const { propagationMap, sourceUris } = toPropagatedTargetMap(ast, '', files);

    [...sourceUris.values()].forEach((relativeUri) => {
        const nodeModulesIndex = relativeUri.indexOf('node_modules');
        const relativeName = nodeModulesIndex > -1 ? relativeUri.slice(nodeModulesIndex) : relativeUri;
        const filesMatchingRelativePath = files.filter((f) => {
            const fullName = fileURLToPath(f.uri);
            return !(nodeModulesIndex === -1 && fullName.includes('node_modules')) && fullName.endsWith(relativeName);
        });
        // required file has shortest uri
        const sourceFile = filesMatchingRelativePath.sort((a, b) => a.uri.length - b.uri.length)[0];
        if (!sourceFile) {
            return;
        }
        const sourceTargets = sourceFile.content.targets;
        const ghostTargets: Target[] = [];
        sourceTargets.forEach((target) => {
            if (propagationMap[target.name]) {
                Object.keys(propagationMap[target.name]).forEach((propagatedTargetName) => {
                    const ghostTarget = Object.assign({}, target);
                    ghostTarget.name = propagatedTargetName;
                    ghostTargets.push(ghostTarget);
                });
            }
        });

        ghostFiles[sourceFile.uri] = Object.assign({}, sourceFile.content);
        ghostFiles[sourceFile.uri].targets = ghostTargets;
    });

    const result: ServiceAnnotationFile[] = files
        .filter((file) => !!ghostFiles[file.uri])
        .map((file) => ({
            uri: GHOST_FILENAME_PREFIX + file.uri,
            content: ghostFiles[file.uri],
            serviceName: 'default'
        }));

    return result;
}
