import type { AnnotationNode } from '@sap-ux/cds-annotation-parser';
import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, TextEdit } from 'vscode-languageserver';

import type { CompletionItemAdapterParams, CompletionItemAdapterWithGate, PropertyNameContext } from '../types';

export const TYPE_PROPERTY_NAME = '$Type';

function gate({ originalItem }: CompletionItemAdapterParams<PropertyNameContext>): boolean {
    return originalItem.label === '$CdsRecordType$';
}

function adapter({
    context: { proposedReplacementRange: replacementRange, flattened, pathToNode, propertyName },
    originalItem
}: CompletionItemAdapterParams<PropertyNameContext>): CompletionItem | undefined {
    if (flattened) {
        return undefined;
    }
    if (!getRecordTypePropertyNode(pathToNode.slice(-3)[0]) || propertyName === TYPE_PROPERTY_NAME) {
        return {
            label: TYPE_PROPERTY_NAME,
            insertTextFormat: InsertTextFormat.PlainText,
            kind: CompletionItemKind.Property,
            documentation: originalItem.documentation,
            sortText: ((propertyName || '').startsWith('@') ? 'Z' : 'A') + '000000',
            filterText: TYPE_PROPERTY_NAME,
            textEdit: TextEdit.replace(replacementRange, TYPE_PROPERTY_NAME)
        };
    }
    return undefined;
}

/**
 * Converts $CdsRecordType$ completion item into $Type property name
 */
export const recordTypePropertyNameAdapter: CompletionItemAdapterWithGate = {
    gate,
    adapter
};

export function getRecordTypePropertyNode(recordNode: AnnotationNode): AnnotationNode {
    const properties = recordNode['properties'] ?? [];
    return properties.find((property) => property.name.value === TYPE_PROPERTY_NAME);
}
