import type {
    Attribute,
    Edm,
    Edmx,
    EDMX_NAMESPACE_ALIAS,
    EDM_NAMESPACE_ALIAS,
    Element,
    TextNode
} from '@sap-ux/odata-annotation-core';
import { createElementNode, createAttributeNode, createTextNode } from '@sap-ux/odata-annotation-core';

export const SNIPPET_FINAL_TABSTOP_ID = 0;

export interface SnippetPlaceholder {
    id: number;
    value: string;
    nested?: SnippetPlaceholder[];
}

type NamespaceAlias = typeof EDMX_NAMESPACE_ALIAS | typeof EDM_NAMESPACE_ALIAS;

export class SnippetBase {
    protected readonly useSnippetSyntax: boolean;
    generic: Element;
    tabStopId: number;

    constructor(name: Edm | Edmx, useSnippetSyntax: boolean, initialTabStopIndex = 1, namespaceAlias?: NamespaceAlias) {
        this.useSnippetSyntax = useSnippetSyntax;
        this.tabStopId = initialTabStopIndex;

        this.generic = createElementNode({
            name,
            content: [],
            attributes: {},
            ...(namespaceAlias && { namespaceAlias })
        });
    }

    getNextTabStopId(): number {
        const currId = this.tabStopId;
        this.tabStopId++;
        return currId;
    }

    // adds content as string nodes or nested elements
    appendContent(content: string | SnippetBase | (string | SnippetBase)[]): SnippetBase {
        if (!Array.isArray(content)) {
            content = [content];
        }

        content.forEach((item) => {
            if (typeof item === 'string') {
                this.generic.content.push(this.generateTextNode(item));
            } else {
                this.generic.content.push(item.generic);
            }
        });
        return this;
    }

    // adds text node with tabstop to content
    appendTabStopToContent(id?: number): SnippetBase {
        this.appendContent(this.getTabStopText(id));
        return this;
    }

    appendFinalTabStopToContent(): SnippetBase {
        return this.appendTabStopToContent(0);
    }

    appendNextTabStopToContent(): SnippetBase {
        this.appendTabStopToContent(this.getNextTabStopId());
        return this;
    }

    setAttribute(name: string, value?: string): SnippetBase {
        this.generic.attributes[name] = this.generateAttribute(name, value);
        return this;
    }

    // adds attribute with tabstop text as attribute name
    setAttributeAsTabStop(id?: number): SnippetBase {
        if (this.useSnippetSyntax) {
            this.setAttribute(this.getTabStopText(typeof id === 'number' ? id : this.getNextTabStopId()));
        }
        return this;
    }

    setAttributeAsFinalTabStop(): SnippetBase {
        return this.setAttributeAsTabStop(0);
    }

    setAttributeWithPlaceholderValue(name: string, ph: SnippetPlaceholder): SnippetBase {
        this.generic.attributes[name] = this.generateAttribute(name, this.getPlaceHolderText(ph));
        return this;
    }

    getTabStopText(id?: number): string {
        return this.useSnippetSyntax ? '$' + (id || 0) : '';
    }

    getPlaceHolderText(placeholder: SnippetPlaceholder, separator = ' '): string {
        const nestedPlaceholders = (placeholder.nested || [])
            .map((item) => this.getPlaceHolderText(item, separator))
            .join(separator);
        return this.useSnippetSyntax
            ? `\${${placeholder.id}:${placeholder.value}${nestedPlaceholders}}`
            : `${placeholder.value}${nestedPlaceholders}`;
    }

    getChoicesText(opts: string | string[]): string {
        if (!this.useSnippetSyntax) {
            return '';
        }
        return `\${|${Array.isArray(opts) ? opts.join(',') : opts}|}`;
    }

    protected generateTextNode(text: string): TextNode {
        return createTextNode(text);
    }

    protected generateAttribute(name: string, value: string | undefined): Attribute {
        return createAttributeNode(name, value);
    }
}
