import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, Range, TextEdit } from 'vscode-languageserver';

import type { Element } from '@sap-ux/odata-annotation-core';
import { Edm } from '@sap-ux/odata-annotation-core';
import { print } from '@sap/ux-cds-odata-annotation-converter';
import { RECORD_PROPERTY_TYPE, RECORD_TYPE } from '@sap-ux/cds-annotation-parser';

import type {
    CompletionContext,
    CompletionHandlerArgs,
    CompletionItemAdapterParams,
    ModularCompletionHandler,
    ProviderResult,
    RecordContainerContext
} from '../types';
import { basicItemProvider, wrapWithExclamationSquareBrackets } from '../utils';
import { valueSnippetAdapter } from '../adapters/valueSnippet';
import { getRecordTypePropertyNode, TYPE_PROPERTY_NAME } from '../adapters/recordTypePropertyName';
import { CompletionItemCategory } from '@sap/ux-annotation-service/dist/types/general';

const VALUE_PROPERTY_NAME = '$value';

function recordContainerGate(context: CompletionContext): boolean {
    return context.type === 'container' && context.kind === 'record';
}

function remainingPropertiesGate({ originalItem }: CompletionItemAdapterParams): boolean {
    return originalItem.data?.generic?.category === 'ValueElementSet';
}

function remainingPropertiesAdapter({
    context: { position, hasComma },
    originalItem
}: CompletionItemAdapterParams<RecordContainerContext>): CompletionItem | undefined {
    const snippet: Element = JSON.parse(JSON.stringify(originalItem.data.generic.data));
    const snippetText = print(snippet);
    // TODO: fix print in adapter, so it does not add trailing commas. We should add comma here, not remove.
    const text = hasComma ? snippetText.substr(0, snippetText.length - 1) : snippetText;
    return {
        label: originalItem?.data?.generic.name,
        insertTextFormat: InsertTextFormat.Snippet,
        kind: CompletionItemKind.Snippet,
        sortText: originalItem?.sortText,
        textEdit: TextEdit.insert(position, text)
    };
}

function nestedAnnotationGate({ originalItem }: CompletionItemAdapterParams): boolean {
    return originalItem.data?.generic?.category === 'Annotation';
}

function nestedAnnotationAdapter({
    context: { position, hasComma },
    originalItem
}: CompletionItemAdapterParams<RecordContainerContext>): CompletionItem | undefined {
    const snippet: Element = JSON.parse(JSON.stringify(originalItem.data.generic.data));
    if (snippet.attributes?.Term?.value !== undefined) {
        // for snippet and insert text
        snippet.attributes.Term.value = wrapWithExclamationSquareBrackets(snippet.attributes.Term.value, true);
    }
    const text = `${print(snippet)}${hasComma ? '' : ','}`;
    return {
        label: wrapWithExclamationSquareBrackets(originalItem?.data?.generic.name, true),
        insertTextFormat: InsertTextFormat.Snippet,
        kind: CompletionItemKind.Class,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        textEdit: TextEdit.insert(position, text)
    };
}

function recordTypePropertyNameGate({ originalItem }: CompletionItemAdapterParams): boolean {
    return originalItem.label === '$CdsRecordType$';
}

function recordTypePropertyNameAdapter({
    context: { position, hasComma, pathToNode },
    originalItem
}: CompletionItemAdapterParams<RecordContainerContext>): CompletionItem | undefined {
    if (!getRecordTypePropertyNode(pathToNode.slice(-1)[0])) {
        const insertText = `\\$Type : '$0'${hasComma ? '' : ','}`;
        return {
            label: TYPE_PROPERTY_NAME,
            insertTextFormat: InsertTextFormat.Snippet,
            kind: CompletionItemKind.Property,
            documentation: originalItem.documentation,
            sortText: 'A000000',
            filterText: TYPE_PROPERTY_NAME,
            textEdit: TextEdit.insert(position, insertText)
        };
    }
    return undefined;
}

function customItemProvider(
    context: RecordContainerContext,
    { getCompletionItems, file, pointer, position }: CompletionHandlerArgs
): ProviderResult {
    const result = basicItemProvider(context, { getCompletionItems, file, pointer, position });

    result.itemsForAdapter.push({
        label: VALUE_PROPERTY_NAME,
        insertTextFormat: InsertTextFormat.Snippet,
        kind: CompletionItemKind.Property,
        sortText: '000000000',
        filterText: VALUE_PROPERTY_NAME,
        textEdit: TextEdit.replace(
            Range.create(context.position, context.position),
            `\\${VALUE_PROPERTY_NAME}: $0${context.hasComma ? '' : ','}`
        )
    });
    return result;
}

function filterAdapterGate({ originalItem, context }: CompletionItemAdapterParams<RecordContainerContext>): boolean {
    const snippet = originalItem?.data?.generic?.data as Element;
    if (originalItem.label === '$CdsRecordType$') {
        return false;
    } else if (originalItem.label === VALUE_PROPERTY_NAME) {
        const [parentNode, recordNode] = context.pathToNode.slice(-2);
        if (
            recordNode.type === RECORD_TYPE &&
            !(parentNode.type === RECORD_PROPERTY_TYPE && parentNode.name.value === VALUE_PROPERTY_NAME)
        ) {
            return !!recordNode.properties.length;
        }
    } else if (
        snippet?.name === Edm.PropertyValue ||
        [CompletionItemCategory.Annotation, CompletionItemCategory.ValueElementSet].includes(
            originalItem.data?.generic?.category
        )
    ) {
        return false;
    }
    return true;
}

function filterAdapter(): CompletionItem | undefined {
    return;
}

export const recordSnippetHandler: ModularCompletionHandler = {
    name: 'record-snippet',
    type: 'modular',
    gate: recordContainerGate,
    providers: [customItemProvider],
    mappers: [],
    adapters: [
        { gate: nestedAnnotationGate, adapter: nestedAnnotationAdapter },
        { gate: remainingPropertiesGate, adapter: remainingPropertiesAdapter },
        valueSnippetAdapter,
        { gate: recordTypePropertyNameGate, adapter: recordTypePropertyNameAdapter },
        { gate: filterAdapterGate, adapter: filterAdapter }
    ]
};
