import { Edm } from '@sap-ux/odata-annotation-core';
import type { CompletionItem } from 'vscode-languageserver';
import { InsertTextFormat, CompletionItemKind, TextEdit } from 'vscode-languageserver';
import type {
    CompletionContext,
    CompletionItemAdapterParams,
    CompletionItemAdapterWithGate,
    JsonElementNameContext,
    ModularCompletionHandler
} from '../types';
import { basicItemProvider } from '../utils';

function jsonElementNameGate(context: CompletionContext): boolean {
    return context.type === 'edm-json' && context.kind === 'element-name';
}

function jsonElementNameAdapter({
    context: { proposedReplacementRange: replacementRange },
    originalItem
}: CompletionItemAdapterParams<JsonElementNameContext>): CompletionItem | undefined {
    const insertText = `$${originalItem.insertText}`;
    return {
        label: insertText,
        insertTextFormat: InsertTextFormat.PlainText,
        kind: CompletionItemKind.Class,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        filterText: insertText,
        textEdit: TextEdit.replace(replacementRange, insertText)
    };
}

function filterGate({ originalItem }: CompletionItemAdapterParams): boolean {
    return originalItem.label === Edm.Annotation;
}

const filter: CompletionItemAdapterWithGate = { gate: filterGate, adapter: (): undefined => undefined };

export const jsonElementNameHandler: ModularCompletionHandler = {
    name: 'json-element-name',
    type: 'modular',
    gate: jsonElementNameGate,
    providers: [basicItemProvider],
    mappers: [],
    adapters: [jsonElementNameAdapter, filter]
};
