import { EMPTY_VALUE_TYPE, RECORD_PROPERTY_TYPE } from '@sap-ux/cds-annotation-parser';
import type { CompletionItem } from 'vscode-languageserver';
import type { CompletionItemAdapterParams, CompletionItemAdapterWithGate, ValueCompletionContext } from '../types';

export const annotationFilterAdapter: CompletionItemAdapterWithGate = {
    gate: ({ originalItem }: CompletionItemAdapterParams) => originalItem.data?.generic?.category === 'Annotation',
    adapter: ({
        context: { pathToNode },
        lastItem
    }: CompletionItemAdapterParams<ValueCompletionContext>): CompletionItem | undefined => {
        const [value] = pathToNode.slice(-1);
        if (value.type === EMPTY_VALUE_TYPE || (value.type === RECORD_PROPERTY_TYPE && value.name.value === '$value')) {
            return undefined;
        } else {
            return lastItem;
        }
    }
};
