import { Range } from 'vscode-languageserver';

import {
    PATH_TYPE,
    STRING_LITERAL_TYPE,
    BOOLEAN_TYPE,
    NUMBER_LITERAL_TYPE,
    ENUM_TYPE,
    EMPTY_VALUE_TYPE,
    COLLECTION_TYPE,
    ANNOTATION_TYPE
} from '@sap-ux/cds-annotation-parser';
import { nodeHasComma } from '../../../utils/hasComma';

import type {
    BooleanValueContext,
    CollectionValueContext,
    CompletionContextResolverArgs,
    EmptyValueContext,
    EnumValueContext,
    NumberValueContext,
    PathValueContext,
    StringValueContext
} from '../types';
import { findNodeWithMatchingPosition } from '../utils';

export function annotationValueResolver({
    pathToNode,
    targetNode,
    position
}: CompletionContextResolverArgs):
    | PathValueContext
    | StringValueContext
    | BooleanValueContext
    | NumberValueContext
    | EnumValueContext
    | EmptyValueContext
    | CollectionValueContext
    | undefined {
    if (pathToNode.length < 2) {
        return;
    }
    const parent = pathToNode[pathToNode.length - 2];
    if (parent.type !== ANNOTATION_TYPE) {
        return;
    }
    const hasComma = nodeHasComma(pathToNode, position);

    if (targetNode.type === PATH_TYPE) {
        const context: PathValueContext = {
            type: 'value',
            kind: 'annotation',
            valueType: PATH_TYPE,
            pathToNode,
            proposedReplacementRange: targetNode.range,
            position,
            hasComma
        };
        if (targetNode.segments.length === 1) {
            return context;
        }
        const segment = findNodeWithMatchingPosition(targetNode.segments, position);
        if (segment) {
            context.proposedReplacementRange = segment.range;
            return context;
        }
        const quoted = targetNode.segments.reduce((acc, segment) => acc || segment.quoted === true, false);
        if (quoted) {
            context.cursorInDelimiter = true;
            return context;
        }
    }
    if (
        targetNode.type === STRING_LITERAL_TYPE ||
        targetNode.type === BOOLEAN_TYPE ||
        targetNode.type === NUMBER_LITERAL_TYPE ||
        targetNode.type === ENUM_TYPE ||
        targetNode.type === EMPTY_VALUE_TYPE
    ) {
        return {
            type: 'value',
            kind: 'annotation',
            valueType: targetNode.type,
            pathToNode,
            proposedReplacementRange:
                targetNode.type === EMPTY_VALUE_TYPE ? Range.create(position, position) : targetNode.range,
            position,
            hasComma
        };
    }
    if (targetNode.type === COLLECTION_TYPE) {
        return {
            type: 'container',
            kind: 'collection',
            pathToNode,
            position,
            hasComma,
            proposedReplacementRange: Range.create(position, position)
        };
    }
}
