import type { XsnCompileModel } from '@sap/cds-compiler';
import type { BlitzIndex } from '@sap/ux-cds-compiler-facade';

import URI from 'vscode-uri';

export function getDependentFileUris(fileUrisRequested: string[], index: BlitzIndex, ast?: XsnCompileModel): string[] {
    const fileUrisCollected = [...fileUrisRequested];
    // add all dependent files
    for (const fileUriOriginal of fileUrisRequested) {
        const dependentFileUris = index.getTransitiveDependencies(fileUriOriginal);
        for (const dependentFileUri of dependentFileUris || new Set()) {
            if (index.forUri(dependentFileUri) && !fileUrisCollected.includes(dependentFileUri)) {
                fileUrisCollected.unshift(dependentFileUri);
            }
        }
    }
    if (!ast?.sources) {
        return fileUrisCollected;
    }
    // if ast is present: sort them based on appearance in ast
    const fileUris: string[] = [];
    const astFileUris = Object.keys(ast.sources).map((astSourceKey) => URI.file(astSourceKey).toString());
    for (const astFileUri of astFileUris) {
        const uri = fileUrisCollected.find((item) => URI.parse(item).toString() === astFileUri);
        if (uri) {
            fileUris.unshift(uri);
        }
    }
    return fileUris;
}
