import { Edm } from '@sap-ux/odata-annotation-core';
import { dynamicExpressionSignatureMap } from '../specification';
import type { CompletionItemCategory } from '../types/general';

export function removeDynamicExpressionsFromMap(elementMap: { [name: string]: CompletionItemCategory }): void {
    if (elementMap) {
        delete elementMap[Edm.Apply];
        [...dynamicExpressionSignatureMap.keys()].forEach((key) => delete elementMap[key]);
    }
}
