import type { Location } from 'vscode-languageserver';
import { toTargetMap, toAnnotationFile } from '@sap/ux-cds-odata-annotation-converter';
import { VocabularyService } from '@sap-ux/odata-vocabularies';
import { prepareAnnotationService } from '../annotationService';
import type { CdsDefinitionParams } from '../lspTypes';
import { createCdsCompilerFacade, createMetadataCollector } from '@sap/ux-cds-compiler-facade';

const vocabularyService = new VocabularyService(true);

export const getDefinition = ({
    cursorPosition,
    annotation,
    ast,
    index
}: CdsDefinitionParams): Location | Location[] | undefined => {
    const { position, textDocument } = cursorPosition;
    const fileUri = annotation.carrier.uri;
    const facade = createCdsCompilerFacade(ast);
    const cdsAnnotationFile = toTargetMap(index.forUri(textDocument.uri), textDocument.uri, vocabularyService, facade);
    const metadataElementMap = new Map();
    const metadataCollector = createMetadataCollector(metadataElementMap, facade);
    const { file: annotationFile, pointer } = toAnnotationFile(
        textDocument.uri,
        vocabularyService,
        cdsAnnotationFile,
        metadataCollector,
        position
    );

    // set definitionFileUri to real fileUri in each metadata element (it is used in LSP Location)
    const genericAnnotationService = prepareAnnotationService(
        vocabularyService,
        index,
        textDocument.uri,
        annotationFile,
        metadataCollector,
        {
            includeDependencies: true, //goto definition needs to see all splitted/overwritten parts (of e.g. record properties)
            annotationFileRestrictions: undefined,
            currentFileOnly: false,
            loadAllFiles: true,
            facade
        }
    );

    return genericAnnotationService.getDefinitionLocation(fileUri, position, pointer, true);
};
