import { SemanticTokenTypes } from 'vscode-languageserver-protocol';
import type { CdsSemanticTokensParams, ContributionContext, SemanticToken } from '../lspTypes';

import { VocabularyService } from '@sap-ux/odata-vocabularies';
import type { MetadataElementMap } from '@sap/ux-cds-compiler-facade';
import { createMetadataCollector } from '@sap/ux-cds-compiler-facade';
import { toAnnotationFile, toTargetMap } from '@sap/ux-cds-odata-annotation-converter';
import type { Range } from 'vscode-languageserver';

const tokenType = {
    term: SemanticTokenTypes.class,
    property: SemanticTokenTypes.property,
    path: SemanticTokenTypes.type,
    enumMember: SemanticTokenTypes.enumMember,
    qualifier: SemanticTokenTypes.parameter
};

export const getSemanticTokens = async (
    { uri, index }: CdsSemanticTokensParams,
    context?: ContributionContext
): Promise<SemanticToken[]> => {
    const semanticTokens: SemanticToken[] = [];
    // build dummy metadata containing all targets of annotation file (as entites)
    // hover does not depend much on metadata, only target path for current position must exist as metadata element
    const vocabularyService = new VocabularyService(true);
    const metadataElementMap: MetadataElementMap = new Map();
    const cdsAnnotationFile = toTargetMap(index.forUri(uri), uri, vocabularyService);
    cdsAnnotationFile.targetMap.forEach((target) =>
        metadataElementMap.set(target.name, {
            node: {
                kind: 'entity',
                path: target.name,
                isEntityType: true,
                isCollectionValued: true,
                isComplexType: false,
                isAnnotatable: true,
                name: target.name,
                content: [],
                targetKinds: ['EntityType']
            }
        })
    );

    const metadataCollector = createMetadataCollector(metadataElementMap);
    const { file: annotationFile } = toAnnotationFile(
        uri,
        vocabularyService,
        cdsAnnotationFile,
        metadataCollector,
        null
    );

    // collect semanticTokens
    processTargets(annotationFile.targets, semanticTokens);

    return Promise.resolve(semanticTokens);
};

/**
/* Convert Range into format which is expected by CDS API for semanticTokens
 */
const rangeToTokenPosition = (range: Range): SemanticToken => {
    if (range.start.line === range.end.line) {
        const length = range.end.character - range.start.character;
        return {
            line: Number(range.start.line),
            character: range.start.character,
            length: length,
            tokenType: SemanticTokenTypes.class,
            tokenModifiers: []
        };
    }
};

const processRecord = (record: any, semanticTokens: SemanticToken[]): void => {
    for (let m = 0; m < record.content.length; m++) {
        // content
        const item = record.content[m];
        if (item.attributes?.Property) {
            // Property
            const tokenPosition = rangeToTokenPosition(item.attributes.Property.valueRange);
            semanticTokens.push({
                ...tokenPosition,
                tokenType: tokenType.property,
                tokenModifiers: []
            });
        }
        if (item.attributes?.Term) {
            // Term of record
            const tokenPosition = rangeToTokenPosition(item.attributes.Term.valueRange);
            semanticTokens.push({
                ...tokenPosition,
                tokenType: tokenType.term,
                tokenModifiers: []
            });
        }

        // PropertyValue
        if (item.text) {
            // Path
            const tokenPosition = rangeToTokenPosition(item.range);
            semanticTokens.push({
                ...tokenPosition,
                tokenType: tokenType.path,
                tokenModifiers: []
            });
        } else {
            for (let n = 0; n < item.content.length; n++) {
                const propertyValue = item.content[n];
                if (propertyValue.name === 'Path' || propertyValue.name === 'PropertyPath') {
                    const tokenPosition = rangeToTokenPosition(propertyValue.contentRange);
                    semanticTokens.push({
                        ...tokenPosition,
                        tokenType: tokenType.path,
                        tokenModifiers: []
                    });
                }
                if (propertyValue.name === 'EnumMember') {
                    const tokenPosition = rangeToTokenPosition(propertyValue.contentRange);
                    semanticTokens.push({
                        ...tokenPosition,
                        tokenType: tokenType.enumMember,
                        tokenModifiers: []
                    });
                }
                if (propertyValue.name === 'Collection') {
                    processCollection(propertyValue.content, semanticTokens);
                }
            }
        }
    }
};

const processCollection = (collection: any, semanticTokens: SemanticToken[]): void => {
    for (let l = 0; l < collection.length; l++) {
        // Record
        const record = collection[l];
        processRecord(record, semanticTokens);
    }
};

const processTargets = (targets: any, semanticTokens: SemanticToken[]): void => {
    for (let i = 0; i < targets.length; i++) {
        const target = targets[i];
        for (let j = 0; j < target.terms.length; j++) {
            // Term
            const term = target.terms[j];
            const tokenPosition = rangeToTokenPosition(term.attributes.Term.valueRange);
            semanticTokens.push({ ...tokenPosition, tokenType: tokenType.term, tokenModifiers: [] });
            if (term.attributes.Qualifier) {
                // Qualifier
                const tokenPosition = rangeToTokenPosition(term.attributes.Qualifier.valueRange);
                semanticTokens.push({ ...tokenPosition, tokenType: tokenType.qualifier, tokenModifiers: [] });
            }
            for (let k = 0; k < term.content.length; k++) {
                if (term.content && term.content[k].name === 'Collection') {
                    // Collection
                    const collection = term.content[k].content;
                    processCollection(collection, semanticTokens);
                }
                if (term.content && term.content[k].name === 'Record') {
                    // Record
                    const record = term.content[k];
                    processRecord(record, semanticTokens);
                }
            }
        }
    }
};
