import { CompletionItemKind, InsertTextFormat } from 'vscode-languageserver-types';
import { EMPTY_VALUE_TYPE, RECORD_PROPERTY_TYPE } from '@sap-ux/cds-annotation-parser';
import type { CompletionItem } from 'vscode-languageserver';
import { CHILD_NODE_MAPPERS } from '../childNodeMappers';
import type { CompletionContext, CompletionItemAdapterParams, ModularCompletionHandler } from '../types';
import { recordTypeItemsProvider } from '../utils';

function handlerGate(context: CompletionContext): boolean {
    return (
        context.type === 'value' &&
        context.kind === 'property' &&
        context.valueType === EMPTY_VALUE_TYPE &&
        ((parent): boolean => parent.type === RECORD_PROPERTY_TYPE && parent.name.value.toLowerCase() === '$type')(
            context.pathToNode.slice(-2)[0]
        )
    );
}

const itemAdapter = ({ originalItem }: CompletionItemAdapterParams): CompletionItem | undefined => {
    return {
        label: `'${originalItem.label}'`,
        insertTextFormat: InsertTextFormat.PlainText,
        kind: CompletionItemKind.Constant,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText
    };
};

export const recordTypeValueHandler: ModularCompletionHandler = {
    name: 'record-type-value',
    type: 'modular',
    gate: handlerGate,
    providers: [recordTypeItemsProvider],
    mappers: [...CHILD_NODE_MAPPERS],
    adapters: [itemAdapter]
};
