import type { XsnKind } from '@sap/cds-compiler';

import type { GenericDefinition } from './types';

export class GenericDefinitionImpl implements GenericDefinition {
    constructor(
        public readonly symbolName: string,
        public readonly kind: XsnKind,
        public readonly absoluteName = symbolName
    ) {}

    /** @deprecated */
    public get fullyQualifiedName(): string {
        return this.symbolName;
    }
}
