import type { Context, ValueType } from '../types/context';
import { Edm } from '../types/edm';
import type {
    EnumType,
    ComplexTypeProperty,
    TypeDefinition,
    VocabularyObject,
    VocabularyType,
    Term
} from '@sap-ux/odata-vocabularies';
import TERM_KIND = Edm.TERM_KIND;
import type { MetadataElement, Facets, Constraints } from '@sap-ux/odata-annotation-core-types';
import type { FullyQualifiedName, Name } from '@sap-ux/odata-annotation-core';

/**
 * Lookup vocabulary type
 * @param name - e.g. "com.sap.vocabularies.UI.v1.Facet"
 */
export function getVocabularyType(context: Context, name: FullyQualifiedName): VocabularyType {
    return name.startsWith('Edm.') ? null : context.vocabularies.getType(name);
}

/**
 * Returns Annotation Term Element
 *   @param fullyQualifiedName     - Term with the namespace  e.g com.sap.vocabularies.Common.v1.Experimental

 *   @returns {Edm.SchemaChild}
 */
export function getVocabularyElementByKind(
    context: Context,
    name: FullyQualifiedName,
    kind: Edm.SchemaChildKind
): VocabularyObject {
    return kind === TERM_KIND ? context.vocabularies.getTerm(name) : context.vocabularies.getType(name);
}

export function getFacetsAndConstraints(
    context: Context,
    termOrProperty: Term | ComplexTypeProperty
): { facets: Facets; constraints: Constraints } {
    // build facets and constraints as new objects (no change of vocabulary content), merge with type definition facets
    const facets: Facets = Object.assign({}, termOrProperty.facets || {});
    const constraints: Constraints = Object.assign({}, termOrProperty.constraints || {});
    const type = getVocabularyType(context, termOrProperty.type);
    if (type && type.kind === Edm.TYPE_DEFINITION_KIND) {
        Object.keys(type.facets || {}).forEach((key) => {
            if (!facets[key]) {
                facets[key] = type.facets[key]; // take over facet from type definition
            }
        });
        Object.keys(type.constraints || {}).forEach((key) => {
            if (!constraints[key]) {
                constraints[key] = type.constraints[key]; // take over constraints from type definition
            }
        });
    }
    return { facets, constraints };
}

/**
 * get value type for complex type property
 * @param type
 * @param propertyName
 */
export function getValueTypeForComplexTypeProperty(
    context: Context,
    type: FullyQualifiedName,
    propertyName: Name
): ValueType {
    // get type for property of complex type
    const valueType: ValueType = { name: '', asCollection: false };
    const property = context.vocabularies.getComplexTypeProperty(type || '', propertyName);
    if (property) {
        valueType.name = property.type;
        valueType.asCollection = !!property.isCollection;
        const { facets, constraints } = getFacetsAndConstraints(context, property);
        if (Object.keys(constraints).length) {
            valueType.constraints = constraints;
        }
        if (Object.keys(facets).length) {
            valueType.facets = facets;
        }
        // adapt facets.isNullable depending on existence of default value
        if (isMandatoryProperty(property)) {
            valueType.facets = valueType.facets || {};
            valueType.facets.isNullable = false;
        }
    }
    return valueType;
}

export function getBuiltInTypeViaUnderlyingType(
    context: Context,
    vocabularyType: VocabularyObject,
    typeDefinitionOnly?: boolean
): string {
    let underlyingTypeName = '';
    if (
        vocabularyType.kind === Edm.TYPE_DEFINITION_KIND ||
        (vocabularyType.kind === Edm.ENUM_TYPE_KIND && !typeDefinitionOnly)
    ) {
        let currentType = vocabularyType;
        underlyingTypeName = currentType.underlyingType || '';
        while (underlyingTypeName && !underlyingTypeName.startsWith('Edm.')) {
            currentType = getVocabularyType(context, currentType.underlyingType) as TypeDefinition | EnumType;
            underlyingTypeName = currentType.underlyingType || '';
        }
        if (!underlyingTypeName && vocabularyType.kind === Edm.ENUM_TYPE_KIND) {
            underlyingTypeName = 'Edm.Int32'; // < 10.1 Underlying Integer Type >
        }
    }
    return underlyingTypeName;
}
export function lookupMetadataService(context: Context, name: FullyQualifiedName): MetadataElement {
    let typeObject;
    if (!name.startsWith('Edm.')) {
        typeObject = context.metadata.getMetadataElement(name);
    }
    return typeObject;
}

export function isMandatoryProperty(property: ComplexTypeProperty): boolean {
    return !(property.facets || {}).isNullable && property.defaultValue === undefined;
}
