import type { CodeActionParams, Range, WorkspaceEdit, Diagnostic } from 'vscode-languageserver';
import { TextEdit, CodeActionKind } from 'vscode-languageserver';
import type { CdsQuickfix } from '../lspTypes';
import type { CaseCheckBase, InvalidType } from '@sap-ux/odata-annotation-core';
import { i18n } from '@sap/ux-annotation-service';

export const getQuickFix = ({ context, textDocument }: CodeActionParams): CdsQuickfix[] => {
    const { diagnostics } = context;
    const { uri } = textDocument;
    const quickFix: CdsQuickfix[] = [];
    const amDiagnostics = context.diagnostics.filter((item) => item?.data !== undefined);

    for (let i = 0; i < amDiagnostics.length; i++) {
        const amDiagnostic = amDiagnostics[i];
        const data = amDiagnostic.data as CaseCheckBase & InvalidType;
        const value = data?.caseCheck?.proposedValue || data.proposedValue;
        if (diagnostics && value) {
            const range = getRange(amDiagnostic.range, value);
            const proposedValue = getProposedValue(amDiagnostic.range, data);
            const edit = TextEdit.replace(range, proposedValue);
            const workspaceEdit: WorkspaceEdit = {
                changes: {
                    [uri]: [edit]
                }
            };
            const title = getTitle(amDiagnostic);
            quickFix.push({
                title,
                kind: CodeActionKind.QuickFix,
                edit: workspaceEdit,
                diagnostics: [amDiagnostic]
            });
        }
    }
    return quickFix;
};

const getTitle = (amDiagnostic: Diagnostic): string => {
    const data = amDiagnostic.data as CaseCheckBase & InvalidType;
    let value = data?.caseCheck?.value || data.value;
    let proposedValue = data?.caseCheck?.proposedValue || data.proposedValue;
    const parts = proposedValue.split('.');
    if (data.alias && parts.length > 1) {
        if (isCharLenDiffer(amDiagnostic.range, proposedValue) === false) {
            // remove namespace or alias for group syntax i.e @(...)
            proposedValue = `${parts.pop()}`;
        } else {
            const charLen = amDiagnostic.range.end.character - amDiagnostic.range.start.character;
            if (charLen === proposedValue.length) {
                // correct title [with namespace] for simple syntax. i.e @Common.label #wrongTerm: 'incidents'
                value = `${data.alias}.${value}`;
            }
            if (charLen > proposedValue.length) {
                // correct title [with namespace] for inline annotation. i.e ![@Common.Label]'
                value = `${data.alias}.${value}`;
            }
        }
    }
    return i18n
        .t('Replace_0_with_1', {
            wrong: value,
            correct: proposedValue
        })
        .replace(/&#x2F;/g, '/');
};

const getProposedValue = (range: Range, data: CaseCheckBase & InvalidType): string => {
    let result = data?.caseCheck?.proposedValue || data.proposedValue;
    const parts = result.split('.');
    if (data.alias && parts.length > 1 && isCharLenDiffer(range, result) === false) {
        // remove namespace or alias for group syntax i.e @(...)
        result = `${parts.pop()}`;
    }
    return result;
};
/**
 * This is a work around to get range for cds inline annotation i.e ![@Common.Label]';
 * @Note: It is hard to distinguish between inline annotation i.e ![@Common.Label]' vs group annotation i.e @(...) or simple syntax in diagnostic api
 */
const getRange = (range: Range, proposedValue: string): Range => {
    if (isCharLenDiffer(range, proposedValue)) {
        const charLen = range.end.character - range.start.character;
        if (charLen > proposedValue.length) {
            const result: Range = {
                start: {
                    character: range.start.character + charLen - proposedValue.length - 1, // -1 exclude `]`
                    line: range.start.line
                },
                end: {
                    character: range.end.character - 1, // -1 exclude `]`
                    line: range.end.line
                }
            };
            return result;
        }
    }

    return range;
};

/**
 * Check character length
 * If character length is greater than proposed value, it is an inline annotation i.e ![@Common.label]
 * If character length is same, it is simple syntax i.e @Common.label
 */
const isCharLenDiffer = (range: Range, proposedValue: string): boolean => {
    let result = false;
    const charLen = range.end.character - range.start.character;
    if (charLen >= proposedValue.length) {
        result = true;
    }
    return result;
};
