import { DiagnosticSeverity } from 'vscode-languageserver-types';
import type { CompletionItem } from '..';
import type { Attribute, Element, ExtendedDiagnostic as Diagnostic } from '@sap-ux/odata-annotation-core';
import { Edm, ELEMENT_TYPE, getElementAttributeValue } from '@sap-ux/odata-annotation-core';
import { getPathTargetInElement, i18n } from '..';
import type { ValueHandlingContext } from '../types/context';
import { isValidSimpleIdentifier } from '../utils/general';
import type { JsonPath } from '../utils/path';
import { findTemplateParameterIndex, getTemplateVariableNames } from './functions';

/**
 * Handler for LabeledElement's Name attribute completion
 * @param element
 * @param path
 */
export function handleLabeledElementNameValue(element: Element, path: JsonPath): CompletionItem[] {
    // handle LabeledElement as sub node of Apply: only Name attribute needs to be handled here!
    // (if Name is set, remaining logic is handled for nested tag)
    let compItems: CompletionItem[] = [];
    const labeledElement = getPathTargetInElement(path, element);
    const target = getPathTargetInElement(labeledElement.remainingPathForElement, labeledElement.element);
    if (target.attribute && target.isAttributeName) {
        compItems = [
            {
                text: Edm.Name,
                name: Edm.Name,
                affectedRange: target.attribute.nameRange
            }
        ];
    } else if (target.attribute && target.isAttributeValue && target.attribute.name === Edm.Name) {
        const functionName = getElementAttributeValue(element, Edm.Function);
        // completion for attribute Name value - valueas are template variable names
        if (functionName === 'odata.fillUriTemplate') {
            const varNames = getTemplateVariableNames(element, findTemplateParameterIndex(functionName)[0]);
            const existingLabeledElelments = (element.content || []).filter(
                (node) => node.type === ELEMENT_TYPE && node.name === Edm.LabeledElement
            );
            const missingNames = varNames.filter(
                (item) =>
                    item === target.attribute.value || // current value is included if it is valid
                    !existingLabeledElelments.find((le) => getElementAttributeValue(le as Element, Edm.Name) === item)
            );

            compItems = missingNames.map((item) => ({
                text: item,
                name: item,
                affectedRange: target.attribute.valueRange
            }));
        }
    }

    return compItems;
}

/**
 * Check labeled element name
 * @param valueHandlingContext
 * @param attribute
 */
export function checkLabeledElementName(
    valueHandlingContext: ValueHandlingContext,
    attribute: Attribute
): Diagnostic[] {
    const messages: Diagnostic[] = [];
    const name = attribute.value || '';
    if (!name) {
        // name needs to be provided
        messages.push({
            message: i18n.t('Labeled_element_must_have_a_name'),
            severity: DiagnosticSeverity.Error,
            range: attribute.nameRange
        });
    } else if (!isValidSimpleIdentifier(name)) {
        // check name is valid simple identifier
        messages.push({
            message: i18n.t('Labeled_element_name_0_should_be_of_type_SimpleIdentifier', { name }),
            severity: DiagnosticSeverity.Error,
            range: attribute.valueRange || attribute.range
        });
    } else {
        // check uniqueness of name (among all siblings? in namespace?)
        let count = 0;
        const namespace = valueHandlingContext.aliasInfo.currentFileNamespace;
        Object.keys(valueHandlingContext.context.labeledElements).forEach((fileUris) => {
            if (valueHandlingContext.context.labeledElements[fileUris][namespace]) {
                count += valueHandlingContext.context.labeledElements[fileUris][namespace].countMap.get(name) || 0;
            }
        });
        if (count > 1) {
            messages.push({
                message: i18n.t('Labeled_element_name_0_must_be_unique_within_namespace_2', { name, namespace }),
                severity: DiagnosticSeverity.Error,
                range: attribute.valueRange || attribute.range
            });
        }
    }
    return messages;
}
