import type { Range, Element, FileContent, TextEdit } from '@sap-ux/odata-annotation-core';
import { isBefore } from '@sap-ux/odata-annotation-core';

/**
 * Applies text edits to document
 *
 * @param fileContent - Annotation element attribute
 * @param textEdits   - Edits that should be applied to a document
 * @param selfClosed  - Self closing XML elements (only relevant for XML)
 */
export function applyTextEdits(
    fileContent: FileContent,
    textEdits: TextEdit[],
    selfClosed?: Map<string, Element>
): FileContent {
    function isForOpeningSelfClosedTag(range: Range): boolean {
        return (
            selfClosed.has(range.start.line + ';' + range.start.character) &&
            range.start.line === range.end.line &&
            range.start.character + 1 === range.end.character
        );
    }

    // add text edits to open up auto closed elements - i.e. replace the self closing '/'
    selfClosed = selfClosed || new Map();
    selfClosed.forEach((element) => {
        const indentation = '\n' + ' '.repeat(element.range.start.character);
        textEdits.push({
            range: {
                start: { line: element.range.end.line, character: element.range.end.character - 2 },
                end: { line: element.range.end.line, character: element.range.end.character - 1 }
            },
            newText: `>${indentation}</` + element.name
        });
    });
    // sort text edits by range.start then range end (so deletions for the same start will be last)
    textEdits.sort((o1, o2) => {
        let r1: Range = o1.range;
        let r2: Range = o2.range;
        // text edits representing opening of self closed tags need to be carried out before any text edits that insert sub elements
        // this is reached by sorting them as if their range would be shifted one character to the right
        if (isForOpeningSelfClosedTag(r1)) {
            r1 = JSON.parse(JSON.stringify(r1));
            ++r1.start.character;
            ++r1.end.character;
        }
        if (isForOpeningSelfClosedTag(r2)) {
            r2 = JSON.parse(JSON.stringify(r2));
            ++r2.start.character;
            ++r2.end.character;
        }
        // sort by start position first, then by ed position
        // this way for same start position, deletion (have non empty range) come last
        if (isBefore(r1.start, r2.start)) {
            return -1;
        } else if (isBefore(r2.start, r1.start)) {
            return +1;
        } else if (isBefore(r1.end, r2.end)) {
            return -1;
        } else if (isBefore(r2.end, r1.end)) {
            return +1;
        } else {
            return 0;
        }
    });
    // apply text edits (in reverse order to keep the positions/ranges valid)
    const contentLines = fileContent.split('\n');
    const emptyLineIndexBeforeUpdate = [];
    contentLines.forEach((line, index) => {
        if (line.trim() === '') {
            emptyLineIndexBeforeUpdate.push(index);
        }
    });
    let emptyLines: number[] = [];
    const usingStatementInsertions: Set<string> = new Set();
    let previousTextEdit: TextEdit;
    for (let i = textEdits.length - 1; i >= 0; i--) {
        const textEdit = textEdits[i];
        if (previousTextEdit && isSameTextEdit(textEdit, previousTextEdit)) {
            continue; // ignore identical text edits (can happen for mass i18n generation)
        }
        let newText = textEdit.newText;
        // omit textEdit containing duplicate using statement
        if (newText.startsWith(`using from '`)) {
            if (usingStatementInsertions.has(newText)) {
                continue;
            } else {
                usingStatementInsertions.add(newText);
            }
        }
        // add new line indent text edits containing lines
        if (newText.indexOf('\n') === 0) {
            const parts = newText.split('\n');
            const textParts = [];
            for (let i = 1; i < parts.length; i++) {
                textParts.push('\n', parts[i]);
            }
            newText = String.prototype.concat.apply('', textParts);
        }
        // Create a new line for the first inserted text edit if the ending of the existing content is not EOL character
        // relevant if CDS file ends with a non empty line
        let newLine = '';
        if (i === textEdits.length - 1) {
            const startCharacter = textEdit.range.start.character;
            const textBeforeFirstInsert = contentLines[textEdit.range.start.line].substring(0, startCharacter);
            if (textBeforeFirstInsert.trim().length > 0 && textBeforeFirstInsert.endsWith(';')) {
                newLine = '\n';
            }
        }
        // use start line to apply text edit
        contentLines[textEdit.range.start.line] =
            contentLines[textEdit.range.start.line].substring(0, textEdit.range.start.character) +
            newLine +
            newText +
            contentLines[textEdit.range.end.line].substring(textEdit.range.end.character);
        // remove other lines covered by text edit range
        const deleteCount = textEdit.range.end.line - textEdit.range.start.line;
        if (deleteCount > 0) {
            // delete the empty lines deleted content range
            for (let i = textEdit.range.start.line + deleteCount; i >= textEdit.range.start.line; i--) {
                const deleteIndex = emptyLineIndexBeforeUpdate.findIndex((arg) => arg === i);
                if (deleteIndex >= 0) {
                    emptyLineIndexBeforeUpdate.splice(deleteIndex, 1);
                }
            }
            contentLines.splice(textEdit.range.start.line + 1, deleteCount);
            // adapt the empty lines indexes in emptyLineIndexBeforeUpdate
            for (let i = 0; i < emptyLineIndexBeforeUpdate.length; i++) {
                if (emptyLineIndexBeforeUpdate[i] > textEdit.range.start.line + deleteCount) {
                    emptyLineIndexBeforeUpdate[i] -= deleteCount;
                }
            }
        }
        previousTextEdit = textEdit;
    }
    emptyLines = [...emptyLineIndexBeforeUpdate];
    let finalContent: string[] = [];
    contentLines.forEach((line, index) => {
        if (line.trim() !== '') {
            emptyLines = adjustEmptyLineIndexBasedOnNewLineChar(emptyLines, index, contentLines[index]);
            finalContent.push(contentLines[index]);
        } else if (line.trim() === '' && emptyLineIndexBeforeUpdate.includes(index)) {
            finalContent.push(contentLines[index]);
        } else {
            emptyLines = adjustEmptyLineIndexBasedOnDeletedLine(emptyLines, index);
            return;
        }
    });

    // removes empty lines added after insertion and deletion of text edits for xml
    finalContent = getFinalXMLContent(fileContent, finalContent, emptyLines);
    return finalContent.join('\n');
}

function isSameTextEdit(textEdit1: TextEdit, textEdit2: TextEdit): boolean {
    if (textEdit1.newText !== textEdit2.newText) {
        return false;
    } else if (textEdit1.range.start.line !== textEdit2.range.start.line) {
        return false;
    } else if (textEdit1.range.start.character !== textEdit2.range.start.character) {
        return false;
    } else if (textEdit1.range.end.line !== textEdit2.range.end.line) {
        return false;
    } else if (textEdit1.range.end.character !== textEdit2.range.end.character) {
        return false;
    } else {
        return true;
    }
}

function getFinalXMLContent(fileContent: FileContent, finalContent: string[], emptyLines: number[]): string[] {
    const newContent = finalContent.join('\n');

    if (fileContent.trim().startsWith('<')) {
        finalContent = newContent.split('\n');
        for (let index = finalContent.length - 1; index >= 0; index--) {
            if (!emptyLines.includes(index) && finalContent[index].trim() === '') {
                finalContent.splice(index, 1);
            }
        }
    }
    return finalContent;
}

function adjustEmptyLineIndexBasedOnNewLineChar(emptyLines: number[], index: number, line: string) {
    // find number of new line character in line to adjust emtpyline indices
    const numberOfNewLine = (line.match(/\n/g) || []).length;
    return emptyLines.map((emptyLineIndex) =>
        emptyLineIndex > index && numberOfNewLine ? emptyLineIndex + numberOfNewLine : emptyLineIndex
    );
}

function adjustEmptyLineIndexBasedOnDeletedLine(emptyLines: number[], index: number): number[] {
    return emptyLines.map((emptyLineIndex) => (emptyLineIndex > index ? emptyLineIndex - 1 : emptyLineIndex));
}
