import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat } from 'vscode-languageserver';

import type { Element } from '@sap-ux/odata-annotation-core';

import type {
    CompletionContext,
    CompletionItemAdapterParams,
    EmptyAssignmentContext,
    ModularCompletionHandler,
    MonolithicCompletionHandler
} from '../types';
import { basicItemProvider, getAliasesFromTermCompletionItems, updatePlaceholder } from '../utils';
import { print } from '@sap/ux-cds-odata-annotation-converter';
import { textArrangementAdapter } from '../adapters/textArrangement';

function emptyAssignmentGate(context: CompletionContext): boolean {
    return context.type === 'empty-assignment';
}

function emptyAssignmentAdapter(
    { isCompoundAnnotation }: EmptyAssignmentContext,
    items: CompletionItem[]
): CompletionItem[] {
    const aliases = getAliasesFromTermCompletionItems(items);
    return aliases.map((alias) => ({
        label: alias,
        insertTextFormat: InsertTextFormat.Snippet,
        kind: CompletionItemKind.Module,
        insertText: `${alias} : { $0 }${isCompoundAnnotation ? ',' : ''}`, // when using textEdit replacement of the typed filter text does not work correctly
        sortText: '000000000'
    }));
}

export const emptyAssignmentAliasHandler: MonolithicCompletionHandler = {
    name: 'empty-assignment-alias',
    type: 'monolithic',
    gate: emptyAssignmentGate,
    providers: [basicItemProvider],
    adapter: emptyAssignmentAdapter
};

function termSnippetAdapter({
    context: { isCompoundAnnotation },
    originalItem
}: CompletionItemAdapterParams<EmptyAssignmentContext>): CompletionItem | undefined {
    if (originalItem?.data?.generic === undefined) {
        return;
    }
    const snippet: Element = JSON.parse(JSON.stringify(originalItem.data.generic.data));
    updatePlaceholder(snippet, false);

    const text = `${print(snippet)}${isCompoundAnnotation ? ',' : ''}`;
    return {
        label: originalItem?.data?.generic.name,
        insertTextFormat: InsertTextFormat.Snippet,
        kind: CompletionItemKind.Class,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        insertText: text // when using textEdit replacement of the typed filter text does not work correctly
    };
}

export const emptyAssignmentTermHandler: ModularCompletionHandler = {
    name: 'empty-assignment-term',
    type: 'modular',
    gate: emptyAssignmentGate,
    providers: [basicItemProvider],
    mappers: [],
    adapters: [textArrangementAdapter, termSnippetAdapter]
};
