export interface ResolvedCursorContext {
    element: Element; // element to do code completion for
    parentElement: Element;
    fixElementName?: ElementName; // element name must be this one
    path: JsonPath; // path into this element
    typeOfAlreadyProvidedValue: FullyQualifiedTypeName; // value is already present and has this type
    alreadyProvidedValueIsAfter?: boolean; // already present value is  a f t e r  cursor position
    types: FullyQualifiedTypeName[]; // allowed result types for code completion
    facets: Facets; // facets (need to be applied for all entries in types)
    constraints: Constraints; // constraints (need to be applied for all entries in types)
    entitySetProperties?: Map<SimpleName, Map<SimpleName, string>>;
}

/**
 * LabeledElement cursor context resolver
 * @param pathTargetInElement
 * @param result
 */
export function resolveCursorContextForLabeledElement(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement,
    result: ResolvedCursorContext
): boolean {
    let doContinue = false;
    const targetElement = pathTargetInElement.element;
    if (!targetElement && !(pathTargetInElement.isSubNode || pathTargetInElement.isTextSubNode)) {
        return doContinue;
    } else {
        if (targetElement) {
            result.element = targetElement;
            result.path = pathTargetInElement.remainingPathForElement;
        }
        doContinue = true;
        valueHandlingContext.nodeContext = {};
        return doContinue;
    }
}

export function resolveCursorContextForApply(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement,
    result: ResolvedCursorContext
): boolean {
    let doContinue = false;
    const targetElement = pathTargetInElement.element;

    if (
        !targetElement ||
        pathTargetInElement.isTextSubNode ||
        pathTargetInElement.isElementSubNodeName ||
        pathTargetInElement.isName
    ) {
        // subelement names and Apply element's attributes are handled within the Apply context
        return doContinue;
    } else {
        const functionName = (getElementAttributeValue(result.element, Edm.Function) || '') as FunctionName;
        const parameterIndex = getChildElementPosition(pathTargetInElement.nodeIndex, result.element, true);
        // TODO: support multiple overloads
        const parameterTypeDefinitions = getFunctionParameterTypeDefinitions(functionName, parameterIndex)[0];
        const target = getPathTargetInElement(pathTargetInElement.remainingPathForElement, targetElement);

        if (targetElement) {
            if (targetElement.name === Edm.LabeledElement) {
                const nameAttr = getElementAttribute(targetElement, Edm.Name);
                if (
                    target.attribute &&
                    (target.isAttributeValue || target.isAttributeName) &&
                    (target.attribute.name === Edm.Name || (!target.attribute.name && !nameAttr))
                ) {
                    // LabeledElement Name attribute is handled within the Apply context
                    // we resolve to current Apply element
                    return false;
                }
            } else {
                // Uri template completion - we resolve to Apply element in order to reach all its content
                if (
                    isParameterOfStringTemplateKind(result.element, pathTargetInElement.nodeIndex) &&
                    targetElement.name === Edm.String &&
                    target.isTextSubNode
                ) {
                    result.types = [EdmType.String];
                    return false;
                }
            }

            result.element = targetElement;
            result.path = pathTargetInElement.remainingPathForElement;
        }

        if (parameterIndex > -1 && parameterTypeDefinitions) {
            result.types = parameterTypeDefinitions.map((type) => {
                let valueTypeName: string;
                if (typeof type === 'object') {
                    valueTypeName = type.isCollection ? `Collection(${type.name})` : type.name;
                } else {
                    valueTypeName = type;
                }
                return valueTypeName;
            });
        }

        doContinue = true;
        valueHandlingContext.nodeContext = {};
        return doContinue;
    }
}

/**
 * for a given element (representing an annotation tag), path into this element and required type
 *  (path can traverse multiple dynamic expressions and Collection/Record/PropertyValue elements):
 *  get the element (with remaining path and required type(s)) for which code completion call shall be processed
 *
 * @param type - result type of the given element
 * @param cursorContext
 */
export function resolve(
    valueHandlingContext: ValueHandlingContext,
    type: ValueType,
    annotation: Element,
    path: JsonPath,
    logger: Logger
): ResolvedCursorContext {
    const result: ResolvedCursorContext = {
        element: annotation,
        parentElement: null,
        path: path,
        types: [convertValueTypeToString(type)],
        typeOfAlreadyProvidedValue: '',
        alreadyProvidedValueIsAfter: false,
        facets: type.facets,
        constraints: type.constraints,
        entitySetProperties: null
    };
    let doContinue = false;
    let rootAnnotation = true;
    do {
        result.parentElement = result.element;
        result.fixElementName = '';
        const pathTargetInElement = getPathTargetInElement(result.path, result.element);
        const elementAttributeMetadata = dynamicExpressionSpecialMap[result.element.name];
        if (elementAttributeMetadata) {
            const previousElement = result.element;
            if (result.element.name === Edm.Annotation) {
                doContinue = resolveCursorContextForAnnotation(valueHandlingContext, pathTargetInElement, result);
                if (!rootAnnotation) {
                    result.fixElementName = null; // for nested annotation completion list not restricted
                }
                rootAnnotation = false;
            } else if (result.element.name === Edm.Collection) {
                if (valueHandlingContext.currentStructureProperty) {
                    valueHandlingContext.currentStructureProperty.propertyPathSegments = null; // no splitting supported inside
                }
                doContinue = resolveCursorContextForCollection(valueHandlingContext, pathTargetInElement, result);
            } else if (result.element.name === Edm.Record) {
                doContinue = resolveCursorContextForRecord(valueHandlingContext, pathTargetInElement, result);
            } else if (result.element.name === Edm.PropertyValue) {
                doContinue = resolveCursorContextForPropertyValue(valueHandlingContext, pathTargetInElement, result);
            } else if (result.element.name === Edm.Apply) {
                doContinue = resolveCursorContextForApply(valueHandlingContext, pathTargetInElement, result);
            } else if (result.element.name === Edm.LabeledElement) {
                doContinue = resolveCursorContextForLabeledElement(valueHandlingContext, pathTargetInElement, result);
            }
            if (doContinue || pathTargetInElement.isTextSubNode) {
                const getTypeOfValueResult = getTypeOfAlreadyProvidedValue(
                    valueHandlingContext,
                    elementAttributeMetadata,
                    previousElement,
                    pathTargetInElement.nodeIndex,
                    logger
                );
                result.typeOfAlreadyProvidedValue = getTypeOfValueResult.providedValueType;
                result.alreadyProvidedValueIsAfter = getTypeOfValueResult.valueIsAfterIndex;
                if (result.typeOfAlreadyProvidedValue && !result.alreadyProvidedValueIsAfter) {
                    doContinue = false;
                } else {
                    doContinue = !pathTargetInElement.isTextSubNode;
                }
            }
        } else if (dynamicExpressionSignatureMap.has(result.element.name as Edm)) {
            doContinue = resolveCursorContextForDynamicExp(valueHandlingContext, pathTargetInElement, result);
        } else {
            doContinue = false;
        }
    } while (doContinue && result.types && result.types.length);
    return result;
}

function getTypeOfAlreadyProvidedValue(
    valueHandlingContext: ValueHandlingContext,
    elementAttributeMetadata,
    element: Element,
    nodeIndex: number,
    logger: Logger
): { providedValueType: FullyQualifiedTypeName; valueIsAfterIndex: boolean } {
    let providedValueType: FullyQualifiedTypeName = '';
    let valueIsAfterIndex = false;
    let providedValueName: ElementName | AttributeName;
    let providedPathValue: PathValue;
    // find out if value providing attributes are present
    Object.keys(element.attributes || {}).forEach((attrName) => {
        if (
            !providedValueName &&
            !(elementAttributeMetadata.mandatoryAttributes || []).includes(attrName) &&
            !(elementAttributeMetadata.optionalAttributes || []).includes(attrName)
        ) {
            providedValueName = attrName;
            if (providedValueName === 'Path') {
                providedPathValue = element.attributes[attrName].value;
            }
        }
    });

    const subNodeName = (element.content[nodeIndex] as Element).name;
    if (providedValueName) {
        // no code completion for sub nodes: value (or error) should already be provided by attribute
        const message = `No CC for element "${subNodeName}": value already provided by attribute!`;
        logger.info(message);
    } else if (!elementAttributeMetadata || !elementAttributeMetadata.multipleValuesAllowed) {
        // find out if value provided already by previous sub element
        for (let i = 0; i < element.content.length && !providedValueName && !providedValueType; i++) {
            const subNode = element.content[i];
            if (!(subNode.type === ELEMENT_TYPE && subNode.name === 'Annotation')) {
                const isEmptyTextSubNode = subNode.type === TEXT_TYPE && isEmptyText(subNode.text);
                if (!isEmptyTextSubNode) {
                    valueIsAfterIndex = i >= nodeIndex;
                    if (subNode.type === ELEMENT_TYPE) {
                        providedValueName = subNode.name;
                        if (providedValueName === 'Path') {
                            const textNodes = subNode.content.filter((node) => {
                                return node.type === TEXT_TYPE && !isEmptyText(node.text);
                            });
                            providedPathValue = textNodes.length ? (textNodes[0] as TextNode).text : '';
                        }
                    } else {
                        providedValueType = 'Edm.UnknownType';
                    }
                }
            }
        }
        if (providedValueName && !valueIsAfterIndex) {
            // no code completion for sub nodes: value (or error) should already be provided by attribute
            const message = `No CC for element "${subNodeName}": value already provided by previous node`;
            logger.info(message);
        }
    }

    if (providedValueName) {
        providedValueType = findTypeForPropertyName(valueHandlingContext, providedValueName, providedPathValue);
        providedValueType = providedValueType || 'Edm.UnknownType';
    }
    if (!providedValueType && element.name === 'Record' && subNodeName === 'PropertyValue') {
        // determine type of property value (for restricting terms annotations embedded in property value)
        const subElement = element.content[nodeIndex] as Element;
        if (subElement.content && subElement.content.length) {
            const subElementAttributeMetadata = dynamicExpressionSpecialMap[subNodeName];
            return getTypeOfAlreadyProvidedValue(
                valueHandlingContext,
                subElementAttributeMetadata,
                subElement,
                0,
                logger
            );
        }
    }

    return { providedValueType, valueIsAfterIndex };
}

function resolveCursorContextForAnnotation(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement,
    result: ResolvedCursorContext
): boolean {
    let doContinue = false;
    valueHandlingContext.nodeContext = {};
    if (pathTargetInElement.element) {
        // code completion for annotation child
        result.element = pathTargetInElement.element;
        result.path = pathTargetInElement.remainingPathForElement;
        doContinue = true;
    } else {
        // do code completion for annotation itself
        result.fixElementName = 'Annotation';
    }
    return doContinue;
}

/**
 * resolve cursor context for element representing an EDMX dynamic expression
 * @param pathTargetInElement
 * @param result
 */
function resolveCursorContextForDynamicExp(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement,
    result: ResolvedCursorContext
): boolean {
    // resolve to sub element if path points to a sub element with list of allowed types
    let doContinue = false;
    let allowedTypesResult;
    if (pathTargetInElement.isElementSubNode && pathTargetInElement.element) {
        // check if remaining path resolves to list of allowed types
        if (dynamicExpressionSignatureMap.has(result.element.name as Edm)) {
            allowedTypesResult = getAllowedTypesForDynamicExp(
                valueHandlingContext,
                dynamicExpressionSignatureMap.get(result.element.name as Edm),
                result.element,
                result.path,
                result.types
            );
        }
        if (allowedTypesResult.allowedTypes.length) {
            result.types = allowedTypesResult.allowedTypes;
            if (!allowedTypesResult.keepFacetsAndConstraints) {
                result.facets = {};
                result.constraints = {};
            }
            result.element = pathTargetInElement.element;
            result.path = pathTargetInElement.remainingPathForElement;
            doContinue = true;
        }
    }
    return doContinue;
}

/**
 * resolve cursor context for element representing 'PropertyValue'
 * @param result
 * @param pathTargetInElement
 */
function resolveCursorContextForPropertyValue(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement,
    result: ResolvedCursorContext
): boolean {
    // element for 'PropertyValue'
    let doContinue = false;

    if (pathTargetInElement.isElementSubNode && pathTargetInElement.element) {
        // resolve to sub node with same type
        result.element = pathTargetInElement.element;
        result.path = pathTargetInElement.remainingPathForElement;
        doContinue = true;
        valueHandlingContext.nodeContext = {
            valueListProps: valueHandlingContext.nodeContext?.valueListProps,
            sideEffectsTargetProperties: valueHandlingContext.nodeContext?.sideEffectsTargetProperties,
            dataFieldValueProperty: valueHandlingContext.nodeContext?.dataFieldValueProperty
        };
    } else {
        result.fixElementName = 'PropertyValue';
    }
    return doContinue;
}

/**
 * resolve cursor context for element representing 'Record'.
 *
 * @param pathTargetInElement
 * @param result
 */
function resolveCursorContextForRecord(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement,
    result: ResolvedCursorContext
): boolean {
    // get record type definition
    const recordType = resolveRecordTypeName(valueHandlingContext, result.types, result.element);
    const recordElement = result.element;
    if (!recordType) {
        return false;
    }

    const structuredTypeDefinition = valueHandlingContext.context.vocabularies.getComplexType(recordType);
    if (structuredTypeDefinition?.constraints?.applicableTerms) {
        result.constraints = result.constraints ?? {};
        result.constraints.applicableTerms = structuredTypeDefinition.constraints.applicableTerms;
    } else if (result.constraints?.applicableTerms) {
        delete result.constraints.applicableTerms;
    }
    const propValueElement = pathTargetInElement.element;
    if (!propValueElement || propValueElement.name !== 'PropertyValue') {
        // record can be resolved only to PropertyValue (provided the property type can be derived)
        return false;
    }

    const pathTargetInPropValue = getPathTargetInElement(pathTargetInElement.remainingPathForElement, propValueElement);
    if (
        pathTargetInPropValue.isName ||
        (pathTargetInPropValue.attribute && pathTargetInPropValue.attribute.name === 'Property')
    ) {
        // path points to element name or Property attribute
        return false;
    }

    // derive property type
    let propertyType: ValueType = null;
    const propTypeName = getElementAttributeValue(propValueElement, 'Property');
    if (propTypeName) {
        propertyType = getValueTypeForComplexTypeProperty(valueHandlingContext.context, recordType, propTypeName);
    }

    let doContinue = false;
    // resolve to PropertyValue subnode only if it's type is clear (based on valid 'Property' attribute)
    if (propertyType?.name) {
        // resolve to 'PropertyValue' with corresponding type
        resolvePropertyValue(
            valueHandlingContext,
            pathTargetInElement,
            {
                recordElement,
                recordType,
                propValueElement,
                propertyType,
                propTypeName
            },
            result
        );

        doContinue = true;
    } else if (
        propTypeName &&
        structuredTypeDefinition.isOpenType &&
        result.constraints.openPropertyTypeConstraints?.length
    ) {
        adjustResolutionResultForOpenTypeRecord(
            valueHandlingContext,
            pathTargetInElement,
            propTypeName,
            propValueElement,
            result
        );
        doContinue = true;
    }

    return doContinue;
}

/**
 * Resolves record property value.
 *
 * @param valueHandlingContext
 * @param pathTargetInElement
 * @param recordResolutionContext
 * @param result
 */
function resolvePropertyValue(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement,
    recordResolutionContext: {
        recordElement: Element;
        propValueElement: Element;
        propertyType: ValueType;
        propTypeName: string;
        recordType: string;
    },
    result: ResolvedCursorContext
): void {
    const { propValueElement, propertyType, propTypeName } = recordResolutionContext;

    const strType = convertValueTypeToString(propertyType);
    result.types = [strType];
    result.facets = propertyType.facets;
    result.constraints = propertyType.constraints;

    if (propertyType.name === EdmType.Untyped || propertyType.name === EdmType.AnyPropertyPath) {
        result.types = getResolvedUntypedValueTypes([{ ...propertyType, constraints: result.constraints }]).map((t) =>
            convertValueTypeToString(t)
        );
        result.constraints = { ...(result.constraints || {}), derivedTypeConstraints: undefined };
    }

    result.element = propValueElement;
    result.path = pathTargetInElement.remainingPathForElement;
    if (valueHandlingContext.currentStructureProperty?.propertyPathSegments) {
        // CDS splitting logic active: accumulate property path segments
        valueHandlingContext.currentStructureProperty?.propertyPathSegments.push(propTypeName);
    }
    adjustResolutionResultForSpecialCases(valueHandlingContext, recordResolutionContext, result);
}

function adjustResolutionResultForSpecialCases(
    valueHandlingContext: ValueHandlingContext,
    recordResolutionContext: {
        recordElement: Element;
        propValueElement: Element;
        propertyType: ValueType;
        propTypeName: string;
        recordType: string;
    },
    result: ResolvedCursorContext
) {
    const { recordType, recordElement, propValueElement, propTypeName } = recordResolutionContext;

    const entityContainerName = valueHandlingContext.context.serviceNamespaceMap?.get(
        resolveName((valueHandlingContext.pathBase?.path || '').split('/')[0])?.namespace
    );

    if (entityContainerName && recordType === 'com.sap.vocabularies.Common.v1.ValueListType') {
        adjustResolutionResultForValueListRecord(
            valueHandlingContext,
            entityContainerName,
            recordElement,
            propTypeName,
            result
        );
    } else if (
        entityContainerName &&
        recordType.startsWith('com.sap.vocabularies.Common.v1.ValueListParameter') &&
        (getPropertyStringValue(propValueElement) || '').indexOf('/') < 0 // no completion list for paths
    ) {
        adjustResolutionResultForValueListParameter(valueHandlingContext, entityContainerName, propTypeName, result);
    } else if (recordType === 'com.sap.vocabularies.Common.v1.SideEffectsType' && propTypeName === 'TargetProperties') {
        valueHandlingContext.nodeContext = { sideEffectsTargetProperties: true };
    } else if (isDataFieldValueProperty(recordType, propTypeName)) {
        valueHandlingContext.nodeContext = { dataFieldValueProperty: true };
    } else {
        valueHandlingContext.nodeContext = {};
    }
    if (isActionNameProperty(recordType, propTypeName, valueHandlingContext.aliasInfo.aliasMap)) {
        result.constraints = result.constraints || {};
        result.constraints.allowedValues = getAllowedActionFunctionNames(valueHandlingContext.context.metadata);
    }
}

function adjustResolutionResultForValueListRecord(
    valueHandlingContext: ValueHandlingContext,
    entityContainerName: string,
    recordElement: Element,
    propTypeName: string,
    result: ResolvedCursorContext
): void {
    valueHandlingContext.nodeContext = {};
    const collectionPath = getValueListCollectionPathValue(recordElement);
    valueHandlingContext.nodeContext.valueListProps = {
        currentEntitySetName: collectionPath
    };
    if (propTypeName === PropertyNamesSpecial.CollectionPath) {
        const entitySetNames = [...(valueHandlingContext.context.availableEntitySetPropertyMap ?? new Map()).keys()]
            .filter((key) => key.split('/')[0] === entityContainerName)
            .map((key) => {
                const entitySetName = key.split('/').pop();
                return { value: entitySetName, description: entitySetName, longDescription: '' };
            });
        result.constraints = result.constraints || {};
        result.constraints.allowedValues = entitySetNames;
    }
}

function adjustResolutionResultForValueListParameter(
    valueHandlingContext: ValueHandlingContext,
    entityContainerName: string,
    propTypeName: string,
    result: ResolvedCursorContext
): void {
    const valueHelpData = valueHandlingContext.nodeContext.valueListProps;
    valueHandlingContext.nodeContext = {};
    if (
        propTypeName === PropertyNamesSpecial.ValueListProperty &&
        valueHelpData &&
        valueHelpData.currentEntitySetName
    ) {
        result.constraints = result.constraints || {};
        const propNameMap: Map<string, string> =
            (valueHandlingContext.context.availableEntitySetPropertyMap ?? new Map()).get(
                entityContainerName + '/' + valueHelpData.currentEntitySetName
            ) || new Map();
        result.constraints.allowedValues = [...propNameMap.keys()].map((key) => ({
            value: key,
            description: key,
            longDescription: ''
        }));
    }
}

function adjustResolutionResultForOpenTypeRecord(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement,
    propTypeName: string,
    propValueElement: Element,
    result: ResolvedCursorContext
): void {
    // resolve to open type 'PropertyValue' with types taken from constraints
    result.types = result.constraints.openPropertyTypeConstraints;
    result.facets = undefined;
    result.constraints = undefined;
    result.element = propValueElement;
    result.path = pathTargetInElement.remainingPathForElement;
    if (valueHandlingContext.currentStructureProperty?.propertyPathSegments) {
        // CDS splitting logic active: accumulate property path segments
        valueHandlingContext.currentStructureProperty?.propertyPathSegments.push(propTypeName);
    }
    valueHandlingContext.nodeContext = {};
}

/**
 * resolve cursor context for element representing 'Collection'
 * @param pathTargetInElement
 * @param result
 */
function resolveCursorContextForCollection(
    valueHandlingContext: ValueHandlingContext,
    pathTargetInElement: PathTargetInElement,
    result: ResolvedCursorContext
): boolean {
    // if path is pointing to any sub node of collection: resolve to that sub node
    let doContinue = false;
    if (pathTargetInElement.isElementSubNode && pathTargetInElement.element) {
        // resolve to collection entry with corresponding type
        const filteredTypes: ValueType[] = result.types
            .map((type) => {
                return convertValueTypeFromString(type);
            })
            .filter((valueType) => valueType.asCollection && !!valueType.name); // only collection types are allowed

        result.types = filteredTypes.map((valueType) => valueType.name); // resolve to collection entry type
        result.element = pathTargetInElement.element;
        result.path = pathTargetInElement.remainingPathForElement;
        doContinue = true;
    }
    return doContinue;
}

export function resolvePathToCursorContext(
    context: Context,
    annotationFile: AnnotationFile,
    aliasInfo: AliasInformation,
    path: JsonPath,
    logger: Logger
): CursorContext {
    const cursorContext = createInitialCursorContext();
    const segments = getPathSegments(path);
    let currentContext = annotationFile;
    let currentElement = null;
    let parentElement = null;

    for (let index = 0; index < segments.length; index++) {
        const segment = segments[index];

        if (isAttributeOrContentSegment(segment, currentElement)) {
            parentElement = currentElement;
            currentElement = currentContext;
            updateElementContext(cursorContext, currentElement, segment);
        }

        currentContext = currentContext[segment];

        if (index === 1) {
            updateTargetPath(cursorContext, currentContext);
        } else if (index === 2) {
            handleTargetCompletion(cursorContext, segment, currentContext, segments);
        } else if (index === 3) {
            updateAnnotation(cursorContext, currentContext);
        } else if (index >= 4) {
            handleEmbeddedAnnotation(parentElement, currentElement, cursorContext, context, aliasInfo, logger);
            updatePathsAndContext(segment, currentElement, cursorContext);
        }
    }

    return cursorContext;
}

function createInitialCursorContext(): CursorContext {
    return {
        targetPath: '',
        embeddedIn: '',
        embeddedType: '',
        annotation: null,
        path: '',
        newTarget: false,
        elementContext: {
            path: '',
            parentElement: null,
            attributeArea: false
        }
    };
}

function isAttributeOrContentSegment(segment: PathSegment, currentElement: Element): boolean {
    return (
        segment === 'attributes' ||
        segment === 'content' ||
        (segment.toString().startsWith('$') && typeof currentElement === 'object')
    );
}

function updateElementContext(cursorContext: CursorContext, currentElement: Element, segment: PathSegment): void {
    cursorContext.elementContext.parentElement = currentElement;
    cursorContext.elementContext.path = '$';
    cursorContext.elementContext.attributeArea = segment === 'attributes';
}

function updateTargetPath(cursorContext: CursorContext, currentContext: any): void {
    const target = currentContext as Target;
    cursorContext.targetPath = target?.name || '';
}

function handleTargetCompletion(
    cursorContext: CursorContext,
    segment: PathSegment,
    currentContext: any,
    segments: PathSegment[]
): void {
    if (segment === 'name') {
        cursorContext.targetPath = '';
    } else if (segment === '') {
        cursorContext.targetPath = null;
    } else if (segment === 'terms' && !cursorContext.targetPath) {
        cursorContext.targetPath = null;
    } else if (segments.length === 3 && typeof segment === 'string' && segment.startsWith('$')) {
        cursorContext.path = "$['" + segment + "']";
    }
}

function updateAnnotation(cursorContext: CursorContext, currentContext: any): void {
    cursorContext.annotation = currentContext as Element;
    cursorContext.path = '$';
}

function handleEmbeddedAnnotation(
    parentElement: Element,
    currentElement: Element,
    cursorContext: CursorContext,
    context: Context,
    aliasInfo: AliasInformation,
    logger: Logger
) {
    if (
        parentElement &&
        currentElement &&
        currentElement.name === Edm.Annotation &&
        cursorContext.annotation !== currentElement
    ) {
        adjustEmbeddedAnnotationCursorContext(context, aliasInfo, currentElement, parentElement, cursorContext, logger);
    }
}

function updatePathsAndContext(segment: PathSegment, currentElement: Element | null, cursorContext: CursorContext) {
    const nextJsonPathSegment = typeof segment === 'string' ? "['" + segment + "']" : '[' + segment + ']';
    cursorContext.path += nextJsonPathSegment;
    cursorContext.elementContext.path += nextJsonPathSegment;
    if (cursorContext.applyContext) {
        cursorContext.applyContext.path += nextJsonPathSegment;
    }
    if (currentElement?.name === Edm.Apply) {
        cursorContext.applyContext = {
            apply: currentElement,
            path: cursorContext.elementContext.path
        };
    }
}

/**
 * finds embeddedType - i.e. which type the node represents where the annotation is embedded
 * and sets cursor context properties to provide embedded annotation context
 * @param context - cursor context object
 * @param aliasInfo - alias information object
 * @param currentAnnotation - annotation element providing value for current context
 * @param parentElement - parent element for embedded annotation
 * @param cursorContext - cursor context object ( is changed within function )
 */
export function adjustEmbeddedAnnotationCursorContext(
    context: Context,
    aliasInfo: AliasInformation,
    currentAnnotation: Element,
    parentElement: Element,
    cursorContext: CursorContext,
    logger: Logger
): void {
    const pathBase = getPathBaseMetadataElement(context.metadata, cursorContext.targetPath, aliasInfo);
    const termAttributeValue = getElementAttributeValue(cursorContext.annotation, Edm.Term) || '';
    const resolvedTermName = resolveName(termAttributeValue, aliasInfo.aliasMapVocabulary);
    const term = context.vocabularies.getTerm(resolvedTermName.qName);
    const valueType: ValueType = getValueTypeFromTerm(context, term);
    const resolved = resolve(
        { context, aliasInfo, pathBase },
        valueType,
        cursorContext.annotation,
        cursorContext.path,
        logger
    );
    let embeddedType = resolved.typeOfAlreadyProvidedValue;
    if (resolved.element.name === Edm.Record && getElementAttribute(resolved.element, Edm.Type)) {
        embeddedType = getFullyQualifiedNameByAttribute(resolved.element, aliasInfo.aliasMap, Edm.Type);
    } else if (embeddedType === 'Edm.UnknownType' && resolved.types.length > 0) {
        embeddedType = resolved.types[0];
    }
    // set annotation to embedded annotation, embeddedIn, embeddedType; reset path
    cursorContext.annotation = currentAnnotation;
    cursorContext.embeddedIn = parentElement.name;
    cursorContext.embeddedType = embeddedType;
    cursorContext.embeddedApplicableTerms = resolved.constraints?.applicableTerms;
    cursorContext.path = '$';
}
