import { MetadataService } from '@sap-ux/odata-entity-model';

import type { AnnotationServiceInterface } from '@sap/ux-annotation-service';
import { AnnotationServiceImpl } from '@sap/ux-annotation-service';
import { cdsLogger } from './log';

import type { VocabularyService } from '@sap-ux/odata-vocabularies';
import { toAnnotationFile, toTargetMap } from '@sap/ux-cds-odata-annotation-converter';
import type { BlitzIndex, CdsCompilerFacade, MetadataCollector } from '@sap/ux-cds-compiler-facade';
import { getMetadataElementsFromMap } from '@sap/ux-cds-compiler-facade';

import type { AnnotationFile, ServiceAnnotationFile } from '@sap-ux/odata-annotation-core';

export interface PrepareOptions {
    includeDependencies?: boolean;
    omitRedundantTypesInSnippets?: boolean;
    annotationFileRestrictions?: {
        targetName: string;
        termName: string;
        qualifier?: string;
    };
    completionOnly?: boolean;
    currentFileOnly?: boolean;
    loadAllFiles?: boolean;
    facade?: CdsCompilerFacade;
}

export const prepareAnnotationService = (
    vocabularyService: VocabularyService,
    index: BlitzIndex,
    uri: string,
    annotationFile: AnnotationFile,
    metadataCollector: MetadataCollector,
    options?: PrepareOptions
): AnnotationServiceInterface => {
    const metadataService = new MetadataService({ uriMap: options.facade?.getUriMap() || new Map() });
    const completionOnly = options && options.completionOnly;
    const omitRedundantTypesInSnippets = options && options.omitRedundantTypesInSnippets;
    const genericAnnotationService: AnnotationServiceInterface = new AnnotationServiceImpl(
        () => {
            console.log('diagnostic');
        },
        true,
        metadataService,
        '',
        cdsLogger,
        { supportSplit: true, omitRedundantTypesInSnippets, completionOnly }
    );
    let otherAnnotationFiles: ServiceAnnotationFile[] = [];

    if (options?.currentFileOnly !== true) {
        let otherFileUris = [];
        if (options && options.includeDependencies) {
            if (options && options.loadAllFiles) {
                otherFileUris = [...index.builtUris].filter((fileUri) => fileUri !== uri);
            } else {
                otherFileUris = [...index.getTransitiveDependencies(uri)].reverse();
            }
        }
        otherAnnotationFiles = otherFileUris.map((uri): ServiceAnnotationFile => {
            const { file: content } = toAnnotationFile(
                uri,
                vocabularyService,
                toTargetMap(index.forUri(uri), uri, vocabularyService, options.facade),
                metadataCollector
            );
            return {
                serviceName: 'default',
                uri,
                content
            };
        });
        const allFiles = [
            ...otherAnnotationFiles.map((item) => ({ uri: item.uri, content: item.content })),
            { uri, content: annotationFile }
        ];
        const ghostFiles = options?.facade?.getGhostFiles(allFiles);
        if (ghostFiles?.length) {
            otherAnnotationFiles.splice(0, 0, ...ghostFiles);
        }
    }

    if (options?.annotationFileRestrictions) {
        const { targetName, termName, qualifier } = options?.annotationFileRestrictions;
        // filter otherAnnotationFiles - only content for same target/term/qualifier is relevant
        otherAnnotationFiles.forEach((annotationFile) => {
            annotationFile.content.targets = annotationFile.content.targets.filter(
                (target) => target.name === targetName
            );
            annotationFile.content.targets.forEach((target) => {
                target.terms = target.terms.filter((term) => {
                    const qualifierValue = term.attributes['Qualifier'] ? term.attributes['Qualifier'].value : '';
                    return (
                        term.attributes['Term'].value === termName &&
                        ((!qualifierValue && !qualifier) || qualifierValue === qualifier)
                    );
                });
            });
            annotationFile.content.targets = annotationFile.content.targets.filter(
                (target) => target.terms && target.terms.length > 0
            );
        });
        otherAnnotationFiles = otherAnnotationFiles.filter(
            (annotationFile) => annotationFile.content.targets && annotationFile.content.targets.length > 0
        );
    }

    const currentAnnotationFile: ServiceAnnotationFile = {
        serviceName: 'default',
        uri: uri,
        content: annotationFile
    };
    // only use top level entries
    const metadataElements = getMetadataElementsFromMap(metadataCollector.metadataElementMap);
    metadataService.import(metadataElements, 'DummyMetadataFileUri');
    genericAnnotationService.loadService([...otherAnnotationFiles, currentAnnotationFile]);
    return genericAnnotationService;
};
