import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, Position, Range, TextEdit } from 'vscode-languageserver';

import type { Element } from '@sap-ux/odata-annotation-core';
import { Edm } from '@sap-ux/odata-annotation-core';

import type {
    AnnotationContainerContext,
    AnnotationContainerRefactorContext,
    CompletionContext,
    CompletionHandlerArgs,
    CompletionItemAdapterParams,
    ModularCompletionHandler,
    ProviderResult
} from '../types';
import { updatePlaceholder, wrapWithExclamationSquareBrackets } from '../utils';
import type { Annotation, RecordProperty } from '@sap-ux/cds-annotation-parser';
import { ANNOTATION_TYPE } from '@sap-ux/cds-annotation-parser';
import { print } from '@sap/ux-cds-odata-annotation-converter';

export const annotationContainerRefactoringHandler: ModularCompletionHandler = {
    name: 'annotation-container-refactoring',
    type: 'modular',
    gate: annotationContainerRefactoringGate,
    providers: [nestedAnnotationProvider],
    mappers: [],
    adapters: [annotationContainerRefactorAdapter]
};
export const annotationContainerHandler: ModularCompletionHandler = {
    name: 'annotation-container',
    type: 'modular',
    gate: annotationContainerGate,
    providers: [nestedAnnotationProvider],
    mappers: [],
    adapters: [annotationContainerAdapter]
};

function annotationContainerRefactoringGate(context: CompletionContext): boolean {
    return context.type === 'refactor' && context.kind === 'annotation-container';
}

function nestedAnnotationProvider(
    _context: CompletionContext,
    { getCompletionItems, file, pointer, position }: CompletionHandlerArgs
): ProviderResult {
    const segments = pointer.split('/').slice(1);
    const isTargetContext = segments.length === 2 && segments[0] === 'targets';
    const adjustedPointer = segments[segments.length - 1]?.includes('$') ? pointer : pointer + '/$0';
    const items = getCompletionItems(file, position, isTargetContext, adjustedPointer);
    return {
        itemsForAdapter: items,
        completionItems: []
    };
}

function annotationContainerRefactorAdapter({
    context,
    originalItem
}: CompletionItemAdapterParams<AnnotationContainerRefactorContext>): CompletionItem | undefined {
    // Only annotation completion items are supported
    if (originalItem?.data?.generic === undefined || originalItem?.data?.generic?.category !== 'Annotation') {
        return;
    }
    const { pathToNode, position, isCompoundAnnotation, hasComma } = context;
    const targetNode = pathToNode[pathToNode.length - 1] as Annotation | RecordProperty;

    const snippet: Element = JSON.parse(JSON.stringify(originalItem.data.generic.data));
    updatePlaceholder(snippet, true);
    const attrNames = Object.keys(snippet.attributes ?? {});

    if (attrNames.includes(Edm.Term)) {
        snippet.attributes[Edm.Term].value = wrapWithExclamationSquareBrackets(
            snippet.attributes[Edm.Term].value,
            true
        );
    }
    const insertTrailingComma = shouldInsertCommaAfterValueContainer(
        targetNode,
        context,
        isCompoundAnnotation,
        hasComma
    );
    const item: CompletionItem = {
        label: wrapWithExclamationSquareBrackets(originalItem.label, true),
        insertTextFormat: InsertTextFormat.Snippet,
        kind: CompletionItemKind.Class,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        filterText: originalItem.label
    };
    const text = print(snippet);
    if (targetNode.value.range?.start?.line === targetNode.value.range?.end.line) {
        delete item.insertText;
        item.textEdit = createTextEditsForSingleLineValueReplacement(
            targetNode,
            text,
            insertTrailingComma,
            position,
            context,
            4,
            false
        );
    } else {
        Object.assign(
            item,
            createTextEditsForMultiLineValueReplacement(
                targetNode,
                text,
                insertTrailingComma,
                isCompoundAnnotation,
                context,
                4,
                false
            )
        );
    }

    return item;
}
function annotationContainerGate(context: CompletionContext): boolean {
    return context.type === 'container' && context.kind === 'annotation';
}

function annotationContainerAdapter({
    context,
    originalItem
}: CompletionItemAdapterParams<AnnotationContainerContext>): CompletionItem | undefined {
    // Only annotation completion items are supported
    if (originalItem?.data?.generic === undefined || originalItem?.data?.generic?.category !== 'Annotation') {
        return;
    }
    const { position, hasComma } = context;

    const snippet: Element = JSON.parse(JSON.stringify(originalItem.data.generic.data));
    updatePlaceholder(snippet, true);
    const attrNames = Object.keys(snippet.attributes ?? {});

    if (attrNames.includes(Edm.Term)) {
        snippet.attributes[Edm.Term].value = wrapWithExclamationSquareBrackets(
            snippet.attributes[Edm.Term].value,
            true
        );
    }
    const text = `${print(snippet)}${hasComma ? '' : ','}`;
    const label = wrapWithExclamationSquareBrackets(originalItem?.data?.generic.name, true);
    return {
        label,
        insertTextFormat: InsertTextFormat.Snippet,
        kind: CompletionItemKind.Class,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        textEdit: TextEdit.insert(position, text)
    };
}

/**
 * Checks if comma is allowed in the current context and if it already exists.
 * @param context
 */
const shouldInsertCommaAfterValueContainer = (
    targetNode: Annotation | RecordProperty,
    context: AnnotationContainerRefactorContext,
    isCompoundAnnotation: boolean,
    hasComma: boolean
): boolean => {
    const trailingCommaAllowed =
        targetNode.type !== ANNOTATION_TYPE || isCompoundAnnotation || context.pathToNode.length > 2;
    return !trailingCommaAllowed || hasComma ? false : true;
};

const createIndent = (indentSize: number, useTabs: boolean): string => (useTabs ? '\t' : ' '.repeat(indentSize));

const indentText = (text: string, indent: string): string =>
    text
        .split('\n')
        .map((line) => indent + line)
        .join('\n');
const createTextEditsForSingleLineValueReplacement = (
    targetNode: Annotation | RecordProperty,
    annotationText: string,
    insertTrailingComma: boolean,
    position: Position,
    context: AnnotationContainerRefactorContext,
    indentSize: number,
    useTabs: boolean
): TextEdit => {
    const indent = createIndent(indentSize, useTabs);
    const escapedValue = (context.text || '').replace(/\$/g, '\\$');
    const indentedText = indentText(annotationText, indent);
    const text = `{\n${indentedText},\n${indent}\\$value: ${escapedValue},\n}${insertTrailingComma ? ',' : ''}`;

    return TextEdit.replace(Range.create(position, targetNode.value.range?.end ?? position), text);
};

const createTextEditsForMultiLineValueReplacement = (
    targetNode: Annotation | RecordProperty,
    annotationText: string,
    insertTrailingComma: boolean,
    isCompoundAnnotation: boolean,
    context: AnnotationContainerRefactorContext,
    indentSize: number,
    useTabs: boolean
): { additionalTextEdits: TextEdit[]; insertText: string } => {
    const indent = useTabs ? '\t' : ' '.repeat(indentSize);
    // since calculating correct indent for different formatting cases gets complicated, just use current indent of the last line
    const lastLineIndent = context.text.split('\n').slice(-1)[0].split(/\S/)[0];
    const indentedText = indentText(annotationText, indent);
    const insertText = `{\n${indentedText},\n${indent}\\$value: `;
    const valueIndentEdits = targetNode.value.range
        ? Array.from(
              {
                  length: targetNode.value.range.end.line - targetNode.value.range.start.line
              },
              (_, index) => {
                  const position = Position.create(targetNode.value.range.start.line + index + 1, 0);
                  return TextEdit.insert(position, indent);
              }
          )
        : [];

    const isTopLevelSingleAnnotation =
        targetNode.type === ANNOTATION_TYPE && !isCompoundAnnotation && context.pathToNode.length <= 2;

    const closingText = isTopLevelSingleAnnotation ? `\n}` : `\n${lastLineIndent}}${insertTrailingComma ? ',' : ''}`;
    // we need to use value range, because there could be something on the same line after the value
    const closingEdit = TextEdit.insert(targetNode.value.range?.end, closingText);

    const additionalTextEdits = [...valueIndentEdits, closingEdit];

    return {
        insertText,
        additionalTextEdits
    };
};
