import { CompletionItemKind, InsertTextFormat, TextEdit } from 'vscode-languageserver';

import type { AnnotationFile, Element } from '@sap-ux/odata-annotation-core';
import { TEXT_TYPE, ELEMENT_TYPE, Edm } from '@sap-ux/odata-annotation-core';

import type {
    CompletionItemMapper,
    CompletionItemMapperWithGate,
    CompletionItemMapperGate,
    ProviderResult,
    ValueCompletionContext,
    CompletionItemMapperParams
} from './types';

const IGNORE_ELEMENT_NAMES = new Set([
    'PropertyValue',
    'Annotation',
    // Primitive Types
    'Binary',
    'Date',
    'DateTimeOffset',
    'Decimal',
    'Duration',
    'Float',
    'Guid',
    'TimeOfDay',
    'Int'
]);

function getElementNodeFrom$Pointer(pointer: string, file: AnnotationFile): Element {
    return pointer
        .split('/')
        .slice(1, -1)
        .reduce((accumulator, segment) => accumulator[segment], file);
}

function getEmptyValuePointer(pointer: string): string {
    return [...pointer.split('/').slice(1, -1), 'content', 0, 'content', 0, 'text'].join('/');
}

function createEmptyValueElement(element: Element, name: Edm): Element {
    return {
        type: ELEMENT_TYPE,
        name,
        nameRange: null,
        contentRange: element.contentRange,
        range: element.contentRange,
        content: [
            {
                type: TEXT_TYPE,
                text: '',
                range: element.contentRange
            }
        ],
        attributes: {}
    };
}

function createChildNodeMapper(name: Edm): CompletionItemMapper {
    return function childNodeMapper({
        args: { getCompletionItems, pointer, file, position }
    }: CompletionItemMapperParams): ProviderResult {
        const targetNode = getElementNodeFrom$Pointer(pointer, file);
        targetNode.content = [createEmptyValueElement(targetNode, name)];
        const newPointer = getEmptyValuePointer(pointer);
        const itemsForAdapter = getCompletionItems(file, position, false, newPointer);
        return {
            itemsForAdapter,
            completionItems: []
        };
    };
}

function createChildNodeMapperGate(name: Edm): CompletionItemMapperGate {
    return function childNodeMapper({ context, item }: CompletionItemMapperParams): boolean {
        return (
            (context.type === 'value' || (context.type === 'container' && context.kind === 'collection')) &&
            item.label === name
        );
    };
}

function createChildNodeMapperWithGate(name: Edm): CompletionItemMapperWithGate {
    return {
        gate: createChildNodeMapperGate(name),
        mapper: createChildNodeMapper(name)
    };
}

export const enumMapper: CompletionItemMapperWithGate = createChildNodeMapperWithGate(Edm.EnumMember);

export const pathMapper: CompletionItemMapperWithGate = createChildNodeMapperWithGate(Edm.Path);
export const propertyPathMapper: CompletionItemMapperWithGate = createChildNodeMapperWithGate(Edm.PropertyPath);
export const navigationPropertyPathMapper: CompletionItemMapperWithGate = createChildNodeMapperWithGate(
    Edm.NavigationPropertyPath
);
export const annotationPathMapper: CompletionItemMapperWithGate = createChildNodeMapperWithGate(Edm.AnnotationPath);

export const stringMapper: CompletionItemMapperWithGate = {
    gate: createChildNodeMapperGate(Edm.String),
    mapper: function ({
        context: { proposedReplacementRange }
    }: CompletionItemMapperParams<ValueCompletionContext>): ProviderResult {
        return {
            itemsForAdapter: [],
            completionItems: [
                {
                    label: `''`,
                    insertText: `'$0'`,
                    sortText: '000000000',
                    filterText: `''`,
                    insertTextFormat: InsertTextFormat.Snippet,
                    kind: CompletionItemKind.Value,
                    textEdit: TextEdit.replace(proposedReplacementRange, "'$0'")
                }
            ]
        };
    }
};

export const collectionMapper: CompletionItemMapperWithGate = {
    gate: createChildNodeMapperGate(Edm.Collection),
    mapper: function ({
        context: { proposedReplacementRange }
    }: CompletionItemMapperParams<ValueCompletionContext>): ProviderResult {
        return {
            itemsForAdapter: [],
            completionItems: [
                {
                    label: `[]`,
                    sortText: '000000000',
                    filterText: `[]`,
                    insertTextFormat: InsertTextFormat.Snippet,
                    kind: CompletionItemKind.Value,
                    textEdit: TextEdit.replace(proposedReplacementRange, '[$0]')
                }
            ]
        };
    }
};
export const recordMapper: CompletionItemMapperWithGate = {
    gate: createChildNodeMapperGate(Edm.Record),
    mapper: function ({
        context: { proposedReplacementRange }
    }: CompletionItemMapperParams<ValueCompletionContext>): ProviderResult {
        return {
            itemsForAdapter: [],
            completionItems: [
                {
                    label: `{}`,
                    sortText: '000000000',
                    filterText: `{}`,
                    insertTextFormat: InsertTextFormat.Snippet,
                    kind: CompletionItemKind.Value,
                    textEdit: TextEdit.replace(proposedReplacementRange, '{$0}')
                }
            ]
        };
    }
};
export const booleanMapper: CompletionItemMapperWithGate = {
    gate: createChildNodeMapperGate(Edm.Bool),
    mapper: function ({
        context: { proposedReplacementRange }
    }: CompletionItemMapperParams<ValueCompletionContext>): ProviderResult {
        return {
            itemsForAdapter: [],
            completionItems: [
                {
                    label: `true`,
                    insertText: `true`,
                    sortText: '000000000',
                    filterText: `true`,
                    insertTextFormat: InsertTextFormat.PlainText,
                    kind: CompletionItemKind.Keyword,
                    textEdit: TextEdit.replace(proposedReplacementRange, 'true')
                },
                {
                    label: `false`,
                    insertText: `false`,
                    sortText: '000000000',
                    filterText: `false`,
                    insertTextFormat: InsertTextFormat.PlainText,
                    kind: CompletionItemKind.Keyword,
                    textEdit: TextEdit.replace(proposedReplacementRange, 'false')
                }
            ]
        };
    }
};
export const filterMapper: CompletionItemMapperWithGate = {
    gate: ({ context, item }: CompletionItemMapperParams): boolean => {
        return (
            (context.type === 'value' || (context.type === 'container' && context.kind === 'collection')) &&
            [...IGNORE_ELEMENT_NAMES].includes(item.label)
        );
    },
    mapper: function (): ProviderResult {
        return {
            itemsForAdapter: [],
            completionItems: []
        };
    }
};

export const CHILD_NODE_MAPPERS = [
    enumMapper,
    pathMapper,
    propertyPathMapper,
    navigationPropertyPathMapper,
    annotationPathMapper,
    stringMapper,
    collectionMapper,
    booleanMapper,
    recordMapper,
    filterMapper
];
