import type { Element } from '@sap-ux/odata-annotation-core';
import { ATTRIBUTE_TYPE, ELEMENT_TYPE, Edm } from '@sap-ux/odata-annotation-core';
import type { CompletionItem } from 'vscode-languageserver';
import { CompletionItemKind, InsertTextFormat, TextEdit } from 'vscode-languageserver';
import { recordTypePropertyNameAdapter } from '../adapters/recordTypePropertyName';

import type {
    CompletionContext,
    CompletionItemAdapterParams,
    CompletionItemMapperParams,
    CompletionItemMapperWithGate,
    ModularCompletionHandler,
    PropertyNameContext,
    ProviderResult
} from '../types';
import { basicItemProvider } from '../utils';

function propertyNameGate(context: CompletionContext): boolean {
    return context.type === 'key' && context.kind === 'property-name';
}

function propertyNameAdapter({
    context: { proposedReplacementRange: replacementRange },
    originalItem
}: CompletionItemAdapterParams<PropertyNameContext>): CompletionItem | undefined {
    const insertText = originalItem.insertText;
    return {
        label: originalItem.insertText,
        insertTextFormat: InsertTextFormat.PlainText,
        kind: CompletionItemKind.Property,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        filterText: insertText,
        textEdit: TextEdit.replace(replacementRange, insertText),
        commitCharacters: ['.']
    };
}

function typeMapperGate({ args: { pointer }, item }: CompletionItemMapperParams<PropertyNameContext>): boolean {
    return item.label === 'Type' && pointer.endsWith('attributes/Type/name');
}

function mapTypeItem({
    args: { pointer, file, position, getCompletionItems }
}: CompletionItemMapperParams<PropertyNameContext>): ProviderResult {
    const segments = pointer.split('/');
    const recordElement: Element = segments.slice(1, -3).reduce((accumulator, segment) => accumulator[segment], file);
    if (!recordElement.content) {
        recordElement.content = [];
    }
    recordElement.content.push({
        type: ELEMENT_TYPE,
        name: Edm.PropertyValue,
        nameRange: null,
        contentRange: recordElement.contentRange,
        range: recordElement.range,
        attributes: {
            [Edm.Property]: {
                type: ATTRIBUTE_TYPE,
                name: Edm.Property,
                nameRange: null,
                value: '',
                valueRange: recordElement.attributes[Edm.Type].valueRange
            }
        },
        content: []
    });
    const newPointer = [
        ...segments.slice(0, -3),
        'content',
        recordElement.content.length - 1,
        'attributes',
        Edm.Property,
        'value'
    ].join('/');

    const itemsForAdapter = getCompletionItems(file, position, false, newPointer);
    return {
        itemsForAdapter,
        completionItems: []
    };
}
const typeMapper: CompletionItemMapperWithGate = { gate: typeMapperGate, mapper: mapTypeItem };

export const propertyNameHandler: ModularCompletionHandler = {
    name: 'property-name',
    type: 'modular',
    gate: propertyNameGate,
    providers: [basicItemProvider],
    mappers: [typeMapper],
    adapters: [propertyNameAdapter, recordTypePropertyNameAdapter]
};
