export function isInitialSegment(startString: string): boolean {
    const segments = (startString || '').split('/');
    return segments.length === 1;
}

export function completeTarget(context: Context, startString: string, aliasInfo: AliasInformation): CompletionItem[] {
    // code completion on target path
    const completionItems: CompletionItem[] = [];
    const originalSegments = startString.split('/');
    // only consider completed segments - remove (maybe unfinished) last segment; remove aliases from completed segments
    originalSegments.pop();
    const segments = originalSegments.map((originalSegment) => {
        return getSegmentWithoutAlias(aliasInfo, originalSegment);
    });
    // lookup cache and assemble completion results
    const valueHandlingContext = {
        context: context,
        aliasInfo: aliasInfo
    };
    const pathInfo = getPathInfo(valueHandlingContext, segments, [], [], false);
    if (pathInfo.validPath) {
        pathInfo.nextPossibleSegments.forEach((segment) => {
            let completionText = segment.name;
            // convert namespaces to alias
            if (completionText.includes('.')) {
                let aliasedName = completionText;
                aliasedName = toAliasQualifiedName(aliasedName, aliasInfo);
                completionText = aliasedName;
            }
            if (completionText) {
                const path = pathInfo.value ? pathInfo.value + '/' + segment.name : segment.name;
                // take first available target kind for metadata element as category
                const targetKinds = context.metadata
                    .getEdmTargetKinds(path)
                    .filter((targetKind) => targetKind !== 'Collection');
                const documentation: string[] = [];
                let truncated = completionText;
                if (completionText.includes('.') && !completionText.includes('@')) {
                    truncated = appendNameToDocumentationAndTruncate(
                        completionText,
                        documentation,
                        context,
                        false,
                        aliasInfo
                    );
                } else {
                    appendNameToDocumentationAndTruncate(completionText, documentation, context, false, null, 'Item');
                }
                let category = '' as CompletionItemCategory;
                if (targetKinds.length) {
                    documentation.push(`**Target Kind:** ${targetKinds[0]} \n`);
                    category = targetKinds[0] as CompletionItemCategory;
                }
                completionItems.push({
                    text: truncated,
                    filterText: completionText,
                    insertText: completionText,
                    name: completionText,
                    commitCharacters: segment.usages === SegmentUsage.asLastSegmentOnly ? [] : ['/'],
                    commitCharacterRequired: segment.usages === SegmentUsage.asIntermediateSegmentOnly,
                    category: category,
                    documentation: { kind: MarkupKind.Markdown, value: documentation.join('\n\n') }
                });
            }
        });
    }

    return completionItems;
}

export function getAffectedRange(commitCharacters, completeString: CompleteString): Range {
    let startStringLength = completeString.position.character - completeString.startString.length;
    let remainingStringLength = completeString.position.character + completeString.remainingString.length;

    const commitCharacter = commitCharacters && commitCharacters.length ? commitCharacters[0] : '';

    // limit to the left with commitCharacter or '/'
    const fragmentArray = completeString.startString.split(commitCharacter || '/');
    if (fragmentArray.length > 1) {
        const newString = fragmentArray.pop();
        startStringLength = completeString.position.character - newString.toString().length;
    }

    // limit to the right only if commitCharacter is present
    if (commitCharacter) {
        const remainingStringFragment = completeString.remainingString.split(commitCharacter);
        if (remainingStringFragment.length > 1) {
            const newString = remainingStringFragment.slice(0, 1);
            remainingStringLength = completeString.position.character + newString.toString().length;
        }
    }

    // Return affected range: Range
    return {
        start: {
            line: completeString.position.line,
            character: startStringLength
        },
        end: {
            line: completeString.position.line,
            character: remainingStringLength
        }
    };
}

function resolveTerm(context: Context, cursorContext: CursorContext, aliasInfo: AliasInformation): Term {
    const termAttributeValue = getElementAttributeValue(cursorContext.annotation, 'Term') || '';
    const resolvedTermName = resolveName(termAttributeValue, aliasInfo.aliasMapVocabulary);
    return context.vocabularies.getTerm(resolvedTermName.qName);
}

export function getTargetTypeAssocKey(
    metadata: MetadataService,
    targetKinds: string[],
    target: MetadataElement
): FullyQualifiedTypeName {
    let targetTypeAssocKey = '';
    if (target.isEntityType && targetKinds.includes(Edm.Property) && targetKinds.includes(Edm.NavigationProperty)) {
        // find type of first key of associated entity
        const assocTarget = metadata.getMetadataElement(target.structuredType);
        const firstKeyName = (assocTarget?.keys || [])[0];
        if (firstKeyName) {
            const mdName = target.structuredType + '/' + firstKeyName;
            targetTypeAssocKey = metadata.getMetadataElement(mdName)?.edmPrimitiveType || '';
        }
    }
    return targetTypeAssocKey;
}

export function getAliasQualifiedNameDefVoc(name: FullyQualifiedName, namespaceToAlias: AliasMap): string {
    const resolvedName = resolveName(name);
    if (resolvedName && namespaceToAlias[resolvedName.namespace]) {
        return namespaceToAlias[resolvedName.namespace] + '.' + resolvedName.name;
    } else {
        return name;
    }
}

export function getTargetInfoFromCursorContext(
    cursorContext: CursorContext,
    context: Context,
    aliasInfo: AliasInformation
): {
    targetKinds: TargetKind[];
    targetType: FullyQualifiedTypeName;
    targetTypeAssocKey: FullyQualifiedTypeName;
    applicableTermsConstraint?: string[];
} {
    let targetKinds: TargetKind[] = [];
    let targetType: FullyQualifiedTypeName = '';
    let targetTypeAssocKey: FullyQualifiedTypeName = '';
    let applicableTermsConstraint: string[] | undefined;
    if (cursorContext.embeddedIn) {
        targetKinds = [cursorContext.embeddedIn];
        targetType = cursorContext.embeddedType;
        applicableTermsConstraint = cursorContext.embeddedApplicableTerms;
    } else {
        const metadataElement = lookupTarget(context, cursorContext.targetPath, aliasInfo).metadataElement;
        if (metadataElement) {
            targetKinds = metadataElement.targetKinds;
            targetType = convertValueTypeToString(getValueTypeForMetadataElement(metadataElement));
            targetTypeAssocKey = getTargetTypeAssocKey(context.metadata, targetKinds, metadataElement);
        }
    }
    return { targetKinds, targetType, targetTypeAssocKey, applicableTermsConstraint };
}

export function getTermsForCompletion(
    context: Context,
    targetKinds: TargetKind[],
    targetType: string,
    targetTypeAssocKey: string,
    aliasInfo: AliasInformation,
    applicableTermsConstraint?: string[]
): TermDataForCompletion[] {
    const result: TermDataForCompletion[] = [];
    let termsByTarget = context.vocabularies.getTermsForTargetKinds(targetKinds, targetType);

    if (targetKinds.includes(Edm.NavigationProperty) && targetKinds.includes(Edm.Property) && targetTypeAssocKey) {
        // CDS associations have target kinds 'Property' and 'NavigationProperty'
        // in that case, when selecting terms applicable to 'Property': check with targetTypeAssocKey
        const additionalTerms = context.vocabularies.getTermsForTargetKinds([Edm.Property], targetTypeAssocKey);
        (additionalTerms || []).forEach((additionalTerm) => {
            if (!termsByTarget.includes(additionalTerm)) {
                termsByTarget.push(additionalTerm);
            }
        });
    }

    // build namespace to alias map including default vocabulary aliases
    const namespaceToAlias: AliasMap = Object.assign({}, aliasInfo.reverseAliasMap);
    context.vocabularies.getVocabularies().forEach((vocabulary) => {
        if (!namespaceToAlias[vocabulary.namespace]) {
            namespaceToAlias[vocabulary.namespace] = vocabulary.defaultAlias;
        }
    });

    if (applicableTermsConstraint) {
        termsByTarget = termsByTarget.filter((term) => applicableTermsConstraint.includes(term));
    }

    termsByTarget.forEach((termName) => {
        const term = context.vocabularies.getTerm(termName);
        // by default show alias
        const name = getAliasQualifiedNameDefVoc(termName, namespaceToAlias);
        const namespace = resolveName(termName).namespace;
        const documentation = context.vocabularies.getDocumentation(term.name, undefined, aliasInfo);
        const truncatedName = appendNameToDocumentationAndTruncate(name, documentation, context, true, aliasInfo);
        result.push({
            term,
            name,
            namespace,
            documentation,
            truncatedName
        });
    });
    return result;
}

export function completeTerm(
    context: Context,
    targetKinds: TargetKind[],
    targetType: string,
    targetTypeAssocKey: string,
    aliasInfo: AliasInformation,
    applicableTermsConstraint?: string[]
): CompletionItem[] {
    return getTermsForCompletion(
        context,
        targetKinds,
        targetType,
        targetTypeAssocKey,
        aliasInfo,
        applicableTermsConstraint
    ).map((item) => {
        if (context.vocabularies.cdsVocabulary.reverseNameMap.has(item.name)) {
            item.name = context.vocabularies.cdsVocabulary.reverseNameMap.get(item.name);
            item.truncatedName = item.name;
        }
        const completionItem: CompletionItem = {
            name: item.name,
            text: item.truncatedName || item.name,
            id: item.term.name,
            filterText: item.name,
            insertText: item.name,
            deprecated: !!item.term.deprecated,
            sorting: {},
            category: CompletionItemCategory.Term,
            documentation: { kind: MarkupKind.Markdown, value: item.documentation.join('\n') }
        };
        completionItem.sorting.isUIVocabulary = item.namespace === 'com.sap.vocabularies.UI.v1';
        completionItem.sorting.isAlias = item.term.name !== item.name;
        return completionItem;
    });
}

export function hoverTerm(
    context: Context,
    pathTargetInElement: PathTargetInElement,
    aliasInfo: AliasInformation
): Hover {
    const resolvedName = resolveName(pathTargetInElement.attribute.value, aliasInfo.aliasMap);
    const namespace = resolvedName.namespace;
    const term = resolvedName.name;
    const fullyQualifiedName: FullyQualifiedName = namespace && term ? `${namespace}.${term}` : '';
    const vocabularyDocumentation: MarkdownString[] = context.vocabularies.getDocumentation(
        fullyQualifiedName,
        undefined,
        aliasInfo
    );
    return {
        contents: {
            kind: MarkupKind.Markdown,
            value: vocabularyDocumentation.join('\n')
        },
        range: pathTargetInElement.attribute.valueRange
    };
}

/**
 * Hover handler for trusted content to provide guide links
 * @param fileUri : file uri
 * @param pathTargetInElement : target path
 * @param aliasInfo : alias info
 */
export function hoverTermTrusted(
    context: Context,
    fileUri: FileUri,
    pathTargetInElement: PathTargetInElement,
    aliasInfo: AliasInformation
): string[] {
    const webappUri = getWebappUri(fileUri);
    let rootPath = webappUri.substr(0, webappUri.lastIndexOf('/webapp'));
    rootPath = Uri.parse(rootPath).fsPath;
    const resolvedName = resolveName(pathTargetInElement.attribute.value, aliasInfo.aliasMap);
    const guideCommandUriLinks: MarkdownString[] = [];
    const defaultAlias = context.vocabularies.getDefaultAlias(resolvedName.namespace);
    const termName = defaultAlias + '.' + resolvedName.name;
    const guidesForTerm = guidesForAnnotationJSON[termName];
    const getGuidedDevUri = (guideId?: string, searchTerm?: string): Uri =>
        Uri.parse(
            `command:sap.ux.help.openGuidedDevelopmentToTheSide?${encodeURIComponent(
                JSON.stringify({
                    projectParameters: { rootPath: rootPath, appId: '' },
                    filterParameters: { guideId, searchTerm },
                    source: 'annotation-lsp'
                } as OpenGuidedDevParameters)
            )}`
        );

    for (let index = 0; index < guidesForTerm.length; index++) {
        if (index === 0) {
            guideCommandUriLinks.push('**Fiori Guides:**');
        }

        const guide = guidesForTerm[index];
        guideCommandUriLinks.push(`\n[${guide.guideTitle}](${getGuidedDevUri(guide.guideId)})`);

        // restrict to atmost 3 guides
        if (index === 2) {
            guideCommandUriLinks.push(`\n[More...](${getGuidedDevUri('', termName)})`);
            break;
        }
    }

    return guideCommandUriLinks;
}

export function hoverTarget(context: Context, element: Target, aliasInfo: AliasInformation): Hover {
    let resolvedName = '';
    let targetKinds = [];

    const segments = element.name.split('/');
    if (segments.length > 1) {
        segments.forEach((segment, index, array) => {
            let metadataElement;
            if (index === 0) {
                resolvedName = resolveName(segment, aliasInfo.aliasMapMetadata).qName;
                metadataElement = context.metadata.getMetadataElement(resolvedName);
            } else {
                const path = resolvedName + '/' + segment;
                metadataElement = context.metadata.getMetadataElement(path);
                if (array.length - 1 !== index && metadataElement.structuredType) {
                    resolvedName = metadataElement.structuredType;
                } else {
                    resolvedName = resolvedName + '/' + segment;
                }
            }
        });
    } else {
        resolvedName = resolveName(element.name, aliasInfo.aliasMapMetadata).qName;
    }
    targetKinds = context.metadata.getEdmTargetKinds(resolvedName);

    return {
        contents: {
            kind: MarkupKind.Markdown,
            value: targetKinds.length ? `**Target Kind:** ${targetKinds[0]} \n` : undefined
        },
        range: element.nameRange
    };
}

export interface AnnotationCompletionContext {
    resolvedTarget: MetadataElement;
    resolvedTerm: Term;
    valueType: ValueType;
    valueHandlingContext: ValueHandlingContext;
    resolvedCursorContext: ResolvedCursorContext;
}

export function getAnnotationCompletionContext(
    context: Context,
    cursorContext: CursorContext,
    aliasInfo: AliasInformation,
    logger: Logger,
    forSnippetCreation?: boolean
): AnnotationCompletionContext {
    // resolve target
    const target = lookupTarget(context, cursorContext.targetPath, aliasInfo).metadataElement;

    // resolve term
    const term = resolveTerm(context, cursorContext, aliasInfo);

    const result: AnnotationCompletionContext = {
        resolvedTarget: target,
        resolvedTerm: term,
        valueType: undefined,
        valueHandlingContext: undefined,
        resolvedCursorContext: undefined
    };

    if (target) {
        result.valueType = getValueTypeFromTerm(context, term, true);
        const qualifier = getElementAttributeValue(cursorContext.annotation, Edm.Qualifier);
        const targetTermQualifier = term ? target.path + '/@' + term.name + (qualifier ? '#' + qualifier : '') : '';
        result.valueHandlingContext = {
            context,
            aliasInfo,
            pathBase: getPathBaseMetadataElement(context.metadata, cursorContext.targetPath, aliasInfo),
            targetTermQualifier
        };
        if (context.supportSplit) {
            // collect data for identification of structure property (for CDS split annotation support)
            if (cursorContext.fileUri) {
                result.valueHandlingContext.currentFileUri = cursorContext.fileUri;
            }
            const segments = cursorContext.targetPath.split('/');
            const targetPathResolved = segments
                .map((segment) => {
                    return getSegmentWithoutAlias(aliasInfo, segment);
                })
                .join('/');
            result.valueHandlingContext.currentStructureProperty = {
                targetPath: targetPathResolved,
                term: term.name,
                qualifier: getElementAttributeValue(cursorContext.annotation, Edm.Qualifier),
                propertyPathSegments: forSnippetCreation ? null : [] // snippet creation: don't consider split annotations
            };
        }
        result.resolvedCursorContext = resolve(
            result.valueHandlingContext,
            result.valueType,
            cursorContext.annotation,
            cursorContext.path,
            logger
        );
    }
    return result;
}

export function completeAnnotationValue(
    context: Context,
    cursorContext: CursorContext,
    startString: string,
    aliasInfo: AliasInformation,
    logger: Logger,
    completeComplexAnnotationSnippet?: CompleteComplexAnnotationSnippetCallback
): CompletionItem[] {
    const { resolvedTarget, resolvedTerm, valueHandlingContext, resolvedCursorContext } =
        getAnnotationCompletionContext(context, cursorContext, aliasInfo, logger);

    if (!resolvedTarget || (!resolvedTerm && !cursorContext.embeddedIn)) {
        return [];
    }

    function logCompletionRequest(typeObject: ValueType, resolvedCursorContext, logger: Logger): void {
        const typeNameText = convertValueTypeToString(typeObject);
        const fixNameText = resolvedCursorContext.fixElementName
            ? ', fixElementName: ' + resolvedCursorContext.fixElementName
            : '';
        const message = `CC for element: ${resolvedCursorContext.element.name}, type: ${typeNameText}, path: ${resolvedCursorContext.path}, startString: ${startString}${fixNameText}`;
        logger.info(message);
    }

    // do completion on value
    const compItems: CompletionItem[] = [];

    const allowedTypes = adjustRequestedTypes(
        resolvedCursorContext.types.map((t) => convertValueTypeFromString(t)),
        valueHandlingContext,
        true
    ).map((t) => convertValueTypeToString(t));

    // get most specific value and possible types for cursor context
    const completionItemsMap: CompletionItemMap = {};
    // collect & consolidate completion items for all possible types
    if (!(resolvedCursorContext.typeOfAlreadyProvidedValue && !resolvedCursorContext.alreadyProvidedValueIsAfter)) {
        (allowedTypes || []).forEach((typeName) => {
            // build type object from type name and facets/constraints
            const valueType = convertValueTypeFromString(typeName);
            valueType.facets = resolvedCursorContext.facets;
            valueType.constraints = resolvedCursorContext.constraints;
            logCompletionRequest(valueType, resolvedCursorContext, logger);
            const compItemsLocal = completeValue(
                valueHandlingContext,
                valueType,
                resolvedCursorContext.element,
                startString,
                resolvedCursorContext.path,
                resolvedCursorContext.fixElementName
            );
            compItemsLocal.forEach((item) => {
                if (!completionItemsMap[item.name]) {
                    completionItemsMap[item.name] = item;
                }
            });
        });
    }

    const elementContext = cursorContext.elementContext;
    if (elementContext.parentElement && !elementContext.attributeArea) {
        if (isAnnotationAllowed(elementContext.parentElement)) {
            const compItemsLocal = completeInlineAnnotationElement(
                cursorContext,
                resolvedCursorContext,
                valueHandlingContext,
                logger,
                completeComplexAnnotationSnippet
            );
            compItemsLocal.forEach((item) => {
                if (!completionItemsMap[item.name]) {
                    completionItemsMap[item.name] = item;
                }
            });
        }
    }

    Object.keys(completionItemsMap).forEach((key) => {
        compItems.push(completionItemsMap[key]);
    });

    return compItems;
}

export function getResolvedUntypedValueTypes(requestedTypes: ValueType[]): ValueType[] {
    const result: ValueType[] = [];
    requestedTypes.forEach((type) => {
        if (type.name === EdmType.Untyped && type.constraints?.derivedTypeConstraints?.length) {
            const derivedTypes: ValueType[] = type.constraints.derivedTypeConstraints.map((dTypeAsString) => {
                const derivedType = convertValueTypeFromString(dTypeAsString);
                derivedType.constraints = { ...type.constraints, derivedTypeConstraints: undefined };
                derivedType.facets = type.facets;
                return derivedType;
            });
            result.push(...derivedTypes);
        } else if (type.name === EdmType.AnyPropertyPath) {
            for (const resolvedTypeName of [EdmType.PropertyPath, EdmType.NavigationPropertyPath]) {
                result.push({ ...type, name: resolvedTypeName });
            }
        } else {
            result.push(type);
        }
    });
    return result;
}

function completeInlineAnnotationElement(
    cursorContext: CursorContext,
    resolvedCursorContext: ResolvedCursorContext,
    valueHandlingContext: ValueHandlingContext,
    logger: Logger,
    callbackEmbeddedAnnotations?: CompleteComplexAnnotationSnippetCallback
): CompletionItem[] {
    const target = getPathTargetInElement(resolvedCursorContext.path, resolvedCursorContext.element);
    if (target.isTextSubNode || target.textNode || target.isWhitespacePosition) {
        if (callbackEmbeddedAnnotations) {
            return callbackEmbeddedAnnotations(
                cursorContext,
                valueHandlingContext.context,
                valueHandlingContext.aliasInfo,
                logger,
                true,
                resolvedCursorContext?.constraints?.applicableTerms
            );
        }
    } else if (target.isElementSubNodeName || target.isName) {
        return [
            {
                name: Edm.Annotation,
                text: Edm.Annotation,
                category: CompletionItemCategory.Annotation
            }
        ];
    } else {
        return [];
    }
}

/********************************************
 * Annotation value check
 * @param context - context object
 * @param annotation - annotation element
 * @param pathBase - metadata element which is used as base for path expressions
 * @param target - annotation target
 * @param targetPath - path which was used to identify the target
 * @param aliasInfo - alias information
 * @param targetTermMap - term/qualifier uniqueness control map (is modified within the function)
 * @param checkTrace - element path trace object
 * @param targetKindsEmbedded - if provided: use this to check term applicability (needed for embedded annotations)
 * @param targetTypeEmbedded - if provided: use this to check term applicability (needed for embedded annotations)
 */
export function checkAnnotationValue(
    context: Context,
    annotation: Element,
    pathBase: MetadataElement,
    target: MetadataElement,
    targetPath: PathValue,
    aliasInfo: AliasInformation,
    targetTermMap: Map<string, boolean>,
    checkTrace: CheckTrace,
    logger: Logger,
    applicableTermsConstraint?: string[],
    targetKindsEmbedded?: TargetKind[],
    targetTypeEmbedded?: FullyQualifiedTypeName
): Diagnostic[] {
    let messages: Diagnostic[] = [];
    const term = getElementAttributeValue(annotation, 'Term');
    const qualifier = getElementAttribute(annotation, 'Qualifier');
    checkTrace.registerTerm(term, qualifier && qualifier.value);
    try {
        if (qualifier && qualifier.value && isQualifierInvalid(qualifier.value)) {
            const message = i18n.t('Qualifier_0_should_be_of_type_SimpleIdentifier', {
                qualifier: qualifier.value
            });
            messages.push({
                message: message,
                severity: DiagnosticSeverity.Error,
                range: qualifier.valueRange
            });
        }

        let targetKinds = [];
        let targetType = '';
        let targetTypeAssocKey = '';
        if (targetKindsEmbedded && targetKindsEmbedded.length) {
            targetKinds = targetKindsEmbedded;
            targetType = targetTypeEmbedded;
        } else {
            targetKinds = target.targetKinds;
            targetType = convertValueTypeToString(getValueTypeForMetadataElement(target));
            targetTypeAssocKey = getTargetTypeAssocKey(context.metadata, targetKinds, target);
        }
        const termResult = lookupTerm(
            context,
            targetKinds,
            targetType,
            targetTypeAssocKey,
            annotation,
            term,
            aliasInfo,
            applicableTermsConstraint
        );
        if (termResult.diagnostic) {
            messages.push(termResult.diagnostic);
        } else {
            const termName = resolveName(termResult.object.name, aliasInfo.aliasMapVocabulary).qName;
            let targetTermKey = `${targetPath}[${termName}]`;

            if (qualifier && qualifier.value) {
                targetTermKey = `${targetTermKey}[${qualifier.value}]`;
            }

            if (targetTermMap.has(targetTermKey)) {
                const message = i18n.t('Enter_a_unique_qualifier_for_0', {
                    term: context.vocabularies.cdsVocabulary.reverseNameMap.get(term) || term
                });
                messages.push({
                    message: message,
                    severity: DiagnosticSeverity.Error,
                    range: qualifier ? qualifier.valueRange : annotation.nameRange,
                    rule: IGNORE_DUPLICATE
                });
            } else {
                targetTermMap.set(targetTermKey, true);
            }

            const valueType = getValueTypeFromTerm(context, termResult.object);
            const valueHandlingContext: ValueHandlingContext = {
                context: context,
                aliasInfo: aliasInfo,
                pathBase: pathBase
            };
            if (context.supportSplit) {
                valueHandlingContext.currentStructureProperty = {
                    targetPath: targetPath,
                    term: termName,
                    qualifier: getElementAttributeValue(annotation, Edm.Qualifier),
                    propertyPathSegments: []
                };
            }
            const valueMessages = checkValue(valueHandlingContext, [valueType], annotation, null, checkTrace, logger);
            messages = messages.concat(valueMessages);
        }
    } catch (exceptionTerm) {
        const msg = `AnnotationService: error checking term "${checkTrace.getPath()}": ${exceptionTerm}`;
        logger.error(msg);
    }
    return messages;
}

export function hoverAnnotationValue(
    context: Context,
    cursorContext: CursorContext,
    aliasInfo: AliasInformation,
    position: Position,
    logger: Logger
): Hover {
    let hover: Hover = null;
    // resolve target
    const target = lookupTarget(context, cursorContext.targetPath, aliasInfo).metadataElement;

    // resolve term
    const term = resolveTerm(context, cursorContext, aliasInfo);

    if (!target || !term) {
        return hover;
    }
    const valueType: ValueType = getValueTypeFromTerm(context, term);
    const pathBase = getPathBaseMetadataElement(context.metadata, cursorContext.targetPath, aliasInfo);
    const valueHandlingContext: ValueHandlingContext = { context: context, aliasInfo: aliasInfo, pathBase: pathBase };
    if (context.supportSplit) {
        // collect data for identification of structure property (for CDS split annotation support)
        if (cursorContext.fileUri) {
            valueHandlingContext.currentFileUri = cursorContext.fileUri;
        }
        const segments = cursorContext.targetPath.split('/');
        const targetPathResolved = segments
            .map((segment) => {
                return getSegmentWithoutAlias(aliasInfo, segment);
            })
            .join('/');
        valueHandlingContext.currentStructureProperty = {
            targetPath: targetPathResolved,
            term: term.name,
            qualifier: getElementAttributeValue(cursorContext.annotation, Edm.Qualifier),
            propertyPathSegments: []
        };
    }
    const resolvedCursorContext = resolve(
        valueHandlingContext,
        valueType,
        cursorContext.annotation,
        cursorContext.path,
        logger
    );
    if (!(resolvedCursorContext.typeOfAlreadyProvidedValue && !resolvedCursorContext.alreadyProvidedValueIsAfter)) {
        (resolvedCursorContext.types || []).forEach((typeName) => {
            const valueType: ValueType = convertValueTypeFromString(typeName);
            valueType.facets = resolvedCursorContext.facets;
            valueType.constraints = resolvedCursorContext.constraints;
            hover = hoverValue(
                valueHandlingContext,
                valueType,
                resolvedCursorContext.element,
                resolvedCursorContext.path,
                position
            );
        });
    }
    return hover;
}

export interface LookupResult {
    metadataElement: MetadataElement;
    errorMessage: string;
    resolvedPath: PathValue;
    resolvedPathWithoutAlias: PathValue;
    caseIssue: CaseIssue;
    isCollection: boolean;
}

export function lookupTarget(context: Context, targetPath: PathValue, aliasInfo: AliasInformation): LookupResult {
    const lookupResult: LookupResult = {
        metadataElement: null,
        errorMessage: '',
        resolvedPath: targetPath,
        resolvedPathWithoutAlias: '',
        caseIssue: null,
        isCollection: false
    };
    // translate targetPath into segments (with removed alias)
    const originalSegments = targetPath.split('/');
    const segments = originalSegments.map((segment) => {
        return getSegmentWithoutAlias(aliasInfo, segment);
    });
    lookupResult.resolvedPathWithoutAlias = segments.join('/');
    // try to lookup target directly in metadata
    lookupResult.metadataElement = getMdElementForMdPath(lookupResult.resolvedPathWithoutAlias, context.metadata);
    if (lookupResult.metadataElement) {
        return lookupResult;
    }
    // resolve target via path expression cache
    const valueHandlingContext = {
        context: context,
        aliasInfo: aliasInfo
    };
    const pathInfo = getPathInfo(valueHandlingContext, segments, [], [], true);
    // fill result
    if (pathInfo.validPath && typeof pathInfo.value === 'string') {
        lookupResult.resolvedPath = targetPath;
        lookupResult.metadataElement = context.metadata.getMetadataElement(pathInfo.value);
        lookupResult.isCollection = pathInfo.isCollection;
    }
    if (pathInfo.caseIssues) {
        const originalSegment = originalSegments[pathInfo.invalidSegmentIndex];
        pathInfo.caseIssues.wrong = originalSegment;
        lookupResult.caseIssue = pathInfo.caseIssues;
    } else if (!lookupResult.metadataElement) {
        if (!context.supportSplit && !Object.keys(aliasInfo.aliasMapMetadata).length) {
            lookupResult.errorMessage = i18n.t('No_namespace_or_Invalid_namespace_defined');
            lookupResult.resolvedPath = '';
        } else if (pathInfo.invalidSegmentIndex >= 0 && pathInfo.invalidSegmentIndex < segments.length) {
            lookupResult.errorMessage = i18n.t('Invalid_target_check_0', {
                segment: originalSegments[pathInfo.invalidSegmentIndex]
            });
            lookupResult.resolvedPath = originalSegments.slice(0, pathInfo.invalidSegmentIndex).join('/');
        } else {
            lookupResult.errorMessage = i18n.t('Invalid_target_0', {
                target: targetPath
            });
            lookupResult.resolvedPath = '';
        }
    }
    return lookupResult;
}

interface LookupTermResult {
    object?: Term;
    diagnostic?: Diagnostic;
}

// TODO reduce range to segments beyond termResult.resolvedPath
const getTermErrorRange = (annotation: Element): Range =>
    annotation.attributes && annotation.attributes['Term']
        ? annotation.attributes['Term'].valueRange
        : annotation.nameRange;

function getXmlDocNamespaceOrAliasByTerm(
    supportedVocabularyNamespace: string,
    termValue: AttributeValue,
    resolvedTerm: ResolvedName
): NamespaceString | Alias {
    if (termValue === supportedVocabularyNamespace || termValue.startsWith(supportedVocabularyNamespace)) {
        return supportedVocabularyNamespace;
    }
    return resolvedTerm.namespace || termValue.split('.')[0];
}

function getTermApplicabilityAndNameSpace(
    context: Context,
    aliasInfo: AliasInformation,
    contextParams: {
        targetKinds: TargetKind[];
        targetType: FullyQualifiedTypeName;
        targetTypeAssocKey: FullyQualifiedTypeName;
        supportedVocabularyNamespace: string;
        resolvedTerm: ResolvedName;
        termValue: AttributeValue;
        applicableTermsConstraint?: string[];
    }
): { termApplicability: TermApplicability | null; xmlDocNamespaceOrAlias: NamespaceString | Alias | undefined } {
    const {
        targetKinds,
        targetType,
        targetTypeAssocKey,
        supportedVocabularyNamespace,
        termValue,
        resolvedTerm,
        applicableTermsConstraint
    } = contextParams;
    let termApplicability: TermApplicability | null = null;
    const currentTermNamespace = resolvedTerm.namespace ? resolvedTerm.namespace : aliasInfo.aliasMap[termValue];
    let xmlDocNamespaceOrAlias: NamespaceString | Alias | undefined;

    if (!aliasInfo.aliasMapVocabulary[supportedVocabularyNamespace]) {
        termApplicability = TermApplicability.UnSupportedVocabulary;
        if (supportedVocabularyNamespace) {
            termApplicability = TermApplicability.UnknownVocabulary;
            xmlDocNamespaceOrAlias = getXmlDocNamespaceOrAliasByTerm(
                supportedVocabularyNamespace,
                termValue,
                resolvedTerm
            );
        }
        return { termApplicability, xmlDocNamespaceOrAlias };
    }

    const value = !resolvedTerm.namespace
        ? context.vocabularies.getVocabulary(currentTermNamespace)?.namespace
        : resolvedTerm.qName;
    termApplicability = context.vocabularies.checkTermApplicability(value, targetKinds, targetType);

    // CDS associations have target kinds 'Property' and 'NavigationProperty'
    // in that case, when selecting terms applicable to 'Property': check with targetTypeAssocKey

    if (
        termApplicability === TermApplicability.TypeNotApplicable &&
        targetTypeAssocKey &&
        [Edm.Property, Edm.NavigationProperty].every((item) => targetKinds.includes(item)) &&
        context.vocabularies.checkTermApplicability(value, [Edm.Property], targetTypeAssocKey) ===
            TermApplicability.Applicable
    ) {
        termApplicability = TermApplicability.Applicable;
    }

    if (
        termApplicability === TermApplicability.Applicable &&
        applicableTermsConstraint?.length &&
        !applicableTermsConstraint.includes(resolvedTerm.qName)
    ) {
        termApplicability = TermApplicability.NotInApplicableTermsConstraint;
    }

    return { termApplicability, xmlDocNamespaceOrAlias };
}

export function lookupTerm(
    context: Context,
    targetKinds: TargetKind[],
    targetType: FullyQualifiedTypeName,
    targetTypeAssocKey: FullyQualifiedTypeName,
    annotation: Element,
    termValue: AttributeValue,
    aliasInfo: AliasInformation,
    applicableTermsConstraint?: string[]
): LookupTermResult {
    const lookupTermResult: LookupTermResult = {};
    const resolvedTerm = resolveName(termValue, aliasInfo.aliasMapVocabulary);

    let unSupportedVocabulary = '';
    let vocabularyTerm: Term;
    const range = getTermErrorRange(annotation);
    const currentTermNamespace = resolvedTerm.namespace || aliasInfo.aliasMap[termValue];
    const namespaceOrAlias = currentTermNamespace || resolvedTerm.name;
    if (!termValue) {
        const message = i18n.t('Invalid_Term');
        lookupTermResult.diagnostic = createErrorDiagnostic(message, range);
        return lookupTermResult;
    }
    const supportedVocabularyNamespace = context.vocabularies.getVocabularyNamespace(namespaceOrAlias);
    const resolvedTermValue = resolveName(termValue);
    unSupportedVocabulary = resolvedTermValue.namespace || resolvedTermValue.name;

    const { termApplicability, xmlDocNamespaceOrAlias } = getTermApplicabilityAndNameSpace(context, aliasInfo, {
        targetKinds,
        targetType,
        targetTypeAssocKey,
        supportedVocabularyNamespace,
        termValue,
        resolvedTerm,
        applicableTermsConstraint
    });
    const termVocabularyObject = context.vocabularies.cdsVocabulary.reverseNameMap.get(termValue) || termValue;

    switch (termApplicability) {
        case TermApplicability.UnknownVocabulary: {
            lookupTermResult.diagnostic = createUnknownVocabularyDiagnostic(
                xmlDocNamespaceOrAlias,
                supportedVocabularyNamespace,
                range,
                context.vocabularies
            );
            break;
        }
        case TermApplicability.UnknownTerm: {
            const name = resolvedTerm.alias ? `${resolvedTerm.alias}.${resolvedTerm.name}` : resolvedTerm.name;
            const message = i18n.t('Annotation_0_is_not_available_in_vocabulary_1', {
                term: name,
                vocabulary: supportedVocabularyNamespace
            });
            lookupTermResult.diagnostic = createErrorDiagnosticWithRule(UNKNOWN_TERM, message, range, {
                name: resolvedTerm.name,
                alias: resolvedTerm.alias,
                namespace: resolvedTerm.namespace,
                isVocabulary: Boolean(context.vocabularies.getVocabularyNamespace(resolvedTerm.name)),
                caseCheck: {
                    value: resolvedTerm.name,
                    lookupPath: ['vocabularies', supportedVocabularyNamespace],
                    isNamespacedValue: true
                }
            });
            break;
        }
        case TermApplicability.TermNotApplicable:
            vocabularyTerm = context.vocabularies.getTerm(resolvedTerm.qName);
            if (vocabularyTerm && vocabularyTerm.appliesTo) {
                const message = i18n.t('Term_0_cannot_be_applied_for_target_kind_1_It_can_be_applied_to_2', {
                    term: termVocabularyObject,
                    wrong: targetKinds.join(', '),
                    correct: vocabularyTerm.appliesTo.join(', ')
                });
                lookupTermResult.diagnostic = createWarningDiagnostic(message, range);
                lookupTermResult.diagnostic.rule = 'term-not-applicable';
                lookupTermResult.diagnostic.data = {
                    name: termValue,
                    wrong: targetKinds.join(', '),
                    correct: vocabularyTerm.appliesTo.join(', ')
                };
            }
            break;
        case TermApplicability.NotInApplicableTermsConstraint:
            vocabularyTerm = context.vocabularies.getTerm(resolvedTerm.qName);
            if (vocabularyTerm) {
                const message = i18n.t('Term_0_is_not_in_applicable_term_constraint_allowed_terms_are_1', {
                    term: termVocabularyObject
                });
                lookupTermResult.diagnostic = createWarningDiagnostic(message, range);
                lookupTermResult.diagnostic.rule = NOT_IN_APPLICABLE_TERMS_CONSTRAINT;
                lookupTermResult.diagnostic.data = {
                    name: termValue
                };
            }
            break;
        case TermApplicability.TypeNotApplicable:
            vocabularyTerm = context.vocabularies.getTerm(resolvedTerm.qName);
            if (vocabularyTerm && vocabularyTerm.constraints?.requiresType) {
                const requiresTypeAlias = toAliasQualifiedName(vocabularyTerm.constraints.requiresType, aliasInfo);
                const message = i18n.t('Term_0_cannot_be_applied_to_this_element_It_can_be_applied_to_1_of_type_2', {
                    term: termValue,
                    elements: vocabularyTerm.appliesTo.join(', '),
                    type: requiresTypeAlias
                });
                lookupTermResult.diagnostic = createErrorDiagnostic(message, range);
            }
            break;
        case TermApplicability.Applicable:
            lookupTermResult.object = context.vocabularies.getTerm(resolvedTerm.qName);
            break;

        case TermApplicability.UnSupportedVocabulary: {
            const message = i18n.t('Unsupported_Vocabulary_0', {
                vocabulary: unSupportedVocabulary
            });
            lookupTermResult.diagnostic = createErrorDiagnosticWithRule(UN_SUPPORTED_VOCABULARY, message, range, {
                name: resolvedTerm.name
            });
            break;
        }
    }

    return lookupTermResult;
}

/**
 * Validate namespace value w.r.t odata spec.
 * @param namespace[string]: qualifier value
 */
export function isValidNamespace(namespace: string): boolean {
    return namespace !== undefined && /^[a-zA-Z_][\w]*(\.[a-zA-Z_][\w]*)*$/.test(namespace) === true;
}

/**
 * Validate qualifier value w.r.t odata spec.
 * @param qualifierValue[string]: qualifier value
 */
export function isQualifierInvalid(qualifierValue: AttributeValue): boolean {
    return qualifierValue !== undefined && !isValidSimpleIdentifier(qualifierValue);
}

/**
 * Check whether qualifier value is a simple identifier
 * @param qualifier - qualifier attribute
 */
export function checkQualifierForSimpleIdentifier(qualifier: Attribute): Diagnostic[] {
    const messages: Diagnostic[] = [];
    if (qualifier && qualifier.value && isQualifierInvalid(qualifier.value)) {
        const message = i18n.t('Qualifier_0_should_be_of_type_SimpleIdentifier', {
            qualifier: qualifier.value
        });
        messages.push({
            message: message,
            severity: DiagnosticSeverity.Error,
            range: qualifier.valueRange
        });
    }
    return messages;
}

/**
 * Get the error message for unique qualifier issue
 * @param annotation - annotation element
 * @param term - term value
 * @param qualifier - qualifier attribute
 */
export function getMessageUniqueQualifier(annotation: Element, term: string, qualifier: Attribute): Diagnostic {
    return {
        message: i18n.t('Enter_a_unique_qualifier_for_0', {
            term: term
        }),
        severity: DiagnosticSeverity.Error,
        // TODO reduce range to segments beyond termResult.resolvedPath
        range: qualifier ? qualifier.valueRange : annotation.nameRange
    };
}

export interface CompleteString {
    startString: string;
    remainingString: string;
    position: Position;
}

export function appendNameToDocumentationAndTruncate(
    fullyQualifiedName: FullyQualifiedName | FullyQualifiedTypeName,
    documentation: string[],
    context: Context,
    isVocabularyElement: boolean,
    aliasInfo?: AliasInformation,
    nameLabel = 'Name'
): string {
    let reducedText = fullyQualifiedName;
    if (fullyQualifiedName) {
        if (aliasInfo) {
            const resolved = resolveName(fullyQualifiedName, aliasInfo.aliasMap);
            let alias = resolved.alias;
            let namespace = resolved.namespace;
            if (namespace === context.vocabularies.cdsVocabulary.namespace) {
                const cdsName = context.vocabularies.cdsVocabulary.reverseNameMap.get(alias + '.' + resolved.name);
                if (cdsName) {
                    documentation.unshift(`**${nameLabel}:** ${cdsName}\n`);
                }
            } else {
                let resolvedName = resolved.name;
                let prefix = alias || namespace;

                const re = RegExp(
                    /[\s\S]{0,100}((com\.sap\.vocabularies)|(Org\.OData))\.[a-zA-Z0-9]{0,100}\.[vV]\d[\s\S]{0,500}/
                );
                const containsVocabularyLongName = re.test(fullyQualifiedName);

                if (!prefix && !containsVocabularyLongName && fullyQualifiedName.includes('.')) {
                    const parts = fullyQualifiedName.split('.');
                    prefix = parts.shift();
                    resolvedName = parts.join('.');
                }
                const ln = (prefix || '').length;

                if (containsVocabularyLongName) {
                    if (fullyQualifiedName.includes('com.sap.vocabularies.')) {
                        reducedText = fullyQualifiedName.replace('.sap.vocabularies.', '...');
                    } else if (fullyQualifiedName.includes('Org.OData.')) {
                        reducedText = fullyQualifiedName.replace('.OData.', '...');
                    }
                } else if (ln > 12) {
                    const vocs = context.vocabularies.getVocabularies();
                    let isVocabularyAlias = false;
                    vocs.forEach((v) => {
                        if (v.defaultAlias === prefix) {
                            isVocabularyAlias = true;
                        }
                    });
                    if (!isVocabularyAlias || !isVocabularyElement) {
                        reducedText = `${prefix.slice(0, 3)}...${prefix.slice(ln - 3, ln)}.${resolvedName}`;
                    }
                }

                if (!alias && isVocabularyElement) {
                    context.vocabularies.getVocabularies().forEach((voc) => {
                        if (
                            containsVocabularyLongName
                                ? fullyQualifiedName.includes(voc.namespace)
                                : voc.defaultAlias === prefix
                        ) {
                            alias = voc.defaultAlias;
                            namespace = voc.namespace;
                        }
                    });
                }

                if (alias) {
                    documentation.unshift(`**Alias:** ${alias}\n`);
                }
                if (namespace) {
                    documentation.unshift(`**Namespace:** ${namespace}\n`);
                }
                documentation.unshift(`**${nameLabel}:** ${alias || namespace ? resolvedName : fullyQualifiedName}\n`);
            }
        } else {
            documentation.unshift(`**${nameLabel}:** ${fullyQualifiedName}\n`);
        }
    }
    return reducedText;
}
/**
 * FInd location of virtual property
 * @param context
 * @param targetMdElementPath
 * @param virtualElementName
 */
export function findVirtualPropertyLocations(
    context: Context,
    targetMdElementPath: string,
    virtualElementName: string
): Location | Location[] | null {
    let elements: Element[];
    let fileUri: FileUri;
    const allLocations: Location[] = [];
    if (targetMdElementPath) {
        // try to find referenced annotation in one of the annotation files (most relevant first)
        for (let i = context.annotationFileSequence.length - 1; i >= 0; i--) {
            fileUri = context.annotationFileSequence[i];
            const file = context.fileCache[fileUri].serviceFile;
            const termName = 'com.sap.vocabularies.Analytics.v1.AggregatedProperties';
            ({ elements } = findElementsForPath(context, file.content, targetMdElementPath, termName));
            fileUri =
                fileUri && fileUri.startsWith(GHOST_FILENAME_PREFIX)
                    ? fileUri.substr(GHOST_FILENAME_PREFIX.length)
                    : fileUri;
            if (fileUri && elements && elements.length) {
                elements
                    .filter((element) => !!element.range)
                    .forEach((element) => {
                        // find range of collection entry representing virtual property
                        const collectionNode = (element.content || []).find(
                            (node) => node.type === ELEMENT_TYPE && node.name === Edm.Collection
                        ) as Element;
                        (collectionNode.content || [])
                            .filter((subNode) => subNode.type === ELEMENT_TYPE && subNode.name === Edm.Record)
                            .filter((recordNode: Element) => {
                                // filter to records that have property 'Name' with value virtualElementName
                                return (recordNode.content || [])
                                    .filter((subNode) => {
                                        return (
                                            subNode.type === ELEMENT_TYPE &&
                                            subNode.name === Edm.PropertyValue &&
                                            getElementAttributeValue(subNode, Edm.Property) === 'Name'
                                        );
                                    })
                                    .filter((nameProp: Element) => {
                                        if (getElementAttributeValue(nameProp, Edm.String) === virtualElementName) {
                                            return true;
                                        }
                                        const stringSubNode = (nameProp.content || []).find(
                                            (node) => node.type === ELEMENT_TYPE && node.name === Edm.String
                                        ) as Element;
                                        if (
                                            stringSubNode &&
                                            getSingleTextNode(stringSubNode)?.text === virtualElementName
                                        ) {
                                            return true;
                                        }
                                    }).length;
                            })
                            .forEach((matchingRecordNode: Element) =>
                                allLocations.push(Location.create(fileUri, matchingRecordNode.range))
                            );
                    });
            }
        }
    }
    return allLocations.length ? (allLocations.length === 1 ? allLocations[0] : allLocations) : null;
}

/**
 * Find references of virtual property
 * @param context
 * @param virtualElementName
 */
export function findVirtualPropertyReferences(
    context: Context,
    aliasInfo: AliasInformation,
    targetMdElementPath: string,
    virtualElementName: string
): Location[] | null {
    const allLocations: Location[] = [];
    if (targetMdElementPath && virtualElementName) {
        // try to find referenced annotation in one of the annotation files (most relevant first)
        context.annotationFileSequence.forEach((fileUri) => {
            const file = context.fileCache[fileUri]?.serviceFile;
            if (file) {
                const ranges = findRangesForPropertyPath(
                    context,
                    aliasInfo,
                    file.content,
                    targetMdElementPath,
                    virtualElementName
                );
                const uri = fileUri.startsWith(GHOST_FILENAME_PREFIX)
                    ? fileUri.substr(GHOST_FILENAME_PREFIX.length)
                    : fileUri;
                allLocations.push(...ranges.map((range) => Location.create(uri, range)));
            }
        });
    }
    return allLocations;
}

export function getAllNamespacesAndReferences(
    namespace: Namespace | undefined,
    reference: Reference[] | undefined
): (Namespace | Reference)[] {
    const result = [];
    if (namespace?.name) {
        result.push(namespace);
    }
    if (reference?.length) {
        result.push(...reference);
    }
    return result;
}
export function getPathValueForGotoDefForValueList(
    metadataService: MetadataService,
    cursorContext: CursorContext,
    cursorValue: string
): string {
    let pathValue = '';
    const { annotation, targetPath } = cursorContext;
    const collectionPath = extractValueListPropertiesFromAnnotation(annotation)?.collectionPath;
    if (collectionPath) {
        const entitySetMdElementPath = getMdElementPathForEntitySet(metadataService, collectionPath, targetPath);
        pathValue = entitySetMdElementPath ? '/' + entitySetMdElementPath + '/' + cursorValue : '';
    }
    return pathValue;
}

function isTemplateValue(cursorContext: CursorContext, targetInElement: PathTargetInElement): boolean {
    const functionName = getElementAttributeValue(cursorContext.applyContext.apply, Edm.Function) || '';
    // TODO: support multiple overloads
    const templateIndex = findTemplateParameterIndex(functionName)[0];
    if (templateIndex < 0) {
        return false;
    }
    const targetParameter = getPathTargetInElement(cursorContext.applyContext.path, cursorContext.applyContext.apply);
    const nodeIndex = targetParameter?.element && targetParameter.nodeIndex;
    const parameterIndex = getChildElementPosition(nodeIndex, cursorContext.applyContext.apply);
    return (
        parameterIndex === templateIndex &&
        targetParameter.element.name === Edm.String &&
        targetInElement.isTextSubNode &&
        !!targetInElement.textNode &&
        !!targetInElement.textNode.range
    );
}

export function getPathValueForStringProperty(
    metadataService: MetadataService,
    cursorValue: string,
    cursorContext: CursorContext,
    targetInElement: PathTargetInElement,
    startString: string,
    annotationAndPropertyPath: string
): { pathValue: string; isTemplateVariable: boolean; isActionName: boolean } {
    let pathValue = '';
    let isTemplateVariable = false;
    let isActionName = false;
    if (cursorValue.indexOf('{@i18n>') !== -1) {
        // go to i18n definition
        pathValue = cursorValue;
    } else if (cursorContext.applyContext && isTemplateValue(cursorContext, targetInElement)) {
        const variables = getTemplateVariablePositions(targetInElement.textNode.text, targetInElement.textNode.range);
        const cursorPosition = Position.create(
            targetInElement.textNode.range.start.line,
            targetInElement.textNode.range.start.character + startString.length
        );
        const varName = [...variables.keys()].find((key) => {
            return variables.get(key).find((range) => positionContained(range, cursorPosition));
        });
        if (varName) {
            pathValue = varName;
            isTemplateVariable = true;
        }
    } else if (annotationAndPropertyPath.endsWith('Action')) {
        // Restrict to complex type "UI.DataFieldForAction" Property "Action"
        // special case: string values representing fully qualified action/function names:
        // add '/' at the beginning to treat name as absolute path
        pathValue = '/' + cursorValue;
        isActionName = true;
    } else if (isTargetPropertiesOfSideEffectsPath(annotationAndPropertyPath)) {
        // handling of @Common.SideEffects TargetProperties value
        pathValue = cursorValue;
    } else if (isAnnotationPathOfCollectionPathProperty(annotationAndPropertyPath)) {
        // handling of @Common.ValueList CollectionPath value
        const targetPath = cursorContext.targetPath;
        const entitySetMdElementPath = getMdElementPathForEntitySet(metadataService, cursorValue, targetPath);
        if (entitySetMdElementPath) {
            pathValue = '/' + entitySetMdElementPath;
        }
    } else if (isAnnotationPathOfValueListProperty(annotationAndPropertyPath)) {
        // handling of @Common.ValueList ValueListProperty path value
        pathValue = getPathValueForGotoDefForValueList(metadataService, cursorContext, cursorValue);
    }
    return { pathValue, isTemplateVariable, isActionName };
}

export function resolvePath(path: PathValue, aliasInfo: AliasInformation): PathValue {
    const segments = path.split('/');
    const segmentsNoAlias = segments.map((segment) => getSegmentWithoutAlias(aliasInfo, segment));
    return segmentsNoAlias.join('/');
}
