import { GenericTokenImpl } from './genericToken';

import type { IdentifierToken, GenericDefinition } from './types';

export class IdentifierTokenImpl extends GenericTokenImpl implements IdentifierToken {
    constructor(
        public readonly uri: string,
        public readonly tokenIndex: number,
        public readonly text: string,

        public readonly line: number,
        public readonly character: number,
        public readonly definitions?: GenericDefinition,
        public annotationValue?: string
    ) {
        super(uri, tokenIndex, text, line, character, annotationValue);
    }
}
