import type { FlexibleColumnLayoutAggregations, ViewTypes } from '../webapp/manifest/sapUi5';
import { PageTypeV2, PageTypeV4 } from '@sap/ux-specification-types';

export type PageType = PageTypeV2 | PageTypeV4;
export const PageType = { ...PageTypeV2, ...PageTypeV4 };

export interface PageConfig {
    $schema?: string;
    $filePath?: string;
}

export interface NavigationEntry {
    route?: string;
    outbound?: string;
}

export interface Page {
    pageType: PageType;
    entitySet?: string;
    entityType?: string;
    contextPath?: string;
    routePattern?: string;
    navigationProperty?: string;
    config?: PageConfig;
    navigation?: { [property: string]: string | NavigationEntry };
    view?: PageView;
    variantManagement?: string;
    controlAggregation?: FlexibleColumnLayoutAggregations;
    level?: number;
}

export interface PageView {
    id: string;
    name: string;
    viewLevel?: number;
    title?: string;
    viewType?: ViewTypes;
    viewPath?: string;
    path?: string;
    template?: string;
}
