import type { AnnotationNode } from '@sap-ux/cds-annotation-parser';
import { PATH_TYPE, ANNOTATION_TYPE } from '@sap-ux/cds-annotation-parser';
import { positionContained } from '@sap-ux/odata-annotation-core';
import type { CompletionContextResolverArgs, NestedAnnotationTermNameContext, PropertyNameContext } from '../types';

export function nestedTermNameResolver({
    pathToNode,
    position,
    targetNode
}: CompletionContextResolverArgs): PropertyNameContext | NestedAnnotationTermNameContext | undefined {
    if (pathToNode.length < 2) {
        return;
    }
    const [, parent] = pathToNode.slice(-3);
    if (
        isNestedAnnotation(pathToNode) &&
        targetNode.type === PATH_TYPE &&
        parent.type === ANNOTATION_TYPE &&
        parent.term === targetNode
    ) {
        const targetIndex = targetNode.segments.findIndex((segment) => positionContained(segment.range, position));
        const propertyNameNode = targetNode.segments[targetIndex];
        if (targetNode.segments.length > 2) {
            // flattened annotation
            if (targetIndex > 1) {
                return {
                    type: 'key',
                    kind: 'property-name',
                    pathToNode,
                    proposedReplacementRange: propertyNameNode.range,
                    isQuoted: propertyNameNode.quoted ?? false,
                    flattened: true,
                    propertyName: propertyNameNode.value
                };
            }
        }
        return {
            type: 'key',
            kind: 'nested-term-name',
            pathToNode,
            proposedReplacementRange: targetNode.range,
            isQuoted: targetIndex > -1 ? targetNode.segments[targetIndex].quoted : false,
            flattened: false
        };
    }
}

function isNestedAnnotation(path: AnnotationNode[]): boolean {
    return path.reduce((count, node) => (node.type === ANNOTATION_TYPE ? ++count : count), 0) > 1;
}
