import type { Position } from 'vscode-languageserver-types';
import type { Element, ElementChild, TextNode } from '@sap-ux/odata-annotation-core';
import {
    getElementAttribute,
    getElementAttributeValue,
    Edm,
    ELEMENT_TYPE,
    positionContained,
    TEXT_TYPE
} from '@sap-ux/odata-annotation-core';

export const getRecordPropertyElement = (recordElement: Element, propertyName: string): Element | undefined => {
    return (recordElement?.content ?? []).find(
        (child) =>
            child.type === ELEMENT_TYPE &&
            child.name === Edm.PropertyValue &&
            getElementAttributeValue(child, Edm.Property) === propertyName
    ) as Element;
};

export const getPropertyStringValue = (propertyElement: Element): string => {
    let value: string;
    if (propertyElement) {
        const attr = getElementAttribute(propertyElement, 'String');
        value = attr && attr.value;
        if (!value && value !== '') {
            const subelement = (propertyElement.content ?? []).find(
                (child) => child.type === ELEMENT_TYPE && child.name === Edm.String
            );
            const textNode = ((subelement as Element)?.content ?? []).find((child) => child.type === TEXT_TYPE);
            value = (textNode as TextNode)?.text;
        }
    }
    return (value ?? '').trim();
};

/**
 * Extracts virtual property names from annotation where they defined
 * @param annotation -
 */
export const getVirtualProperties = (annotation: Element): string[] => {
    const result: string[] = [];
    const collection = (annotation.content ?? []).find(
        (node) => node.type === ELEMENT_TYPE && node.name === Edm.Collection
    );
    if (collection) {
        ((collection as Element).content ?? [])
            .filter((node) => node.type === ELEMENT_TYPE)
            .forEach((node) => {
                const nameProperty = getRecordPropertyElement(node as Element, 'Name');
                const virtualPropertyName = getPropertyStringValue(nameProperty);
                if (virtualPropertyName) {
                    result.push(virtualPropertyName);
                }
            });
    }
    return result;
};

/**
 * Extracts virtual property record element by position from annotation
 * @param annotation
 * @param position
 */
export const getVirtualPropertyRecordByPosition = (annotation: Element, position: Position): ElementChild => {
    let recordElement: ElementChild;
    const collection = (annotation.content ?? []).find(
        (node) => node.type === ELEMENT_TYPE && node.name === Edm.Collection
    );
    if (collection) {
        ((collection as Element).content ?? [])
            .filter((node) => node.type === ELEMENT_TYPE)
            .forEach((node) => {
                const isRecordMatchingPosition = positionContained(node.range, position);
                if (isRecordMatchingPosition) {
                    recordElement = node;
                }
            });
    }
    return recordElement;
};
