import type { Position } from 'vscode-languageserver';

import type { Assignment } from '@sap-ux/cds-annotation-parser';
import { RECORD_PROPERTY_TYPE } from '@sap-ux/cds-annotation-parser';
import {
    collectionValueResolver,
    recordPropertyNameResolver,
    recordPropertyValueResolver
} from './context/recordProperty';
import { annotationRefactoringResolver } from './context/annotationContainerRefactoring';
import { recordContainerResolver } from './context/recordContainer';
import { nestedTermNameResolver } from './context/nestedTermName';
import { termNameInGroupResolver, termNameResolver } from './context/termName';
import { vocabularyAliasResolver } from './context/vocabularyAlias';
import { annotationGroupResolver } from './context/annotationGroup';
import { annotationValueResolver } from './context/annotationValue';
import { expressionResolver } from './context/expression';
import type { CompletionContextResolver, CompletionContext, CompletionContextResolverArgs } from './types';
import { jsonAttributeValueResolver, jsonElementResolver, jsonContentResolver } from './context/json';
import { getPathToNode } from '../../utils/pointer';

/**
 * List of context resolvers. Order is important, because the first resolver that returns a context will be used
 */
const defaultResolvers: CompletionContextResolver[] = [
    annotationGroupResolver,
    termNameInGroupResolver,
    vocabularyAliasResolver,
    termNameResolver,
    nestedTermNameResolver,
    expressionResolver,
    annotationValueResolver,
    annotationRefactoringResolver,
    recordPropertyNameResolver,
    recordPropertyValueResolver,
    recordContainerResolver,
    collectionValueResolver
];

const edmJsonResolvers: CompletionContextResolver[] = [
    jsonContentResolver,
    jsonElementResolver,
    jsonAttributeValueResolver
];

export const getCompletionContext = (
    assignment: Assignment | undefined,
    position: Position,
    isCompoundAnnotation: boolean,
    // pointer: string,
    text: string,
    startPosition: Position
): CompletionContext => {
    if (!assignment) {
        return {
            type: 'empty-assignment',
            position,
            isCompoundAnnotation,
            hasComma: isCompoundAnnotation ? text.indexOf(',') !== -1 : undefined
        };
    }

    const pathToNode = getPathToNode(assignment, position);
    const [targetNode] = pathToNode.slice(pathToNode.length - 1);
    const hasEdmJson = pathToNode.find((node) => node.type === RECORD_PROPERTY_TYPE && node.name.value === '$edmJson');

    const args: CompletionContextResolverArgs = {
        text,
        pathToNode,
        position,
        startPosition,
        targetNode,
        isCompoundAnnotation
    };
    if (hasEdmJson) {
        return resolveContext(edmJsonResolvers, args);
    }
    return resolveContext(defaultResolvers, args);
};

/**
 * Provides restrictions that can be applied on annotation file contents, before initializing annotation
 * service. This is needed for performance reasons.
 * @param context
 */
export function getAnnotationFileRestrictions(
    context: CompletionContext
): { termName: string; qualifier?: string } | undefined | 'current-file-only' {
    const CURRENT_FILE_ONLY = 'current-file-only';
    if (context.type === 'value' && (context.valueType === 'path' || context.valueType === 'string')) {
        // No restrictions for path values, we need full file content
        // Old syntax allows to use strings for OData paths
        return undefined;
    }
    if (context.type === 'key' || context.type === 'refactor') {
        // Paths can't be added for the keys (on the left side of the colon)
        // Paths currently can't be added in refacoring context
        return CURRENT_FILE_ONLY;
    }
    if (context.type === 'container' && context.kind === 'annotation-group') {
        // In annotation group only terms are allowd
        return CURRENT_FILE_ONLY;
    }
    if (context.type === 'empty-assignment') {
        // Only terms are allowed here
        return CURRENT_FILE_ONLY;
    }
    if (context.type === 'unknown') {
        // We don't need to perform anything for unknown contexts
        return CURRENT_FILE_ONLY;
    }
    if (context.type === 'container' && context.kind === 'record') {
        // In record only properties and annotation terms are allowed
        return {
            termName: context.termName,
            qualifier: context.termQualifier
        };
    }
}

function resolveContext(
    resolvers: CompletionContextResolver[],
    args: CompletionContextResolverArgs
): CompletionContext {
    for (const resolver of resolvers) {
        const context = resolver(args);
        if (context) {
            return context;
        }
    }
    return {
        type: 'unknown'
    };
}
