import type { SnippetHandlingContext } from '.';
import { Snippet } from './snippet';
import { getApplyFunctionSnippets } from './applyFunction';
import { dynamicExpressionSignatureMap } from '../specification';
import { Edm } from '@sap-ux/odata-annotation-core';
import { getDynamicExpressionDocumentation } from '../value-handling';
import { MarkupKind } from 'vscode-languageserver-types';
import type { CompletionItem } from '../types/general';
import { getElementNamesProvidingValue } from './collection';

/**
 * Simple element snippets
 * @param valueHandlingContext - value handling context object
 * @param type - value type
 * @param useSnippets - use snippets flag
 */
export function snippetsForElementsProvidingValue(context: SnippetHandlingContext): CompletionItem[] {
    const propNames = getElementNamesProvidingValue(context);
    const compItems = Object.keys(propNames)
        .filter((entry) => ![Edm.Apply, Edm.LabeledElement].includes(entry as Edm))
        .map((entry) => {
            const snippet = new Snippet(entry as Edm, context.useSnippets).addMandatoryAttributesWithTabStops();
            if (entry === Edm.If) {
                snippet.appendNextTabStopToContent().appendNextTabStopToContent();
            } else if (
                [...dynamicExpressionSignatureMap.keys()]
                    .filter((key) => dynamicExpressionSignatureMap.get(key).metadata?.comparisonOperator)
                    .includes(entry as Edm)
            ) {
                snippet.appendNextTabStopToContent();
            }
            const completionItem = snippet.appendFinalTabStopToContent().toCompletionItem(null, null, propNames[entry]);
            if (dynamicExpressionSignatureMap.has(entry as Edm)) {
                completionItem.documentation = {
                    kind: MarkupKind.Markdown,
                    value: (getDynamicExpressionDocumentation(entry as Edm) || []).join('\n')
                };
            }
            return completionItem;
        });
    if (propNames[Edm.Apply]) {
        compItems.push(...getApplyFunctionSnippets(context));
    }
    return compItems;
}
