import type { DiagnosticBase, RuleType, ExtendedDiagnostic as Diagnostic } from '@sap-ux/odata-annotation-core';
import type { Range } from 'vscode-languageserver-types';
import { DiagnosticSeverity } from 'vscode-languageserver-types';

export const createErrorDiagnostic = (message: string, range: Range): Diagnostic => ({
    severity: DiagnosticSeverity.Error,
    range,
    message
});

export const createWarningDiagnostic = (message: string, range: Range): Diagnostic => ({
    severity: DiagnosticSeverity.Warning,
    range,
    message
});

export const createErrorDiagnosticWithRule = <D, R extends RuleType>(
    rule: R,
    message: string,
    range: Range,
    data?: D
): DiagnosticBase<R, D> => Object.assign({}, createErrorDiagnostic(message, range), { rule, data });
