import type { CompletionItem } from 'vscode-languageserver';
import { Position } from 'vscode-languageserver';

import type { MetadataElementMap, MetadataCollector } from '@sap/ux-cds-compiler-facade';
import { toTargetMap, toAnnotationFile, adjustCdsTermNames } from '@sap/ux-cds-odata-annotation-converter';
import { createCdsCompilerFacade, createMetadataCollector } from '@sap/ux-cds-compiler-facade';
import { parse } from '@sap-ux/cds-annotation-parser';
import { positionContained } from '@sap-ux/odata-annotation-core';
import { VocabularyService } from '@sap-ux/odata-vocabularies';

import { cdsLogger } from '../../log';
import { prepareAnnotationService } from '../../annotationService';
import type { CdsCompletionParams, ContributionContext } from '../../lspTypes';
import { Setting } from '../../lspTypes';
import { getCompletionContext, getAnnotationFileRestrictions } from './context';
import type { CompletionContext, CompletionHandlerArgs } from './types';
import { runHandlers } from './runners';
import { DEFAULT_COMPLETION_HANDLERS } from './handlers';
import { getTarget } from '../../utils/pointer';
import { GLOBAL_ADAPTERS } from './adapters';

const vocabularyService = new VocabularyService(true);

export function getCompletionItems(
    { cursorPosition, index, annotation, ast, isCompoundAnnotation }: CdsCompletionParams,
    contribContext: ContributionContext
): CompletionItem[] {
    const { position, textDocument } = cursorPosition;
    cdsLogger.info('---new CC API called:');

    cdsLogger.info(`annotation.text: "${annotation.text}"`);
    if (annotation.carrier.definitions) {
        const message = `annotation.carrier.definitions.fullyQualifiedName: ${annotation.carrier.definitions['fullyQualifiedName']}`;
        cdsLogger.info(message);
    } else {
        const message = `annotation.carrier.text: ${annotation.carrier.text}`;
        cdsLogger.info(message);
    }

    // Work around solution: CDS returns annotation text along with entity type property
    let text = annotation.text;
    if (
        annotation.range &&
        annotation.carrier?.range &&
        positionContained(annotation.range, annotation.carrier.range.start)
    ) {
        text = annotation.text.substring(
            0,
            annotation.text.length - (annotation.carrier.range.end.character - annotation.carrier.range.start.character)
        );
    }
    // end of work around solution

    //if position is after annotation text: adjust it to be at the end of annotation text
    const posForPointer = position;
    const lines = annotation.text.split('\n');
    const lastLine = annotation.line + lines.length - 1;
    const lastChar =
        lines.length === 1 ? annotation.character + annotation.text.length : lines[lines.length - 1].length;
    if (position.line > lastLine || (position.line === lastLine && position.character > lastChar)) {
        posForPointer.line = lastLine;
        posForPointer.character = lastChar;
    }
    const facade = createCdsCompilerFacade(ast);
    const startPosition = Position.create(annotation.line, annotation.character);
    const assignment = adjustCdsTermNames(parse(text, startPosition), vocabularyService.cdsVocabulary);
    const cdsAnnotationFile = toTargetMap(index.forUri(textDocument.uri), textDocument.uri, vocabularyService, facade);
    // for code completion: all metadata elements are needed (e.g. to find available segments in paths)
    const metadataElementMap: MetadataElementMap = facade.getMetadata();
    const metadataCollector: MetadataCollector = createMetadataCollector(metadataElementMap, facade);
    const { file: annotationFile, pointer } = toAnnotationFile(
        textDocument.uri,
        vocabularyService,
        cdsAnnotationFile,
        metadataCollector,
        posForPointer
    );
    const omitRedundantTypesInSnippets = contribContext.settings.get(Setting.OmitRedundantTypesInSnippets) as boolean;
    const context: CompletionContext = getCompletionContext(
        assignment,
        position,
        isCompoundAnnotation,
        text,
        startPosition
    );

    let updatedPointer = pointer;
    // fix pointer when adding new annotation e.g @(|) or @|
    if (!pointer && annotation.text === '') {
        const { range } = annotation.carrier;
        const id = JSON.stringify(range);
        if (cdsAnnotationFile.targetMap.has(id)) {
            const index = [...cdsAnnotationFile.targetMap.keys()].findIndex((item) => item === id);
            updatedPointer = ['', 'targets', index].join('/');
        }
    }

    const restrictions = getAnnotationFileRestrictions(context);
    const annotationFileRestrictions =
        restrictions && restrictions !== 'current-file-only'
            ? {
                  targetName: getTarget(annotationFile, updatedPointer),
                  ...restrictions
              }
            : undefined;
    const annotationService = prepareAnnotationService(
        vocabularyService,
        index,
        textDocument.uri,
        annotationFile,
        metadataCollector,
        {
            includeDependencies: true,
            omitRedundantTypesInSnippets,
            annotationFileRestrictions,
            currentFileOnly: restrictions === 'current-file-only',
            completionOnly: true,
            facade
        }
    );

    const args: CompletionHandlerArgs = {
        getCompletionItems: annotationService.complete.bind(annotationService),
        position,
        pointer: updatedPointer,
        file: annotationFile
    };

    return runHandlers(DEFAULT_COMPLETION_HANDLERS, context, args, GLOBAL_ADAPTERS);
}
