import { Edm } from '@sap-ux/odata-annotation-core';
import type { CompletionItem } from 'vscode-languageserver';
import { InsertTextFormat, CompletionItemKind, TextEdit } from 'vscode-languageserver';
import type {
    CompletionContext,
    CompletionItemAdapterParams,
    JsonAttributeValueContext,
    ModularCompletionHandler
} from '../types';
import { basicItemProvider } from '../utils';

function jsonAttributeValueGate(context: CompletionContext): boolean {
    return context.type === 'edm-json' && context.kind === 'attribute-value';
}

const KIND_MAP = new Map<Edm | string, CompletionItemKind>([[Edm.Function, CompletionItemKind.Function]]);

function jsonAttributeValueAdapter({
    context: { proposedReplacementRange: replacementRange, attributeName, isStringLiteral },
    originalItem
}: CompletionItemAdapterParams<JsonAttributeValueContext>): CompletionItem | undefined {
    const insertText = originalItem.insertText;
    return {
        label: insertText,
        insertTextFormat: InsertTextFormat.PlainText,
        kind: KIND_MAP.get(attributeName) ?? originalItem.kind,
        documentation: originalItem.documentation,
        sortText: originalItem?.sortText,
        filterText: insertText,
        textEdit: TextEdit.replace(replacementRange, isStringLiteral ? insertText : `'${insertText}'`)
    };
}

export const jsonAttributeValueHandler: ModularCompletionHandler = {
    name: 'json-attribute-value',
    type: 'modular',
    gate: jsonAttributeValueGate,
    providers: [basicItemProvider],
    mappers: [],
    adapters: [jsonAttributeValueAdapter]
};
