import {
    createMetadataCollector,
    createCdsCompilerFacade,
    getMetadataElementsFromMap
} from '@sap/ux-cds-compiler-facade';

import { CdsDomainAdapter } from '@sap/ux-cds-annotation-adapter';
import type { CdsAnnotationFile } from '@sap/ux-cds-odata-annotation-converter';
import { toAnnotationFile, toTargetMap } from '@sap/ux-cds-odata-annotation-converter';

import { VocabularyService } from '@sap-ux/odata-vocabularies';
import type { CdsDiagnosticParams, ContributionContext } from '../lspTypes';
import { Setting } from '../lspTypes';
import type { AnnotationServiceInterface } from '@sap/ux-annotation-service';
import { AnnotationServiceImpl } from '@sap/ux-annotation-service';
import { MetadataService } from '@sap-ux/odata-entity-model';
import { cdsLogger } from '../log';
import type { ExtendedDiagnostic as Diagnostic, ServiceAnnotationFile } from '@sap-ux/odata-annotation-core';
import { getDependentFileUris } from '../utils/general';
const domainAdapter: CdsDomainAdapter = new CdsDomainAdapter();
const vocabularyService = new VocabularyService(true);

function getAndAdaptDiagnostics(
    annotationFiles: ServiceAnnotationFile[],
    fileUrisRequested: string[],
    enableMissingTranslationDiagnostics,
    conversionDiagnostics,
    targetMaps,
    genericAnnotationService
) {
    const allDiagnostics: Map<string, Diagnostic[]> = new Map();
    for (const file of annotationFiles) {
        if (!fileUrisRequested.includes(file.uri)) {
            continue; // skip ghost files and results for non requested files
        }
        let diagnostics = genericAnnotationService.check(file.content);
        diagnostics = [...diagnostics, ...conversionDiagnostics.get(file.uri)];
        let result = domainAdapter.adaptDiagnosticMessage(
            diagnostics,
            enableMissingTranslationDiagnostics,
            targetMaps.get(file.uri) ? targetMaps.get(file.uri).targetMap : new Map()
        );
        result = result.map((diagnostic) => {
            // avoid follow up issues if range is null but still keep the message to find root causes
            diagnostic.range = diagnostic.range || {
                start: { line: 0, character: 1 },
                end: { line: 0, character: 1 }
            };
            return diagnostic;
        });

        if (result.length) {
            allDiagnostics.set(file.uri, result);
        }
    }
    return allDiagnostics;
}

export const getDiagnostics = async (
    { uri, uris, index, ast }: CdsDiagnosticParams,
    context: ContributionContext
    // eslint-disable-next-line @typescript-eslint/require-await
): Promise<Map<string, Diagnostic[]> | Diagnostic[]> => {
    let allDiagnostics: Map<string, Diagnostic[]>;
    const facade = createCdsCompilerFacade(ast);
    const enableMissingTranslationDiagnostics = context.settings.get(Setting.MarkMissingTranslations) as boolean;
    const metadataService = new MetadataService({ uriMap: facade.getUriMap() });
    const genericAnnotationService: AnnotationServiceInterface = new AnnotationServiceImpl(
        () => {
            console.log('diagnostic');
        },
        true,
        metadataService,
        '',
        cdsLogger,
        { supportSplit: true }
    );
    const targetMaps: Map<string, CdsAnnotationFile> = new Map();
    const fileUrisRequested = Array.isArray(uris) ? uris : [uri];
    const fileUris = getDependentFileUris(fileUrisRequested, index, ast);
    // CDS-LSP fix not yet present? fill collector with all metadata
    const metadataElementMap = new Map();
    const metadataCollector = createMetadataCollector(metadataElementMap, facade);
    const conversionDiagnostics = new Map();
    let annotationFiles = fileUris.reduce((annoFiles: ServiceAnnotationFile[], uri): ServiceAnnotationFile[] => {
        const targetMap: CdsAnnotationFile = toTargetMap(index.forUri(uri), uri, vocabularyService, facade);
        targetMaps.set(uri, targetMap);
        const { file: content, diagnostics } = toAnnotationFile(uri, vocabularyService, targetMap, metadataCollector);
        conversionDiagnostics.set(uri, diagnostics);

        annoFiles.push({
            serviceName: 'default',
            uri,
            content
        });
        return annoFiles;
    }, []);
    if (annotationFiles.length === 0) {
        allDiagnostics = new Map();
        return Array.isArray(uris) ? allDiagnostics : [];
    }
    if (ast) {
        const ghostFiles = facade.getGhostFiles(annotationFiles);
        annotationFiles.splice(0, 0, ...ghostFiles);
    }
    annotationFiles = annotationFiles.filter(
        (file) => file.content && file.content.targets && file.content.targets.length
    );
    const metadataElementNodes = getMetadataElementsFromMap(metadataCollector.metadataElementMap);
    metadataService.import(metadataElementNodes, 'DummyMetadataFileUri');
    genericAnnotationService.loadService(annotationFiles);

    allDiagnostics = getAndAdaptDiagnostics(
        annotationFiles,
        fileUrisRequested,
        enableMissingTranslationDiagnostics,
        conversionDiagnostics,
        targetMaps,
        genericAnnotationService
    );
    if (Array.isArray(uris)) {
        return allDiagnostics;
    } else {
        // Todo: remove this when new CDS LSP version which support `uris` is publicly available.
        return allDiagnostics.get(uri) ?? [];
    }
};
