import { EXPRESSION_TYPES } from '@sap-ux/cds-annotation-parser';
import type { CompletionContextResolverArgs, ExpressionContext } from '../types';

export function expressionResolver({
    targetNode,
    pathToNode
}: CompletionContextResolverArgs): ExpressionContext | undefined {
    if (pathToNode.length < 2) {
        return;
    }
    const parent = pathToNode[pathToNode.length - 2];
    if (EXPRESSION_TYPES.includes(targetNode.type) || EXPRESSION_TYPES.includes(parent.type)) {
        return {
            type: 'container',
            kind: 'expression',
            pathToNode
        };
    }
}
