import type { Element } from '@sap-ux/odata-annotation-core';
import { Edm, getElementAttributeValue } from '@sap-ux/odata-annotation-core';

export class CheckTrace {
    private path: string;
    private pathStack: string[];

    constructor() {
        this.path = '';
        this.pathStack = [];
    }

    getPath() {
        return this.path;
    }

    addTokensToPath(tokens: string | string[]): CheckTrace {
        const tList: string[] = Array.isArray(tokens) ? tokens : [tokens];
        this.path += '[' + tList.join('=') + ']';
        return this;
    }

    registerTarget(target: string): CheckTrace {
        return this.addTokensToPath([Edm.Target, target]);
    }

    registerTerm(term: string, qualifier?: string): CheckTrace {
        return this.addTokensToPath([Edm.Term, term + (qualifier ? '#' + qualifier : '')]);
    }

    registerElement(element: Element, idx?: number): CheckTrace {
        switch (element.name) {
            case Edm.Collection:
                this.addTokensToPath(Edm.Collection).addTokensToPath(idx + '');
                break;
            case Edm.Record: {
                const type = getElementAttributeValue(element, 'Type') || '<unknown>';
                this.addTokensToPath([Edm.Record, type]);
                break;
            }
            case Edm.PropertyValue: {
                const prop = getElementAttributeValue(element, 'Property') || '<unknown>';
                this.addTokensToPath([Edm.PropertyValue, prop]);
                break;
            }
            default:
                this.addTokensToPath(element.name);
        }
        return this;
    }

    push() {
        this.pathStack.push(this.path);
    }

    pop() {
        if (this.pathStack.length) {
            this.path = this.pathStack.pop();
        } else {
            this.path = '';
        }
    }
}
