import { ANNOTATION_GROUP_ITEMS_TYPE, ANNOTATION_GROUP_TYPE } from '@sap-ux/cds-annotation-parser';
import { nodeHasComma } from '../../../utils/hasComma';
import type { AnnotationGroupContainerContext, CompletionContextResolverArgs } from '../types';

export function annotationGroupResolver({
    targetNode,
    pathToNode,
    position
}: CompletionContextResolverArgs): AnnotationGroupContainerContext | undefined {
    if (pathToNode.length < 2) {
        return;
    }
    if (targetNode.type === ANNOTATION_GROUP_ITEMS_TYPE) {
        const parent = pathToNode[pathToNode.length - 2];
        if (parent.type === ANNOTATION_GROUP_TYPE) {
            const hasComma = nodeHasComma(pathToNode, position);
            return {
                type: 'container',
                kind: 'annotation-group',
                pathToNode,
                position,
                groupName: parent.name.value,
                hasComma
            };
        }
    }
}
