import { RECORD_TYPE } from '@sap-ux/cds-annotation-parser';
import { nodeHasComma } from '../../../utils/hasComma';
import type { AnnotationContainerContext, CompletionContextResolverArgs, RecordContainerContext } from '../types';
import { getContainingAnnotationDetails } from '../utils';

export function recordContainerResolver({
    pathToNode,
    position,
    targetNode
}: CompletionContextResolverArgs): RecordContainerContext | AnnotationContainerContext | undefined {
    if (targetNode.type === RECORD_TYPE) {
        const hasComma = nodeHasComma(pathToNode, position);
        if (targetNode.properties.find((property) => property.name.value === '$value')) {
            // annotation container context
            return {
                type: 'container',
                kind: 'annotation',
                pathToNode,
                position,
                hasComma
            };
        }
        const annotationDetails = getContainingAnnotationDetails(pathToNode);
        if (annotationDetails) {
            return {
                type: 'container',
                kind: 'record',
                pathToNode,
                position,
                hasComma,
                ...annotationDetails
            };
        }
    }
}
